      private static string TestRescueFromFoe(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("rescue_from_foe");

         Rescue.RescueBehavior rescue = Rescue.RescueBehavior.Instance;
         if (t.Skip(rescue == null, "the rescue behaviour is not active")) return t.Line();
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && !h.IsPrisoner && h.Clan != Clan.PlayerClan && !h.IsChild
                                                             && h.PartyBelongedTo == null && h.Clan?.IsBanditFaction != true);
         Hero captor = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h != lord && h.Clan != Clan.PlayerClan && !h.IsChild);
         if (t.Skip(lord == null || captor == null, "no free, partyless lord and another lord to hold them")) return t.Line();

         rescue.DebugForgetCredit(lord);
         try
         {
            TakePrisonerAction.Apply(PartyBase.MainParty, lord);
            rescue.DebugMarkTakenFromFoe(lord, captor, (int) CampaignTime.Now.ToDays);
            EndCaptivityAction.ApplyByReleasedByChoice(lord, Hero.MainHero);

            NpcProfile profile = behavior.Store.Get(lord.StringId);
            string memory = profile?.Events?.LastOrDefault(e => e.summary?.StartsWith("You freed me from") == true)?.summary ?? "";
            t.Note($"{lord.Name}: {memory}");
            t.Expect("freedLordRemembersIt", memory.Length > 0, true);
            t.Expect("andNamesWhoHeldThem", memory.Contains(captor.Name.ToString()), true);
         }
         finally
         {
            if (lord.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(lord);
            rescue.DebugForgetCredit(lord);
         }

         return t.Line();
      }

