      private static string TestDivorceProcess(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("divorce_process");

         if (t.Abort(DivorceProcessBehavior.Instance == null, "DivorceProcessBehavior not active")) return t.Line();
         if (t.Abort(WorldEventStore.Instance == null, "WorldEventStore not active")) return t.Line();
         if (t.Abort(GrudgeBehavior.Instance == null, "GrudgeBehavior not active")) return t.Line();

         var processes = DivorceProcessBehavior.Instance;
         var usedNpcIds = new HashSet<string>();

         // ── Scenario A: REPUDIATED (the spouse resisted at least once before the deadline) — exercises
         // ── DivorceConsequencePolicy's PlantGrudge branch on the set-aside spouse ──────────────────────
         (Hero npc, Hero spouse)? pair = ResolveDivorceEligibleCouple();

         if (t.Skip(pair == null, "no married couple available whose leaving spouse is free to relocate")) return t.Line();
         (Hero npc, Hero spouse) = pair.Value;
         usedNpcIds.Add(npc.StringId);

         NpcProfile profile = GetOrCreate(behavior, npc);
         ArrangeCleanNpc(behavior, profile, npc, spouse);
         NeutralizeRelation(spouse, Hero.MainHero); // deterministic baseline for the exSpouse->player delta assertion below

         // Force the two relation gates: an unhappy marriage, a deep bond with the player.
         Mapping.RelationLedgerBehavior.SetAsHistory(npc, spouse, DivorcePolicy.UnhappyThreshold - 10);
         ChangeRelationAction.ApplyRelationChangeBetweenHeroes(npc, Hero.MainHero, DivorcePolicy.BondThreshold + 10 - npc.GetRelation(Hero.MainHero), false);

         if (t.Abort(!DivorceEligibilityResolver.IsEligible(npc, out string ineligibleReason), $"seed not eligible: {ineligibleReason}")) return t.Line();

         ActionOutcome seedOutcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "end_marriage"}, npc, new ActionContext(profile, null));

         if (t.Abort(seedOutcome is not {IsPositive: true}, "end_marriage seed failed (wiring bug, not a judgment call)")) return t.Line();

         DivorceProcess process = processes.FindActive(npc.StringId);

         if (t.Abort(process == null, "seeded process not found in Active list")) return t.Line();

         // Force one day of spousal resistance BEFORE forcing the end day, so DivorcePolicy.IsMutualConsent
         // (cumulativeDelayDays == 0 -> mutual) reads this as REPUDIATED rather than mutual, and the
         // matrix's grudge-planting branch, not its relief branch, is what actually gets exercised below.
         process.CumulativeDelayDays = DivorcePolicy.DelayDaysPerDelay;
         process.EndDay = behavior.GameStateBridge.GetCurrentGameDay();

         int worldEventsBefore = WorldEventStore.Instance.Count;
         int spouseVsNpcBefore = spouse.GetRelation(npc);
         int spouseVsPlayerBefore = spouse.GetRelation(Hero.MainHero);
         int today = behavior.GameStateBridge.GetCurrentGameDay();
         // The consequences SET target relations from the pre-dissolution baselines (CR corrects for the
         // engine's own hidden penalty during the act), signed by mutual consent, which the behavior reads
         // from the spouse's RESISTANCE (no delay days = acquiescence). Read it now, matching the behavior.
         bool mutualConsent = DivorcePolicy.IsMutualConsent(process.CumulativeDelayDays, spouseVsPlayerBefore);

         processes.DebugRunDailyAdvance();

         bool bothSpousesNulled = npc.Spouse == null && spouse.Spouse == null;
         bool recordedAsExSpouses = npc.ExSpouses != null &&
                                    npc.ExSpouses.Contains(spouse) &&
                                    spouse.ExSpouses != null &&
                                    spouse.ExSpouses.Contains(npc);
         bool neitherLeftClanless = npc.Clan != null && spouse.Clan != null;
         int worldEventsAfter = WorldEventStore.Instance.Count;
         int spouseVsNpcAfter = spouse.GetRelation(npc);
         int spouseVsPlayerAfter = spouse.GetRelation(Hero.MainHero);
         bool repudiatedSpouseGrudgePlanted = GrudgeBehavior.Instance.GrudgesFor(spouse.StringId)
                                                            .Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today);

         t.Note($"{npc.Name} x {spouse.Name} ({(mutualConsent ? "mutual consent" : "repudiated")}): " +
                $"spouseVsNpc {spouseVsNpcBefore}->{spouseVsNpcAfter}, " +
                $"spouseVsPlayer {spouseVsPlayerBefore}->{spouseVsPlayerAfter}, worldEvents {worldEventsBefore}->{worldEventsAfter}");
         t.Expect("bothSpousesNulled", bothSpousesNulled, true);
         t.Expect("recordedAsExSpouses", recordedAsExSpouses, true);
         t.Expect("neitherLeftClanless", neitherLeftClanless, true);
         t.Expect("scandalWorldEventRecorded", worldEventsAfter > worldEventsBefore, true);
         t.Expect("exSpouseVsNpcOutcome", spouseVsNpcAfter, spouseVsNpcBefore + DivorcePolicy.ExSpouseNpcHit(mutualConsent));
         t.Expect("exSpouseVsPlayerOutcome", spouseVsPlayerAfter, spouseVsPlayerBefore + DivorcePolicy.ExSpousePlayerHit(mutualConsent));
         t.Expect("repudiatedSpouseGrudgePlanted", repudiatedSpouseGrudgePlanted, true);

         // Owner ruling 04/07/2026: a repudiated divorce also grudges the spouse's immediate ADULT family
         // and three best friends, not the whole clan. Best-effort: this campaign's seeded couple may not
         // actually have a qualifying family member or friend, so a barren case is logged, not failed.
         var directFamilyCandidates = new List<Hero>();
         if (spouse.Father is {IsAlive: true, IsChild: false} father && father != npc && father != Hero.MainHero)
            directFamilyCandidates.Add(father);
         if (spouse.Mother is {IsAlive: true, IsChild: false} mother && mother != npc && mother != Hero.MainHero)
            directFamilyCandidates.Add(mother);
         if (spouse.Siblings != null)
            directFamilyCandidates.AddRange(spouse.Siblings.Where(s => s is {IsAlive: true, IsChild: false} && s != npc && s != Hero.MainHero));
         if (spouse.Children != null)
            directFamilyCandidates.AddRange(spouse.Children.Where(c => c is {IsAlive: true, IsChild: false} && c != npc && c != Hero.MainHero));

         if (directFamilyCandidates.Count == 0)
         {
            t.Note("directFamilyGrudgePlanted skipped: seeded spouse has no qualifying adult family member in this campaign");
         }
         else
         {
            bool directFamilyGrudgePlanted = directFamilyCandidates.Any(member =>
               GrudgeBehavior.Instance.GrudgesFor(member.StringId).Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today));
            t.Expect("directFamilyGrudgePlanted", directFamilyGrudgePlanted, true);
         }

         Hero bestFriendCandidate = Hero.AllAliveHeroes
                                        .Where(h => h != null && h != spouse && h != npc && h != Hero.MainHero && !directFamilyCandidates.Contains(h))
                                        .Where(h => Mapping.PairBondReader.Points(h, spouse) >= VanillaRelation.TrustedTier)
                                        .OrderByDescending(h => Mapping.PairBondReader.Points(h, spouse))
                                        .FirstOrDefault();

         if (bestFriendCandidate == null)
         {
            t.Note("friendGrudgePlanted skipped: no qualifying best friend for the seeded spouse in this campaign");
         }
         else
         {
            bool friendGrudgePlanted = GrudgeBehavior.Instance.GrudgesFor(bestFriendCandidate.StringId)
                                                     .Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today);
            t.Expect("friendGrudgePlanted", friendGrudgePlanted, true);
         }

         // ── Scenario B: MUTUAL CONSENT (never resisted) — the SAME matrix must plant NO spouse grudge ──
         // A second, distinct couple is needed: the first pair is no longer married after Scenario A.
         // Best-effort: if the campaign has no second eligible couple, this half is skipped WITHOUT
         // failing Scenario A's already-recorded verdict above.
         // Neither of the second couple may already hold a Divorce grudge of today: the first couple's divorce grudges its
         // family and friends, and on Gabriel's save (20/10/2026) the second couple's husband was the first wife's kin, so the
         // check read Scenario A's grudge (and the same-day dedup would have hidden a real one from Scenario B).
         (Hero npc, Hero spouse)? secondPair = ResolveDivorceEligibleCouple(usedNpcIds,
            h => GrudgeBehavior.Instance.GrudgesFor(h.StringId).Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today));
         if (secondPair == null)
         {
            t.Note("mutualConsentSpouseGrudgeAbsent skipped: no second eligible couple available");

            return t.Line();
         }

         (Hero npc2, Hero spouse2) = secondPair.Value;

         NpcProfile profile2 = GetOrCreate(behavior, npc2);
         ArrangeCleanNpc(behavior, profile2, npc2, spouse2);
         NeutralizeRelation(spouse2, Hero.MainHero);

         Mapping.RelationLedgerBehavior.SetAsHistory(npc2, spouse2, DivorcePolicy.UnhappyThreshold - 10);
         ChangeRelationAction.ApplyRelationChangeBetweenHeroes(npc2, Hero.MainHero, DivorcePolicy.BondThreshold + 10 - npc2.GetRelation(Hero.MainHero), false);

         if (!DivorceEligibilityResolver.IsEligible(npc2, out string ineligibleReason2))
         {
            t.Note($"mutualConsentSpouseGrudgeAbsent skipped: second seed not eligible: {ineligibleReason2}");

            return t.Line();
         }

         ActionOutcome secondSeedOutcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "end_marriage"}, npc2, new ActionContext(profile2, null));
         if (secondSeedOutcome is not {IsPositive: true})
         {
            t.Note("mutualConsentSpouseGrudgeAbsent skipped: second end_marriage seed failed");

            return t.Line();
         }

         DivorceProcess process2 = processes.FindActive(npc2.StringId);
         if (process2 == null)
         {
            t.Note("mutualConsentSpouseGrudgeAbsent skipped: second seeded process not found");

            return t.Line();
         }

         // CumulativeDelayDays is left at its natural default of 0 (never resisted), so this second
         // dissolution reads as MUTUAL consent — the contrasting half of the repudiated Scenario A above.
         int today2 = behavior.GameStateBridge.GetCurrentGameDay();
         process2.EndDay = today2;

         processes.DebugRunDailyAdvance();

         bool mutualConsentSpouseGrudgeAbsent = !GrudgeBehavior.Instance.GrudgesFor(spouse2.StringId)
                                                               .Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today2);

         t.Note($"{npc2.Name} x {spouse2.Name} (mutual consent, second couple): " +
                $"mutualConsentSpouseGrudgeAbsent={mutualConsentSpouseGrudgeAbsent}");
         t.Expect("mutualConsentSpouseGrudgeAbsent", mutualConsentSpouseGrudgeAbsent, true);

         return t.Line();
      }

      private static string TestFeedIngest(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("feed_ingest");

         if (t.Abort(WorldEventStore.Instance == null, "WorldEventStore not active")) return t.Line();

         string id = "selftest_" + Guid.NewGuid().ToString("N");
         var e = new ExternalWorldEvent {
            Id = id, SourceMod = "SelfTest", Summary = "[SELFTEST] an external rumour reached Calradia", Magnitude = 30
         };

         int before = WorldEventStore.Instance.Count;
         FeedResult first = Feed.Record(e);
         int afterFirst = WorldEventStore.Instance.Count;
         FeedResult second = Feed.Record(e); // same id -> deduped
         int afterSecond = WorldEventStore.Instance.Count;

         t.Note($"first={first}, second={second}, count {before}->{afterFirst}->{afterSecond}");
         t.Expect("recorded", first, FeedResult.Recorded);
         t.Expect("countRose", afterFirst, before + 1);
         t.Expect("dedupRejected", second, FeedResult.RejectedDuplicate);
         t.Expect("noDoubleCount", afterSecond, afterFirst);

         return t.Line();
      }

      private static string TestFeedUpdate(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("feed_update");

         if (t.Abort(WorldEventStore.Instance == null, "WorldEventStore not active")) return t.Line();

         string id = "selftest_upd_" + Guid.NewGuid().ToString("N");
         FeedResult rec = Feed.Record(new ExternalWorldEvent {
            Id = id, SourceMod = "SelfTest", Summary = "[SELFTEST] a homestead stands near Pen Cannoc", Magnitude = 30
         });

         if (t.Abort(rec != FeedResult.Recorded, $"record failed: {rec}")) return t.Line();
         // Feed.List (since 2.8.10, Bhelogan): a mod reads back what it recorded, and only its own.
         t.Expect("listedForItsSource", Feed.List("SelfTest").Any(e => e.Id == id && e.Summary.Contains("Pen Cannoc")), true);
         t.Expect("notListedForAnother", Feed.List("SelfTestOther").Any(e => e.Id == id), false);

         // The homestead moves -> the modder corrects the standing fact by the same id.
         FeedResult upd = Feed.Update(new ExternalWorldEvent {
            Id = id, SourceMod = "SelfTest", Summary = "[SELFTEST] the homestead has moved to near Marunath", Magnitude = 30
         });
         string afterUpdate = WorldEventStore.Instance.GetById(id)?.Summary;

         // The homestead is gone -> retract it; a second retract finds nothing.
         FeedResult ret = Feed.Retract(id);
         bool goneAfterRetract = WorldEventStore.Instance.GetById(id) == null;
         t.Expect("noLongerListedOnceRetracted", Feed.List("SelfTest").Any(e => e.Id == id), false);
         FeedResult retAgain = Feed.Retract(id);

         t.Note($"update={upd}, summary now '{Preview(afterUpdate)}', retract={ret}, retractAgain={retAgain}");
         t.Expect("updated", upd, FeedResult.Updated);
         t.Expect("contentReplaced", afterUpdate != null && afterUpdate.Contains("Marunath"), true);
         t.Expect("retracted", ret, FeedResult.Retracted);
         t.Expect("goneAfterRetract", goneAfterRetract, true);
         t.Expect("retractMissingIsNotFound", retAgain, FeedResult.NotFound);

         return t.Line();
      }

      private static string TestHeardDiagnostic(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("heard_diagnostic");

         WorldEventStore store = WorldEventStore.Instance;

         if (t.Abort(store == null, "WorldEventStore not active")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.MapFaction != null
                                                           && (h.PartyBelongedTo != null || h.CurrentSettlement != null));

         if (t.Skip(lord == null, "no free lord with a realm and a position")) return t.Line();

         Settlement place = lord.CurrentSettlement ?? Settlement.All?.FirstOrDefault(x => x.IsTown);

         if (t.Skip(place == null, "no settlement to place the news at")) return t.Line();

         // Its own source, so repeated testall runs on one day never meet the SelfTest quota other tests share.
         const string source = "SelfTestHeard";
         string suffix = Guid.NewGuid().ToString("N");
         string placedId = "selftest_heard_placed_" + suffix;
         string bogusId = "selftest_heard_bogus_" + suffix;
         string namedId = "selftest_heard_named_" + suffix;
         var today = (int) CampaignTime.Now.ToDays;

         try
         {
            Feed.Record(new ExternalWorldEvent {
               Id = placedId, SourceMod = source, Summary = "[SELFTEST] a siege was laid and lifted", Magnitude = 60,
               FactionIds = new List<string> {lord.MapFaction.StringId}, PlaceId = place.StringId
            });
            WorldEvent placed = store.GetById(placedId);

            if (t.Abort(placed == null, "the placed event was not recorded")) return t.Line();

            t.Expect("aRealPlaceIsKept", placed.PlaceId, place.StringId);

            RumorAwarenessBreakdown verdict = store.Explain(lord, placed, today);
            t.Note($"{lord.Name} at {place.Name}: {verdict.Describe()}");
            t.Expect("theRealmTagReachesALordOfThatRealm", verdict.FactionMatches, true);
            t.Expect("heHasHeardIt", verdict.Knows, true);
            if (lord.CurrentSettlement == place) t.Expect("beingThereCountsFully", verdict.GeoBonus, RumorAwareness.GeoBonusMax);

            // The console must never say "heard" about a fact the prompt would not give him, or the reverse.
            t.Expect("cr.heardAgreesWithThePrompt", store.GetKnownEvents(lord, today, 1000).Any(e => e.Id == placedId), verdict.Knows);

            Feed.Record(new ExternalWorldEvent {
               Id = bogusId, SourceMod = source, Summary = "[SELFTEST] something happened somewhere", Magnitude = 10,
               PlaceId = "no_such_settlement_selftest"
            });
            t.Expect("aBogusPlaceIsDroppedNotKept", store.GetById(bogusId) != null && store.GetById(bogusId).PlaceId == null, true);

            // Magnitude 30, untagged: under the threshold for anyone but the one it names.
            Feed.Record(new ExternalWorldEvent {
               Id = namedId, SourceMod = source, Summary = "[SELFTEST] a quiet word about one lord", Magnitude = 30,
               HeroIds = new List<string> {lord.StringId}
            });
            WorldEvent named = store.GetById(namedId);

            if (t.Abort(named == null, "the named event was not recorded")) return t.Line();

            t.Expect("theLordItNamesCanSpeakOfIt", store.GetKnownEventsRated(lord, today, 1000).Any(x => x.Event.Id == namedId), true);

            Hero bystander = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != lord && h.IsLord);
            if (bystander != null) t.Expect("aBystanderHasNotHeardIt", store.IsAwareOf(bystander, named, today), false);

            // The command itself, by the lord's name. A namesake may resolve first, so only the id is asserted.
            string report = ModCheats.Heard(new List<string> {lord.Name.ToString(), placedId});
            t.Note("cr.heard: " + Preview(report));
            t.Expect("cr.heardReportsTheEvent", report != null && report.Contains(placedId), true);
         }
         finally
         {
            Feed.Retract(placedId);
            Feed.Retract(bogusId);
            Feed.Retract(namedId);
         }

         return t.Line();
      }

      private static string TestSharedPastDraw(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("shared_past_draw");

         SharedPastBehavior past = SharedPastBehavior.Instance;
         WorldEventStore store = WorldEventStore.Instance;
         if (t.Abort(past == null || store == null, "the shared past or the world-event store is not active")) return t.Line();

         Hero hero = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsChild && h.Clan != null && h.MapFaction is Kingdom);
         if (t.Skip(hero == null, "no adult lord of a realm")) return t.Line();

         List<Hero> others = ((Kingdom) hero.MapFaction).Clans.Where(c => c != null && !c.IsEliminated && c != hero.Clan && c.Leader != null && !c.Leader.IsChild)
                                                       .Select(c => c.Leader).Where(o => !past.WasDrawn(hero, o)).Take(6).ToList();
         if (t.Skip(others.Count == 0, $"every house lord of {hero.MapFaction.Name} was already drawn with {hero.Name}")) return t.Line();

         int start = (int) Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.ToDays;
         int year = CampaignTime.DaysInSeason * CampaignTime.SeasonsInYear;
         int ofAge = Campaign.Current.Models.AgeModel.HeroComesOfAge;

         try
         {
            int drawn = past.DrawFor(hero, others);
            t.Note($"{hero.Name}: {drawn} pair(s) drawn among {others.Count}");
            if (t.Skip(drawn == 0, "every candidate pair already has a story of its own (a trace of 10 or more) or is kin")) return t.Line();
            t.Expect("everyDrawIsMarked", others.Count(o => past.WasDrawn(hero, o)), drawn);

            var pasts = others.Select(o => store.GetHistoryById(SharedPastBehavior.RecordId(SharedPastBehavior.PairKey(hero, o)))).Where(e => e != null).ToList();
            t.Note($"{pasts.Count} past(s): " + string.Join(" | ", pasts.Select(e => e.Summary)));
            t.Expect("everyPastIsBeforeTheCampaign", pasts.All(e => e.Day < start), true);
            t.Expect("bothWereOfAgeThen", pasts.All(e => e.ActorIds.All(id => {
               Hero h = Hero.FindFirst(x => x.StringId == id);
               return h != null && (e.Day - (int) h.BirthDay.ToDays) / Math.Max(1, year) >= ofAge;
            })), true);

            int again = past.DrawFor(hero, others);
            t.Expect("aSecondDrawChangesNothing", again == 0 && others.Select(o => store.GetHistoryById(SharedPastBehavior.RecordId(SharedPastBehavior.PairKey(hero, o)))).Count(e => e != null) == pasts.Count, true);
         }
         finally
         {
            foreach (Hero o in others) past.DebugForget(hero, o);
         }

         return t.Line();
      }

      private sealed class SelfTestPairRegardSource : IPairRegardSource
      {
         public string SpeakerId, OtherId;
         public int Weight;

         public IEnumerable<Logic.PairRegardTrace> TracesFor(Hero speaker, Hero other, int today)
         {
            if (speaker?.StringId == SpeakerId && other?.StringId == OtherId)
               yield return new Logic.PairRegardTrace {Weight = Weight, Line = "[SELFTEST] years of battles side by side", PageLine = "[SELFTEST] years of battles side by side", KnownToPlayer = true};
         }
      }

      private static string TestLetterFromAnotherMod(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("letter_from_another_mod");
         var store = behavior?.Store;
         if (t.Skip(store == null, "no profile store")) return t.Line();

         // A lord CR already knows, so nothing is created for the test; free to write.
         Hero sender = store.ListIds().Select(id => Hero.FindFirst(h => h.StringId == id))
                            .FirstOrDefault(h => h != null && h.IsLord && h != Hero.MainHero && Mapping.ActionGate.Allows(h, Logic.ActionKind.Letter));
         if (t.Skip(sender == null, "no lord with a profile is free to write")) return t.Line();
         t.Note(sender.Name.ToString());

         const string body = "[SELFTEST] You are invited to the tournament in my town. Come if you can.";
         PendingLetter sent = null;
         try
         {
            t.Expect("theLetterIsAccepted", CrLetters.Deliver(sender, body, "selftest"), true);
            sent = store.Get(sender.StringId)?.SentLetters.LastOrDefault(l => l.Content == body);
            // STAKE: it rides like CR's own letters: a courier out today, its body as given, never regenerated.
            t.Expect("itWaitsForItsCourier", sent != null && !sent.IsDelivered && sent.DispatchDay == (int) CampaignTime.Now.ToDays && sent.Reason == LetterReason.FromAnotherMod, true);
            t.Expect("thePlayerCannotSendOne", CrLetters.Deliver(Hero.MainHero, body, "selftest"), false);
            t.Expect("noBodyNoLetter", CrLetters.Deliver(sender, "  ", "selftest"), false);

            // The id, the status and the two notices (2.7.19), through the letter window's own notices.
            string id = CrLetters.DeliverWithId(sender, body + " (id)", "selftest");
            PendingLetter withId = store.Get(sender.StringId)?.SentLetters.LastOrDefault(l => l.Id == id);
            t.Expect("anIdIsGiven", !string.IsNullOrEmpty(id) && withId != null, true);
            t.Expect("stillOnTheRoad", CrLetters.GetStatus(id), "on_the_road");
            t.Expect("anUnknownIdIsUnknown", CrLetters.GetStatus("no-such-letter"), "unknown");
            if (withId != null)
            {
               int setAside = 0;
               string repliedId = null, repliedText = null;
               Hero repliedSender = null;
               void OnSetAside(string letterId, Hero from) { if (letterId == id) setAside++; }
               void OnReplied(string letterId, Hero from, string text) { if (letterId == id) (repliedId, repliedSender, repliedText) = (letterId, from, text); }
               CrLetters.SetAside += OnSetAside;
               CrLetters.Replied += OnReplied;
               try
               {
                  withId.IsDelivered = true;
                  t.Expect("delivered", CrLetters.GetStatus(id), "delivered");
                  Letters.ModLetterNotices.OnSetAside(withId);
                  Letters.ModLetterNotices.OnSetAside(withId);
                  t.Expect("setAsideIsRaisedOnce", setAside, 1);
                  t.Expect("setAside", CrLetters.GetStatus(id), "set_aside");
                  withId.PlayerReply = "[SELFTEST] I will come.";
                  Letters.ModLetterNotices.OnReplied(withId);
                  t.Expect("theReplyIsRaisedWithItsIdAndSender", repliedId == id && repliedSender == sender, true);
                  t.Expect("theReplyCarriesItsText", repliedText, "[SELFTEST] I will come.");
                  t.Expect("answered", CrLetters.GetStatus(id), "answered");
                  t.Expect("getReplyReadsIt", CrLetters.GetReply(id), "[SELFTEST] I will come.");
               }
               finally
               {
                  CrLetters.SetAside -= OnSetAside;
                  CrLetters.Replied -= OnReplied;
               }
            }
         }
         finally
         {
            NpcProfile p = store.Get(sender.StringId);
            if (p != null && p.SentLetters.RemoveAll(l => l.Content == body || l.Content == body + " (id)") > 0) store.Set(p);
         }

         return t.Line();
      }

      private static string TestPairRegardSource(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("pair_regard_source");

         // Two lords of different houses with nothing between them here: the test's source alone must decide them.
         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && h != Hero.MainHero && h.Clan != null && !h.IsChild).Take(200).ToList();
         (Hero a, Hero b) = lords.SelectMany(x => lords.Where(y => y.Clan != x.Clan).Take(10).Select(y => (x, y)))
                                 .FirstOrDefault(p => PairRegardReader.Assess(p.x, p.y) is {Verdict: Logic.PairRegardVerdict.Neither, Points: 0}
                                                      && PairRegardReader.Assess(p.y, p.x) is {Verdict: Logic.PairRegardVerdict.Neither});
         if (t.Skip(a == null, "no two lords of different houses with nothing between them")) return t.Line();
         t.Note($"{a.Name} and {b.Name}");

         var source = new SelfTestPairRegardSource {SpeakerId = a.StringId, OtherId = b.StringId, Weight = 30};
         CrPairRegard.RegisterPairRegardSource(source);
         try
         {
            Logic.PairRegard r = PairRegardReader.Assess(a, b);
            t.Expect("anotherModsReasonMakesThemFriends", r.Verdict, Logic.PairRegardVerdict.Friend);
            t.Expect("andThePageGivesItsReason", Logic.PairRegardPolicy.PageReason(r) ?? "", "[SELFTEST] years of battles side by side");
            t.Expect("theOtherWayRoundIsUntouched", PairRegardReader.Assess(b, a).Verdict, Logic.PairRegardVerdict.Neither);

            source.Weight = 500;
            t.Expect("howeverMuchItClaimsItCountsAtMostTheCap", PairRegardReader.Assess(a, b).Points, Logic.PairRegardPolicy.OutsideCap);
         }
         finally
         {
            CrPairRegard.UnregisterPairRegardSource(source);
         }

         t.Expect("unregisteredItIsGone", PairRegardReader.Assess(a, b).Verdict, Logic.PairRegardVerdict.Neither);

         // The function form (tashmetu, 20/10/2026), for a mod that keeps CR optional: the same weighing, no CR type named.
         const string fnId = "cr.test all.pair_regard";
         CrPairRegard.RegisterPairRegardSource(fnId, (speaker, other, today) => speaker == a && other == b
            ? new[] {(30, "[SELFTEST] you rode together", "[SELFTEST] rode together", true)}
            : Array.Empty<(int, string, string, bool)>());
         try
         {
            Logic.PairRegard r = PairRegardReader.Assess(a, b);
            t.Expect("aFunctionSourceMakesThemFriends", r.Verdict, Logic.PairRegardVerdict.Friend);
            t.Expect("andThePageGivesItsLine", Logic.PairRegardPolicy.PageReason(r) ?? "", "[SELFTEST] rode together");
         }
         finally
         {
            CrPairRegard.UnregisterPairRegardSource(fnId);
         }

         t.Expect("theFunctionSourceUnregisteredIsGone", PairRegardReader.Assess(a, b).Verdict, Logic.PairRegardVerdict.Neither);

         return t.Line();
      }

      private static string TestNpcRegardReason(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("npc_regard_reason");

         AuthoredHistoryBehavior history = AuthoredHistoryBehavior.Instance;
         if (t.Abort(history == null || WorldEventStore.Instance == null, "authored history or the world-event store is not active")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && h.IsLord && h.Clan != null && h.MapFaction != null && !h.MapFaction.IsBanditFaction
                                                          && h.BirthDay.GetYear < Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.GetYear - 20).ToList();
         // Two house heads, so the houses check reads the same pair a house list does (lord to lord).
         Hero wronged = lords.FirstOrDefault(h => h.Clan.Leader == h);
         Hero betrayer = lords.FirstOrDefault(h => wronged != null && h.Clan.Leader == h && h.MapFaction != wronged.MapFaction && h.Clan != wronged.Clan);
         Hero stranger = lords.FirstOrDefault(h => wronged != null && betrayer != null && h.Clan != wronged.Clan && h.Clan != betrayer.Clan
                                                   && h.MapFaction != wronged.MapFaction && h.MapFaction != betrayer.MapFaction);
         if (t.Skip(wronged == null || betrayer == null || stranger == null, "no two house heads and a third lord of three houses and realms")) return t.Line();

         string authorText = null;
         try { if (System.IO.File.Exists(AuthoredHistoryBehavior.HistoryPath)) authorText = System.IO.File.ReadAllText(AuthoredHistoryBehavior.HistoryPath); }
         catch (Exception ex) { t.Note("the author's file could not be read: " + ex.Message); }

         var doc = Logic.AuthoredHistory.AuthoredHistoryLoader.Parse(authorText, new List<string>()) ?? new Logic.AuthoredHistory.AuthoredHistoryDocument();
         string id = "selftest_" + Guid.NewGuid().ToString("N");
         doc.Events.Add(new Logic.AuthoredHistory.AuthoredHistoryEvent {
            Id = id, Year = Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.GetYear - 3, Season = "spring", Kind = "betrayal",
            Summary = "[SELFTEST] " + betrayer.Name + " betrayed " + wronged.Name + " at the ford.", Actors = new List<string> {betrayer.StringId},
            Harmed = new List<string> {wronged.StringId}, Importance = 100
         });

         try
         {
            t.Note("sync: " + history.SyncFrom(Newtonsoft.Json.JsonConvert.SerializeObject(doc)));

            string asked = "What do you think of " + betrayer.Name + "?";
            string block = ContextualNameResolver.Resolve(wronged, asked) ?? "";
            string line = block.Split((char) 10).FirstOrDefault(l => l.Contains("[SELFTEST]")) ?? "";
            t.Note("line: " + line);
            t.Expect("theWrongedLordCallsHimAnEnemyAndSaysWhy", line.Contains("an enemy, for what lies between you"), true);
            t.Expect("theReasonSaysHowLongAgo", line.Contains("years ago"), true);
            t.Expect("aStrangerIsToldNothingOfIt", (ContextualNameResolver.Resolve(stranger, asked) ?? "").Contains("[SELFTEST]"), false);

            // The houses (design 5.4): the betrayer's house is at odds with the wronged lord's, with the betrayal as reason.
            PairRegard house = PairRegardReader.Assess(wronged, betrayer);
            var houses = Logic.ClanRegardListPolicy.Lists(new[] {
               new Logic.ClanRegardCandidate {Name = betrayer.Clan.Name.ToString(), Derived = house.Verdict, DerivedReason = PairRegardPolicy.PageReason(house),
                  VanillaRelation = Mapping.PairBondReader.Points(wronged, betrayer)}
            });
            t.Expect("theBetrayersHouseIsAtOdds", houses.AtOdds.Any(l => l.Contains(betrayer.Clan.Name.ToString()) && l.Contains("[SELFTEST]")), true);

            // The encyclopedia (design section 8, route b): the wronged lord's page lists the betrayer among his
            // enemies, after the page is built and after it refreshes again (the mixin must run after vanilla's fill).
            TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.Pages.EncyclopediaHeroPageVM page = null;
            try
            {
               page = new TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.Pages.EncyclopediaHeroPageVM(
                  new TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.Pages.EncyclopediaPageArgs(wronged));
               bool Lists(TaleWorlds.Library.MBBindingList<TaleWorlds.CampaignSystem.ViewModelCollection.HeroVM> a,
                          TaleWorlds.Library.MBBindingList<TaleWorlds.CampaignSystem.ViewModelCollection.HeroVM> b) => a.Concat(b).Any(h => h.Hero == betrayer);
               t.Expect("hisPageListsTheBetrayerAsAnEnemy", Lists(page.Enemies, page.AdditionalEnemies), true);
               t.Expect("notAsAFriend", Lists(page.Allies, page.AdditionalAllies), false);
               page.RefreshValues();
               t.Expect("stillAfterTheVanillaRefresh", Lists(page.Enemies, page.AdditionalEnemies), true);

               // Gabriel (22/10/2026): the reasons and the houses are rows, a portrait or banners, a red or pale green marker.
               var people = RegardPeopleOf?.Invoke(page);
               var houseRows = RegardHouseRowsOf?.Invoke(page);
               if (people == null || houseRows == null) t.Note("no regard rows on this page (UIExtenderEx not attached here)");
               else
               {
                  var row = people.FirstOrDefault(r => r.Person == betrayer);
                  t.Expect("theBetrayerHasARowWithHisPortrait", row.Person != null, true);
                  t.Expect("markedAsAnEnemy", row.IsFriend, false);
                  t.Expect("itsReasonIsTheBetrayal", row.Reason?.Contains("[SELFTEST]") == true, true);
                  var houseRow = houseRows.FirstOrDefault(r => r.Houses.Any(h => h.Faction == betrayer.Clan));
                  t.Expect("hisHouseHasItsBannerInARedRow", houseRow.Houses != null && !houseRow.IsFriend, true);
                  t.Expect("namedThroughHim", houseRow.Houses?.FirstOrDefault(h => h.Faction == betrayer.Clan).Note?.Contains("through") == true, true);
               }
               string vanillaRelation = TaleWorlds.Core.GameTexts.FindText("str_enc_sf_relation")?.ToString();
               if (page.Stats.Any(s => s.Definition == "Clan Relation" || s.Definition == vanillaRelation))
                  t.Expect("theClanRelationLabelSurvivesTheRefresh", page.Stats.Any(s => s.Definition == "Clan Relation"), true);
            }
            catch (Exception ex) { t.Note("the encyclopedia page could not be built here: " + ex.GetType().Name + ": " + ex.Message); }
            finally { try { page?.OnFinalize(); } catch { /* the page held nothing of the game's */ } }
         }
         finally
         {
            history.SyncFrom(authorText);
         }

         t.Expect("theTestEventIsGoneAfter", WorldEventStore.Instance.GetHistoryById("authored:" + id) == null, true);

         return t.Line();
      }

      private static string TestCompanionNewsFresh(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("companion_news_fresh");

         WorldEventStore store = WorldEventStore.Instance;
         if (t.Abort(store == null, "the world-event store is not active")) return t.Line();

         Settlement place = Settlement.All.FirstOrDefault(s => s != null && s.IsCastle);
         List<Kingdom> others = Kingdom.All.Where(k => k != null && !k.IsEliminated && k != Hero.MainHero?.MapFaction).Take(2).ToList();
         if (t.Skip(place == null || others.Count < 2, "no castle, or fewer than two realms other than the player's")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         string suffix = Guid.NewGuid().ToString("N");
         string mine = Hero.MainHero?.MapFaction?.StringId ?? Clan.PlayerClan?.StringId;
         var siege = new WorldEvent {Id = "selftest_news_siege_" + suffix, Type = WorldEventType.Battle, IsSiege = true, PlaceId = place.StringId, Day = today - 2, Magnitude = 60, Summary = "[SELFTEST] a siege fight."};
         var fell = new WorldEvent {Id = "selftest_news_fell_" + suffix, Type = WorldEventType.SettlementCaptured, PlaceId = place.StringId, Day = today - 1, Magnitude = 60, Summary = "[SELFTEST] the castle fell."};
         var ownWar = new WorldEvent {Id = "selftest_news_war_" + suffix, Type = WorldEventType.WarDeclared, Day = today, Magnitude = 75, Summary = "[SELFTEST] war.",
            FactionIds = new List<string> {mine, others[0].StringId}};
         var old = new WorldEvent {Id = "selftest_news_old_" + suffix, Type = WorldEventType.Other, Day = today - 10, Magnitude = 70, Summary = "[SELFTEST] old news."};
         var fresh = new WorldEvent {Id = "selftest_news_fresh_" + suffix, Type = WorldEventType.Other, Day = today, Magnitude = 70, Summary = "[SELFTEST] fresh news.",
            FactionIds = new List<string> {others[0].StringId, others[1].StringId}};

         try
         {
            store.Record(siege);
            store.Record(fell);

            string Why(WorldEvent e) => CalradiaRemembers.Logic.Companions.CompanionRumourFreshnessPolicy.WhyNotNews(CompanionAudienceTopicResolver.FreshnessFacts(e, today));

            t.Expect("aSiegeFightOvertakenByTheFall", Why(siege) != null, true);
            t.Expect("thePlayersOwnWarIsNoNews", mine != null && Why(ownWar) != null, true);
            t.Expect("tenDayOldNewsIsTooOld", Why(old) != null, true);
            t.Expect("freshNewsOfOtherRealmsMayCome", Why(fresh), null);
         }
         finally
         {
            store.Remove(siege.Id);
            store.Remove(fell.Id);
         }

         return t.Line();
      }

