                                                          && h.BirthDay.GetYear < Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.GetYear - 20).ToList();
         Hero a = lords.FirstOrDefault();
         Hero b = lords.FirstOrDefault(h => a != null && h.MapFaction != a.MapFaction && h.Clan != a.Clan);
         Hero stranger = lords.FirstOrDefault(h => a != null && b != null && h.Clan != a.Clan && h.Clan != b.Clan && h.MapFaction != a.MapFaction
                                                   && h.MapFaction != b.MapFaction && !IsKinOf(h, a) && !IsKinOf(h, b));

         if (t.Skip(a == null || b == null || stranger == null, "no three adult lords of three houses and realms")) return t.Line();

         // The author's own file is read but never written: the test event rides on a copy of its text.
         string authorText = null;
         try { if (System.IO.File.Exists(AuthoredHistoryBehavior.HistoryPath)) authorText = System.IO.File.ReadAllText(AuthoredHistoryBehavior.HistoryPath); }
         catch (Exception ex) { t.Note("the author's file could not be read: " + ex.Message); }

         var problems = new List<string>();
         var doc = Logic.AuthoredHistory.AuthoredHistoryLoader.Parse(authorText, problems) ?? new Logic.AuthoredHistory.AuthoredHistoryDocument();
         int startYear = Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.GetYear;
         string id = "selftest_" + Guid.NewGuid().ToString("N");
         doc.Events.Add(new Logic.AuthoredHistory.AuthoredHistoryEvent {
            Id = id, Year = startYear - 10, Season = "spring", Kind = "betrayal", Summary = "[SELFTEST] " + a.Name + " betrayed " + b.Name + ".",
            Actors = new List<string> {a.StringId}, Harmed = new List<string> {b.StringId}, Importance = 30,
            Relations = new List<Logic.AuthoredHistory.AuthoredRelation> {new() {A = a.StringId, B = b.StringId, Change = -15}}
         });
         doc.Events.Add(new Logic.AuthoredHistory.AuthoredHistoryEvent {
            Id = id + "_late", Year = startYear + 1, Kind = "feud", Summary = "[SELFTEST] too late.", Actors = new List<string> {a.StringId}
         });

         int before = CharacterRelationManager.GetHeroRelation(a, b);
         bool clamped = before - 15 < -100;

         try
         {
            string report = history.SyncFrom(Newtonsoft.Json.JsonConvert.SerializeObject(doc));
            t.Note("sync: " + report);

            WorldEvent kept = store.GetHistoryById("authored:" + id);
            t.Expect("theEventIsInTheLongTermMemory", kept != null && kept.IsAuthored, true);
            t.Expect("theLateEventIsSetAside", store.GetHistoryById("authored:" + id + "_late") == null, true);
            if (t.Abort(kept == null, "the authored event never reached the long-term memory")) return t.Line();

            t.Expect("theBetrayerKnowsIt", WorldEventStore.WouldKnow(a, kept), true);
            t.Expect("aStrangerFarAwayDoesNot", WorldEventStore.WouldKnow(stranger, kept), false);
            if (!clamped) t.Expect("theRelationMovedByTheChange", CharacterRelationManager.GetHeroRelation(a, b) - before, -15);

            history.SyncFrom(Newtonsoft.Json.JsonConvert.SerializeObject(doc));
            if (!clamped) t.Expect("aSecondLoadDoesNotStack", CharacterRelationManager.GetHeroRelation(a, b) - before, -15);
         }
         finally
         {
            // The author's file alone: the test event leaves and the ledger takes back its relation.
            history.SyncFrom(authorText);
         }

         t.Expect("theTestEventIsGoneAfter", store.GetHistoryById("authored:" + id) == null, true);
         t.Expect("theRelationIsRestored", CharacterRelationManager.GetHeroRelation(a, b), before);

         return t.Line();
      }

      private static string TestWorldLongTermMemory(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("world_long_term_memory");

         WorldEventStore store = WorldEventStore.Instance;

         if (t.Abort(store == null, "WorldEventStore not active")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;

         if (t.Skip(today - 50 <= 0, "the campaign is younger than 50 days, so nothing can be dated 50 days ago")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && h.Clan != null && h.MapFaction != null
                                                           && !h.MapFaction.IsBanditFaction);

         if (t.Skip(lord == null, "no lord with a house and a realm")) return t.Line();

         var kin = new HashSet<Hero> {lord.Father, lord.Mother, lord.Spouse};
         foreach (Hero c in lord.Children) kin.Add(c);
         foreach (Hero s in lord.Siblings) kin.Add(s);
         Hero stranger = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != lord && h.IsLord && h.Clan != null && h.Clan != lord.Clan
                                                               && h.MapFaction != null && h.MapFaction != lord.MapFaction && !kin.Contains(h));

         if (t.Skip(stranger == null, "no lord of another realm and house who is not his kin")) return t.Line();

         string suffix = Guid.NewGuid().ToString("N");
         string battleId = "selftest_history_battle_" + suffix;
         string skirmishId = "selftest_history_skirmish_" + suffix;
         string risingId = "selftest_history_rising_" + suffix;
         string divorceId = "selftest_history_divorce_" + suffix;
         string fellId = "selftest_history_fell_" + suffix;

         try
         {
            // Magnitude 35, under the realm-wide line: only the ties of the event can reach a lord, never his realm alone.
            store.Record(new WorldEvent {
               Id = battleId, Type = WorldEventType.Battle, Day = today - 50, Magnitude = 35, MenAtStart = 400,
               Summary = "[SELFTEST] " + lord.Name + " fought a battle of several hundred men.",
               ActorIds = new List<string> {lord.StringId}, FactionIds = new List<string> {lord.MapFaction.StringId}
            });
            store.Record(new WorldEvent {
               Id = skirmishId, Type = WorldEventType.Battle, Day = today - 50, Magnitude = 25, MenAtStart = 40,
               Summary = "[SELFTEST] " + lord.Name + " chased off a few dozen men.",
               ActorIds = new List<string> {lord.StringId}, FactionIds = new List<string> {lord.MapFaction.StringId}
            });

            WorldEvent kept = store.GetHistoryById(battleId);
            t.Expect("theBattleIsInTheLongTermMemory", kept != null, true);
            t.Expect("theBattleIsNoLongerNews", store.GetById(battleId) == null, true);
            t.Expect("theSkirmishIsForgotten", store.GetById(skirmishId) == null && store.GetHistoryById(skirmishId) == null, true);

            if (t.Abort(kept == null, "the battle never reached the long-term memory")) return t.Line();

            t.Expect("heIsNotToldItAsNews", store.GetKnownEvents(lord, today, 1000).Any(e => e.Id == battleId), false);
            t.Expect("aCompanionSentForNewsDoesNotBringItBack", store.GetRecentSignificant(today, 1000, 0).Any(e => e.Id == battleId), false);
            t.Expect("heRemembersHisOwnBattle", WorldEventStore.WouldKnow(lord, kept), true);
            t.Expect("aStrangerFarAwayDoesNot", WorldEventStore.WouldKnow(stranger, kept), false);
            t.Expect("theReadDoorFindsItForHim", store.GetHistory(new HistoryQuery {Involving = lord, KnownTo = lord}).Any(e => e.Id == battleId), true);
            t.Expect("theReadDoorKeepsItFromTheStranger", store.GetHistory(new HistoryQuery {Involving = lord, KnownTo = stranger}).Any(e => e.Id == battleId), false);

            // A namesake may resolve first, so the command is asked without a name. It lists the newest first, up to its
            // page: the assertion holds only when the page reaches back 50 days.
            string report = ModCheats.History(new List<string>());
            t.Note("cr.history: " + Preview(report));
            if (store.AllHistory().Count(e => e.Day >= today - 50) <= ModCheats.HistoryPageSize)
               t.Expect("cr.historyListsIt", report != null && report.Contains(battleId), true);
            else
               t.Note("cr.history's page is filled by newer history, so its listing is not asserted");

            // The secret reaches the long-term tier: the command finds the aged event, and only those it names keep it.
            Hero clanmate = lord.Clan.Heroes.FirstOrDefault(h => h != lord && h != Hero.MainHero && h.IsAlive);
            string secretReply = ModCheats.SecretWorldEvent(new List<string> {battleId});
            t.Note("cr.world_event_secret: " + Preview(secretReply));
            t.Expect("theAgedBattleIsNowASecret", kept.KnownOnlyToThoseInvolved, true);
            t.Expect("heStillKnowsHisSecret", WorldEventStore.WouldKnow(lord, kept), true);
            if (clanmate != null)
               t.Expect("aClanmateNoLongerKnowsIt", WorldEventStore.WouldKnow(clanmate, kept), false);
            else
               t.Note("his house has no other living member, so the clanmate is not asserted");
            if (store.AllHistory().Count(e => e.Day >= today - 50) <= ModCheats.HistoryPageSize)
               t.Expect("cr.historyMarksItSecret", (ModCheats.History(new List<string>()) ?? "").Split((char) 10).Any(l => l.Contains(battleId) && l.Contains("SECRET")), true);

            // Gabriel's answer 2 (17/10/2026): risings, divorces and lords fallen in battle are history too.
            store.Record(new WorldEvent {
               Id = risingId, Type = WorldEventType.Rebellion, Day = today - 50, Magnitude = 50,
               Summary = "[SELFTEST] " + lord.Clan.Name + " rose against its realm.", ActorIds = new List<string> {lord.StringId},
               FactionIds = new List<string> {lord.MapFaction.StringId}
            });
            store.Record(new WorldEvent {
               Id = divorceId, Type = WorldEventType.Divorce, Day = today - 50, Magnitude = 30,
               Summary = "[SELFTEST] " + lord.Name + " is no longer wed.", ActorIds = new List<string> {lord.StringId}
            });
            store.Record(new WorldEvent {
               Id = fellId, Type = WorldEventType.Other, Status = LongTermHistoryPolicy.FellInBattleStatus, Day = today - 50,
               Magnitude = LongTermHistoryPolicy.FellInBattleMagnitude, Summary = "[SELFTEST] " + lord.Name + " fell in battle.",
               ActorIds = new List<string> {lord.StringId}, FactionIds = new List<string> {lord.MapFaction.StringId}
            });
            t.Expect("aRisingIsHistory", store.GetHistoryById(risingId) != null, true);
            t.Expect("aDivorceIsHistory", store.GetHistoryById(divorceId) != null, true);
            t.Expect("aLordFallenInBattleIsHistory", store.GetHistoryById(fellId) != null, true);
         }
         finally
         {
            store.Remove(battleId);
            store.Remove(skirmishId);
            store.Remove(risingId);
            store.Remove(divorceId);
            store.Remove(fellId);
         }

         return t.Line();
      }

      private static string TestFeedPlayerNamed(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("feed_player_named");

         WorldEventStore store = WorldEventStore.Instance;

         if (t.Abort(store == null, "WorldEventStore not active")) return t.Line();
         if (t.Skip(Hero.MainHero == null, "no player hero")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.MapFaction != null);

         if (t.Skip(lord == null, "no free lord with a realm")) return t.Line();

         const string source = "SelfTestPlayerNamed";
         string suffix = Guid.NewGuid().ToString("N");
         string namedId = "selftest_named_" + suffix;
         string actedId = "selftest_acted_" + suffix;
         var today = (int) CampaignTime.Now.ToDays;

         try
         {
            // The Bellum shape: a siege of a town the PLAYER owns, the owner named among the heroes.
            Feed.Record(new ExternalWorldEvent {
               Id = namedId, SourceMod = source, Summary = "[SELFTEST] a town held by the player is under siege", Magnitude = 85,
               HeroIds = new List<string> {Hero.MainHero.StringId, lord.StringId},
               FactionIds = new List<string> {lord.MapFaction.StringId}
            });
            WorldEvent named = store.GetById(namedId);

            if (t.Abort(named == null, "the named event was not recorded")) return t.Line();

            t.Expect("namingThePlayerDoesNotMakeItTheirDeed", named.InvolvesPlayer, false);
            t.Expect("itStaysOutOfTheirChronicle", store.GetPlayerChronicle().Any(e => e.Id == namedId), false);
            t.Expect("aLordOfTheRealmHearsItAsNews", store.GetKnownEvents(lord, today, 1000).Any(e => e.Id == namedId), true);

            // The other half: the bridge says the player DID it.
            Feed.Record(new ExternalWorldEvent {
               Id = actedId, SourceMod = source, Summary = "[SELFTEST] the player had a lord executed", Magnitude = 85,
               HeroIds = new List<string> {lord.StringId}, ActorHeroIds = new List<string> {Hero.MainHero.StringId}
            });
            WorldEvent acted = store.GetById(actedId);

            if (t.Abort(acted == null, "the acted event was not recorded")) return t.Line();

            t.Expect("thePlayerAsActorMakesItTheirDeed", acted.InvolvesPlayer, true);
            t.Expect("anActorCountsAsConcernedToo", acted.ActorIds.Contains(Hero.MainHero.StringId), true);
            t.Expect("itEntersTheirChronicle", store.GetPlayerChronicle().Any(e => e.Id == actedId), true);
         }
         finally
         {
            Feed.Retract(namedId);
            Feed.Retract(actedId);
         }

         return t.Line();
      }

      /// <summary>
      ///   Heroes Voices (TTS addon) request: drives the REAL internal CrConversation raisers directly (this
      ///   file lives in the same assembly, so it may call them) rather than the engine chat path, so the test
      ///   runs with no campaign, no LLM, and nothing to clean up. Asserts the whole point of the sequencer:
      ///   one session's Started/LineSpoken/Ended share a SessionId and LineIndex counts up from 0, and a
      ///   fresh session never reuses either.
      /// </summary>
      private static string TestConversationSessionSequencing(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("conversation_session_sequencing");

         string startedSessionId = null;
         string endedSessionId = null;
         var lineSessionIds = new List<string>();
         var lineIndices = new List<int>();

         void OnStarted(CrConversationInfo info) => startedSessionId = info.SessionId;
         void OnLineSpoken(CrSpeechLine line)
         {
            lineSessionIds.Add(line.SessionId);
            lineIndices.Add(line.LineIndex);
         }
         void OnEnded(CrConversationLog log) => endedSessionId = log.SessionId;

         CrConversation.Started += OnStarted;
         CrConversation.LineSpoken += OnLineSpoken;
         CrConversation.Ended += OnEnded;

         try
         {
            CrConversation.RaiseStarted("selftest_npc", 1);
            CrConversation.RaiseLineSpoken(new CrSpeechLine(null, "selftest_npc", "Selftest NPC", false, false, false, false, null, "[SELFTEST] first line"));
            CrConversation.RaiseLineSpoken(new CrSpeechLine(null, "selftest_npc", "Selftest NPC", false, false, false, false, null, "[SELFTEST] second line"));
            CrConversation.RaiseEnded("selftest_npc", 1, new List<CrTranscriptLine>());

            string firstSessionId = startedSessionId;

            t.Expect("startedSessionIdNotEmpty", string.IsNullOrEmpty(startedSessionId), false);
            t.Expect("lineCount", lineSessionIds.Count, 2);
            t.Expect("line1SharesSession", lineSessionIds.Count > 0 && lineSessionIds[0] == firstSessionId, true);
            t.Expect("line2SharesSession", lineSessionIds.Count > 1 && lineSessionIds[1] == firstSessionId, true);
            t.Expect("endedSharesSession", endedSessionId, firstSessionId);
            t.Expect("lineIndex0", lineIndices.Count > 0 ? lineIndices[0] : -1, 0);
            t.Expect("lineIndex1", lineIndices.Count > 1 ? lineIndices[1] : -1, 1);

            // A second conversation must get a fresh id and its own count from 0, or two exchanges could
            // collide on the same (SessionId, LineIndex) pair.
            CrConversation.RaiseStarted("selftest_npc", 2);
            string secondSessionId = startedSessionId;
            CrConversation.RaiseLineSpoken(new CrSpeechLine(null, "selftest_npc", "Selftest NPC", false, false, false, false, null, "[SELFTEST] second session first line"));

            t.Expect("secondSessionDiffers", secondSessionId != firstSessionId, true);
            t.Expect("secondSessionLineIndexReset", lineIndices.Count > 2 ? lineIndices[2] : -1, 0);
            t.Note($"session1={firstSessionId}, session2={secondSessionId}");
         }
         finally
         {
            CrConversation.Started -= OnStarted;
            CrConversation.LineSpoken -= OnLineSpoken;
            CrConversation.Ended -= OnEnded;
         }

         return t.Line();
      }

      private static string TestFreePrisoner(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("free_prisoner");

         // Mirror prisoner_trade's pick (testall 2026-07-23 A/B evidence: within the same second,
         // TakePrisonerAction succeeded on an in-party lord and failed on Arcor picked without this filter,
         // and on every partyless minted nemesis hero). A lord OFF the map (no party, at court, a governor)
         // is not reliably capturable by the raw action on the current game build, and capturing one is not
         // what this test exists to prove anyway.
         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h);

         if (t.Skip(captive == null, "no free in-party lord to capture")) return t.Line();

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);
         bool captured = captive.IsPrisoner && captive.PartyBelongedToAsPrisoner?.LeaderHero == Hero.MainHero;

         if (t.Abort(!captured, $"capture failed for {captive.Name} (party={captive.PartyBelongedTo?.StringId ?? "none"})")) return t.Line();

         behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "free_prisoner"}, captive, null);

         t.Note($"{captive.Name}");
         t.Expect("freed", !captive.IsPrisoner, true);

         return t.Line();
      }

      /// <summary>
      ///   v2.5.3 player report (2026-09-07): "npc gave me a quest to rescue a clan member from a prison. i
      ///   got the person out of prison but then a couple days later i get 'so and so is lost, they are no
      ///   longer on the map' and the quest is failed." His success cancelled his quest: freeing someone from
      ///   a dungeon raises no battle, so QuestDeedTracker never credited the rescue, and the daily void sweep
      ///   then read the freed target as proof the task was impossible. Drives the REAL free_prisoner bridge
      ///   action (the same action ExecuteFreePrisoner/free_prisoner tests above use, standing in for "got the
      ///   person out of prison") on a real captured lord bound to a real outstanding RescuePrisoner quest, so
      ///   the REAL CampaignEvents.HeroPrisonerReleased dispatch reaches QuestDeedTracker.OnHeroPrisonerReleased
      ///   with no Debug seam involved. THE LOAD-BEARING ASSERTION: after the release, the quest is SATISFIED
      ///   (awaiting reward), and running the REAL daily maintenance sweep afterward must not undo that by
      ///   cancelling it, which is exactly what the reporter saw.
      /// </summary>
      private static string TestRescueCreditedOnRelease(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("quest_rescue_release_credit");

         if (t.Abort(Hero.MainHero == null, "no player hero")) return t.Line();

         // Same in-party-lord filter TestFreePrisoner/TestCaptiveKinAwareness use (off-map lords are not
         // reliably capturable by the raw action on this build); the choice of WHICH lord must not matter to
         // the outcome, so the predicate names only what is required, never a specific hero.
         Hero target = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h);

         if (t.Skip(target == null, "no capturable in-party lord to stand as the rescue target")) return t.Line();

         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != target && h.IsLord && !h.IsPrisoner);

         if (t.Skip(giver == null, "no other live lord to stand as the quest giver")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         const string marker = "[SELFTEST] free my kinsman from captivity.";

         try
         {
            TakePrisonerAction.Apply(PartyBase.MainParty, target);
            bool captured = target.IsPrisoner && target.PartyBelongedToAsPrisoner?.LeaderHero == Hero.MainHero;

            if (t.Abort(!captured, $"capture failed for {target.Name} (party={target.PartyBelongedTo?.StringId ?? "none"})")) return t.Line();

            NpcProfile profile = GetOrCreate(behavior, giver);
            var quest = new InformalQuest {
               Type = QuestType.RescuePrisoner,
               Description = marker,
               TargetHeroId = target.StringId,
               TargetHeroName = target.Name?.ToString(),
               IssuedOnDay = today,
               Status = QuestStatus.Active
            };
            profile.ActiveQuests.Add(quest);
            QuestJournalBridge.OpenMirror(quest, giver);
            behavior.Store.Set(profile);

            // THE PLAYER'S OWN DEED: free them through the real bridge action, not a battle, so the credit
            // must come from QuestDeedTracker's new HeroPrisonerReleased hook, not the pre-existing battle path.
            behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "free_prisoner"}, target, null);

            InformalQuest afterRelease = behavior.Store.Get(giver.StringId)?.ActiveQuests
                                                  .FirstOrDefault(q => q.Description == marker);

            t.Expect("targetFreedByRealAction", !target.IsPrisoner, true);
            t.Expect("stillActiveNotCancelledAfterRelease", afterRelease?.Status, QuestStatus.Active);
            t.Expect("awaitingRewardAfterRelease", afterRelease?.IsAwaitingReward, true);

            // THE LOAD-BEARING ASSERTION: the daily safety-net sweep, run for real, must not undo the credit
            // the release just earned. Before this fix, this exact call is what cancelled the reporter's quest.
            QuestService.RunDailyMaintenance(behavior.Store, today);

            InformalQuest afterSweep = behavior.Store.Get(giver.StringId)?.ActiveQuests
                                               .FirstOrDefault(q => q.Description == marker);

            t.Note($"{giver.Name} -> free {target.Name}: afterRelease.status={afterRelease?.Status}, evidence={afterRelease?.Evidence}, afterSweep.status={afterSweep?.Status}");
            t.Expect("survivesDailySweepSatisfiedNotCancelled", afterSweep?.Status, QuestStatus.Active);
            t.Expect("stillAwaitingRewardAfterSweep", afterSweep?.IsAwaitingReward, true);
         }
         finally
         {
            try
            {
               NpcProfile clean = behavior.Store.Get(giver.StringId);
               InformalQuest leftover = clean?.ActiveQuests.FirstOrDefault(q => q.Description == marker);

               if (leftover != null)
               {
                  QuestJournalBridge.CloseAsCancelled(leftover, giver, "[SELFTEST] cleanup.");
                  clean.ActiveQuests.Remove(leftover);
                  behavior.Store.Set(clean);
               }
            }
            catch (Exception ex) { ModLog.Error($"[SELFTEST] quest_rescue_release_credit quest cleanup failed: {ex.Message}"); }

            try { if (target.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(target); }
            catch (Exception ex) { ModLog.Error($"[SELFTEST] quest_rescue_release_credit release cleanup failed: {ex.Message}"); }
         }

         return t.Line();
      }

      /// <summary>
      ///   A player report (09/08/2026): the player held enemy lords prisoner, then met their parent, who
      ///   called the player a liar ("my child is safe within our walls") because the RELATIONSHIPS block named
      ///   the captured child with no captivity marker. Captures a real in-party lord who has a living parent,
      ///   rebuilds that parent's block, and asserts the captured child now reads as held by the player.
      ///   Releases the captive in cleanup so the sweep leaves no one caged.
      /// </summary>
      /// <summary>
      ///   Maifailun via tashmetu (15/10/2026): a parent must know a daughter who died in childbirth, and a widower the wife
      ///   who died. Arranges its own family (Gabriel, 13/10: testall arranges its context): three clanless wanderers minted
      ///   off the map, a father, his daughter and his wife; the two women die in labor through the game's own action, the
      ///   father's RELATIONSHIPS is read, then he is removed too. The dead stay in the save's dead list, harmless, as the
      ///   minted companion of ArrangedCompanion does.
      /// </summary>
      private static string TestDeadKin(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("dead_kin");

         List<CharacterObject> templates = MBObjectManager.Instance.GetObjectTypeList<CharacterObject>()
            .Where(c => c != null && c.IsTemplate && c.Occupation == Occupation.Wanderer).ToList();
         CharacterObject man = templates.FirstOrDefault(c => !c.IsFemale), woman = templates.FirstOrDefault(c => c.IsFemale);
         if (t.Abort(man == null || woman == null, "no wanderer template of each sex to mint a family from")) return t.Line();

         Hero father = null, daughter = null, wife = null;
         try
         {
            father = HeroCreator.CreateSpecialHero(man, null, null, null, 50);
            wife = HeroCreator.CreateSpecialHero(woman, null, null, null, 45);
            daughter = HeroCreator.CreateSpecialHero(woman, null, null, null, 22);
            daughter.Father = father;
            father.Spouse = wife;

            KillCharacterAction.ApplyInLabor(daughter, false);
            KillCharacterAction.ApplyInLabor(wife, false);
            if (t.Abort(!daughter.IsDead || !wife.IsDead, "the game refused the deaths (another mod's CanHeroDie?)")) return t.Line();

            string block = RelationshipsBuilder.Build(father) ?? "";
            t.Note($"father={father.Name} daughter={daughter.Name} wife={wife.Name}: {block.Replace(Environment.NewLine, " | ")}");
            t.Expect("fatherNamesTheDeadDaughter", block.IndexOf($"the late {daughter.Name} (female", StringComparison.OrdinalIgnoreCase) >= 0, true);
            t.Expect("theDaughterDiedInChildbirth", block.IndexOf("died in childbirth this very day", StringComparison.OrdinalIgnoreCase) >= 0, true);
            t.Expect("widowerNamesTheDeadWife", block.IndexOf($"Spouse now dead: the late {wife.Name}", StringComparison.OrdinalIgnoreCase) >= 0, true);

            // "Which Debana?": the name hint finds his own dead daughter when the player names her.
            string hint = ContextualNameResolver.Resolve(father, $"I grieve for {daughter.Name}.") ?? "";
            t.Expect("theNameHintFindsTheLateDaughter", hint.IndexOf("your late daughter", StringComparison.OrdinalIgnoreCase) >= 0, true);
         }
         finally
         {
            try
            {
               if (father is {IsDead: false})
               {
                  if (father.Gold != 0) father.ChangeHeroGold(-father.Gold);
                  KillCharacterAction.ApplyByRemove(father);
               }
            }
            catch (Exception ex) { ModLog.Info($"[SELFTEST] dead_kin cleanup failed: {ex.GetType().Name}: {ex.Message}"); }
         }

         return t.Line();
      }

      private static string TestCaptiveKinAwareness(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_kin");

         // A capturable in-party lord (see TestFreePrisoner's note on why off-map lords are unreliable) who
         // ALSO has a living parent (not the player) to voice the denial: that parent is the NPC whose block
         // must reveal the captivity.
         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h &&
            ((h.Father is {IsAlive: true} && h.Father != Hero.MainHero) || (h.Mother is {IsAlive: true} && h.Mother != Hero.MainHero)));

         if (t.Skip(captive == null, "no capturable in-party lord with a living parent to test")) return t.Line();

         Hero parent = captive.Father is {IsAlive: true} && captive.Father != Hero.MainHero
            ? captive.Father
            : captive.Mother;

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);
         bool captured = captive.IsPrisoner && captive.PartyBelongedToAsPrisoner?.LeaderHero == Hero.MainHero;

         if (t.Abort(!captured, $"capture failed for {captive.Name}")) return t.Line();

         try
         {
            string block = RelationshipsBuilder.Build(parent);
            bool namesChild = block.IndexOf(captive.Name.ToString(), StringComparison.OrdinalIgnoreCase) >= 0;
            bool marksHeld = block.IndexOf("hold prisoner", StringComparison.OrdinalIgnoreCase) >= 0;

            t.Note($"parent={parent.Name} lists captive={captive.Name}: names={namesChild}, markedHeld={marksHeld}");
            t.Expect("parentNamesTheChild", namesChild, true);
            t.Expect("childMarkedHeldByPlayer", marksHeld, true);
         }
         finally
         {
            behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "free_prisoner"}, captive, null);
         }

         return t.Line();
      }

      /// <summary>
      ///   Bug #4 wiring (deterministic, no LLM): two DIFFERENT gang leaders sharing a settlement must be
      ///   framed as RIVALS in the name-mention hint, never left neutral (where the LLM hallucinated a
      ///   same-culture friendship). Skips when the campaign has no same-town gang-leader pair.
      /// </summary>
      private static string TestGangRivalry(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("gang_rivalry");

         (Hero npc, Hero rival) = FindSameTownGangLeaderPair();

         if (t.Skip(npc == null, "no same-town gang-leader pair on this campaign")) return t.Line();

         string hint = ContextualNameResolver.Resolve(npc, $"Tell me what you make of {rival.Name}.", behavior.GameStateBridge);
         bool framedAsRival = hint != null && hint.IndexOf("rival gang leader", StringComparison.OrdinalIgnoreCase) >= 0;

         t.Expect("sameTownGangLeaderFramedAsRival", framedAsRival, true);
         t.Note($"{npc.Name} asked about same-town gang leader {rival.Name}: {(framedAsRival ? "RIVAL" : "NOT framed rival")}. | hint: {Show(hint)}");

         return t.Line();
      }

      /// <summary>
      ///   Maifailun (Nexus, 14/10/2026): he held Adrichea (Honor -1, a clan leader), asked her to swear fealty or
      ///   share his bed, she answered "kill me if you must", and nothing in CR could hold a counter-offer anyway.
      ///   Gabriel: the captive proposes terms herself, settled through one new verb. Drives the REAL path three
      ///   ways on one held captive: (a) a fresh ActionConfirmationController queues a ransom offer, naming it; (b)
      ///   the real bridge settles it, paying the player, charging the payer, freeing the captive; (c) a term not
      ///   open to her right now (service, regard far under the recruit floor) is refused and moves nothing. A
      ///   fourth part, fealty actually changing a real realm, only runs under 'cr.test full' (MayArrangeDiplomacy),
      ///   since CR records a realm change as world news; otherwise it is noted, never silently skipped.
      /// </summary>
      private static string TestCaptiveCounterOffer(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_counter_offer");
         if (t.Abort(Hero.MainHero == null || PartyBase.MainParty == null, "no player party")) return t.Line();

         // Same free-lord-of-another-realm arrangement TestCaptiveTerms uses, reused here.
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsChild
                                                            && h.Clan != null && h.Clan != Clan.PlayerClan && h.MapFaction != Hero.MainHero.MapFaction
                                                            && (h.PartyBelongedTo == null || h.PartyBelongedTo.LeaderHero != h)
                                                            && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(lord == null, "no free lord of another realm exists to take captive")) return t.Line();

         int honorBefore = lord.GetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor);
         Hero payer = lord.Clan?.Leader ?? lord;
         int payerGoldBefore = payer.Gold;
         int playerGoldBefore = Hero.MainHero.Gold;
         NpcProfile profile = GetOrCreate(behavior, lord);
         int regardBefore = profile.ReputationWithPlayer;

         TakePrisonerAction.Apply(PartyBase.MainParty, lord);
         bool captured = lord.IsPrisoner && lord.PartyBelongedToAsPrisoner?.LeaderHero == Hero.MainHero;
         if (t.Abort(!captured, $"capture failed for {lord.Name}")) return t.Line();

         try
         {
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, -1);

            // GABRIEL'S RULE (13/10/2026): arrange it rather than skip. Ensure the payer can actually settle 300.
            if (payer.Gold < 300) payer.ChangeHeroGold(300 - payer.Gold);

            // A prior test in the same sweep may have already moved this lord's regard; part (c) needs it
            // deterministically under the recruit floor (60) so "service" is closed to her whatever ran before.
            profile.ReputationWithPlayer = 0;
            behavior.Store.Set(profile);

            // (a) A fresh ActionConfirmationController queues the offer, naming the ransom.
            var ransomOffer = new GameAction {Type = "counter_offer", Parameters = new Dictionary<string, string> {["terms"] = "ransom", ["amount"] = "300"}};
            var confirmation = new ActionConfirmationController();
            ActionDisposition disposition = confirmation.Preprocess(ransomOffer, lord, profile, new ActionContext(profile, null));
            t.Expect("ransomOfferIsQueued", disposition, ActionDisposition.Queued);
            t.Expect("theQuestionNamesTheRansom", confirmation.DebugNextQuestion?.Contains("300") == true, true);

            // (c) A term not open to her now (regard 0, far under the recruit floor) is refused, moving nothing.
            var closedOffer = new GameAction {Type = "counter_offer", Parameters = new Dictionary<string, string> {["terms"] = "service"}};
            ActionOutcome refused = behavior.GameStateBridge.ExecuteAction(closedOffer, lord, new ActionContext(profile, null));
            t.Note($"closed term (service): {refused?.Message}");
            t.Expect("aTermNotOpenIsRefused", refused?.WasRefused, true);
            t.Expect("aRefusedOfferFreesNoOne", lord.IsPrisoner, true);

            // (b) Execute the ransom for real: the player is paid, the payer pays, she walks free.
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(ransomOffer, lord, new ActionContext(profile, null));
            int paidToPlayer = Hero.MainHero.Gold - playerGoldBefore;
            t.Note($"{lord.Name}: {outcome?.Message}");
            t.Expect("thePlayerIsPaidTheRansom", paidToPlayer, 300);
            t.Expect("thePayerPaysTheRansom", payerGoldBefore - payer.Gold >= 300, true);
            t.Expect("theLordWalksFree", lord.IsPrisoner, false);

            // (d) Fealty actually swears a house to a real realm, which CR records as world news: only under
            // 'cr.test full', never silently skipped otherwise (Gabriel: note why instead).
            if (_diplomacyMayBeArranged)
            {
               Clan playerClan = Hero.MainHero.Clan;
               Kingdom originalPlayerKingdom = playerClan?.Kingdom;
               float playerInfluenceBefore = playerClan?.Influence ?? 0f;
               var arrangedPlayerJoin = false;

               try
               {
                  if (playerClan != null && originalPlayerKingdom == null)
                  {
                     Kingdom anyKingdom = Kingdom.All?.FirstOrDefault(k => k is {IsEliminated: false});
                     if (anyKingdom != null)
                     {
                        ChangeKingdomAction.ApplyByJoinToKingdom(playerClan, anyKingdom, default, false);
                        arrangedPlayerJoin = playerClan.Kingdom == anyKingdom;
                     }
                  }

                  Kingdom realm = playerClan?.Kingdom;
                  if (realm == null)
                  {
                     t.Note("fealty part (d) not run: the player's clan belongs to no kingdom, and no living kingdom exists to arrange one with");
                  }
                  else
                  {
                     // A clan leader whose house does NOT already rule a kingdom (CaptiveOfferPolicy.RulesHerRealm:
                     // swearing a sovereign's house would orphan the realm she rules) and is not already in the
                     // player's own realm.
                     Hero fealtyLord = Hero.AllAliveHeroes.FirstOrDefault(h =>
                        h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsChild && h.Clan != null && h.Clan.Leader == h
                        && h.Clan.Kingdom != null && h.Clan.Kingdom != realm && h.Clan.Kingdom.RulingClan != h.Clan
                        && Mapping.HeroPresence.IsInTheWorld(h));

                     if (fealtyLord == null)
                     {
                        t.Note("fealty part (d) not run: no clan-leading lord of another realm, not that realm's own sovereign, to swear fealty");
                     }
                     else
                     {
                        Kingdom fealtyLordOriginalKingdom = fealtyLord.Clan.Kingdom;
                        TakePrisonerAction.Apply(PartyBase.MainParty, fealtyLord);
                        bool fealtyLordCaptured = fealtyLord.IsPrisoner && fealtyLord.PartyBelongedToAsPrisoner?.LeaderHero == Hero.MainHero;

                        if (fealtyLordCaptured)
                           try
                           {
                              var fealtyProfile = GetOrCreate(behavior, fealtyLord);
                              var fealtyOffer = new GameAction {Type = "counter_offer", Parameters = new Dictionary<string, string> {["terms"] = "fealty"}};
                              ActionOutcome fealtyOutcome = behavior.GameStateBridge.ExecuteAction(fealtyOffer, fealtyLord, new ActionContext(fealtyProfile, null));

                              t.Note($"fealty: {fealtyLord.Name} of {fealtyLordOriginalKingdom?.Name} -> {fealtyOutcome?.Message}");
                              t.Expect("fealtySwearsTheHouseToTheRealm", fealtyLord.Clan.Kingdom == realm, true);
                              t.Expect("fealtyFreesHer", fealtyLord.IsPrisoner, false);
                           }
                           finally
                           {
                              if (fealtyLord.Clan.Kingdom != fealtyLordOriginalKingdom)
                              {
                                 float influenceBefore = fealtyLord.Clan.Influence;
                                 if (fealtyLordOriginalKingdom != null) ChangeKingdomAction.ApplyByJoinToKingdom(fealtyLord.Clan, fealtyLordOriginalKingdom, default, false);
                                 else ChangeKingdomAction.ApplyByLeaveKingdom(fealtyLord.Clan, false);
                                 ChangeClanInfluenceAction.Apply(fealtyLord.Clan, influenceBefore - fealtyLord.Clan.Influence);
                              }

                              if (fealtyLord.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(fealtyLord, Hero.MainHero);
                           }
                        else
                           t.Note($"fealty: capture of {fealtyLord.Name} failed, part (d) skipped");
                     }
                  }
               }
               finally
               {
                  if (arrangedPlayerJoin && playerClan != null)
                  {
                     ChangeKingdomAction.ApplyByLeaveKingdom(playerClan, false);
                     ChangeClanInfluenceAction.Apply(playerClan, playerInfluenceBefore - playerClan.Influence);
                  }
               }
            }
            else
            {
               t.Note("fealty part (d) not run: would change a real realm, which CR records as world news; only arranged in 'cr.test full'");
            }
         }
         finally
         {
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, honorBefore);
            if (lord.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(lord, Hero.MainHero);
            Hero.MainHero.ChangeHeroGold(playerGoldBefore - Hero.MainHero.Gold);
            payer.ChangeHeroGold(payerGoldBefore - payer.Gold);
            profile.ReputationWithPlayer = regardBefore;
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestCaptiveTerms(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_terms");
         if (t.Abort(Hero.MainHero == null || PartyBase.MainParty == null, "no player party")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsChild
                                                            && h.Clan != null && h.Clan != Clan.PlayerClan && h.MapFaction != Hero.MainHero.MapFaction
                                                            && (h.PartyBelongedTo == null || h.PartyBelongedTo.LeaderHero != h)
                                                            && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(lord == null, "no free lord of another realm outside a party exists to take captive")) return t.Line();

         int honorBefore = lord.GetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor);
         int calculatingBefore = lord.GetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Calculating);
         TakePrisonerAction.Apply(PartyBase.MainParty, lord);
         try
         {
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, -1);
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Calculating, 0);
            NpcProfile profile = GetOrCreate(behavior, lord);
            EncounterContext ctx = EncounterContextBuilder.Build(lord, profile, behavior.GameStateBridge);
            string prompt = behavior.LlmServices?.ChatService?.PromptBuilder?.BuildSystemPrompt(profile, new WorldState {CurrentDay = behavior.GameStateBridge.GetCurrentGameDay()}, ctx) ?? "";
            Hero payer = lord.Clan?.Leader ?? lord;
            bool intimacyAllowed = ModSettings.AdultContentLevel != AdultContentLevel.Off && profile.Romantic?.IsCompatibleWith(Hero.MainHero.IsFemale) == true;

            t.Note($"{lord.Name}: disposition={ctx.CaptiveDisposition}, terms={string.Join(",", ctx.CaptiveTerms)}, ransom up to {ctx.CaptiveRansomCeiling} (payer {payer.Name} holds {payer.Gold})");
            t.Expect("sheIsThePlayersCaptive", ctx.PlayerStatus, PlayerStatusVsNpc.NpcIsCaptive);
            t.Expect("anHonorlessCaptiveOffersFirst", ctx.CaptiveDisposition, "offers_first");
            t.Expect("theRansomIsWhatHerHouseCanPay", ctx.CaptiveTerms.Contains("ransom") ? ctx.CaptiveRansomCeiling == payer.Gold : payer.Gold < CaptiveOfferPolicy.RansomFloor, true);
            t.Expect("intimacyOnlyWhereAllowed", ctx.CaptiveTerms.Contains("intimacy"), intimacyAllowed);
            t.Expect("theCaptiveIsToldWhatSheCanOffer", prompt.Contains("WHAT YOU CAN OFFER FOR YOUR FREEDOM (") && prompt.Contains("no taste for martyrdom"), true);
         }
         finally
         {
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, honorBefore);
            lord.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Calculating, calculatingBefore);
            if (lord.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(lord, Hero.MainHero);
         }

         return t.Line();
      }

      private static string TestSellItem(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("sell_item");
         ItemRoster roster = MobileParty.MainParty?.ItemRoster;
         if (t.Abort(roster == null || Hero.MainHero == null, "no player item roster")) return t.Line();

         Hero buyer = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && h.Gold >= 500 && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(buyer == null, "no lord in the world with 500 denars")) return t.Line();

         // A trade good: nothing anyone would wear, so the sale moves only the item and the coin.
         ItemObject good = MBObjectManager.Instance?.GetObjectTypeList<ItemObject>()?.FirstOrDefault(it => it != null && it.IsTradeGood && it.Value > 0);
         if (t.Skip(good == null, "no trade good in the game data")) return t.Line();

         int heldBefore = roster.GetItemNumber(good);
         int playerGold = Hero.MainHero.Gold;
         int buyerGold = buyer.Gold;
         // Within what the good fetches: a price above its ceiling is brought down, which coin_matches_words drives.
         int price = Math.Min(100, ItemSalePolicy.MostFor(good.Value));
         roster.AddToCounts(good, 1);
         var paid = 0;
         try
         {
            var ctx = new ActionContext(GetOrCreate(behavior, buyer), null) {OfferedItemId = good.StringId};
            var sale = new GameAction {Type = "sell_item", Parameters = new Dictionary<string, string> {["item"] = good.Name.ToString(), ["price"] = price.ToString()}};
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(sale, buyer, ctx);
            paid = Hero.MainHero.Gold - playerGold;
            t.Note($"{good.Name} to {buyer.Name}: {outcome?.Message}");
            t.Expect("theItemIsGone", roster.GetItemNumber(good), heldBefore);
            t.Expect("thePlayerIsPaid", paid, price);
            t.Expect("theBuyerPaysTheSame", buyerGold - buyer.Gold, price);

            // A gift written in words is asked first, naming the real item the game would take.
            roster.AddToCounts(good, 1);
            var confirmation = new ActionConfirmationController();
            var gift = new GameAction {Type = "give_item", Parameters = new Dictionary<string, string> {["item"] = good.Name.ToString()}};
            ActionDisposition d = confirmation.Preprocess(gift, buyer, GetOrCreate(behavior, buyer), new ActionContext(GetOrCreate(behavior, buyer), null));
            t.Expect("aWordedGiftIsAskedFirst", d, ActionDisposition.Queued);
            t.Expect("theQuestionNamesTheRealItem", confirmation.DebugNextQuestion?.Contains(good.Name.ToString()) == true, true);
            // The item the player says yes to is the item that leaves: the pending gift is pinned to the resolved item.
            string resolved = BannerlordGameStateBridge.PreviewItem(gift, new ActionContext(GetOrCreate(behavior, buyer), null))?.Id;
            t.Expect("theConfirmedGiftTakesThatItem", confirmation.DebugNextContext?.OfferedItemId, resolved);
         }
         finally
         {
            if (paid > 0) GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, buyer, paid);
            int extra = roster.GetItemNumber(good) - heldBefore;
            if (extra > 0) roster.AddToCounts(good, -extra);
         }

         return t.Line();
      }

      private static string TestCompanyGift(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("company_gift");
         using var arranged = ArrangedCompanion.Get(behavior, mustBeInMainParty: true);
         if (t.Skip(arranged == null || MobileParty.MainParty == null, "no companion in the main party, and none could be arranged")) return t.Line();

         Hero companion = arranged.Companion;
         ItemObject grain = Game.Current?.ObjectManager?.GetObject<ItemObject>("grain");
         if (t.Skip(grain == null, "no grain item in this game")) return t.Line();

         ItemRoster roster = MobileParty.MainParty.ItemRoster;
         var goods = new EquipmentElement(grain);
         int before = roster.GetItemNumber(grain);
         NpcProfile profile = GetOrCreate(behavior, companion);
         int regardBefore = profile.ReputationWithPlayer;
         try
         {
            t.Expect("theCompanionSharesTheStores", BannerlordGameStateBridge.SharesTheStores(companion), true);

            // Three put in the stores for the test, then, as the hand-over does, taken out before the gift is settled.
            roster.AddToCounts(goods, 3);
            roster.AddToCounts(goods, -3);
            ActionOutcome outcome = BannerlordGameStateBridge.CompanyGift(companion, new ActionContext(profile, null), new List<(EquipmentElement Goods, int Count)> {(goods, 3)});
            t.Note(outcome?.Message);

            // STAKE (Aporo): what the companion does not put on is still the company's.
            t.Expect("theGrainIsBackInTheStores", roster.GetItemNumber(grain), before + 3);
            // STAKE: an item that comes straight back buys no regard.
            t.Expect("noRegardForWhatCameBack", behavior.Store.Get(companion.StringId)?.ReputationWithPlayer ?? regardBefore, regardBefore);
         }
         finally
         {
            int extra = roster.GetItemNumber(grain) - before;
            if (extra != 0) roster.AddToCounts(goods, -extra);
         }

         return t.Line();
      }

      private static string TestRelationLedgerPrune(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("relation_ledger_prune");
         if (t.Skip(Campaign.Current == null || Mapping.RelationLedgerBehavior.Instance == null, "no campaign")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && h.IsLord && Mapping.HeroPresence.IsInTheWorld(h)).Take(3).ToList();
         if (t.Skip(lords.Count < 3, "three lords are needed")) return t.Line();

         int ab = CharacterRelationManager.GetHeroRelation(lords[0], lords[1]);
         int ac = CharacterRelationManager.GetHeroRelation(lords[0], lords[2]);
         var ledger = new Logic.Relations.RelationBaselineLedger();
         ledger.Saw(lords[0].StringId, lords[1].StringId, ab);                  // back at its start
         ledger.Saw(lords[0].StringId, lords[2].StringId, ac > 0 ? ac - 30 : ac + 30); // moved since
         ledger.Saw(lords[0].StringId, "cr_selftest_nobody", 10);               // someone not in the world

         int dropped = Mapping.RelationLedgerBehavior.PruneWithWorld(ledger);
         // STAKE (tashmetu): what reads the same without it, or concerns no one alive, no longer weighs on the save.
         t.Expect("droppedTheTwoNotNeeded", dropped, 2);
         t.Expect("aPairBackAtItsStartIsDropped", ledger.BaselineOf(lords[0].StringId, lords[1].StringId) == null, true);
         t.Expect("aPairWithSomeoneUnknownIsDropped", ledger.BaselineOf(lords[0].StringId, "cr_selftest_nobody") == null, true);
         // STAKE: a history built in play is kept.
         t.Expect("aPairThatMovedIsKept", ledger.BaselineOf(lords[0].StringId, lords[2].StringId) != null, true);

         t.Note($"this campaign's ledger: {Mapping.RelationLedgerBehavior.Instance.Ledger.Baselines.Count:N0} pairs (pruned at each save)");

         return t.Line();
      }

      private static string TestQuestRepeat(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("quest_repeat");
         if (t.Skip(behavior.Store == null || Hero.MainHero?.MapFaction == null, "no campaign")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && h.IsLord && Mapping.HeroPresence.IsInTheWorld(h)
                                                           && behavior.Store.Get(h.StringId) is NpcProfile p && !p.ActiveQuests.Any(q => q.IsOutstanding))
                                               .Take(2).ToList();
         if (t.Skip(lords.Count < 2, "two lords with a profile and no open task are needed")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         InformalQuest done = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.ScoutArmy, Description = "[SELFTEST] scout"}, lords[0], today);
         if (t.Skip(done == null, "the player is at war with no realm, so no scouting can be set")) return t.Line();

         done.Status = QuestStatus.Completed;
         done.SatisfiedOnDay = today;
         done.Evidence = "[SELFTEST] seen";
         NpcProfile first = behavior.Store.Get(lords[0].StringId);
         NpcProfile second = behavior.Store.Get(lords[1].StringId);
         var hideout = new InformalQuest {
            Type = QuestType.BanditHideout, Description = "[SELFTEST] camp", TargetSettlement = "[SELFTEST] town", TargetHideoutId = "selftest_camp_a",
            Status = QuestStatus.Completed, SatisfiedOnDay = today
         };
         try
         {
            first.ActiveQuests.Add(done);
            behavior.Store.Set(first);

            // STAKE (bdionysis80): the scouting just done is not set again by another lord, and the player is told whose.
            string refusal = null;
            Quests.QuestService.IssueQuest(second, lords[1], new QuestProposal {Type = QuestType.ScoutArmy, TargetFaction = done.TargetFactionName, Description = "[SELFTEST] scout again"},
                                           today, behavior.Store, (text, positive) => { if (!positive) refusal = text; });
            t.Note($"second offer: {refusal ?? "recorded"}");
            t.Expect("theSameScoutingIsRefused", refusal?.Contains("already carry") == true, true);
            t.Expect("theRefusalNamesWhoseItIs", refusal?.Contains(first.Name) == true, true);
            t.Expect("noTaskWasAdded", behavior.Store.Get(lords[1].StringId).ActiveQuests.Any(q => q.Description == "[SELFTEST] scout again"), false);

            // STAKE (bdionysis80): the council reads the scouting as done, with what was found.
            List<string> lines = Logic.Quests.QuestRepeatPolicy.CouncilLines(Quests.QuestService.HeldQuests(behavior.Store), today);
            t.Expect("theCouncilReadsItAsDone", lines.Any(l => l.Contains(first.Name) && l.Contains("done") && l.Contains("[SELFTEST] seen")), true);

            // THE REPORT (Aporo, Discord, 14/11/2026): a second bandit camp near the same town is its own task. Read through
            // the REAL held-task reader, so the hideout reaches the key the repeat check compares.
            first.ActiveQuests.Add(hideout);
            behavior.Store.Set(first);
            List<Logic.Quests.HeldQuest> held = Quests.QuestService.HeldQuests(behavior.Store);
            t.Expect("anotherCampNearTheTownIsNoRepeat",
               Logic.Quests.QuestRepeatPolicy.RepeatOf(QuestType.BanditHideout, Logic.Quests.QuestRepeatPolicy.KeyOf(null, null, "[SELFTEST] town", "selftest_camp_b"), today, held) == null, true);
            t.Expect("theSameCampIsStillARepeat",
               Logic.Quests.QuestRepeatPolicy.RepeatOf(QuestType.BanditHideout, Logic.Quests.QuestRepeatPolicy.KeyOf(null, null, "[SELFTEST] town", "selftest_camp_a"), today, held) != null, true);
         }
         finally
         {
            first.ActiveQuests.Remove(done);
            first.ActiveQuests.Remove(hideout);
            behavior.Store.Set(first);
            NpcProfile after = behavior.Store.Get(lords[1].StringId);
            if (after.ActiveQuests.RemoveAll(q => q.Description == "[SELFTEST] scout again") > 0) behavior.Store.Set(after);
         }

         // STAKE (bdionysis80): the table's count of the company is the game's own.
         int? days = MobileParty.MainParty?.GetNumDaysForFoodToLast();
         t.Note($"company: {MobileParty.MainParty?.MemberRoster?.TotalManCount} men, food for {days} days");
         t.Expect("theFoodDaysAreRead", days.HasValue, true);

         return t.Line();
      }

