      private static string TestPromptFollowsPlayer(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prompt_follows_player");
         if (t.Skip(Campaign.Current == null || Hero.MainHero == null || behavior?.LlmServices == null, "no campaign")) return t.Line();

         LlmServices services = behavior.LlmServices;
         string priorName = LlmServices.TestPlayerNameOverride;
         try
         {
            NpcChatService first = services.ChatService;
            if (t.Skip(first == null, "no provider configured: the chat service is not built")) return t.Line();

            // STAKE: an unchanged player keeps the prompt already built (no rebuild on every reply).
            t.Expect("samePlayerKeepsThePrompt", ReferenceEquals(services.ChatService, first), true);

            // THE REPORT: the player's name changes (a switch to another hero of the same clan), the prompt follows.
            LlmServices.TestPlayerNameOverride = "Selftest Switched Hero";
            NpcChatService switched = services.ChatService;
            t.Expect("aSwitchedPlayerRebuildsThePrompt", ReferenceEquals(switched, first), false);

            // THE REPORT: an edited player_description.txt reaches the next reply after the reload.
            IReadOnlyList<string> failed = CrPrompt.Reload();
            t.Note(failed.Count == 0 ? "every prompt file reloaded" : "failed to reload: " + string.Join(", ", failed));
            t.Expect("theReloadRebuildsThePrompt", ReferenceEquals(services.ChatService, switched), false);
         }
         finally
         {
            LlmServices.TestPlayerNameOverride = priorName;
            services.Invalidate();
         }

         return t.Line();
      }

