      private static string TestCampaignOverrides(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("campaign_overrides");
         string folder = CrLore.CampaignFolder();
         if (t.Skip(Campaign.Current == null || folder == null, "no campaign")) return t.Line();

         string file = System.IO.Path.Combine(folder, "character_overrides.json");
         if (t.Skip(System.IO.File.Exists(file), "this campaign already has its own character_overrides.json; the test never touches it")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero);
         if (t.Skip(lord == null, "no lord")) return t.Line();

         bool madeFolder = !System.IO.Directory.Exists(folder);
         try
         {
            System.IO.Directory.CreateDirectory(folder);
            System.IO.File.WriteAllText(file, "[{\"id\": \"" + lord.StringId + "\", \"backstory\": \"Selftest campaign backstory.\"}]");
            CharacterOverrideLoader.Load();
            t.Note($"{lord.Name}, overlay {CharacterOverrideLoader.LastOverlayPath}");
            // THE REPORT: a character written for this campaign is read for this campaign.
            t.Expect("theLordResolvesToTheCampaignEntry", CharacterOverrideLoader.For(lord)?.Backstory, "Selftest campaign backstory.");
            t.Expect("theOverlayIsReported", CharacterOverrideLoader.LastOverlayCount, 1);
         }
         finally
         {
            try
            {
               System.IO.File.Delete(file);
               if (madeFolder) System.IO.Directory.Delete(folder);
            }
            catch (Exception ex) { t.Note($"cleanup: {ex.GetType().Name}"); }
            CharacterOverrideLoader.Load();
         }

         // STAKE: once the campaign's file is gone, the lord is back to the shared file alone.
         t.Expect("goneWithTheFile", CharacterOverrideLoader.For(lord)?.Backstory == "Selftest campaign backstory.", false);

         return t.Line();
      }

      private static string TestCharacterText(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("character_text");
         if (t.Skip(Campaign.Current == null || Hero.MainHero == null, "no campaign")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero);
         if (t.Skip(lord == null, "no lord")) return t.Line();

         const string source = "cr_selftest_character_text";
         CrCharacterText.RegisterSource(source, f =>
            f.HeroId == lord.StringId
               ? new[] {
                  new CrCharacterTextEntry {Section = CrCharacterTextSection.Appearance, Text = "A selftest scar crosses the brow.", Lean = true},
                  new CrCharacterTextEntry {Section = CrCharacterTextSection.Private, Text = "The selftest secret is buried gold.", ShowInPanel = true, Lean = true}
               }
               : f.IsPlayer
                  ? new[] {new CrCharacterTextEntry {Section = CrCharacterTextSection.Backstory, Text = "The selftest player keeps hounds.", Lean = true}}
                  : null);
         try
         {
            t.Note(lord.Name.ToString());
            // THE REPORT: a mod's description reaches the model and the panel.
            t.Expect("theAppearanceBlockCarriesIt", Mapping.EncounterContextBuilder.ComposeAppearance(lord, AppearanceVoice.Self)?.Contains("selftest scar") == true, true);
            t.Expect("thePanelShowsIt", Chat.ChatViewModel.PanelAppearanceFor(lord).Contains("selftest scar"), true);
            // STAKE: a secret reaches the model, never the panel, even when the mod asks.
            t.Expect("theModelKnowsTheSecret", Mapping.EncounterContextBuilder.ModTextFor(lord, Logic.Character.CharacterTextSection.Private)?.Contains("buried gold") == true, true);
            t.Expect("thePanelNeverShowsTheSecret", Chat.ChatViewModel.PanelAppearanceFor(lord).Contains("buried gold")
                                                   || Chat.ChatViewModel.PanelCharacterFor(lord, null).Contains("buried gold"), false);
            // THE REPORT: "the same for the player".
            t.Expect("thePlayersTextReachesThePrompt", Mapping.EncounterContextBuilder.ModTextFor(Hero.MainHero, Logic.Character.CharacterTextSection.Backstory)?.Contains("keeps hounds") == true, true);
         }
         finally
         {
            CrCharacterText.UnregisterSource(source);
         }

         // STAKE: with no source, nothing is added.
         t.Expect("goneOnceUnregistered", Mapping.EncounterContextBuilder.ComposeAppearance(lord, AppearanceVoice.Self)?.Contains("selftest scar") == true, false);

         return t.Line();
      }

      private static string TestPlayerReport(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("player_report");

         DateTime opened = DateTime.Now.AddSeconds(-1);
         Services.ReportRecorder.Instance.OnExchange(
            new LlmRequest {SystemPrompt = "SELFTEST prompt for Lady Arwa, key sk-or-v1-selftest0123456789abcdef", Messages = new[] {new LlmMessage(MessageRole.User, "SELFTEST hello")}, Subject = "selftest"},
            new LlmResponse {Content = "SELFTEST reply: well met.", IsSuccess = true}, "selftest/model");

         Logic.Diagnostics.PlayerReportFacts facts = Diagnostics.PlayerReportService.Gather("[SELFTEST] she asked for the coin twice", false, new List<string> {"Selftest: a line"}, "Selftest Lady", opened);
         // Gabriel (14/11/2026): the report holds this conversation's exchanges only.
         t.Expect("onlyThisConversationsExchanges", facts.Exchanges.Count > 0 && facts.Exchanges.Any(e => e.Subject == "selftest"), true);
         t.Expect("noOlderExchange", Services.ReportRecorder.Instance.Since(DateTime.Now.AddMinutes(1)).Count, 0);
         string path = Diagnostics.PlayerReportService.Write(facts, opened);
         try
         {
            if (t.Abort(path == null || !System.IO.File.Exists(path), "the report file could not be written")) return t.Line();

            string written = System.IO.File.ReadAllText(path);
            t.Note(path);
            // THE REQUEST: the report holds the player's words, the prompt and the reply.
            t.Expect("thePlayersWordsAreIn", written.Contains("she asked for the coin twice"), true);
            t.Expect("thePromptAndReplyAreIn", written.Contains("SELFTEST prompt for Lady Arwa") && written.Contains("SELFTEST reply: well met."), true);
            // STAKE: a key never reaches a public channel.
            t.Expect("theKeyIsMasked", written.Contains("selftest0123456789abcdef"), false);
            // THE REQUEST: the report is written into the log too.
            t.Expect("theLogHoldsTheReport", Diagnostics.PlayerReportService.SessionLogLines().Any(l => l.Contains("she asked for the coin twice")), true);
            // Gabriel (14/11/2026): "il faudrait pas réinjecter le log au complet": the copy in the log points to its lines.
            t.Expect("theLogCopyPointsToItsLines", Diagnostics.PlayerReportService.SessionLogLines().Any(l => l.Contains("this conversation's log lines are above in this file")), true);
         }
         finally
         {
            try { if (path != null) System.IO.File.Delete(path); }
            catch (Exception ex) { t.Note($"cleanup: {ex.GetType().Name}"); }
         }

         return t.Line();
      }

      private static string TestClanTaskNoCoin(NpcMemoryCampaignBehavior behavior)
