      }

      private static string TestQuestConsent(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("quest_consent");
         if (t.Skip(Campaign.Current == null || Hero.MainHero == null || behavior?.Store == null, "no campaign")) return t.Line();

         IFaction mine = Hero.MainHero.MapFaction;
         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && Mapping.HeroPresence.IsInTheWorld(h) && h.MapFaction is Kingdom && h.MapFaction != mine);
         if (t.Skip(giver == null, "no lord of another realm alive")) return t.Line();
         Settlement place = Settlement.All.FirstOrDefault(s => (s.IsCastle || s.IsTown) && s.MapFaction != null && s.MapFaction != giver.MapFaction && s.MapFaction != mine);
         if (t.Skip(place == null, "no town or castle of a third realm")) return t.Line();

         NpcProfile profile = GetOrCreate(behavior, giver);
         List<InformalQuest> setAside = profile.ActiveQuests.Where(q => q.IsOutstanding).ToList();
         int eventsBefore = profile.Events.Count;
         InformalQuest accepted = null;
         var notes = new List<string>();
         var response = new ParsedResponse {Dialogue = "", QuestGiven = new QuestProposal {Type = QuestType.ScoutPlace, TargetSettlement = place.Name.ToString()}};
         int today = (int) CampaignTime.Now.ToDays;
         try
         {
            foreach (InformalQuest q in setAside) profile.ActiveQuests.Remove(q);
            LlmFeedbackNotes.ConsumeFor(giver.StringId);

            // STAKE (Schmidt): declined, nothing is the player's; while the window is open, nothing is recorded either.
            bool recordedWhileAsked = true;
            Quests.QuestService.ConsentForTest = q =>
            {
               recordedWhileAsked = profile.ActiveQuests.Any(a => a.IsOutstanding);

               return false;
            };
            Quests.QuestService.ApplyResponse(profile, giver, response, today, behavior.GameStateBridge, behavior.Store, (text, _) => notes.Add(text));
            t.Expect("nothingIsRecordedWhileTheOfferWaits", recordedWhileAsked, false);
            t.Expect("theChatSaysATaskWasPutNotGiven", notes.Any(n => n.Contains("puts a task to you")), true);
            t.Expect("declinedNoTaskIsThePlayers", profile.ActiveQuests.Any(q => q.IsOutstanding), false);
            t.Expect("declinedTheGiverRemembersTheRefusal", profile.Events.Skip(eventsBefore).Any(e => e.summary.Contains("they declined it")), true);
            t.Expect("declinedTheModelIsTold", LlmFeedbackNotes.ConsumeFor(giver.StringId)?.Contains("DECLINED") == true, true);

            // STAKE: accepted, the task is the player's, with its journal entry.
            Quests.QuestService.ConsentForTest = q => true;
            Quests.QuestService.ApplyResponse(profile, giver, response, today, behavior.GameStateBridge, behavior.Store, (text, _) => notes.Add(text));
            accepted = profile.ActiveQuests.FirstOrDefault(q => q.IsOutstanding && q.Type == QuestType.ScoutPlace);
            t.Expect("acceptedTheTaskIsThePlayers", accepted?.TargetSettlement, place.Name.ToString());
            t.Expect("acceptedItsJournalEntryOpens", accepted != null && Quests.QuestJournalBridge.FindMirror(accepted, giver) != null, true);
            t.Expect("acceptedTheModelIsTold", LlmFeedbackNotes.ConsumeFor(giver.StringId)?.Contains("ACCEPTED") == true, true);
         }
         finally
         {
            Quests.QuestService.ConsentForTest = null;
            if (accepted != null)
            {
               Quests.QuestJournalBridge.CloseAsCancelled(accepted, giver, "a self-test task, withdrawn");
               profile.ActiveQuests.Remove(accepted);
            }
            while (profile.Events.Count > eventsBefore) profile.Events.RemoveAt(profile.Events.Count - 1);
            foreach (InformalQuest q in setAside) profile.ActiveQuests.Add(q);
            behavior.Store.Set(profile);
            LlmFeedbackNotes.ConsumeFor(giver.StringId);
         }

         return t.Line();
      }

      private static string TestRealmsAndArmies(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("realms_and_armies");
         if (t.Skip(Campaign.Current == null || behavior?.GameStateBridge == null, "no campaign")) return t.Line();

         // STAKE (Schmidt): every realm standing is named with what it holds.
         string realms = behavior.GameStateBridge.GetRealmStanding();
         t.Note(realms);
         Kingdom standing = Kingdom.All.FirstOrDefault(k => !k.IsEliminated);
         if (t.Skip(standing == null, "no realm stands in this world")) return t.Line();
         t.Expect("aStandingRealmIsNamedWithItsFiefs", realms.Contains($"{standing.Name} holds"), true);

         // STAKE (Schmidt): a destroyed realm is told as fallen. With none fallen in this campaign, one realm is counted
         // destroyed for the read only (the game's own flag, restored at once), so the fallen line is always exercised.
         Kingdom fallen = Kingdom.All.FirstOrDefault(k => k.IsEliminated);
         FieldInfo eliminated = fallen == null ? typeof(Kingdom).GetField("_isEliminated", BindingFlags.Instance | BindingFlags.NonPublic) : null;
         Kingdom felled = fallen ?? Kingdom.All.LastOrDefault(k => !k.IsEliminated && k != standing && k != Hero.MainHero?.MapFaction);
         if (t.Skip(felled == null || (fallen == null && eliminated == null), "no realm can be counted fallen (Kingdom._isEliminated not found)")) return t.Line();
         try
         {
            eliminated?.SetValue(felled, true);
            string withFallen = behavior.GameStateBridge.GetRealmStanding();
            t.Note(withFallen);
            t.Expect("aFallenRealmIsToldAsFallen", withFallen.Contains($"no longer a power: ") && withFallen.Contains(felled.Name.ToString()), true);
            t.Expect("aFallenRealmIsNotToldAsHoldingFiefs", withFallen.Contains($"{felled.Name} holds"), false);
         }
         finally
         {
            eliminated?.SetValue(felled, false);
         }

         // STAKE (Schmidt): a lord in an army knows the other lords in it and the whole. With no army of two parties in the
         // field, one is raised from two lords of one realm for the read and disbanded at once.
         Army raised = null;
         MobileParty member = MobileParty.All.FirstOrDefault(p => p?.Army != null && p.Army.Parties.Count >= 2 && p.LeaderHero != null && p != MobileParty.MainParty && !p.LeaderHero.IsPrisoner);
         try
         {
            if (member == null)
            {
               List<MobileParty> idle = MobileParty.All.Where(p => p != null && p.IsLordParty && p != MobileParty.MainParty && p.Army == null && p.LeaderHero != null
                                                                   && !p.LeaderHero.IsPrisoner && p.MapFaction is Kingdom && p.MemberRoster.TotalManCount > 0).ToList();
               MobileParty leader = idle.FirstOrDefault(p => idle.Any(o => o != p && o.MapFaction == p.MapFaction));
               MobileParty second = leader == null ? null : idle.First(o => o != leader && o.MapFaction == leader.MapFaction);
               if (t.Skip(leader == null, "no two idle lord parties of one realm to raise an army from")) return t.Line();

               raised = new Army((Kingdom) leader.MapFaction, leader, Army.ArmyTypes.Patrolling);
               second.Army = raised;
               member = second;
            }

            IReadOnlyList<string> roster = Mapping.ArmyRosterReader.Read(member.LeaderHero);
            MobileParty other = member.Army.Parties.FirstOrDefault(p => p != member && p.LeaderHero != null);
            t.Note(roster == null ? "no roster" : string.Join(" | ", roster));
            t.Expect("theArmyIsTold", roster != null && roster.Any(l => l.StartsWith("In all,")), true);
            t.Expect("anotherLordOfTheArmyIsNamed", other != null && roster != null && roster.Any(l => l.Contains(other.LeaderHero.Name.ToString())), true);
         }
         finally
         {
            if (raised != null) DisbandArmyAction.ApplyByUnknownReason(raised);
         }

         Hero alone = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.PartyBelongedTo != null && h.PartyBelongedTo.Army == null && h != Hero.MainHero && !h.IsPrisoner);
         if (alone != null) t.Expect("aLordInNoArmyIsToldNone", Mapping.ArmyRosterReader.Read(alone) == null, true);

         return t.Line();
      }

      private static string TestScoutPlace(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scout_place");
         if (t.Skip(Campaign.Current == null || Hero.MainHero == null, "no campaign")) return t.Line();

         IFaction mine = Hero.MainHero.MapFaction;
         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && Mapping.HeroPresence.IsInTheWorld(h) && h.MapFaction is Kingdom && h.MapFaction != mine);
         if (t.Skip(giver == null, "no lord of another realm alive")) return t.Line();

         Settlement third = Settlement.All.FirstOrDefault(s => s.IsCastle && s.MapFaction != null && s.MapFaction != giver.MapFaction && s.MapFaction != mine)
                            ?? Settlement.All.FirstOrDefault(s => s.IsTown && s.MapFaction != null && s.MapFaction != giver.MapFaction && s.MapFaction != mine);
         Settlement own = Settlement.All.FirstOrDefault(s => (s.IsTown || s.IsCastle) && s.MapFaction == giver.MapFaction);
         if (t.Skip(third == null, "no town or castle held by a realm other than the giver's and the player's")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         // STAKE (bdionysis80): a place of another realm, at war or not, becomes a task on that very place.
         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.ScoutPlace, TargetSettlement = third.Name.ToString()}, giver, today);
         t.Expect("aPlaceOfAnotherRealmIsTheTask", quest?.TargetSettlement, third.Name.ToString());
         // STAKE: scouting is no war deed: a peace must not void it, so no war faction is bound.
         t.Expect("noWarFactionIsBound", quest?.TargetFactionId == null, true);
         if (own != null)
         {
            // STAKE: no lord sends the player to look at his own walls.
            InformalQuest none = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.ScoutPlace, TargetSettlement = own.Name.ToString()}, giver, today);
            t.Expect("aPlaceOfTheGiversRealmSetsNoTask", none == null, true);
         }

         // STAKE: the council's pledge grounds as this deed, not as an army somewhere else.
         t.Expect("theCouncilGroundsIt", Logic.Assemblies.CouncilQuestTypePolicy.TryResolve("scout_place", out QuestType grounded) && grounded == QuestType.ScoutPlace, true);

         // STAKE: the deed is done when the party has the place in sight, through the check the hourly tick runs, and not
         // from afar, or the task would close by itself or never.
         if (quest != null)
         {
            TaleWorlds.Library.Vec2 at = third.GetPosition2D;
            t.Expect("inSightTheDeedIsDone", Quests.QuestDeedTracker.ScoutPlaceInSight(quest, at)?.StringId, third.StringId);
            t.Expect("fromAfarItIsNot", Quests.QuestDeedTracker.ScoutPlaceInSight(quest, new TaleWorlds.Library.Vec2(at.x + 40f, at.y + 40f)) == null, true);
         }

         // STAKE: a lord at war is offered a place of his enemy to scout, so a grounded menu can give this task too.
         Hero atWar = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && Mapping.HeroPresence.IsInTheWorld(h) && h.MapFaction is Kingdom k && k != mine
                                                              && Kingdom.All.Any(o => o != k && !o.IsEliminated && FactionManager.IsAtWarAgainstFaction(k, o)));
         if (atWar != null)
         {
            Logic.Quests.QuestMenuEntry offered = Quests.ViableQuestScanner.ScanEntries(atWar).FirstOrDefault(e => e.TypeToken == "scout_place");
            t.Note(offered == null ? $"{atWar.Name}: no scout_place offered" : $"{atWar.Name}: scout_place offered on {offered.TargetName}");
            Settlement offeredPlace = offered == null ? null : Settlement.All.FirstOrDefault(s => s.Name?.ToString() == offered.TargetName);
            t.Expect("aLordAtWarIsOfferedAnEnemyPlace", offeredPlace?.MapFaction != null && FactionManager.IsAtWarAgainstFaction(atWar.MapFaction, offeredPlace.MapFaction), true);
         }
         else t.Note("no lord of another realm is at war: the menu entry is not exercised");

         // STAKE: what the giver reads is what the game shows of the place, not a report the model invents.
         string report = Logic.Quests.ScoutPlacePolicy.Report(Quests.QuestDeedTracker.SightingOf(third, today));
         t.Note(report);
         t.Expect("theReportNamesThePlaceAndItsHolder", report.Contains(third.Name.ToString()) && report.Contains("held by"), true);
         t.Expect("theReportCountsTheGarrison", report.Contains("garrison of about"), true);

         return t.Line();
      }

      private static string TestScoutArmyPlace(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scout_army_place");
         Hero giver = Hero.MainHero;
         if (t.Skip(Campaign.Current == null || giver?.MapFaction == null, "no campaign")) return t.Line();

