         // STAKE: the player's recent words are shown under "You".
         t.Expect("thePlayersRecentWordsAreShown", prompt.Contains("You: CRSELFTEST my word 35"), true);
         // STAKE: nothing folded is shown twice.
         t.Expect("foldedLinesAreNotShownWhole", prompt.Contains("CRSELFTEST my word 0") || prompt.Contains("CRSELFTEST seat line 1" + Environment.NewLine), false);

         return t.Line();
      }

      private static string TestSaveBlobs(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("save_blobs");
         if (t.Skip(behavior.Store == null || Campaign.Current == null, "no campaign")) return t.Line();

         var stores = new List<(string Name, string Json)> {("memories", behavior.Store.SerializeProfiles())};
         string ledger = Campaign.Current.GetCampaignBehavior<Mapping.RelationLedgerBehavior>()?.Ledger?.Serialize();
         if (ledger != null) stores.Add(("relation ledger", ledger));

         foreach ((string name, string json) in stores)
         {
            var clock = System.Diagnostics.Stopwatch.StartNew();
            byte[] stored = Logic.Saving.SaveBlobCodec.Encode(json);
            long encodeMs = clock.ElapsedMilliseconds;
            string back = Logic.Saving.SaveBlobCodec.Decode(stored);
            int raw = Encoding.UTF8.GetByteCount(json ?? "");
            t.Note($"{name}: {raw:N0} bytes raw, {stored.Length:N0} saved ({(raw == 0 ? 0 : 100.0 * stored.Length / raw):0.0}%), compressed in {encodeMs} ms, read in {clock.ElapsedMilliseconds - encodeMs} ms");
            // STAKE (tashmetu): what the save holds is what loads, and the save stays loadable.
            t.Expect($"{name}ComesBackIdentical", string.IsNullOrEmpty(json) ? back == null : back == json, true);
            t.Expect($"{name}StaysUnderTheCeiling", stored.Length < Logic.Saving.SaveBlobCodec.RefuseAt, true);
            // STAKE (2.8.8): every piece is a string the game saves whole, and the pieces join back into the same store.
            List<string> pieces = Logic.Saving.SaveBlobCodec.ToPieces(stored);
            t.Note($"{name}: {pieces.Count:N0} piece(s) in the save");
            t.Expect($"{name}PiecesFitOneSavedString", pieces.All(p => Encoding.UTF8.GetByteCount(p) <= Logic.Saving.SaveBlobCodec.EngineStringLimit), true);
            t.Expect($"{name}PiecesComeBackIdentical", Logic.Saving.SaveBlobCodec.Decode(Logic.Saving.SaveBlobCodec.FromPieces(pieces)) == back, true);
         }

         // SaveBlob itself, the path every compressed store takes, on a stand-in data store holding what each save writes.
         string memories = stores[0].Json ?? "";
         const string probeKey = "cr_selftest_blob_gz";
         const string olderKey = "cr_selftest_blob_bytes";
         try
         {
            // STAKE (Gabriel, 09/11/2026: "continuer a supporter les anciennes sauvegardes"): a 2.8.6-2.8.7 save still loads.
            var save287 = new StandInDataStore(false);
            save287.Data[probeKey] = Logic.Saving.SaveBlobCodec.EncodeGzip(memories);
            t.Expect("a287SaveStillLoads", (SaveBlob.Read(save287, probeKey, olderKey) ?? "") == memories, true);

            // STAKE (10/11/2026): the first 2.8.8 builds wrote GZip pieces; those saves still load now the pieces are PPMd.
            var saveGzipPieces = new StandInDataStore(false);
            saveGzipPieces.Data[probeKey + SaveBlob.PiecesSuffix] = Logic.Saving.SaveBlobCodec.ToPieces(Logic.Saving.SaveBlobCodec.EncodeGzip(memories));
            t.Expect("gzipPiecesStillLoad", (SaveBlob.Read(saveGzipPieces, probeKey, olderKey) ?? "") == memories, true);

            // STAKE: a save older than 2.8.6, plain JSON in a byte[], still loads.
            var saveOlder = new StandInDataStore(false);
            saveOlder.Data[olderKey] = Encoding.UTF8.GetBytes(memories);
            t.Expect("anOlderPlainSaveStillLoads", (SaveBlob.Read(saveOlder, probeKey, olderKey) ?? "") == memories, true);

            // STAKE (2.8.8): a new save writes the pieces alone, never the byte[] that bricked tashmetu's campaign.
            var saving = new StandInDataStore(true);
            SaveBlob.Write(saving, probeKey, memories);
            t.Expect("aNewSaveWritesPiecesOnly", string.Join(",", saving.Data.Keys), probeKey + SaveBlob.PiecesSuffix);
            // STAKE (Gabriel, 10/11/2026: "ppmd est le bon choix"): what a new save holds is PPMd, the smaller form.
            t.Expect("aNewSaveIsPpmd", string.IsNullOrEmpty(memories)
               || Logic.Saving.SaveBlobCodec.IsPpmd(Logic.Saving.SaveBlobCodec.FromPieces((IList<string>) saving.Data[probeKey + SaveBlob.PiecesSuffix])), true);

            // STAKE: the pieces are read first, before any older form the save might also hold.
            var reload = new StandInDataStore(false);
            foreach (var kv in saving.Data) reload.Data[kv.Key] = kv.Value;
            reload.Data[probeKey] = Logic.Saving.SaveBlobCodec.EncodeGzip("{\"stale\":1}");
            t.Expect("thePiecesAreReadFirst", (SaveBlob.Read(reload, probeKey, olderKey) ?? "") == memories, true);
         }
         finally { SaveBlob.Forget(probeKey); }

         return t.Line();
      }

      /// <summary>A data store held in memory, saving or loading, for SaveBlob's own path (save_blobs).</summary>
      private sealed class StandInDataStore : IDataStore
      {
         internal readonly Dictionary<string, object> Data = new Dictionary<string, object>();

         internal StandInDataStore(bool saving) { IsSaving = saving; }

         public bool IsSaving { get; }

         public bool IsLoading => !IsSaving;

         public bool SyncData<T>(string key, ref T data)
         {
            if (IsSaving)
            {
               Data[key] = data;

               return true;
            }

            if (key == null || !Data.TryGetValue(key, out object held) || !(held is T typed)) return false;

            data = typed;

            return true;
         }
      }

      private static string TestMemorySettings(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("memory_settings");
         if (t.Skip(behavior.Store == null || Hero.MainHero == null || CrSettings.Instance == null, "no campaign or no MCM")) return t.Line();

         // One with more lived memories than the cap below, so the cap has something to leave out.
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && Mapping.HeroPresence.IsInTheWorld(h)
                                                            && behavior.Store.Get(h.StringId) is NpcProfile p
                                                            && HistoryWindowPolicy.LatestLived(p.Events, int.MaxValue).Count >= 3);
         if (t.Skip(lord == null, "no lord holds 3 memories of the player yet")) return t.Line();

         NpcProfile profile = GetOrCreate(behavior, lord);
         var world = new WorldState {CurrentDay = behavior.GameStateBridge.GetCurrentGameDay()};
         int limitBefore = CrSettings.Instance.PromptMemoryLimit;
         int thresholdBefore = CrSettings.Instance.MemoryCompressionThreshold;
         try
         {
            CrSettings.Instance.PromptMemoryLimit = 0;
            EncounterContext open = EncounterContextBuilder.Build(lord, profile, behavior.GameStateBridge);
            string whole = behavior.LlmServices?.ChatService?.PromptBuilder?.BuildSystemPrompt(profile, world, open) ?? "";
            // STAKE: the default leaves the history as it was before the setting existed.
            t.Expect("noCapByDefault", open?.HistoryMemoryCap == null, true);

            CrSettings.Instance.PromptMemoryLimit = 2;
            EncounterContext capped = EncounterContextBuilder.Build(lord, profile, behavior.GameStateBridge);
            string shorter = behavior.LlmServices?.ChatService?.PromptBuilder?.BuildSystemPrompt(profile, world, capped) ?? "";
            t.Note($"{lord.Name}: {whole.Length} chars with every memory, {shorter.Length} with 2");
            // STAKE (avalanche24): the cap the player set reaches the prompt and makes it shorter.
            t.Expect("theCapReachesThePrompt", capped?.HistoryMemoryCap == 2, true);
            t.Expect("thePromptIsShorter", whole.Length > 0 && shorter.Length < whole.Length, true);

            CrSettings.Instance.MemoryCompressionThreshold = 8;
            // STAKE: the fold point the player set is the one compression reads.
            t.Expect("theFoldPointIsRead", ModSettings.MemoryCompressionThreshold, 8);
         }
         finally
         {
            CrSettings.Instance.PromptMemoryLimit = limitBefore;
            CrSettings.Instance.MemoryCompressionThreshold = thresholdBefore;
         }

         return t.Line();
      }

