      /// <summary>
      ///   The letter box end to end on the real arrival path (Gabriel, 30/10/2026): a letter arrives into the box unread, the
      ///   count rises, the book does not show it, a throw silences its subject from that sender, and the next letter on that
      ///   subject arrives unseen. The test letters carry SenderRemembers so no memory is filed; all are removed after.
      /// </summary>
      private static string TestQuestJournalPlain(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("quest_journal_plain");
         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h.MapFaction != null);
         if (t.Skip(giver == null, "no lord in the world")) return t.Line();

         TaleWorlds.CampaignSystem.Settlements.Settlement town =
            TaleWorlds.CampaignSystem.Settlements.Settlement.All.FirstOrDefault(s => s.IsTown && s.MapFaction != null && s.MapFaction.IsAtWarWith(giver.MapFaction))
            ?? TaleWorlds.CampaignSystem.Settlements.Settlement.All.FirstOrDefault(s => s.IsTown);
         if (t.Skip(town == null, "no town in the world")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         var scout = new InformalQuest {Type = QuestType.ScoutTown, TargetSettlement = town.Name.ToString(), IssuedOnDay = today, DeadlineDay = today + 20};
         Logic.Quests.QuestJournalFacts facts = Quests.CalradiaRemembersQuest.FactsOf(scout, giver);
         string title = Logic.Quests.QuestJournalText.Title(facts) ?? "";
         string steps = Logic.Quests.QuestJournalText.WhatToDo(facts) ?? "";

         t.Expect("theTitleNamesTheTownAndTheGiver", title.Contains(town.Name.ToString()) && title.Contains(giver.Name.ToString()), true);
         t.Expect("theStepsNameTheGangLeaderAndTheChat", steps.Contains("gang leader") && steps.Contains("Calradia Remembers chat"), true);
         t.Expect("theDeadlineIsAGameDate", steps.Contains("Do it by " + CampaignTime.Days(today + 20)), true);

         var forge = new InformalQuest {Type = QuestType.CraftWeapon, RequiredItemCategory = CraftWeaponPolicy.KeyPrefix + "two_handed_sword", RequiredItemCount = 1, IssuedOnDay = today};
         t.Expect("aForgeTaskNamesTheWeapon", Logic.Quests.QuestJournalText.Title(Quests.CalradiaRemembersQuest.FactsOf(forge, giver)), $"Forge a two-handed sword ({giver.Name})");

         int owed = 0, plain = 0;
         foreach (Quests.CalradiaRemembersQuest q in Campaign.Current.QuestManager.Quests.OfType<Quests.CalradiaRemembersQuest>().Where(q => q.IsOngoing).ToList())
         {
            if (!q.OwesPlainSteps) continue;
            owed++;
            if (q.EnsurePlainSteps() && q.HasPlainSteps) plain++;
         }
         t.Expect("everyTaskStillToDoHasItsSteps", plain, owed);

         return t.Line();
      }

      private static string TestLetterBox(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("letter_box");
         if (t.Skip(LetterWindowManager.IsOpen, "a letter window is open; close it first")) return t.Line();

         NpcProfile profile = null;
         foreach (string id in behavior.Store.ListIds())
         {
            NpcProfile p = behavior.Store.Get(id);
            Hero h = p == null ? null : Hero.FindFirst(x => x.StringId == p.Id);
            if (h != null && h != Hero.MainHero && Mapping.ActionGate.Allows(h, ActionKind.Letter)) { profile = p; break; }
         }

         if (t.Skip(profile == null, "no remembered character who may write")) return t.Line();

         if (t.Skip(profile.SentLetters == null, "the correspondent has no letter list")) return t.Line();
         List<string> silencedBefore = profile.SilencedLetterSubjects == null ? null : new List<string>(profile.SilencedLetterSubjects);
         int interestBefore = profile.CorrespondenceInterest;
         string envelopeMemoryId = null;
         var thrownCongratulations = false;
         var thrownNews = false;
         int today = (int)CampaignTime.Now.ToDays;
         PendingLetter Make(LetterReason reason) => new PendingLetter {
            SenderId = profile.Id, SenderName = profile.Name, Reason = reason, Content = "[SELFTEST] letter box", SentOnDay = today,
            DeliveryDay = today, SenderRemembers = true
         };
         var made = new List<PendingLetter>();

         try
         {
            int before = LetterBox.WaitingCount();
            PendingLetter first = Make(LetterReason.RealmTidings);
            made.Add(first);
            profile.SentLetters.Add(first);
            LetterPopupManager.Show(first, profile);
            t.Note($"sender={profile.Name}");
            t.Expect("arrivesIntoTheBox", first.InBox, true);
            t.Expect("theCountRisesByOne", LetterBox.WaitingCount(), before + 1);
            t.Expect("notInTheBookUnread", LetterArchivePolicy.IsArchived(first), false);
            t.Expect("noWindowOpened", LetterWindowManager.IsOpen, false);
            t.Expect("theMapBarBadgeCountsIt", LetterBox.WaitingCountCached(), before + 1);
            t.Expect("theBoxWindowListsIt", new LetterBoxViewModel().Letters.Count, before + 1);

            BoxedLetter boxed = LetterBox.Waiting().FirstOrDefault(b => b.Letter == first);
            LetterBox.Throw(boxed);
            thrownNews = true;
            t.Expect("thrownLeavesTheBox", first.InBox, false);
            t.Expect("newsSilencedFromThisSender", LetterBox.IsSilenced(profile, LetterReason.RealmTidings), true);

            // Never written at all: no placeholder, so no model call (only tried once the silence is in place, so a failure
            // here can never spend a real call).
            if (LetterBox.IsSilenced(profile, LetterReason.RealmTidings))
            {
               int lettersBefore = profile.SentLetters.Count;
               LetterGenerationService.QueueInitialLetter(profile, Hero.FindFirst(x => x.StringId == profile.Id), LetterReason.RealmTidings, "[SELFTEST]", behavior.LlmServices, behavior.Store, today);
               t.Expect("aSilencedSubjectIsNeverWritten", profile.SentLetters.Count, lettersBefore);
               t.Expect("aSilencedCandidateLeavesThePool", LetterBoxPolicy.Unsilenced(new[] {new LetterCandidate {SenderId = profile.Id, Reason = LetterReason.RealmTidings}}, id => behavior.Store.Get(id)?.SilencedLetterSubjects).Count, 0);
            }

            PendingLetter second = Make(LetterReason.RealmTidings);
            made.Add(second);
            profile.SentLetters.Add(second);
            LetterPopupManager.Show(second, profile);
            t.Expect("aSilencedSubjectArrivesUnseen", second.ThrownAway && !second.InBox, true);

            // Step 3 (31/10/2026): a letter sent through the real door travels as an envelope, unwritten, and thrown away it
            // is never written: no model call at all.
            int beforeEnvelope = profile.SentLetters.Count;
            LetterGenerationService.QueueInitialLetter(profile, Hero.FindFirst(x => x.StringId == profile.Id), LetterReason.TournamentVictory, "[SELFTEST] envelope", behavior.LlmServices, behavior.Store, today);
            PendingLetter envelope = profile.SentLetters.Count > beforeEnvelope ? profile.SentLetters[profile.SentLetters.Count - 1] : null;
            if (envelope != null) made.Add(envelope);
            t.Expect("sentAsAnUnwrittenEnvelope", envelope != null && LetterEnvelopePolicy.IsUnwritten(envelope), true);
            if (envelope != null)
            {
               envelopeMemoryId = envelope.MemoryEventId;
               t.Expect("theSenderRemembersWritingIt", !string.IsNullOrEmpty(envelopeMemoryId), true);
               LetterPopupManager.Show(envelope, profile);
               t.Expect("theEnvelopeWaitsInTheBox", envelope.InBox, true);
               LetterBox.Throw(LetterBox.Waiting().FirstOrDefault(b => b.Letter == envelope));
               thrownCongratulations = true;
               t.Expect("thrownUnreadItIsNeverWritten", string.IsNullOrEmpty(envelope.Content), true);
            }

            PendingLetter summons = Make(LetterReason.WarSummons);
            made.Add(summons);
            profile.SentLetters.Add(summons);
            LetterPopupManager.Show(summons, profile);
            LetterBox.Throw(LetterBox.Waiting().FirstOrDefault(b => b.Letter == summons));
            t.Expect("aThrownSummonsSilencesNothing", LetterBox.IsSilenced(profile, LetterReason.WarSummons), false);
         }
         finally
         {
            foreach (PendingLetter l in made) profile.SentLetters.Remove(l);
            if (envelopeMemoryId != null) profile.Events.RemoveAll(e => e.Id == envelopeMemoryId);
            profile.SilencedLetterSubjects = silencedBefore;
            profile.CorrespondenceInterest = interestBefore;
            // The throw cooled the news subject for every writer as an Acknowledge does: give it back.
            if (thrownNews) behavior.LetterEvaluator?.NudgeSubject(LetterReason.RealmTidings, -CorrespondenceInterestPolicy.OnAcknowledge().SubjectDelta);
            if (thrownCongratulations) behavior.LetterEvaluator?.NudgeSubject(LetterReason.TournamentVictory, -CorrespondenceInterestPolicy.OnAcknowledge().SubjectDelta);
            LetterBox.Invalidate();
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestCoinMatchesWords(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("coin_matches_words");
         string id = behavior.Store.ListIds().FirstOrDefault();
         NpcProfile profile = id != null ? behavior.Store.Get(id) : null;
         Hero hero = profile?.Id == null ? null : Hero.FindFirst(h => h != null && h.StringId == profile.Id);
         if (t.Skip(hero == null || Hero.MainHero == null, "no NPC profile with a live hero yet (chat with someone once, then re-run)")) return t.Line();
         if (t.Skip(behavior.LlmServices?.ChatService?.PromptBuilder == null, "the prompt builder is not up")) return t.Line();

         int purse = hero.Gold, playerPurse = Hero.MainHero.Gold, regard = profile.ReputationWithPlayer, gifted = profile.GiftedInWindow;
         int? window = profile.GiftWindowStartDay;
         ActionOutcome Give(int sum) => behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "give_gold", Parameters = new Dictionary<string, string> {["amount"] = sum.ToString()}}, hero, new ActionContext(profile, null));

         try
         {
            hero.ChangeHeroGold(100000 - hero.Gold);
            profile.ReputationWithPlayer = 0;
            profile.GiftedInWindow = 0;
            profile.GiftWindowStartDay = null;

            int ceiling = ExchangeService.GiftCeilingFor(hero, profile);
            t.Expect("aStrangerGivesAShareOfTheirPurse", ceiling, 1000);

            EncounterContext ctx = EncounterContextBuilder.Build(hero, profile, behavior.GameStateBridge, null);
            string prompt = behavior.LlmServices.ChatService.PromptBuilder.BuildSystemPrompt(profile, new WorldState {CurrentDay = (int) CampaignTime.Now.ToDays}, ctx);
            t.Expect("theModelIsToldTheCeilingFirst", prompt.Contains($"you would give {ceiling:N0} at the very most"), true);
            t.Expect("paymentsCountAgainstItToo", prompt.Contains("Every coin you hand the player counts against that"), true);
            t.Expect("theOwedPartIsTheBridgeOne", ctx.GiftOwed, ExchangeService.GiftOwedBy(hero, profile));
            t.Expect("theModelReadsThePriceTable", ctx.PriceReference != null && prompt.Contains(ctx.PriceReference.Trim()), true);

            int before = Hero.MainHero.Gold;
            ActionOutcome first = Give(20000);
            t.Expect("thePlayerReceivesWhatTheModelWasTold", Hero.MainHero.Gold - before, ceiling);
            t.Expect("theNoticeSaysWhyLess", first?.Message?.Contains("not the 20000 named") == true, true);
            // Aporo (10/11/2026): the model reads on its next turn what moved, so the character does not act as if 20,000 had.
            t.Expect("theModelIsToldWhatMoved", LlmFeedbackNotes.ConsumeFor(hero.StringId)?.Contains($"only {ceiling} changed hands") == true, true);

            before = Hero.MainHero.Gold;
            Give(20000);
            t.Expect("askingAgainMovesNothing", Hero.MainHero.Gold - before, 0);
            t.Expect("theModelIsToldNothingMoved", LlmFeedbackNotes.ConsumeFor(hero.StringId)?.Contains("none changed hands") == true, true);

            // Gabriel's token: one fill, so what is spoken, remembered and paid is one sum.
            profile.GiftedInWindow = 0;
            profile.GiftWindowStartDay = null;
            hero.ChangeHeroGold(100000 - hero.Gold);
            EncounterContext live = EncounterContextBuilder.Build(hero, profile, behavior.GameStateBridge, null, offerMoneyTokens: true);
            t.Expect("theGiftTokenIsTheCeiling", live.MoneyTokens?["gift"], ExchangeService.GiftCeilingFor(hero, profile));
            string raw = "[DIALOGUE]Take {gift} denars.[/DIALOGUE]\n[EVENT]\ntype: other\nsummary: I offered {gift} denars.\n[/EVENT]\n[ACTION]\ntype: give_gold\namount: {gift}\n[/ACTION]";
            ParsedResponse read = new NpcMemoryService.Core.Parsing.SectionResponseParser().Parse(NpcMemoryService.Core.Parsing.MoneyTokens.Fill(raw, live.MoneyTokens));
            string sum = live.MoneyTokens["gift"].ToString();
            t.Expect("theLineCarriesTheSum", read.Dialogue, $"Take {sum} denars.");
            t.Expect("theMemoryCarriesTheSameSum", read.NewEventData?.Summary?.Contains(sum), true);
            before = Hero.MainHero.Gold;
            behavior.GameStateBridge.ExecuteAction(read.Actions[0], hero, new ActionContext(profile, null));
            t.Expect("thePlayerReceivesTheSum", (Hero.MainHero.Gold - before).ToString(), sum);

            // The door moves nothing for no sum: a refused price must not become a payment of a coin.
            before = Hero.MainHero.Gold;
            ExchangeService.Pay(ExchangeKind.ItemSale, hero, Hero.MainHero, 0);
            t.Expect("noSumMovesNothing", Hero.MainHero.Gold - before, 0);
         }
         finally
         {
            hero.ChangeHeroGold(purse - hero.Gold);
            Hero.MainHero.ChangeHeroGold(playerPurse - Hero.MainHero.Gold);
            profile.ReputationWithPlayer = regard;
            profile.GiftedInWindow = gifted;
            profile.GiftWindowStartDay = window;
            LlmFeedbackNotes.ConsumeFor(hero.StringId);
         }

         return t.Line();
      }

      private static string TestMemoryDiscussed(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("memory_discussed");
         const string tagged = "CRSELFTEST: we cleared the Hollowmere road together.";
         const string quiet = "CRSELFTEST: we shared a fire at the Hollowmere ford.";

         string id = behavior.Store.ListIds().FirstOrDefault();
         NpcProfile profile = id != null ? behavior.Store.Get(id) : null;
         Hero hero = profile?.Id == null ? null : Hero.FindFirst(h => h != null && h.StringId == profile.Id);
         if (t.Skip(hero == null, "no NPC profile with a live hero yet (chat with someone once, then re-run)")) return t.Line();
         if (t.Skip(behavior.LlmServices?.ChatService?.PromptBuilder == null, "the prompt builder is not up")) return t.Line();

         IPromptBuilder builder = behavior.LlmServices.ChatService.PromptBuilder;
         int today = behavior.GameStateBridge?.GetCurrentGameDay() ?? (int) CampaignTime.Now.ToDays;
         string Prompt(ChatViewModel vm) => builder.BuildSystemPrompt(profile, new WorldState {CurrentDay = today},
            EncounterContextBuilder.Build(hero, profile, behavior.GameStateBridge, null, memoriesDiscussedAtOpening: vm.MemoriesDiscussedAtOpening(profile)));

         try
         {
            profile.Events.Add(new NotableEvent(today, NotableEventType.Other, tagged));
            profile.Events.Add(new NotableEvent(today, NotableEventType.Other, quiet));
            var talk = new ChatViewModel();
            string opening = Prompt(talk);
            NotableEvent memory = profile.Events.First(e => e.summary == tagged);
            NotableEvent other = profile.Events.First(e => e.summary == quiet);
            t.Expect("theMemoryCarriesACode", opening.Contains($" {memory.ShortUid}: {tagged}"), true);
            t.Expect("theTagIsTaught", opening.Contains("[DISCUSSED]"), true);

            // The Enhanced road: the interpreter's reading replaces the deeds, the tag stays the writer's.
            ParsedResponse written = new NpcMemoryService.Core.Parsing.SectionResponseParser().Parse($"[DIALOGUE]Aye, that road.[/DIALOGUE]\n[DISCUSSED]\nmemories: {memory.ShortUid}\n[/DISCUSSED]");
            ParsedResponse spliced = ActionInterpreterComposer.WithInterpretedTags(written, new ParsedResponse {Dialogue = ""});
            ProfileMutator.Apply(profile, spliced, today, romanticContentEnabled: false);
            t.Expect("theTaggedMemoryIsMarked", memory.DiscussedDay, today);
            t.Expect("theOtherIsNot", other.DiscussedDay, null);

            t.Expect("theTalksCachedLinesDoNotMove", NpcMemoryService.Core.Prompts.PromptCacheSplit.StablePrefixOf(Prompt(talk)) == NpcMemoryService.Core.Prompts.PromptCacheSplit.StablePrefixOf(opening), true);

            string next = Prompt(new ChatViewModel());
            t.Expect("theNextConversationReadsItAsDiscussed", next.Contains("[already discussed with"), true);
            t.Expect("theMemoryItselfIsStillThere", next.Contains(tagged), true);
         }
         finally
         {
            profile.Events.RemoveAll(e => e?.summary == tagged || e?.summary == quiet);
         }

         return t.Line();
      }

      private sealed class LetterAnswerClient : NpcMemoryService.Core.LlmClient.ILlmClient
      {
         private readonly string _answer;

         public LetterAnswerClient(string answer) => _answer = answer;

         public string LastPrompt { get; private set; }

         public System.Threading.Tasks.Task<LlmResponse> CompleteAsync(LlmRequest request, CancellationToken ct = default)
         {
            LastPrompt = request.SystemPrompt;

            return System.Threading.Tasks.Task.FromResult(new LlmResponse {Content = _answer ?? "", IsSuccess = _answer != null});
         }
      }

      private static string TestFixedLetterTranslation(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("fixed_letter_translation");
         CrSettings s = CrSettings.Instance;
         if (t.Skip(s == null, "no MCM settings")) return t.Line();

         NpcProfile profile = behavior.Store.ListIds().Select(id => behavior.Store.Get(id)).FirstOrDefault(p => p != null);
         if (t.Skip(profile == null, "no remembered character")) return t.Line();

         const string english = "[SELFTEST] Send me 5000 denars.";
         PendingLetter Threat() => new PendingLetter {SenderId = profile.Id, SenderName = profile.Name, Reason = LetterReason.Blackmail, Content = english};
         string Run(string answer)
         {
            var boxed = new BoxedLetter {Letter = Threat(), Sender = profile};
            var client = new LetterAnswerClient(answer);
            LetterBox.ApplyTranslation(boxed, LetterGenerationService.TranslateFixedLetterAsync(boxed.Letter, profile, client).GetAwaiter().GetResult());
            if (answer != null) t.Expect("theModelIsToldTheLanguage", client.LastPrompt?.Contains("into French"), true);

            return boxed.Letter.Content;
         }

         string languageBefore = s.ReplyLanguage;
         try
         {
            s.ReplyLanguage = "French";
            t.Expect("aFixedLetterAsksForItsLanguage", LetterBox.WillTranslate(Threat()), true);
            t.Expect("aModelWrittenLetterDoesNot", LetterBox.WillTranslate(new PendingLetter {Reason = LetterReason.RealmTidings, Content = english}), false);
            t.Expect("theTranslationLandsInTheLetter", Run("[SELFTEST] Envoyez-moi 5 000 deniers."), "[SELFTEST] Envoyez-moi 5 000 deniers.");
            t.Expect("aLostNumberLeavesTheEnglish", Run("[SELFTEST] Envoyez-moi de l'or."), english);
            t.Expect("aFailedCallLeavesTheEnglish", Run(null), english);

            s.ReplyLanguage = "English";
            t.Expect("anEnglishPlayerSpendsNoCall", LetterBox.WillTranslate(Threat()), false);
         }
         finally
         {
            s.ReplyLanguage = languageBefore;
         }

         return t.Line();
      }

