      /// <summary>
      ///   Prisoner trade, the buy direction end to end: a real lord is taken captive into the player's
      ///   party, a second lord (the buyer) purchases him through the real bridge action, and the test
      ///   asserts the gold moved to the player (clamped by PrisonerTradePolicy around the ransom anchor)
      ///   and the captive left the player's custody. Cleanup releases the captive whatever happened.
      /// </summary>
      private static string TestPrisonerTrade(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prisoner_trade");

         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h);

         if (t.Skip(captive == null, "no free lord to take captive")) return t.Line();

         // The buyer must be able to raise the CEILING, not merely the floor. PrisonerRansomExecutor pays
         // Math.Min(clampedPrice, buyer.Gold) by design (a broke buyer must not be handed a hostage for a
         // pittance, and GiveGoldAction self-clamps to the purse anyway), so a poorer buyer legitimately pays
         // less than the clamp and this test's whole assertion is about the clamp. Picking the first lord in
         // the list made the result turn on how rich that lord happened to be: it FAILED on 2026-09-09 with
         // "paid=4550 (expected 7650)" against a solvent-but-not-wealthy Arion, reporting a product bug where
         // there was none. A self-test must never depend on which hero the campaign lists first.
         int ceilingForCaptive = PrisonerTradePolicy.ClampPrice(999999, BuyPrisonerVerb.RansomAnchor(captive));

         Hero buyer = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h != captive && h.IsLord && !h.IsPrisoner && h.Clan != captive.Clan
            && h.Gold >= ceilingForCaptive && BuyPrisonerVerb.BondTo(h, captive) == CaptiveBond.None);

         if (t.Skip(buyer == null, $"no lord solvent enough ({ceilingForCaptive}g) to prove the price clamp rather than their purse"))
            return t.Line();

         NpcProfile profile = GetOrCreate(behavior, buyer);

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);

         if (t.Abort(!captive.IsPrisoner, "could not take the test captive")) return t.Line();

         try
         {
            int goldBefore = Hero.MainHero.Gold;
            int anchor = BuyPrisonerVerb.RansomAnchor(captive);

            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
               new GameAction {
                  Type = "buy_prisoner",
                  Parameters = new Dictionary<string, string> {
                     {"target", captive.Name.ToString()},
                     {"price", "999999"} // an absurd ask, so the clamp itself is what gets proven
                  }
               }, buyer, new ActionContext(profile, null));

            int paid = Hero.MainHero.Gold - goldBefore;
            int expected = PrisonerTradePolicy.ClampPrice(999999, anchor);
            bool leftCustody = BuyPrisonerVerb.PlayerHeldHeroPrisoners().All(h => h != captive);

            t.Note($"captive={captive.Name}, buyer={buyer.Name}, anchor={anchor}, paid={paid} (expected {expected}), outcome=\"{outcome?.Message}\"");
            t.Expect("outcomePositive", outcome?.IsPositive, true);
            t.Expect("paidTheClampedPrice", paid == expected, true);
            t.Expect("captiveLeftPlayerCustody", leftCustody, true);
         }
         finally
         {
            // Whatever happened, the test lord goes free so the campaign is left unharmed.
            try
            {
               if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive, buyer);
            }
            catch
            {
               /* best-effort cleanup */
            }
         }

         return t.Line();
      }

      /// <summary>
      ///   A lord free in a party, not his clan's leader, whose clan leader is free, alive and not the player: the
      ///   captive and the kinsman who will ransom him. Null when this campaign has no such pair.
      /// </summary>
      private static Hero CaptiveWithFreeClanLeader()
         => Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsChild && h.PartyBelongedTo != null
            && h.Clan != null && h.Clan != Clan.PlayerClan && h.Clan.Leader != null && h.Clan.Leader != h
            && h.Clan.Leader != Hero.MainHero && h.Clan.Leader.IsAlive && !h.Clan.Leader.IsPrisoner);

      /// <summary>
      ///   The own-side ransom, shared by prisoner_ransom_home and prisoner_gift: take the captive, have his clan
      ///   leader run buy_prisoner with <paramref name="parameters" />, and report what the player was paid. Both
      ///   purses are restored and the captive freed whatever happened.
      /// </summary>
      private static void RunOwnSideRansom(TestRun t, NpcMemoryCampaignBehavior behavior, Hero captive, Dictionary<string, string> parameters, Action<int, ActionOutcome> check)
      {
         Hero buyer = captive.Clan.Leader;
         int playerGold0 = Hero.MainHero.Gold;
         int buyerGold0 = buyer.Gold;

         int ceiling = PrisonerTradePolicy.ClampPrice(999999, BuyPrisonerVerb.RansomAnchor(captive), BuyPrisonerVerb.BondTo(buyer, captive));
         if (buyer.Gold < ceiling) buyer.ChangeHeroGold(ceiling - buyer.Gold); // solvent, so the clamp is what is proven

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);

         try
         {
            if (t.Abort(!captive.IsPrisoner, $"could not take {captive.Name} captive")) return;

            parameters["target"] = captive.Name.ToString();
            int before = Hero.MainHero.Gold;
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
               new GameAction {Type = "buy_prisoner", Parameters = parameters}, buyer, new ActionContext(GetOrCreate(behavior, buyer), null));

            t.Note($"captive={captive.Name}, his clan leader={buyer.Name}, outcome=\"{outcome?.Message}\"");
            t.Expect("outcomePositive", outcome?.IsPositive == true && outcome.WasRefused == false, true);
            t.Expect("captiveWentHomeFree", captive.IsPrisoner, false);
            t.Expect("captiveLeftPlayerCustody", BuyPrisonerVerb.PlayerHeldHeroPrisoners().All(h => h != captive), true);
            check(Hero.MainHero.Gold - before, outcome);
         }
         finally
         {
            try { if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive, buyer); }
            catch { /* best-effort cleanup */ }

            Hero.MainHero.ChangeHeroGold(playerGold0 - Hero.MainHero.Gold);
            buyer.ChangeHeroGold(buyerGold0 - buyer.Gold);
         }
      }

      /// <summary>
      ///   fkasad (26/09/2026): a captive ransomed by his OWN count was transferred into his own side's cells, and the
      ///   game reported him escaped. Bought by his own house, he now goes home free by ransom; this proves it on a
      ///   real lord, with the player paid the clamped price all the same.
      /// </summary>
      private static string TestPrisonerRansomHome(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prisoner_ransom_home");

         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Hero captive = CaptiveWithFreeClanLeader();
         if (t.Skip(captive == null, "no free lord whose clan leader is free to ransom him")) return t.Line();

         // The clan leader is often his father or brother, who pays more (Thoragoros1, 03/11/2026).
         int expected = PrisonerTradePolicy.ClampPrice(999999, BuyPrisonerVerb.RansomAnchor(captive), BuyPrisonerVerb.BondTo(captive.Clan.Leader, captive));
         RunOwnSideRansom(t, behavior, captive, new Dictionary<string, string> {["price"] = "999999"}, (paid, outcome) =>
         {
            t.Note($"paid={paid} (expected {expected}); told: {outcome?.Message}");
            t.Expect("paidTheClampedPrice", paid == expected, true);
            // tashmetu (27/09/2026): a figure paid short of the one named says why, so nobody invents a reason.
            if (expected < 999999) t.Expect("toldWhyLessWasPaid", outcome?.Message?.Contains("(not the 999999 named: ") == true, true);
         });

         return t.Line();
      }

      /// <summary>
      ///   fkasad (26/09/2026): telling an envoy the prisoner was his for 0 denars paid him the whole budget. The
      ///   envoy's binder now writes a gift (EnvoyMandatePolicy.Bind, unit-tested); this proves the verb honours it on
      ///   a real lord: no gold moves, and the captive goes home.
      /// </summary>
      private static string TestPrisonerGift(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prisoner_gift");

         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Hero captive = CaptiveWithFreeClanLeader();
         if (t.Skip(captive == null, "no free lord whose clan leader is free to receive him")) return t.Line();

         // Exactly what the envoy's binder hands the bridge for "yours for nothing".
         EnvoyDeal deal = EnvoyMandatePolicy.Bind("buy_prisoner", new Dictionary<string, string> {["price"] = "0"},
            new EnvoyMandate {WantedCaptiveName = captive.Name.ToString(), RansomCeiling = 5000},
            new EnvoyTurnFacts {PlayerLine = "He is yours for nothing."});

         if (t.Abort(deal == null, "the envoy's binder produced no deal for a gift")) return t.Line();

         RunOwnSideRansom(t, behavior, captive, new Dictionary<string, string>(deal.Parameters), (paid, outcome) =>
         {
            t.Note($"paid={paid}");
            t.Expect("noGoldMoved", paid, 0);
            t.Expect("toldItWasAGift", outcome?.Message?.Contains("for nothing") == true, true);
         });

         return t.Line();
      }

      /// <summary>
      ///   The exchange end to end on real lords (fkasad, 25/09/2026; Gabriel: heroes only). The player takes lord A;
      ///   lord B's own party takes lord C, of neither B's house nor the player's realm. B then trades C for A through
      ///   the real bridge: A is B's kin and goes home FREE, C changes gaolers into the player's party, and the gold
      ///   that evens the swap moves as PrisonerExchangePolicy.GoldToSettle says.
      /// </summary>
      private static string TestExchangePrisoners(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("exchange_prisoners");

         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Hero a = CaptiveWithFreeClanLeader();
         Hero b = a?.Clan.Leader;
         if (t.Skip(a == null, "no free lord whose clan leader is free to trade for him")) return t.Line();
         if (t.Skip(b.PartyBelongedTo?.Party == null || b.PartyBelongedTo.LeaderHero != b, $"{b.Name} leads no party to hold a captive in")) return t.Line();

         IFaction playerRealm = Hero.MainHero.MapFaction;
         Hero c = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h != a && h != b && h.IsLord && !h.IsPrisoner && !h.IsChild && h.PartyBelongedTo != null
            && h.Clan != null && h.Clan != b.Clan && h.Clan != Clan.PlayerClan && h.Clan.Leader != h
            && h.MapFaction != b.MapFaction && h.MapFaction != playerRealm);
         if (t.Skip(c == null, "no third lord, of neither side, for B to hold")) return t.Line();

         int playerGold0 = Hero.MainHero.Gold;
         int bGold0 = b.Gold;
         int gold = PrisonerExchangePolicy.GoldToSettle(BuyPrisonerVerb.RansomAnchor(a), BuyPrisonerVerb.RansomAnchor(c));
         if (gold > 0 && b.Gold < gold) b.ChangeHeroGold(gold - b.Gold);
         if (gold < 0 && Hero.MainHero.Gold < -gold) Hero.MainHero.ChangeHeroGold(-gold - Hero.MainHero.Gold);

         TakePrisonerAction.Apply(PartyBase.MainParty, a);
         TakePrisonerAction.Apply(b.PartyBelongedTo.Party, c);

         try
         {
            if (t.Abort(!a.IsPrisoner || !c.IsPrisoner, $"could not set the table ({a.Name} held={a.IsPrisoner}, {c.Name} held={c.IsPrisoner})")) return t.Line();

            int before = Hero.MainHero.Gold;
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
               new GameAction {
                  Type = "exchange_prisoners",
                  Parameters = new Dictionary<string, string> {["give"] = a.Name.ToString(), ["receive"] = c.Name.ToString()}
               }, b, new ActionContext(GetOrCreate(behavior, b), null));

            int paid = Hero.MainHero.Gold - before;
            t.Note($"A={a.Name} (player's), B={b.Name}, C={c.Name} (B's), gold to the player {paid} (expected {gold}), outcome=\"{outcome?.Message}\"");
            t.Expect("outcomePositive", outcome?.IsPositive == true && outcome.WasRefused == false, true);
            t.Expect("kinWentHomeFree", a.IsPrisoner, false);
            t.Expect("receivedIsThePlayersPrisoner", c.IsPrisoner && c.PartyBelongedToAsPrisoner == PartyBase.MainParty, true);
            t.Expect("goldEvenedTheSwap", paid, gold);
         }
         finally
         {
            try { if (a.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(a, b); }
            catch { /* best-effort cleanup */ }

            try { if (c.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(c, Hero.MainHero); }
            catch { /* best-effort cleanup */ }

            Hero.MainHero.ChangeHeroGold(playerGold0 - Hero.MainHero.Gold);
            b.ChangeHeroGold(bGold0 - b.Gold);
         }

         return t.Line();
      }

      /// <summary>
      ///   Player report: a ransom-offer letter showed only a Close button (no Accept) for a captured lord who had
      ///   NOT escaped, because he sat in the player's own town dungeon and the held-prisoner enumeration only
      ///   looked at the travelling party. Captures a real in-party lord, moves him into a player-owned settlement's
      ///   prison, and asserts BuyPrisonerVerb.PlayerHeldHeroPrisoners still counts him there. Frees him in cleanup.
      /// </summary>
      private static string TestPrisonerCustodySettlement(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prisoner_custody_settlement");

         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Settlement prison = Clan.PlayerClan?.Settlements?.FirstOrDefault(s =>
            s != null && (s.IsTown || s.IsCastle) && s.Party != null);

         // GABRIEL'S RULE (13/10/2026) considered and declined: PlayerHeldHeroPrisoners() (BuyPrisonerVerb.cs)
         // reads REAL ownership off Clan.PlayerClan.Settlements, so arranging this would mean a real
         // ChangeOwnerOfSettlementAction transfer. That fires CampaignEventDispatcher.OnSettlementOwnerChanged
         // to every listener (garrison spin-up, notable reactions, diplomatic stance recalculation, and CR's
         // own world-event feeders may record the seizure as a lasting memory a later transfer-back would NOT
         // undo), which is not a self-test's to risk for one assertion. MANUAL stays, for this reason, not
         // merely because the fact is missing.
         if (t.Skip(prison == null, "the player owns no town or castle to hold a prisoner in, and arranging one would require a real, hard-to-cleanly-reverse settlement-ownership transfer")) return t.Line();

         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h);

         if (t.Skip(captive == null, "no free in-party lord to capture")) return t.Line();

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);

         if (t.Abort(!captive.IsPrisoner, $"could not take {captive.Name} captive")) return t.Line();

         try
         {
            TransferPrisonerAction.Apply(captive.CharacterObject, PartyBase.MainParty, prison.Party);

            bool inSettlement = captive.PartyBelongedToAsPrisoner == prison.Party;
            bool counted = BuyPrisonerVerb.PlayerHeldHeroPrisoners().Contains(captive);

            t.Note($"captive={captive.Name}, dungeon={prison.Name}, heldInSettlement={inSettlement}, counted={counted}");
            t.Expect("movedToSettlementDungeon", inSettlement, true);
            t.Expect("countedAsPlayerHeldFromTheDungeon", counted, true);
         }
         finally
         {
            // Whatever happened, the test lord goes free so the campaign is left unharmed.
            try
            {
               if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive, Hero.MainHero);
            }
            catch
            {
               /* best-effort cleanup */
            }
         }

         return t.Line();
      }

      /// <summary>
      ///   Player report (Mimo, Standard/Roleplay mode): holding a captive and ordering them kept safe still
      ///   planted a CaptiveAbuse grudge. Drives the REAL grudge-decision chain the closed captor scene now uses
      ///   (intent severity -> CaptorSceneGrudgePolicy with no conduct read -> Tier2GrudgeRules) and asserts a
      ///   merciful lesser intent forms nothing while Torture still forms. Pure, plants no grudge, needs no setup.
      /// </summary>
      private static string TestCaptorGrudgeConduct(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captor_grudge_conduct");

         bool interrogation = CaptorGrudgeFormsWithoutRead(CaptiveSceneIntent.Interrogation);
         bool domination = CaptorGrudgeFormsWithoutRead(CaptiveSceneIntent.Domination);
         bool personalDesire = CaptorGrudgeFormsWithoutRead(CaptiveSceneIntent.PersonalDesire);
         bool torture = CaptorGrudgeFormsWithoutRead(CaptiveSceneIntent.Torture);

         t.Note($"no-read grudge forms: interrogation={interrogation}, domination={domination}, personalDesire={personalDesire}, torture={torture}");
         t.Expect("mercifulInterrogationFormsNoGrudge", interrogation, false);
         t.Expect("mercifulDominationFormsNoGrudge", domination, false);
         t.Expect("mercifulPersonalDesireFormsNoGrudge", personalDesire, false);
         t.Expect("tortureStillForms", torture, true);

         return t.Line();
      }

      /// <summary>Whether a closed captor scene of this intent would plant a grudge with NO conduct read, via the real production chain.</summary>
      private static bool CaptorGrudgeFormsWithoutRead(CaptiveSceneIntent intent)
      {
         int severity = CaptorSceneGrudgePolicy.GrudgeSeverity(CaptiveIntentRules.CaptiveAbuseSeverity(intent), null);

         return Tier2GrudgeRules.CaptiveAbuseGrudge(
            new CaptiveAbuseFacts {Severity = severity, PlayerWasThePerpetrator = true}).Forms;
      }

      // ── Tests ─────────────────────────────────────────────────────────────

      // ── Unknown-verb refusal (feedback funnel). The model can emit an [ACTION] whose type has no executor ──
      // ── (an invented "grant a fief" / "bless a marriage"). The bridge must refuse it AND flag it as an ──
      // ── unknown verb, carrying the deed-scoped base message, so the chat can log the invented verb for the ──
      // ── author and show the immersive notice instead of the old "(That cannot be done here. Nothing ──
      // ── happened.)" that read as contradicting a triumphant scene where a +1 regard and a quest DID land. ──
      // ── A refusal touches no game state, so nothing needs restoring. ──────────────────────────────────────

      private static string TestUnknownActionNotice(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("unknown_action_notice");

         Hero npc = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner);

         if (t.Abort(npc == null, "no live lord to address")) return t.Line();

         ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "grant_fief_to_player_xyz"},
            npc, null);

         if (t.Abort(outcome == null, "the bridge returned null instead of a refusal")) return t.Line();

         t.Note($"npc={npc.Name}");
         t.Expect("refused", outcome.WasRefused, true);
         t.Expect("unknownVerb", outcome.WasUnknownVerb, true);
         t.Expect("message", outcome.Message, UnknownActionNotice.BaseMessage);

         return t.Line();
      }

      private static string TestSecretLoverLeak(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("secret_lover_leak");

         if (t.Abort(WorldEvents.SecretLoverGossipBehavior.Instance == null || WorldEvents.WorldEventStore.Instance == null,
                "secret-lover / world-event behavior not initialized")) return t.Line();

         Hero subject = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsAlive && !h.IsPrisoner);
         if (t.Abort(subject == null, "no live hero to stand in as the secret-lover subject")) return t.Line();

         string id = "cr_secretlover_" + subject.StringId;
         WorldEvents.WorldEventStore.Instance.Remove(id); // clear any prior residue so the assertion is clean

         try
         {
            bool forced = WorldEvents.SecretLoverGossipBehavior.Instance.DebugForceLeak(subject);
            if (t.Abort(!forced, "DebugForceLeak returned false")) return t.Line();

            WorldEvents.WorldEvent we = WorldEvents.WorldEventStore.Instance.GetById(id);

            t.Note($"subject={subject.Name}");
            t.Expect("whisper recorded", we != null, true);
            t.Expect("identity hidden (InvolvesPlayer)", we?.InvolvesPlayer, false);
            t.Expect("subject is the actor", we != null && we.ActorIds != null && we.ActorIds.Contains(subject.StringId), true);
            t.Expect("gossip-worthy magnitude", we != null && we.Magnitude >= 55, true);
         }
         finally
         {
            WorldEvents.WorldEventStore.Instance.Remove(id);
         }

         return t.Line();
      }

      private static string TestAdmitSecretLover(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("admit_secret_lover");

         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Abort(gossip == null || behavior?.Store == null || behavior.GameStateBridge == null,
                "secret-lover behavior / store / bridge not initialized")) return t.Line();

         Hero npc = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner);
         if (t.Abort(npc == null, "no live lord to confess to")) return t.Line();

         // A companion stands in as the hidden lover: PlayerSecretLoverSubjectIds only counts companions.
         // Arranged per GABRIEL'S RULE (13/10/2026): minted when the player has none at all.
         using var arranged = ArrangedCompanion.Get(behavior, exclude: npc);
         if (t.Abort(arranged == null, "no wanderer template available to arrange a secret-lover subject from")) return t.Line();
         Hero subject = arranged.Companion;

         NpcProfile subjectProfile = GetOrCreate(behavior, subject);
         if (subjectProfile.Romantic == null) subjectProfile.Romantic = new RomanticProfile();
         bool prevFlag = subjectProfile.Romantic.IsSecretLover;
         RomanticStatus prevStatus = subjectProfile.Romantic.Status;

         NpcProfile npcProfile = GetOrCreate(behavior, npc);
         int memoryCountBefore = npcProfile.Events?.Count ?? 0;

         try
         {
            subjectProfile.Romantic.IsSecretLover = true;
            subjectProfile.Romantic.Status = RomanticStatus.SecretLover;
            behavior.Store.Set(subjectProfile);
            gossip.ForgetKnows(npc, subject.StringId); // clean slate

            string prompted = EncounterContextBuilder.Build(npc, npcProfile, behavior.GameStateBridge, "About the whispers.").ExtraActionTeachings;
            bool taughtBefore = prompted?.Contains("type: admit_secret_lover") == true;

            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
               new GameAction {Type = "admit_secret_lover"}, npc, new ActionContext(npcProfile, null));

            if (t.Abort(outcome == null, "the bridge returned null instead of an outcome")) return t.Line();

            t.Note($"npc={npc.Name} subject={subject.Name}");
            t.Expect("confession upheld", outcome.IsPositive, true);
            t.Expect("the lord now knows the identity", gossip.Knows(npc.StringId, subject.StringId), true);
            // STAKE: and before he knew, the confession was taught in his REAL prompt: the verb sat in no list until 22/10/2026.
            t.Expect("the confession was taught in his prompt", taughtBefore, true);
            t.Expect("the confession is remembered", (npcProfile.Events?.Count ?? 0) > memoryCountBefore, true);
            // The identity is never deduced, only confessed: a lord who was NOT told stays ignorant.
            t.Expect("an untold lord stays ignorant", gossip.Knows("cr_never_told_lord", subject.StringId), false);
         }
         finally
         {
            subjectProfile.Romantic.IsSecretLover = prevFlag;
            subjectProfile.Romantic.Status = prevStatus;
            behavior.Store.Set(subjectProfile);
            gossip.ForgetKnows(npc, subject.StringId);
            if (npcProfile.Events != null)
               while (npcProfile.Events.Count > memoryCountBefore) npcProfile.Events.RemoveAt(npcProfile.Events.Count - 1);
            behavior.Store.Set(npcProfile);
         }

         return t.Line();
      }

      private static string TestEveryVerbTaught(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("every_verb_taught");

         List<string> own = Verbs.VerbRegistry.Instance.OwnNames;
         if (t.Abort(own.Count == 0, "the verb registry is empty")) return t.Line();

         var covered = new HashSet<string>(EncounterContextBuilder.VerbsInTeachingLists.Concat(EncounterContextBuilder.VerbsTaughtElsewhere), StringComparer.OrdinalIgnoreCase);
         List<string> untaught = own.Where(n => !covered.Contains(n)).ToList();
         t.Note($"verbs={own.Count}");
         // STAKE: a verb in no list is executable but never taught: the model meets it as a bare catalogue line.
         t.Expect("untaught", string.Join(",", untaught), "");
         // STAKE: a name in a list that no verb carries is a typo, and the verb it meant is untaught.
         t.Expect("listedButUnregistered", string.Join(",", covered.Where(n => !own.Contains(n, StringComparer.OrdinalIgnoreCase))), "");

         return t.Line();
      }

      private static string TestHeldSecret(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("held_secret");

         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Abort(gossip == null || behavior?.Store == null || behavior.GameStateBridge == null,
                "secret-lover behavior / store / bridge not initialized")) return t.Line();

         Hero npc = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner);
         if (t.Abort(npc == null, "no live lord to hold the secret")) return t.Line();

         // Arranged per GABRIEL'S RULE (13/10/2026): minted when the player has no companion at all.
         using var arranged = ArrangedCompanion.Get(behavior, exclude: npc);
         if (t.Abort(arranged == null, "no wanderer template available to arrange a secret-lover subject from")) return t.Line();
         Hero subject = arranged.Companion;

         NpcProfile subjectProfile = GetOrCreate(behavior, subject);
         if (subjectProfile.Romantic == null) subjectProfile.Romantic = new RomanticProfile();
         bool prevFlag = subjectProfile.Romantic.IsSecretLover;
         RomanticStatus prevStatus = subjectProfile.Romantic.Status;
         NpcProfile npcProfile = GetOrCreate(behavior, npc);

         try
         {
            subjectProfile.Romantic.IsSecretLover = true;
            subjectProfile.Romantic.Status = RomanticStatus.SecretLover;
            behavior.Store.Set(subjectProfile);
            gossip.RecordKnows(npc, subject.StringId);

            EncounterContext ctx = EncounterContextBuilder.Build(npc, npcProfile, behavior.GameStateBridge, "hello");
            bool adultOn = ModSettings.AdultContentLevel != AdultContentLevel.Off;
            t.Note($"npc={npc.Name} subject={subject.Name} adultLevel={ModSettings.AdultContentLevel}");

            if (adultOn)
            {
               string subjectName = subject.Name?.ToString() ?? "";
               t.Expect("a lord who was told surfaces the subject",
                  !string.IsNullOrEmpty(ctx.HeldSecretLoverSubject) && ctx.HeldSecretLoverSubject.Contains(subjectName), true);
            }
            else
            {
               // The adult-content gate holds: no held-secret injection at all when the feature is off.
               t.Expect("the adult gate suppresses the held secret", string.IsNullOrEmpty(ctx.HeldSecretLoverSubject), true);
            }
         }
         finally
         {
            subjectProfile.Romantic.IsSecretLover = prevFlag;
            subjectProfile.Romantic.Status = prevStatus;
            behavior.Store.Set(subjectProfile);
            gossip.ForgetKnows(npc, subject.StringId);
         }

         return t.Line();
      }

      private static string TestSecretPropagation(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("secret_propagation");

         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Abort(gossip == null || behavior?.Store == null, "secret-lover behavior / store not initialized")) return t.Line();
         if (t.Abort(Hero.MainHero == null, "no main hero")) return t.Line();

         // A teller who actually has a friend (relation >= the propagation floor) to confide in.
         Hero teller = null;
         foreach (Hero cand in Hero.AllAliveHeroes.Where(h => h != null && h != Hero.MainHero && h.IsLord && !h.IsPrisoner))
         {
            if (Hero.AllAliveHeroes.Any(f => f != null && f != cand && f != Hero.MainHero && !f.IsPrisoner
                   && CalradiaRemembers.Logic.Romance.SecretPropagationPolicy.IsFriend(new NpcMemoryService.Core.Standing.VanillaRelation(Mapping.PairBondReader.Points(cand, f)))))
            {
               teller = cand;
               break;
            }
         }

         if (t.Abort(teller == null, "no lord with a friend to propagate to")) return t.Line();

         Hero subject = Hero.AllAliveHeroes.FirstOrDefault(h => h != null && h != Hero.MainHero && h != teller && h.IsAlive);
         if (t.Abort(subject == null, "no hero to stand in as the secret-lover subject")) return t.Line();

         // Force the teller to a neutral personal regard so the "a friend of the player guards it" gate does not skip.
         NpcProfile tellerProfile = GetOrCreate(behavior, teller);
         int prevRegard = tellerProfile.ReputationWithPlayer;

         string told = null;
         try
         {
            tellerProfile.ReputationWithPlayer = 0;
            behavior.Store.Set(tellerProfile);
            gossip.ForgetKnows(teller, subject.StringId);
            gossip.RecordKnows(teller, subject.StringId);

            told = gossip.DebugSpreadOnce(teller, subject.StringId);

            t.Note($"teller={teller.Name} subject={subject.Name} told={(told == null ? "(none)" : told)}");
            t.Expect("the secret reached a friend", !string.IsNullOrEmpty(told), true);
            t.Expect("that friend now knows", told != null && gossip.Knows(told, subject.StringId), true);
            t.Expect("the friend is not the player", told != Hero.MainHero.StringId, true);
         }
         finally
         {
            gossip.ForgetKnows(teller, subject.StringId);
            if (told != null)
            {
               Hero friend = Hero.AllAliveHeroes.FirstOrDefault(h => h != null && h.StringId == told);
               if (friend != null) gossip.ForgetKnows(friend, subject.StringId);
            }

            tellerProfile.ReputationWithPlayer = prevRegard;
            behavior.Store.Set(tellerProfile);
         }

         return t.Line();
      }

      private static string TestPayForSilence(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("pay_for_silence");

         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Abort(gossip == null || behavior?.Store == null || behavior.GameStateBridge == null,
                "secret-lover behavior / store / bridge not initialized")) return t.Line();

         Hero npc = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner);
         if (t.Abort(npc == null, "no live lord to hold the secret")) return t.Line();

         // Arranged per GABRIEL'S RULE (13/10/2026): minted when the player has no companion at all.
         using var arranged = ArrangedCompanion.Get(behavior, exclude: npc);
         if (t.Abort(arranged == null, "no wanderer template available to arrange a secret-lover subject from")) return t.Line();
         Hero subject = arranged.Companion;

         NpcProfile subjectProfile = GetOrCreate(behavior, subject);
         if (subjectProfile.Romantic == null) subjectProfile.Romantic = new RomanticProfile();
         bool prevFlag = subjectProfile.Romantic.IsSecretLover;
         RomanticStatus prevStatus = subjectProfile.Romantic.Status;
         NpcProfile npcProfile = GetOrCreate(behavior, npc);
         int memoryCountBefore = npcProfile.Events?.Count ?? 0;

         int playerGold0 = Hero.MainHero.Gold;
         int npcGold0 = npc.Gold;
         int price = CalradiaRemembers.Logic.Bastards.HushMoneyPolicy.MinPayment;

         try
         {
            subjectProfile.Romantic.IsSecretLover = true;
            subjectProfile.Romantic.Status = RomanticStatus.SecretLover;
            behavior.Store.Set(subjectProfile);
            gossip.RecordKnows(npc, subject.StringId);
            gossip.ForgetHushPaid(npc, subject.StringId);

            if (Hero.MainHero.Gold < price) Hero.MainHero.ChangeHeroGold(price - Hero.MainHero.Gold); // make the player solvent
            int playerBefore = Hero.MainHero.Gold;
            int npcBefore = npc.Gold;

            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
               new GameAction {Type = "pay_for_silence", Parameters = new Dictionary<string, string> {["price"] = price.ToString()}},
               npc, new ActionContext(npcProfile, null));

            if (t.Abort(outcome == null, "the bridge returned null instead of an outcome")) return t.Line();

            var today = (int) CampaignTime.Now.ToDays;
            t.Note($"npc={npc.Name} subject={subject.Name} price={price}");
            t.Expect("the player paid the price", Hero.MainHero.Gold, playerBefore - price);
            t.Expect("the lord received the price", npc.Gold, npcBefore + price);
            t.Expect("the hush is recorded as recent",
               CalradiaRemembers.Logic.Bastards.HushMoneyPolicy.IsRecentlyPaid(gossip.HushPaidDay(npc.StringId, subject.StringId), today), true);
            t.Expect("a memory of the payment is kept", (npcProfile.Events?.Count ?? 0) > memoryCountBefore, true);
         }
         finally
         {
            subjectProfile.Romantic.IsSecretLover = prevFlag;
            subjectProfile.Romantic.Status = prevStatus;
            behavior.Store.Set(subjectProfile);
            gossip.ForgetKnows(npc, subject.StringId);
            gossip.ForgetHushPaid(npc, subject.StringId);
            if (npcProfile.Events != null)
               while (npcProfile.Events.Count > memoryCountBefore) npcProfile.Events.RemoveAt(npcProfile.Events.Count - 1);
            behavior.Store.Set(npcProfile);
            Hero.MainHero.ChangeHeroGold(playerGold0 - Hero.MainHero.Gold);
            npc.ChangeHeroGold(npcGold0 - npc.Gold);
         }

         return t.Line();
      }

      private static string TestLordSecretLover(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("lord_secret_lover");

         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Abort(gossip == null || behavior?.Store == null || behavior.GameStateBridge == null,
                "secret-lover behavior / store / bridge not initialized")) return t.Line();

         // A NON-companion lord standing in as the married lord the player is secretly the lover of (Stolen Love /
         // infidelity marks the SDK Status SecretLover, not the companion-only IsSecretLover flag).
         Hero subject = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsPlayerCompanion);
         if (t.Abort(subject == null, "no non-companion lord to stand in as the secret-lover subject")) return t.Line();

         Hero holder = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h != subject && h.IsLord && !h.IsPrisoner);
         if (t.Abort(holder == null, "no second lord to hold the secret")) return t.Line();

         NpcProfile subjectProfile = GetOrCreate(behavior, subject);
         if (subjectProfile.Romantic == null) subjectProfile.Romantic = new RomanticProfile();
         RomanticStatus prevStatus = subjectProfile.Romantic.Status;
         NpcProfile holderProfile = GetOrCreate(behavior, holder);

         try
         {
            // Only Status is set (no IsSecretLover), exactly as a seduced married lord's profile looks.
            subjectProfile.Romantic.Status = RomanticStatus.SecretLover;
            behavior.Store.Set(subjectProfile);

            t.Note($"subject(lord)={subject.Name} holder={holder.Name} adultLevel={ModSettings.AdultContentLevel}");
            t.Expect("a lord affair is detected as a secret-lover bond",
               gossip.PlayerSecretLoverSubjectIds().Contains(subject.StringId), true);

            gossip.RecordKnows(holder, subject.StringId);
            EncounterContext ctx = EncounterContextBuilder.Build(holder, holderProfile, behavior.GameStateBridge, "hello");

            if (ModSettings.AdultContentLevel != AdultContentLevel.Off)
            {
               string subjectName = subject.Name?.ToString() ?? "";
               t.Expect("the held-secret payoff names the lord subject",
                  !string.IsNullOrEmpty(ctx.HeldSecretLoverSubject) && ctx.HeldSecretLoverSubject.Contains(subjectName), true);
            }
            else
            {
               t.Expect("the adult gate suppresses the held secret", string.IsNullOrEmpty(ctx.HeldSecretLoverSubject), true);
            }
         }
         finally
         {
            subjectProfile.Romantic.Status = prevStatus;
            behavior.Store.Set(subjectProfile);
            gossip.ForgetKnows(holder, subject.StringId);
         }

         return t.Line();
      }

      private static string TestExtortion(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("extortion");
         Violence.ExtortionBehavior extortion = Violence.ExtortionBehavior.Instance;
         if (t.Skip(extortion == null || Hero.MainHero == null || behavior.Store == null, "no campaign")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan && h.Clan.Villages.Count > 0);
         Hero lover = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsChild && h != lord);
         if (t.Skip(lord == null || lover == null || Hero.MainHero.IsPrisoner, "no lord with villages, or the player is a prisoner")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId) ?? HeroProfileMapper.FromHero(lord);
         behavior.Store.Set(profile);
         RomanticProfile romantic = profile.Romantic;
         int regard = profile.ReputationWithPlayer;
         int events = profile.Events.Count;
         int lordGold = lord.Gold;
         int playerGold = Hero.MainHero.Gold;
         int ownGrudges = GrudgeBehavior.Instance?.GrudgesFor(lord.StringId).Count ?? 0;
         Logic.Extortion.ExtortionLedger kept = extortion.Ledger;
         var verbCtx = new VerbContext(lord, profile, behavior.GameStateBridge, null, null);
         try
         {
            extortion.Ledger = new Logic.Extortion.ExtortionLedger();
            profile.Romantic = new RomanticProfile {TakenLoverId = lover.StringId, LoverIsSecret = true, LoverKnownToPlayer = true};
            if (lord.Gold < 5000) GiveGoldAction.ApplyBetweenCharacters(null, lord, 5000 - lord.Gold, true);
            int purse = lord.Gold;
            int most = Logic.Extortion.ExtortionPolicy.MostTaken(purse);
            int gold = Hero.MainHero.Gold;

            extortion.ForcedRoll = 0;
            string yes = VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"extort"}) ?? "";
            t.Note(yes);
            // STAKE: the hold is named to the model, so it has nothing to invent.
            t.Expect("theHoldIsNamed", yes.Contains($"hidden affair with {lover.Name}"), true);
            // STAKE: the answer is told before they speak: the words and the coin cannot disagree.
            t.Expect("theAnswerIsToldBeforeTheySpeak", yes.Contains("you give in"), true);
            t.Expect("theCeilingIsToldInDenars", yes.Contains($"{most} denars"), true);

            ActionOutcome paid = VerbRegistry.Instance.Execute(new GameAction {Type = "extort", Parameters = new Dictionary<string, string> {{"amount", "999999"}}}, verbCtx);
            t.Note(paid?.Message);
            // STAKE: the model's figure never moves more than the share of the purse.
            t.Expect("theCoinIsHeldToTheCeiling", Hero.MainHero.Gold - gold, most);
            t.Expect("thePageTellsIt", Mapping.MisdeedLedgerBehavior.All().Any(r => r.VictimId == lord.StringId && r.Kind == Logic.Trauma.MisdeedKind.Extorted), true);
            t.Expect("theyKeepAGrudge", GrudgeBehavior.Instance?.GrudgesFor(lord.StringId).Any(g => g.Source == GrudgeSource.Extorted) == true, true);
            t.Expect("theirRegardFell", behavior.Store.Get(lord.StringId).ReputationWithPlayer < regard, true);
            // STAKE: no milking a purse day after day.
            t.Expect("theyAreClosedForAMonth", VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"extort"}) ?? "", "");

            extortion.Ledger = new Logic.Extortion.ExtortionLedger();
            extortion.ForcedRoll = 99;
            string no = VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"extort"}) ?? "";
            t.Expect("aRefusalIsToldToo", no.Contains("you refuse"), true);
            gold = Hero.MainHero.Gold;
            ActionOutcome refused = VerbRegistry.Instance.Execute(new GameAction {Type = "extort"}, verbCtx);
            t.Note(refused?.Message);
            t.Expect("aRefusalMovesNoCoin", Hero.MainHero.Gold, gold);
            // STAKE: a refusal spends the attempt: no re-rolling the same lord.
            t.Expect("aRefusalIsAnAttempt", extortion.Ledger.TimesPressed(lord.StringId), 1);

            extortion.Ledger = new Logic.Extortion.ExtortionLedger();
            extortion.Ledger.Attempts.Add(new Logic.Extortion.ExtortionRecord {
               VictimId = lord.StringId, ClanId = lord.Clan.StringId, Lever = Logic.Extortion.ExtortionLever.Lands, Day = (int) CampaignTime.Now.ToDays, Amount = 500
            });
            extortion.OnVillageStateChanged(lord.Clan.Villages[0], Village.VillageStates.Normal, Village.VillageStates.BeingRaided, MobileParty.MainParty);
            // STAKE: Gabriel's go on the kept word: without this the promise that earned the coin is worth nothing.
            t.Expect("aRaidBreaksTheBargain", extortion.Ledger.Attempts[0].BargainBroken, true);
            t.Expect("thePageSaysWhatBroke", Mapping.MisdeedLedgerBehavior.All().Any(r => r.VictimId == lord.StringId && r.Kind == Logic.Trauma.MisdeedKind.BrokeExtortionBargain), true);
         }
         finally
         {
            extortion.ForcedRoll = null;
            extortion.Ledger = kept;
            profile.Romantic = romantic;
            profile.ReputationWithPlayer = regard;
            while (profile.Events.Count > events) profile.Events.RemoveAt(profile.Events.Count - 1);
            behavior.Store.Set(profile);
            foreach (Grudge grudge in (GrudgeBehavior.Instance?.GrudgesFor(lord.StringId) ?? new List<Grudge>()).Skip(ownGrudges).ToList()) GrudgeBehavior.Instance.RemoveGrudge(grudge);
            Mapping.MisdeedLedgerBehavior.Forget(lord.StringId, Logic.Trauma.MisdeedKind.Extorted);
            Mapping.MisdeedLedgerBehavior.Forget(lord.StringId, Logic.Trauma.MisdeedKind.BrokeExtortionBargain);
            int backToThePlayer = playerGold - Hero.MainHero.Gold;
            if (backToThePlayer != 0) GiveGoldAction.ApplyBetweenCharacters(null, Hero.MainHero, backToThePlayer, true);
            int backToTheLord = lordGold - lord.Gold;
            if (backToTheLord != 0) GiveGoldAction.ApplyBetweenCharacters(null, lord, backToTheLord, true);
         }

         return t.Line();
      }

      private static string TestReconcileWith(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("reconcile_with");
         WorldEventStore store = WorldEventStore.Instance;
         PairPeaceBehavior peace = PairPeaceBehavior.Instance;
         if (t.Skip(store == null || peace == null || behavior.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         int daysInYear = Math.Max(1, CampaignTime.DaysInSeason * CampaignTime.SeasonsInYear);
         const string eventId = "selftest_reconcile_with";
         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && !h.IsChild && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan && HeroPresence.IsInTheWorld(h)).Take(60).ToList();
         Hero a = null, b = null;
         // No kin and no spouse: a tie weighs for them (PairRegardPolicy KinWeight, SpouseWeight) and evens out the -20 of the
         // rivalry below, so they never start as enemies (second run 08/11/2026: Lucon and his kinswoman Zoana, 'Neither / Neither').
         bool Tied(Hero x, Hero y)
         {
            PairRegardFacts f = PairRegardReader.Facts(x, y, today);
            return f.IsSpouse || f.IsParentOrChild || f.IsSibling;
         }

         foreach (Hero x in lords)
         {
            b = lords.FirstOrDefault(y => y != x && y.Clan != x.Clan && y.MapFaction == x.MapFaction && !Tied(x, y) && store.EventsNamingBoth(x.StringId, y.StringId).Count == 0
                                          && PairRegardReader.Facts(x, y, today).Traces.Count == 0 && PairRegardReader.Facts(y, x, today).Traces.Count == 0
                                          && !peace.PeaceDay(x.StringId, y.StringId).HasValue && !peace.PeaceDay(y.StringId, x.StringId).HasValue);
            if (b == null) continue;

            a = x;
            break;
         }

         if (t.Skip(a == null, "no two lords of one realm, not kin, with nothing between them")) return t.Line();

         NpcProfile pa = behavior.Store.Get(a.StringId) ?? HeroProfileMapper.FromHero(a);
         NpcProfile pb = behavior.Store.Get(b.StringId) ?? HeroProfileMapper.FromHero(b);
         behavior.Store.Set(pa);
         behavior.Store.Set(pb);
         int eventsA = pa.Events.Count, eventsB = pb.Events.Count;
         int relationBefore = RelationLedgerBehavior.Between(a, b);
         try
         {
            store.RecordHistory(new WorldEvent {
               Id = eventId, Type = WorldEventType.Other, Status = SharedPastPolicy.StatusPrefix + SharedPastKind.TourneyRivalry,
               // A rivalry still at full weight (SharedPastPolicy.FullWeightYears), so it alone makes enemies of them.
               Day = today - 30, Magnitude = SharedPastPolicy.Magnitude,
               Summary = SharedPastPolicy.Summary(SharedPastKind.TourneyRivalry, a.Name.ToString(), b.Name.ToString(), null),
               ActorIds = new List<string> {a.StringId, b.StringId}, SourceMod = "CalradiaRemembers.SelfTest"
            });
            // Below zero, as a rivalry leaves it, so the evening-out can be seen.
            if (relationBefore >= VanillaRelation.NeutralTier) RelationLedgerBehavior.Change(a, b, VanillaRelation.EnemyTier - relationBefore);

            t.Note($"{a.Name} and {b.Name}; before: {PairRegardReader.Assess(a, b).Verdict} / {PairRegardReader.Assess(b, a).Verdict}");
            // STAKE (kurushimi00): a tourney rivalry that still weighs makes enemies of them.
            t.Expect("theRivalryMakesEnemies", PairRegardReader.Assess(a, b).Verdict == PairRegardVerdict.Enemy && PairRegardReader.Assess(b, a).Verdict == PairRegardVerdict.Enemy, true);

            var present = new List<string> {a.StringId, b.StringId};
            var teach = new VerbContext(a, pa, behavior.GameStateBridge, null, null) {OthersPresentIds = new List<string> {b.StringId}};
            string taught = VerbRegistry.Instance.ComposeTeachings(teach, new[] {"reconcile_with"}) ?? "";
            // STAKE: the speaker is offered the peace only with someone in the room they hold something against.
            t.Expect("taughtWithTheRivalPresent", taught.Contains("reconcile_with") && taught.Contains(b.Name.ToString()), true);
            string alone = VerbRegistry.Instance.ComposeTeachings(new VerbContext(a, pa, behavior.GameStateBridge, null, null), new[] {"reconcile_with"}) ?? "";
            // STAKE: alone with the player there is no one to make peace with, so nothing is spent teaching it.
            t.Expect("notTaughtAlone", alone.Contains("reconcile_with"), false);
            EncounterContext real = EncounterContextBuilder.Build(a, pa, behavior.GameStateBridge, null,
               new List<WitnessEntry> {new WitnessEntry {Name = b.Name.ToString(), HeroStringId = b.StringId, RelationToNpc = "a rival"}});
            // STAKE: the prompt the game really builds for a speaker with the rival in the room carries the verb, not only a
            // hand-built teaching (the round-table lap and the witness turns both come through here).
            t.Expect("theRealPromptTeachesIt", real?.ExtraActionTeachings?.Contains("reconcile_with") == true, true);

            ActionOutcome nobody = VerbRegistry.Instance.Execute(new GameAction {Type = "reconcile_with", Parameters = new Dictionary<string, string> {{"target", "Someone Absent"}}},
               new VerbContext(a, pa, behavior.GameStateBridge, null, new ActionContext(pa, null) {PresentHeroIds = present}));
            t.Note(nobody?.Message);
            // STAKE: peace is made with a person in the room, never with a name the model reaches for.
            t.Expect("aNameNotInTheRoomIsRefused", peace.PeaceDay(a.StringId, b.StringId).HasValue, false);

            ActionOutcome first = behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "reconcile_with", Parameters = new Dictionary<string, string> {{"target", b.Name.ToString()}}},
               a, new ActionContext(pa, null) {PresentHeroIds = present});
            t.Note(first?.Message);
            PairRegard aToB = PairRegardReader.Assess(a, b), bToA = PairRegardReader.Assess(b, a);
            // STAKE (Gabriel's ruling): his pardon lays HIS grudge to rest, and speaks for no one else.
            t.Expect("hisPardonEndsHisEnmity", aToB.Verdict != PairRegardVerdict.Enemy && aToB.Reconciled, true);
            t.Expect("sheStillHoldsTheRivalry", bToA.Verdict, PairRegardVerdict.Enemy);
            // STAKE: the game keeps one number for the pair, so it waits for both pardons.
            t.Expect("theGamesNumberWaitsForBoth", RelationLedgerBehavior.Between(a, b) < VanillaRelation.NeutralTier, true);

            behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "reconcile_with", Parameters = new Dictionary<string, string> {{"target", a.Name.ToString()}}},
               b, new ActionContext(pb, null) {PresentHeroIds = present});
            bToA = PairRegardReader.Assess(b, a);
            // STAKE (kurushimi00): both have made their peace: the page no longer calls them enemies.
            t.Expect("bothReconciled", bToA.Verdict != PairRegardVerdict.Enemy && bToA.Reconciled, true);
            t.Expect("theGamesNumberEvensOut", RelationLedgerBehavior.Between(a, b) >= VanillaRelation.NeutralTier, true);
            // STAKE: each keeps the memory of the peace, so they can speak of it.
            t.Expect("eachRemembersThePeace", pa.Events.Count > eventsA && pb.Events.Count > eventsB, true);
         }
         finally
         {
            store.RemoveHistory(eventId);
            peace.Forget(a.StringId, b.StringId);
            peace.Forget(b.StringId, a.StringId);
            if (pa.Events.Count > eventsA) pa.Events.RemoveRange(eventsA, pa.Events.Count - eventsA);
            if (pb.Events.Count > eventsB) pb.Events.RemoveRange(eventsB, pb.Events.Count - eventsB);
            behavior.Store.Set(pa);
            behavior.Store.Set(pb);
            int now = RelationLedgerBehavior.Between(a, b);
            if (now != relationBefore) RelationLedgerBehavior.Change(a, b, relationBefore - now);
         }

         return t.Line();
      }

      private static string TestSecretExposure(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("secret_exposure");
         Violence.ExtortionBehavior extortion = Violence.ExtortionBehavior.Instance;
         WorldEvents.SecretLoverGossipBehavior gossip = WorldEvents.SecretLoverGossipBehavior.Instance;
         if (t.Skip(extortion == null || gossip == null || Jealousy.JealousyBehavior.Instance == null || Hero.MainHero == null || behavior.Store == null, "no campaign")) return t.Line();
         if (t.Skip(ModSettings.AdultContentLevel == AdultContentLevel.Off, "adult content is off: affairs cannot be told")) return t.Line();

         List<string> ownLovers = gossip.PlayerSecretLoverSubjectIds();
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan && h.Spouse is {IsAlive: true} && h.Spouse != Hero.MainHero && !ownLovers.Contains(h.StringId));
         Hero listener = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsChild && !h.IsPrisoner && h != lord && h != lord?.Spouse);
         if (t.Skip(lord == null || listener == null, "no married lord, or nobody to tell")) return t.Line();

         Hero spouse = lord.Spouse;
         NpcProfile profile = behavior.Store.Get(lord.StringId) ?? HeroProfileMapper.FromHero(lord);
         behavior.Store.Set(profile);
         NpcProfile heard = behavior.Store.Get(listener.StringId) ?? HeroProfileMapper.FromHero(listener);
         behavior.Store.Set(heard);
         NpcProfile wronged = behavior.Store.Get(spouse.StringId) ?? HeroProfileMapper.FromHero(spouse);
         behavior.Store.Set(wronged);

         RomanticProfile romantic = profile.Romantic;
         int regard = profile.ReputationWithPlayer;
         var events = new Dictionary<NpcProfile, int> {{profile, profile.Events.Count}, {heard, heard.Events.Count}, {wronged, wronged.Events.Count}};
         int ownGrudges = GrudgeBehavior.Instance?.GrudgesFor(lord.StringId).Count ?? 0;
         int betrayal = Mapping.PairBondReader.Points(spouse, lord);
         float renown = lord.Clan.Renown;
         float influence = lord.Clan.Influence;
         float ownRenown = Clan.PlayerClan.Renown;
         float ownInfluence = Clan.PlayerClan.Influence;
         int pendingBefore = Jealousy.JealousyBehavior.Instance.DebugPendingCount;
         Logic.Extortion.ExtortionLedger kept = extortion.Ledger;
         string eventId = null;
         try
         {
            extortion.Ledger = new Logic.Extortion.ExtortionLedger();
            profile.Romantic = new RomanticProfile {Status = RomanticStatus.SecretLover};
            behavior.Store.Set(profile);

            var verbCtx = new VerbContext(listener, heard, behavior.GameStateBridge, null, new ActionContext(heard, null) {PlayerWordsThisConversation = "A fine evening, my lord."});
            string taught = VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"expose_secret"}) ?? "";
            t.Note(taught);
            // STAKE: only a secret the game holds is taught, so a false accusation has no verb.
            t.Expect("theSecretIsTaught", taught.Contains(lord.Name.ToString()), true);
            // STAKE: the listener reads the secret to recognise it: without this line they would raise it unprompted.
            t.Expect("theyAreToldTheyDoNotKnowIt", taught.Contains("You do not know this"), true);

            var action = new GameAction {Type = "expose_secret", Parameters = new Dictionary<string, string> {{"target", lord.Name.ToString()}}};
            ActionOutcome silent = VerbRegistry.Instance.Execute(action, verbCtx);
            t.Note(silent?.Message);
            // STAKE: a model that decides on its own that the player told it moves nothing, as Maifailun's sway did.
            t.Expect("wordsThatNameNobodyMoveNothing", extortion.Ledger.Exposures.Count, 0);

            extortion.Ledger.Attempts.Add(new Logic.Extortion.ExtortionRecord {
               VictimId = lord.StringId, ClanId = lord.Clan.StringId, Lever = Logic.Extortion.ExtortionLever.Secret, Day = (int) CampaignTime.Now.ToDays, Amount = 500
            });
            ActionOutcome told = VerbRegistry.Instance.Execute(action, new VerbContext(listener, heard, behavior.GameStateBridge, null,
               new ActionContext(heard, null) {PlayerWordsThisConversation = $"{lord.Name} has been in my bed."}));
            t.Note(told?.Message);

            eventId = WorldEvents.WorldEventStore.Instance?.GetPlayerChronicle().LastOrDefault(e => e.Type == WorldEventType.Scandal && e.ActorIds.Contains(lord.StringId))?.Id;
            WorldEvent scandal = WorldEvents.WorldEventStore.Instance?.GetPlayerChronicle().LastOrDefault(e => e.Id == eventId);
            t.Note(scandal?.Summary);
            // STAKE: a Scandal without InvolvesPlayer reaches prompts only with NpcsRaiseWorldNews, off by default: nobody would ever speak of it.
            t.Expect("theScandalNamesThePlayer", scandal?.InvolvesPlayer == true && scandal.Summary.Contains(Hero.MainHero.Name.ToString()), true);
            t.Expect("theHouseIsShamed", lord.Clan.Renown < renown || renown == 0f, true);
            t.Expect("thePlayersHouseToo", Clan.PlayerClan.Influence < ownInfluence, true);
            t.Expect("theyKeepAGrudge", GrudgeBehavior.Instance?.GrudgesFor(lord.StringId).Any(g => g.Source == GrudgeSource.SecretExposed) == true, true);
            // STAKE: taking the coin and telling anyway is the worse deed, and the page says so.
            t.Expect("thePaidSilenceIsBroken", Mapping.MisdeedLedgerBehavior.All().Any(r => r.VictimId == lord.StringId && r.Kind == Logic.Trauma.MisdeedKind.BrokeSecretBargain), true);
            t.Expect("theBargainIsMarked", extortion.Ledger.Attempts[0].BargainBroken, true);
            t.Expect("theSpouseTurnsOnThem", Mapping.PairBondReader.Points(spouse, lord) < betrayal, true);
            // STAKE: Gabriel's go on mutual ruin: the betrayed spouse answers the player through the jealousy that exists.
            t.Expect("theSpouseAnswersThePlayer", Jealousy.JealousyBehavior.Instance.DebugPendingCount, pendingBefore + 1);
            // STAKE: told once, it is spent: no second scandal, no silence to sell.
            t.Expect("theSecretIsSpent", SecretExposureHeld(listener), 0);
         }
         finally
         {
            extortion.Ledger = kept;
            profile.Romantic = romantic;
            profile.ReputationWithPlayer = regard;
            foreach (KeyValuePair<NpcProfile, int> entry in events)
            {
               while (entry.Key.Events.Count > entry.Value) entry.Key.Events.RemoveAt(entry.Key.Events.Count - 1);
               behavior.Store.Set(entry.Key);
            }

            foreach (Grudge grudge in (GrudgeBehavior.Instance?.GrudgesFor(lord.StringId) ?? new List<Grudge>()).Skip(ownGrudges).ToList()) GrudgeBehavior.Instance.RemoveGrudge(grudge);
            Mapping.MisdeedLedgerBehavior.Forget(lord.StringId, Logic.Trauma.MisdeedKind.BrokeSecretBargain);
            Mapping.MisdeedLedgerBehavior.Forget(lord.StringId, Logic.Trauma.MisdeedKind.ExposedSecret);
            gossip.DebugUnretire(lord.StringId);
            Jealousy.JealousyBehavior.Instance.DebugForgetPending(spouse.StringId);
            if (eventId != null) WorldEvents.WorldEventStore.Instance?.Remove(eventId);
            Mapping.RelationLedgerBehavior.SetAsHistory(spouse, lord, betrayal);
            lord.Clan.Renown = renown;
            Clan.PlayerClan.Renown = ownRenown;
            ChangeClanInfluenceAction.Apply(lord.Clan, influence - lord.Clan.Influence);
            ChangeClanInfluenceAction.Apply(Clan.PlayerClan, ownInfluence - Clan.PlayerClan.Influence);
         }

         return t.Line();
      }

      private static int SecretExposureHeld(Hero listener) => Violence.SecretExposure.HeldFor(listener).Count;

      private static string TestHiddenAffairs(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("hidden_affairs");
         Mapping.HiddenAffairBehavior affairs = Mapping.HiddenAffairBehavior.Instance;
         Violence.ExtortionBehavior extortion = Violence.ExtortionBehavior.Instance;
         CompanionMissionBehavior missions = CompanionMissionBehavior.Instance;
         if (t.Skip(affairs == null || extortion == null || missions == null || Hero.MainHero == null || behavior.Store == null, "no campaign")) return t.Line();
         if (t.Skip(ModSettings.AdultContentLevel == AdultContentLevel.Off, "adult content is off: no affair exists")) return t.Line();
         if (t.Skip(!ModSettings.HiddenAffairs, "Hidden Affairs Among Lords is off")) return t.Line();
         if (t.Skip(missions.DebugActiveCount > 0, "a companion is already away: the test resolves the first errand")) return t.Line();

         bool Free(Hero h) => h != Hero.MainHero && h.IsLord && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan && affairs.Ledger.Of(h.StringId) == null && string.IsNullOrEmpty(behavior.Store.Get(h.StringId)?.Romantic?.TakenLoverId);
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => Free(h) && Mapping.HeroPresence.IsInTheWorld(h.Spouse) && h.Spouse != Hero.MainHero && (h.CurrentSettlement != null || h.PartyBelongedTo != null));
         Hero lover = Hero.AllAliveHeroes.FirstOrDefault(h => Free(h) && h.Spouse == null && h != lord);
         Hero listener = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsChild && !h.IsPrisoner && h != lord && h != lover && h != lord?.Spouse);
         if (t.Skip(lord == null || lover == null || listener == null, "no married lord, no free lord, or nobody to tell")) return t.Line();

         using var arranged = ArrangedCompanion.Get(behavior, mustBeInMainParty: true);
         if (t.Skip(arranged == null, "no available companion in your party, and no wanderer template to arrange one")) return t.Line();
         Hero companion = arranged.Companion;
         if (arranged.WasMinted) companion.SetSkillValue(DefaultSkills.Roguery, 40);

         NpcProfile profile = GetOrCreate(behavior, lord);
         profile.Romantic ??= new RomanticProfile();
         NpcProfile told = GetOrCreate(behavior, companion);
         int toldEvents = told.Events.Count;
         HiddenAffairLedger kept = affairs.Ledger;
         Logic.Extortion.ExtortionLedger keptExtortion = extortion.Ledger;
         try
         {
            affairs.Ledger = new HiddenAffairLedger();
            extortion.Ledger = new Logic.Extortion.ExtortionLedger();
            t.Expect("theAffairBegins", affairs.Begin(lord, lover, (int) CampaignTime.Now.ToDays), true);

            string own = affairs.PromptFor(lord) ?? "";
            string other = affairs.PromptFor(lover) ?? "";
            // STAKE: Gabriel: the character knows it. Without these two lines the lovers would answer as if nothing were hidden.
            t.Expect("theMarriedOneCarriesIt", own.Contains(lover.Name.ToString()) && own.Contains("never deny it with a lie"), true);
            t.Expect("theLoverCarriesItToo", other.Contains(lord.Name.ToString()), true);
            // STAKE: the player finds it or it does not exist for them: no verb before a companion brings it back.
            t.Expect("thePlayerHoldsNothingYet", SecretExposureHeld(listener), 0);

            // STAKE: the partner path's every line calls a lover a betrayal of the player: left in it, a lord's affair would make a scandal about them.
            t.Expect("thePartnerPathLeavesItAlone", affairs.IsHidden(lord.StringId), true);
            ActionOutcome ended = behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "end_affair"}, lord, new ActionContext(profile, null));
            t.Note(ended?.Message);
            t.Expect("thePlayerCannotEndIt", behavior.Store.Get(lord.StringId)?.Romantic?.TakenLoverId, lover.StringId);

            // STAKE: NPCs never lie: a poor errand says nothing certain, never "nothing hidden".
            t.Expect("aPoorInquiryFindsNothing", affairs.Inquire(lord, Logic.Companions.MissionResult.Partial).SubjectId, (string) null);
            // STAKE: the lover has no field of their own: looking into them must still lead to the affair.
            t.Expect("lookingIntoTheLoverFindsIt", affairs.Inquire(lover, Logic.Companions.MissionResult.Success).SubjectId, lord.StringId);

            (bool dispatched, string refusal) = missions.Dispatch(companion, CompanionMissionType.Spy, lord.Name.ToString());
            if (t.Skip(!dispatched, $"dispatch refused for {companion.Name}: {refusal}")) return t.Line();

            missions.DebugForceFirstQuality(Logic.Companions.MissionResult.Success);
            missions.ForceResolveFirst();
            string report = missions.ConsumeNewsReport(companion) ?? "";
            t.Note(report);
            // STAKE: the one road Gabriel chose: the report is what tells the player.
            t.Expect("theReportTellsIt", report.Contains(lover.Name.ToString()), true);
            t.Expect("thePlayerNowKnows", behavior.Store.Get(lord.StringId)?.Romantic?.LoverKnownToPlayer == true, true);
            t.Expect("itCanBeTold", Violence.SecretExposure.HeldFor(listener).Any(s => s.Subject == lord && s.Lover == lover), true);
            t.Expect("theMarriedOneCanBePressed", extortion.HoldOver(lord)?.Lever == Logic.Extortion.ExtortionLever.Secret || !Logic.Extortion.ExtortionPolicy.IsWorthAsking(lord.Gold), true);
            t.Expect("theLoverCanBePressed", extortion.HoldOver(lover)?.Lever == Logic.Extortion.ExtortionLever.Secret || !Logic.Extortion.ExtortionPolicy.IsWorthAsking(lover.Gold) || lover.IsPrisoner, true);

            // STAKE: a told secret is over: a lord still "secret" after the whole realm heard would contradict the scandal.
            affairs.OnExposed(lord.StringId);
            t.Expect("aToldAffairEnds", affairs.Ledger.Of(lord.StringId), (HiddenAffair) null);
            t.Expect("theFieldsAreClear", behavior.Store.Get(lord.StringId)?.Romantic?.TakenLoverId, (string) null);
            t.Expect("theyCarryItNoMore", affairs.PromptFor(lover), (string) null);
         }
         finally
         {
            foreach (HiddenAffair affair in affairs.Ledger.Affairs.ToList()) affairs.End(affair);
            affairs.Ledger = kept;
            extortion.Ledger = keptExtortion;
            while (told.Events.Count > toldEvents) told.Events.RemoveAt(told.Events.Count - 1);
            behavior.Store.Set(told);
         }

         return t.Line();
      }

      private static string TestAffairVeto(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("affair_veto");
         const string source = "cr.test affair_veto";
         const string broken = "cr.test affair_veto (broken)";
         Mapping.HiddenAffairBehavior affairs = Mapping.HiddenAffairBehavior.Instance;
         if (t.Skip(affairs == null || Hero.MainHero == null || behavior.Store == null, "no campaign")) return t.Line();

         bool Free(Hero h) => h != Hero.MainHero && h.IsLord && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan && affairs.Ledger.Of(h.StringId) == null && string.IsNullOrEmpty(behavior.Store.Get(h.StringId)?.Romantic?.TakenLoverId);
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => Free(h) && Mapping.HeroPresence.IsInTheWorld(h.Spouse) && h.Spouse != Hero.MainHero);
         Hero lover = Hero.AllAliveHeroes.FirstOrDefault(h => Free(h) && h.Spouse == null && h != lord);
         if (t.Skip(lord == null || lover == null, "no married lord or no free lord")) return t.Line();

         var heard = new List<CrHiddenAffairChange>();
         void Listen(CrHiddenAffairChange c) => heard.Add(c);
         HiddenAffairLedger kept = affairs.Ledger;
         try
         {
            CrRomance.RegisterAffairVeto(source, (m, l) => m == lord || l == lover ? "already in an affair (self-test)" : null);
            // STAKE: tashmetu: a lord in an affair in another mod is never given a second one by CR.
            t.Expect("theOtherModRefuses", Mapping.HiddenAffairBehavior.OtherModsAllow(lord, lover), false);
            CrRomance.UnregisterAffairVeto(source);
            t.Expect("withdrawnItAllows", Mapping.HiddenAffairBehavior.OtherModsAllow(lord, lover), true);

            // STAKE: Gabriel: CR depends on no mod; a broken one must not stop CR's affairs.
            CrRomance.RegisterAffairVeto(broken, (m, l) => throw new InvalidOperationException("self-test"));
            t.Expect("aBrokenVetoNeverRefuses", Mapping.HiddenAffairBehavior.OtherModsAllow(lord, lover), true);
            CrRomance.UnregisterAffairVeto(broken);

            affairs.Ledger = new HiddenAffairLedger();
            CrRomance.HiddenAffairChanged += Listen;
            t.Expect("theAffairBegins", affairs.Begin(lord, lover, (int) CampaignTime.Now.ToDays), true);
            // STAKE: the other mod hears CR's affair the moment it begins, and can read it from either lord.
            t.Expect("itsBeginningIsHeard", heard.Any(c => c.Began && c.SubjectId == lord.StringId && c.LoverId == lover.StringId), true);
            t.Expect("itReadsFromTheLover", CrRomance.GetHiddenAffair(lover.StringId)?.SubjectId, lord.StringId);
            affairs.End(affairs.Ledger.Of(lord.StringId));
            t.Expect("itsEndIsHeard", heard.Any(c => !c.Began && c.SubjectId == lord.StringId), true);
            t.Expect("itIsGone", CrRomance.GetHiddenAffair(lord.StringId), (CrHiddenAffair) null);
         }
         finally
         {
            CrRomance.HiddenAffairChanged -= Listen;
            CrRomance.UnregisterAffairVeto(source);
            CrRomance.UnregisterAffairVeto(broken);
            foreach (HiddenAffair affair in affairs.Ledger.Affairs.ToList()) affairs.End(affair);
            affairs.Ledger = kept;
         }

         return t.Line();
      }

      private static string TestPersonalWorth(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("personal_worth");
         if (t.Abort(Hero.MainHero == null || MobileParty.MainParty == null, "no player party")) return t.Line();

         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && !h.IsChild && h.PartyBelongedTo != null && h.Clan != null && h.Clan != Clan.PlayerClan
            && h.Clan.Leader != null && h.Clan.Leader != h && h.Clan.Leader != Hero.MainHero && Mapping.HeroPresence.IsInTheWorld(h.Clan.Leader)
            && !h.Clan.Leader.IsPrisoner && BuyPrisonerVerb.BondTo(h.Clan.Leader, h) is CaptiveBond.Kin or CaptiveBond.SpouseOrChild);
         if (t.Skip(captive == null, "no free lord whose clan leader is his kin")) return t.Line();

         Hero buyer = captive.Clan.Leader;
         CaptiveBond bond = BuyPrisonerVerb.BondTo(buyer, captive);
         int anchor = BuyPrisonerVerb.RansomAnchor(captive);
         int expected = PrisonerTradePolicy.ClampPrice(999999, anchor, bond);
         int playerGold0 = Hero.MainHero.Gold;
         int buyerGold0 = buyer.Gold;
         if (buyer.Gold < expected) buyer.ChangeHeroGold(expected - buyer.Gold);

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);
         try
         {
            if (t.Abort(!captive.IsPrisoner, $"could not take {captive.Name} captive")) return t.Line();

            NpcProfile profile = GetOrCreate(behavior, buyer);
            IReadOnlyDictionary<string, int> tokens = ExchangeService.MoneyTokensFor(buyer, profile, null, false);
            tokens.TryGetValue(NpcMemoryService.Core.Parsing.MoneyTokens.Key("most", captive.Name.ToString()), out int offered);

            int before = Hero.MainHero.Gold;
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(new GameAction {
               Type = "buy_prisoner", Parameters = new Dictionary<string, string> {["target"] = captive.Name.ToString(), ["price"] = "999999"}
            }, buyer, new ActionContext(profile, null));
            int paid = Hero.MainHero.Gold - before;

            t.Note($"captive={captive.Name}, buyer={buyer.Name} ({bond}), anchor={anchor}, token={offered}, paid={paid}, expected={expected}, told: {outcome?.Message}");
            // STAKE: Thoragoros1: kin pay above the game's low valuation, beyond the ordinary three times.
            t.Expect("kinPayMoreThanAStranger", expected > PrisonerTradePolicy.MaxPrice(anchor), true);
            // STAKE: RaveN017Mod: the sum the character may name is the sum the player receives.
            // A spouse or child is offered the whole purse, which may hold more than the sum named.
            t.Expect("theOfferCoversWhatIsPaid", bond == CaptiveBond.SpouseOrChild ? offered >= paid : offered == paid, true);
            t.Expect("thePolicyIsWhatIsPaid", paid, expected);
         }
         finally
         {
            try { if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive, buyer); }
            catch { /* best-effort cleanup */ }

            Hero.MainHero.ChangeHeroGold(playerGold0 - Hero.MainHero.Gold);
            buyer.ChangeHeroGold(buyerGold0 - buyer.Gold);
         }

         return t.Line();
      }

      private static string TestCourtshipLapse(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("courtship_lapse");
         var store = behavior?.Store;
         if (t.Abort(store == null, "no memory store")) return t.Line();

         Hero wed = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsChild && h.IsFemale != Hero.MainHero.IsFemale
                                                            && h.Spouse == null && store.Get(h.StringId)?.Romantic != null);
         Hero other = wed == null ? null : Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != wed && h.IsLord && !h.IsChild);
         if (t.Skip(wed == null || other == null, "no unwed lord or lady with a romantic profile")) return t.Line();

         NpcProfile profile = store.Get(wed.StringId);
         RomanticStatus status0 = profile.Romantic.Status;
         int? since0 = profile.Romantic.StatusSinceDay, lovers0 = profile.Romantic.LoversSinceDay;
         int events0 = profile.Events.Count;
         try
         {
            profile.Romantic.Status = RomanticStatus.Courting;
            store.Set(profile);

            bool moved = Marriage.CourtshipLapseBehavior.Lapse(wed, other);
            NpcProfile after = store.Get(wed.StringId);
            t.Note($"{wed.Name} weds {other.Name}: {after.Romantic.Status}; last memory '{after.Events.LastOrDefault()?.summary}'");
            // STAKE: avalanche24: the courtship ends the day she weds another; her page and letters stop calling it a courtship.
            t.Expect("theCourtshipEnds", moved && after.Romantic.Status == RomanticStatus.Estranged, true);
            // STAKE: NPCs never lie: she remembers choosing another, so she never denies what was.
            t.Expect("sheRemembersTheWedding", after.Events.Count > events0 && after.Events.Last().type == NotableEventType.OwnLife, true);
            // STAKE: wedding the player is no lapse.
            after.Romantic.Status = RomanticStatus.Courting;
            t.Expect("weddingThePlayerKeepsIt", Marriage.CourtshipLapseBehavior.Lapse(wed, Hero.MainHero), false);
         }
         finally
         {
            NpcProfile back = store.Get(wed.StringId);
            back.Romantic.Status = status0;
            back.Romantic.StatusSinceDay = since0;
            back.Romantic.LoversSinceDay = lovers0;
            while (back.Events.Count > events0) back.Events.RemoveAt(back.Events.Count - 1);
            store.Set(back);
         }

         return t.Line();
      }

