      private static string TestCourtshipLapsePast(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("courtship_lapse_past");
         var store = behavior?.Store;
         if (t.Abort(store == null, "no memory store")) return t.Line();

         Hero wed = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.Spouse != null && h.Spouse != Hero.MainHero && !h.IsChild
                                                            && store.Get(h.StringId)?.Romantic != null);
         if (t.Skip(wed == null, "no hero married to someone other than the player with a romantic profile")) return t.Line();

         NpcProfile profile = store.Get(wed.StringId);
         RomanticStatus status0 = profile.Romantic.Status;
         int? since0 = profile.Romantic.StatusSinceDay, lovers0 = profile.Romantic.LoversSinceDay;
         int events0 = profile.Events.Count;
         int? wedding0 = Mapping.WeddingDayBehavior.WeddedOn(wed);
         var today = (int) CampaignTime.Now.ToDays;
         try
         {
            // A courtship begun AFTER her wedding: the player's affair to pursue, never ended by it.
            Mapping.WeddingDayBehavior.DebugSet(wed, today - 20);
            profile.Romantic.Status = RomanticStatus.Courting;
            profile.Romantic.StatusSinceDay = today - 10;
            store.Set(profile);
            Marriage.CourtshipLapseBehavior.Reconcile();
            t.Expect("aCourtshipAfterTheWeddingStays", store.Get(wed.StringId).Romantic.Status, RomanticStatus.Courting);

            // STAKE: avalanche24's Rhagaea: courted before she was wed to another, the courtship ends on the next day's reconcile.
            NpcProfile before = store.Get(wed.StringId);
            before.Romantic.StatusSinceDay = today - 30;
            store.Set(before);
            Marriage.CourtshipLapseBehavior.Reconcile();
            t.Note($"{wed.Name}, wed to {wed.Spouse?.Name}: {store.Get(wed.StringId).Romantic.Status}");
            t.Expect("aCourtshipBeforeTheWeddingEnds", store.Get(wed.StringId).Romantic.Status, RomanticStatus.Estranged);

            // STAKE: avalanche24: her page said only "grown distant"; it now names the one she wed.
            string heart = string.Join(" | ", Mapping.HeartPageReader.LinesFor(wed));
            t.Note($"Heart: {heart}");
            t.Expect("herPageNamesTheOneSheWed", heart.Contains(wed.Spouse.Name.ToString()), true);

            // STAKE: avalanche24: the bond reaches the model dated, as a fact she cannot disown.
            NpcProfile lapsed = store.Get(wed.StringId);
            lapsed.Romantic.Status = RomanticStatus.Courting;
            t.Expect("theCourtshipIsDatedInThePrompt",
               Mapping.EncounterContextBuilder.Build(wed, lapsed, behavior.GameStateBridge, "").RomanticBondSince,
               lapsed.Romantic.StatusSinceDay is int bondDay ? Mapping.HeartPageReader.When(bondDay) : "(no day recorded)");
            lapsed.Romantic.Status = RomanticStatus.Estranged;
         }
         finally
         {
            NpcProfile back = store.Get(wed.StringId);
            back.Romantic.Status = status0;
            back.Romantic.StatusSinceDay = since0;
            back.Romantic.LoversSinceDay = lovers0;
            while (back.Events.Count > events0) back.Events.RemoveAt(back.Events.Count - 1);
            store.Set(back);
            Mapping.WeddingDayBehavior.DebugSet(wed, wedding0);
         }

         return t.Line();
      }

      private static string TestBagLotSale(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("bag_lot_sale");
         ItemRoster roster = MobileParty.MainParty?.ItemRoster;
         if (t.Abort(roster == null || Hero.MainHero == null, "no player item roster")) return t.Line();

         Hero buyer = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && h.Gold >= 5000 && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(buyer == null, "no lord in the world with 5000 denars")) return t.Line();

         List<ItemObject> goods = MBObjectManager.Instance?.GetObjectTypeList<ItemObject>()?.Where(it => it != null && it.IsTradeGood && it.Value > 0).Take(2).ToList();
         if (t.Skip(goods == null || goods.Count < 2, "fewer than two trade goods in the game data")) return t.Line();

         ItemObject a = goods[0], b = goods[1];
         int heldA = roster.GetItemNumber(a), heldB = roster.GetItemNumber(b);
         int playerGold = Hero.MainHero.Gold, buyerGold = buyer.Gold;
         int worth = 3 * a.Value + 2 * b.Value;
         int price = Math.Min(worth, ItemSalePolicy.MostFor(worth));
         roster.AddToCounts(a, 3);
         roster.AddToCounts(b, 2);
         var paid = 0;
         try
         {
            var lot = new GiftBundle {Items = new List<ItemOffer> {new ItemOffer(a.StringId, 3), new ItemOffer(b.StringId, 2)}, AskingPrice = price};
            var ctx = new ActionContext(GetOrCreate(behavior, buyer), null) {OfferedItemId = a.StringId, OfferedBundle = lot};
            var sale = new GameAction {Type = "sell_item", Parameters = new Dictionary<string, string> {["item"] = a.Name.ToString(), ["price"] = price.ToString()}};

            // STAKE: the player is asked about the whole lot, at its worth, not about one good of it.
            ItemPreview preview = BannerlordGameStateBridge.PreviewItem(sale, ctx);
            t.Note($"preview: {preview?.Name} ({preview?.Value})");
            t.Expect("thePreviewIsTheLot", preview?.IsLot == true && preview.Value == worth, true);

            // STAKE: every good laid out leaves, in its amount, paid once.
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(sale, buyer, ctx);
            paid = Hero.MainHero.Gold - playerGold;
            t.Note($"sell_item: {outcome?.Message}");
            t.Expect("bothGoodsAreSold", roster.GetItemNumber(a) == heldA && roster.GetItemNumber(b) == heldB, true);
            t.Expect("thePlayerIsPaidOnce", paid > 0 && buyerGold - buyer.Gold == paid, true);

            // STAKE: a lot no longer held in full is not sold short for the same price.
            roster.AddToCounts(a, 3);
            var tooMuch = new GiftBundle {Items = new List<ItemOffer> {new ItemOffer(a.StringId, 3), new ItemOffer(b.StringId, heldB + 5)}, AskingPrice = price};
            int goldBefore = Hero.MainHero.Gold;
            ActionOutcome refused = behavior.GameStateBridge.ExecuteAction(sale, buyer, new ActionContext(GetOrCreate(behavior, buyer), null) {OfferedItemId = a.StringId, OfferedBundle = tooMuch});
            t.Note($"short lot: {refused?.Message}");
            t.Expect("aShortLotSellsNothing", roster.GetItemNumber(a) == heldA + 3 && Hero.MainHero.Gold == goldBefore, true);
         }
         finally
         {
            if (paid > 0) GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, buyer, paid);
            int extraA = roster.GetItemNumber(a) - heldA, extraB = roster.GetItemNumber(b) - heldB;
            if (extraA != 0) roster.AddToCounts(a, -extraA);
            if (extraB != 0) roster.AddToCounts(b, -extraB);
         }

         return t.Line();
      }

      private static string TestBagSale(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("bag_sale");
         ItemRoster roster = MobileParty.MainParty?.ItemRoster;
         if (t.Abort(roster == null || Hero.MainHero == null, "no player item roster")) return t.Line();

         Hero buyer = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && h.Gold >= 2000 && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(buyer == null, "no lord in the world with 2000 denars")) return t.Line();

         ItemObject good = MBObjectManager.Instance?.GetObjectTypeList<ItemObject>()?.FirstOrDefault(it => it != null && it.IsTradeGood && it.Value > 0);
         if (t.Skip(good == null, "no trade good in the game data")) return t.Line();

         int heldBefore = roster.GetItemNumber(good);
         int playerGold = Hero.MainHero.Gold;
         int buyerGold = buyer.Gold;
         int price = Math.Min(3 * good.Value, ItemSalePolicy.MostFor(3 * good.Value));
         roster.AddToCounts(good, 3);
         var paid = 0;
         try
         {
            var bundle = new GiftBundle {Items = new List<ItemOffer> {new ItemOffer(good.StringId, 3)}, AskingPrice = price};
            var ctx = new ActionContext(GetOrCreate(behavior, buyer), null) {OfferedItemId = good.StringId, OfferedBundle = bundle};

            // STAKE: froggyluv: goods held out for a price never leave as a gift.
            ActionOutcome gift = behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "give_item"}, buyer, ctx);
            t.Expect("noGiftOfGoodsForSale", roster.GetItemNumber(good), heldBefore + 3);
            t.Note($"give_item: {gift?.Message}");

            // STAKE: froggyluv: the whole amount chosen in the bag is sold, and paid for.
            var sale = new GameAction {Type = "sell_item", Parameters = new Dictionary<string, string> {["item"] = good.Name.ToString(), ["price"] = price.ToString()}};
            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(sale, buyer, ctx);
            paid = Hero.MainHero.Gold - playerGold;
            t.Note($"sell_item: {outcome?.Message}");
            t.Expect("allThreeAreSold", roster.GetItemNumber(good), heldBefore);
            t.Expect("thePlayerIsPaid", paid > 0 && buyerGold - buyer.Gold == paid, true);
         }
         finally
         {
            if (paid > 0) GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, buyer, paid);
            int extra = roster.GetItemNumber(good) - heldBefore;
            if (extra != 0) roster.AddToCounts(good, -extra);
         }

         return t.Line();
      }

      private static string TestCaptiveTradeContext(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_trade_context");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();
         Hero captive = Verbs.BuyPrisonerVerb.PlayerHeldHeroPrisoners().FirstOrDefault(h => h.Name != null && h.Clan != null);

         // Arranged per GABRIEL'S RULE (05/11/2026: "injecte un captif et fait le test automatiquement"): with no hero
         // captive held, a free lord with no party of his own is taken into the player's party and released after.
         Hero arranged = null;
         if (captive == null)
         {
            arranged = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && !h.IsPrisoner && h.Clan != Clan.PlayerClan && !h.IsChild
                                                              && h.PartyBelongedTo == null && h.Clan != null && h.Clan.IsBanditFaction != true
                                                              && Mapping.HeroPresence.IsInTheWorld(h));
            if (t.Skip(arranged == null, "no hero captive held, and no free partyless lord to take")) return t.Line();
            TakePrisonerAction.Apply(PartyBase.MainParty, arranged);
            captive = arranged;
            t.Note($"arranged: {arranged.Name} taken into the player's party for the test");
         }

         try
         {
            return CaptiveTradeContextChecks(t, behavior, captive);
         }
         finally
         {
            if (arranged != null && arranged.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(arranged);
         }
      }

      private static string CaptiveTradeContextChecks(TestRun t, NpcMemoryCampaignBehavior behavior, Hero captive)
      {
         string name = captive.Name.ToString();
         var history = new List<LlmMessage> {
            new LlmMessage(MessageRole.Assistant, "Ten thousand, and not a coin more."),
            new LlmMessage(MessageRole.User, $"Then take {name} for that."),
            new LlmMessage(MessageRole.Assistant, "Done. I'll take him.")
         };
         t.Expect("theCaptiveIsHeldByThePlayer", Verbs.BuyPrisonerVerb.PlayerHeldHeroPrisoners().Contains(captive), true);
         string block = Chat.ActionInterpreterComposer.TradeBackgroundFor(history, $"Then take {name} for that.", "Done. I'll take him.");
         t.Note($"{name}; block {block?.Length ?? 0} chars");
         // STAKE: RaveN017Mod's sales in a row: "him" and "for that" are readable only with the captives and the turn before.
         t.Expect("theInterpreterReadsTheCaptivesHeld", block != null && block.Contains(name), true);
         t.Expect("theInterpreterReadsThePlayersLine", block != null && block.Contains("PLAYER: Then take " + name), true);
         t.Expect("theInterpreterReadsTheFigureSaidBefore", block != null && block.Contains("Ten thousand, and not a coin more."), true);

         // STAKE: a talk about something else reads exactly what it read before.
         var other = new List<LlmMessage> {new LlmMessage(MessageRole.User, "How fares your family?"), new LlmMessage(MessageRole.Assistant, "Well enough.")};
         t.Expect("anotherTalkReadsNothingMore", Chat.ActionInterpreterComposer.TradeBackgroundFor(other, "How fares your family?", "Well enough."), (string) null);

         Hero buyer = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != Clan.PlayerClan && h.Gold > 0
                                                            && Mapping.HeroPresence.IsInTheWorld(h));
         if (buyer == null || captive.Clan == null)
         {
            t.Note("no lord with a purse, or the captive has no house: echo and token checks left out");

            return t.Line();
         }

         // STAKE: the reply where the sale was made, read again, must not sell the captive back (nothing is moved here).
         var noted = Verbs.BuyPrisonerVerb.NotedTradeOf(captive);
         Verbs.BuyPrisonerVerb.RecordTrade(captive, buyer);
         try
         {
            t.Expect("theSameTradeNamedAgainIsAnEcho", Verbs.BuyPrisonerVerb.IsEchoOfLastTrade(captive, buyer), true);
            t.Expect("anotherBuyerIsNoEcho", Verbs.BuyPrisonerVerb.IsEchoOfLastTrade(captive, Hero.MainHero), false);
         }
         finally
         {
            Verbs.BuyPrisonerVerb.PutNotedTrade(captive, noted);
         }

         IReadOnlyDictionary<string, int> table = GameState.ExchangeService.MoneyTokensFor(buyer, behavior.Store.Get(buyer.StringId), null, false);
         string bare = NpcMemoryService.Core.Parsing.MoneyTokens.Fill("{most:" + name + "}", table);
         if (bare == NpcMemoryService.Core.Parsing.MoneyTokens.NoFigure)
         {
            t.Note($"{buyer.Name} could not pay a fair price for {name}: token check left out");

            return t.Line();
         }

         // STAKE: a token written with the house used to read "a fair sum", and the sale paid the floor instead of the agreed figure.
         t.Expect("aTokenWithTheHouseFillsTheSameSum", NpcMemoryService.Core.Parsing.MoneyTokens.Fill("{most:" + name + " of " + captive.Clan.Name + "}", table), bare);

         return t.Line();
      }

