      private static string TestPairBond(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("pair_bond");
         if (t.Abort(Mapping.RelationLedgerBehavior.Instance == null, "the relation ledger is not running")) return t.Line();

         // The pair is chosen by the reader itself, so whatever could explain a start (neighbouring realms, kin married
         // out, a reason another mod gives) passes the pair over instead of turning the test red.
         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && h.IsLord && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan
                                                           && h.Clan.Leader != null && h.Clan.Leader != h && Mapping.HeroPresence.IsInTheWorld(h)).ToList();
         Hero a = null, b = null;
         int pair0 = 0, tried = 0;
         Logic.Relations.PairBond drawn = null;
         foreach (Hero x in lords)
         {
            foreach (Hero y in lords.Where(y => y.Clan != x.Clan && x.MapFaction != y.MapFaction
                                                && Mapping.RelationLedgerBehavior.Instance.Ledger.BaselineOf(x.StringId, y.StringId) == null))
            {
               if (++tried > 60) break;

               int before = CharacterRelationManager.GetHeroRelation(x, y);
               // A start written as the game's draw writes it: no change announced.
               x.SetPersonalRelation(y, -80);
               Logic.Relations.PairBond read = Mapping.PairBondReader.Of(x, y);
               if (read.Basis == Logic.Relations.PairBondBasis.Unexplained)
               {
                  a = x;
                  b = y;
                  pair0 = before;
                  drawn = read;
                  break;
               }

               x.SetPersonalRelation(y, before);
            }

            if (a != null || tried > 60) break;
         }

         if (t.Skip(a == null, "no two lords (not heads of house) with nothing to explain a start between them")) return t.Line();

         Hero headA = a.Clan.Leader, headB = b.Clan.Leader;
         int heads0 = CharacterRelationManager.GetHeroRelation(headA, headB);
         try
         {
            t.Note($"{a.Name} ({a.MapFaction?.Name}) / {b.Name} ({b.MapFaction?.Name}): start -80 read as {drawn.Basis}, {drawn.Points}, {drawn.Echo}, reason '{drawn.Reason}'");
            // STAKE: tashmetu's Derthert and Tasynor: a blind draw between strangers starts no plot and no news.
            t.Expect("theDrawIsNotBelieved", drawn.Points == 0 && drawn.Basis == Logic.Relations.PairBondBasis.Unexplained, true);
            // STAKE: Gabriel: "mefiance vague": the feeling is left, in words only.
            t.Expect("aVagueUneaseRemains", drawn.Echo, Logic.Relations.PairBondEcho.VagueUnease);

            Mapping.RelationLedgerBehavior.Change(a, b, -15);
            Logic.Relations.PairBond changed = Mapping.PairBondReader.Of(a, b);
            t.Note($"after a change of -15: own slot {CharacterRelationManager.GetHeroRelation(a, b)}, believed {changed.Points}, heads {CharacterRelationManager.GetHeroRelation(headA, headB)} (was {heads0})");
            // STAKE: what happens in play is history, believed even between strangers.
            t.Expect("onlyTheChangeCounts", changed.Points, -15);
            // STAKE: tashmetu: a younger son's quarrel is his own; his father's standing does not move.
            t.Expect("theHeadsAreUntouched", CharacterRelationManager.GetHeroRelation(headA, headB), heads0);
            t.Expect("writtenOnTheirOwnSlot", CharacterRelationManager.GetHeroRelation(a, b), -95);
         }
         finally
         {
            a.SetPersonalRelation(b, pair0);
            headA.SetPersonalRelation(headB, heads0);
            Mapping.RelationLedgerBehavior.Instance.Ledger.Forget(a.StringId, b.StringId);
         }

         return t.Line();
      }

      private static string TestFolkTales(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("folk_tales");
         if (t.Skip(Hero.MainHero == null, "no campaign")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && !h.IsChild && h.Clan != Clan.PlayerClan && h.Culture != null).ToList();
         List<string> peoples = CalradiaRemembers.Logic.Folklore.FolkTalePolicy.GameCultureIds
            .Where(id => Mapping.NarrativeLoader.FolkTales(id).Count > 0 && lords.Any(h => h.Culture.StringId == id)).ToList();
         if (t.Skip(peoples.Count == 0, "no lord of a people with a folklore file")) return t.Line();

         foreach (string people in peoples)
         {
            Hero lord = lords.First(h => h.Culture.StringId == people);
            NpcProfile profile = GetOrCreate(behavior, lord);
            NpcMemoryService.Core.Knowledge.FolkloreFacts tales = Mapping.EncounterContextBuilder.KnowledgeContextFor(lord, profile).Folklore;
            bool anyTellable = Mapping.NarrativeLoader.FolkTales(people).Any(x => x.Beats.Count > 0);

            t.Expect($"{people}:carriesTales", tales?.Tales.Count > 0, true);
            if (tales == null || tales.Tales.Count == 0) continue;

            t.Expect($"{people}:favouriteCanBeTold", tales.Tales[0].Beats.Count > 0, anyTellable);
            t.Expect($"{people}:sameFavouriteNextTime",
               Mapping.EncounterContextBuilder.KnowledgeContextFor(lord, profile).Folklore?.Tales[0].Title, tales.Tales[0].Title);

            var sb = new StringBuilder();
            new NpcMemoryService.Core.Knowledge.FolklorePack().Render(sb, new EncounterContext {Folklore = tales}, false);
            t.Expect($"{people}:toldAsATale", sb.ToString().Contains("stories, not history"), true);
         }

         Hero untold = lords.FirstOrDefault(h => Mapping.NarrativeLoader.FolkTales(h.Culture.StringId).Count == 0);
         if (untold != null)
            t.Expect("aPeopleWithNoFileCarriesNone", Mapping.EncounterContextBuilder.KnowledgeContextFor(untold, GetOrCreate(behavior, untold)).Folklore, null);

         return t.Line();
      }

      private static string TestOutsideTalesLooks(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("outside_tales_looks");
         if (t.Skip(Hero.MainHero == null, "no campaign")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && !h.IsChild && h.Clan != Clan.PlayerClan && Mapping.HeroPresence.IsInTheWorld(h)).Take(2).ToList();
         if (t.Skip(lords.Count < 2, "fewer than two lords in the world")) return t.Line();

         Hero lord = lords[0], other = lords[1];
         const string source = "CR self-test", broken = "CR self-test (throws)";
         const string title = "The Self-Test Saint";
         const string selfLine = "A self-test scar crosses your brow.", seenLine = "A self-test scar crosses the brow.";
         try
         {
            CrFolklore.RegisterTaleSource(source, h => h == lord ? $"[{title}]\ngist: a saint the self-test made up.\nbeat: The saint walked.\n" : null);
            CrFolklore.RegisterTaleSource(broken, h => throw new InvalidOperationException("self-test"));
            CrAppearance.RegisterLineSource(source, (id, seen) => id == lord.StringId ? (seen ? seenLine : selfLine) : null);
            CrAppearance.RegisterLineSource(broken, (id, seen) => throw new InvalidOperationException("self-test"));

            // STAKE: tashmetu: a faith's legend reaches the character who keeps that faith, beside their people's tales.
            NpcMemoryService.Core.Knowledge.FolkloreFacts tales = Mapping.EncounterContextBuilder.BuildFolklore(lord);
            t.Expect("theLordCarriesTheOutsideTale", tales?.Tales.Any(x => x.Title == title) == true, true);
            t.Expect("anotherLordDoesNot", Mapping.EncounterContextBuilder.BuildFolklore(other)?.Tales.Any(x => x.Title == title) == true, false);

            // STAKE: tashmetu: "we would only add a line, never replace yours": CR's face comes first, the line after it.
            string own = Mapping.EncounterContextBuilder.ComposeAppearance(lord, AppearanceVoice.Self);
            string seen = Mapping.EncounterContextBuilder.ComposeAppearance(lord, AppearanceVoice.Subject);
            t.Note($"{lord.Name}: {own}");
            t.Expect("hisOwnAppearanceEndsOnTheLine", own?.EndsWith(selfLine) == true, true);
            t.Expect("asSeenByAnotherEndsOnTheLine", seen?.EndsWith(seenLine) == true, true);
            t.Expect("anotherLordHasNoLine", Mapping.EncounterContextBuilder.ComposeAppearance(other, AppearanceVoice.Self)?.Contains("self-test scar") == true, false);
         }
         finally
         {
            CrFolklore.UnregisterTaleSource(source);
            CrFolklore.UnregisterTaleSource(broken);
            CrAppearance.UnregisterLineSource(source);
            CrAppearance.UnregisterLineSource(broken);
         }

         return t.Line();
      }

      private static string TestLegends(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("legends");
         WorldEvents.LegendBehavior legends = WorldEvents.LegendBehavior.Instance;
         if (t.Skip(legends == null || Hero.MainHero == null, "no campaign")) return t.Line();
         if (t.Skip(!ModSettings.Legends, "Legends is off")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan && h.MapFaction != null).ToList();
         Hero hero = lords.FirstOrDefault();
         Hero witness = lords.FirstOrDefault(h => h != hero && h.Clan != hero?.Clan);
         Hero stranger = lords.FirstOrDefault(h => hero != null && witness != null && h.Clan != hero.Clan && h.MapFaction != hero.MapFaction && h != witness);
         if (t.Skip(stranger == null, "no three lords of two realms")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         var tale = new Logic.Legends.Legend {
            Kind = Logic.Legends.LegendKind.SiegeHeld, Name = "The Holding of Nowhere", Day = today, HeroId = hero.StringId, HeroName = hero.Name.ToString(), ClanId = hero.Clan.StringId,
            RealmId = hero.MapFaction.StringId, PlaceName = "Nowhere", FewMen = 120, ManyMen = 450, BesideIds = new List<string> {witness.StringId}
         };

         Logic.Legends.LegendLedger before = legends.Ledger;
         try
         {
            legends.Ledger = new Logic.Legends.LegendLedger();
            legends.Ledger.Legends.Add(tale);
            t.Expect("theOneItHonoursCarriesItAtOnce", WorldEvents.LegendBehavior.LineFor(hero)?.Contains("your own deed") == true, true);
            t.Expect("aWitnessCarriesItWithPride", WorldEvents.LegendBehavior.LineFor(witness)?.Contains("with pride") == true, true);
            t.Expect("aStrangerHasNotHeard", WorldEvents.LegendBehavior.LineFor(stranger), null);

            tale.Day = today - Logic.Legends.LegendPolicy.DaysToReachCalradia;
            t.Expect("aMonthLaterTheStrangerHas", WorldEvents.LegendBehavior.LineFor(stranger)?.Contains("a story people tell") == true, true);
            t.Expect("theFactsAreTheSameInEveryMouth", WorldEvents.LegendBehavior.LineFor(stranger)?.Contains("with 120 men against 450") == true, true);
         }
         finally
         {
            legends.Ledger = before;
         }

         return t.Line();
      }

      private static string TestRaidRestraint(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("raid_restraint");
         Stance.RaidRestraintBehavior restraint = Stance.RaidRestraintBehavior.Instance;
         if (t.Skip(restraint == null || Hero.MainHero == null, "no campaign")) return t.Line();
         if (t.Skip(!ModSettings.RaidRestraint, "Friends May Spare Your Villages is off")) return t.Line();

         TaleWorlds.CampaignSystem.ComponentInterfaces.TargetScoreCalculatingModel model = Campaign.Current.Models.TargetScoreCalculatingModel;
         t.Note(model?.GetType().FullName);
         t.Expect("theGameScoresThroughOurModel", model is Stance.RaidRestraintScoreModel, true);

         MobileParty party = MobileParty.AllLordParties.FirstOrDefault(p => p.LeaderHero != null && p.LeaderHero != Hero.MainHero && p.MapFaction != null && p.ActualClan != null
                                                                            && TaleWorlds.CampaignSystem.Settlements.Village.All.Any(v => v.Settlement.MapFaction.IsAtWarWith(p.MapFaction) && v.VillageState == TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.Normal));
         if (t.Skip(party == null, "no lord at war with a village's realm")) return t.Line();

         TaleWorlds.CampaignSystem.Settlements.Settlement village = TaleWorlds.CampaignSystem.Settlements.Village.All.First(v => v.Settlement.MapFaction.IsAtWarWith(party.MapFaction) && v.VillageState == TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.Normal).Settlement;
         Hero lord = party.LeaderHero;
         t.Note($"{lord.Name}, {village.Name}");

         float Score() => model.GetTargetScoreForFaction(village, Army.ArmyTypes.Raider, party, party.Party.EstimatedStrength);

         Logic.Raids.RaidRestraintLedger before = restraint.Ledger;
         Stance.RaidRestraintBehavior.DebugProtectedClan = village.OwnerClan;
         Letters.VillagesSparedLetterBehavior.DebugSuppressLetters = true;
         try
         {
            var ledger = new Logic.Raids.RaidRestraintLedger();
            restraint.ReplaceLedger(ledger);
            float free = Score();
            if (t.Skip(free <= 0f, "the base game gives this target no score")) return t.Line();

            ledger.Add(lord.StringId, party.MapFaction.StringId, false, 0);
            restraint.ReplaceLedger(ledger);
            t.Expect("aFailedDrawLeavesTheScore", Score() > 0f, true);

            ledger = new Logic.Raids.RaidRestraintLedger();
            ledger.Add(lord.StringId, party.MapFaction.StringId, true, 0);
            restraint.ReplaceLedger(ledger);
            t.Expect("aFriendWhoSparesScoresItAtZero", Score(), 0f);

            t.Expect("aLetterOnTheRoadStillHolds", restraint.StillSpares(lord.StringId), true);
            restraint.BreakForHouse(lord.Clan, "cr.test");
            t.Expect("aBrokenRestraintGivesItBack", Score() > 0f, true);
            t.Expect("aLetterOnTheRoadIsNowStale", restraint.StillSpares(lord.StringId), false);

            Hero writer = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.HasMet && h.Clan != Clan.PlayerClan && Mapping.ActionGate.Allows(h, ActionKind.Letter)
                                                                  && h.MapFaction != null && behavior?.Store?.Get(h.StringId) != null);
            if (writer != null)
            {
               ledger = new Logic.Raids.RaidRestraintLedger();
               ledger.Add(writer.StringId, writer.MapFaction.StringId, true, 0);
               ledger.Add("nobody", writer.MapFaction.StringId, true, 0);
               restraint.ReplaceLedger(ledger);
               Letters.VillagesSparedLetterBehavior.TellThePlayer();
               Letters.VillagesSparedLetterBehavior.TellThePlayer();
               t.Expect("oneWriterOneWar", ledger.Draws.Count(d => d.PlayerWasTold), 1);
               t.Expect("theLordWhoMayWriteIsTheOne", ledger.Draws[0].PlayerWasTold, true);
            }
         }
         finally
         {
            Stance.RaidRestraintBehavior.DebugProtectedClan = null;
            Letters.VillagesSparedLetterBehavior.DebugSuppressLetters = false;
            restraint.ReplaceLedger(before);
         }

         return t.Line();
      }

      private static string TestCaptorTerms(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captor_terms");
         Quests.CaptorTermsBehavior terms = Quests.CaptorTermsBehavior.Instance;
         if (t.Skip(behavior?.Store == null || terms == null || Hero.MainHero == null, "no campaign")) return t.Line();
         if (t.Skip(Hero.MainHero.IsPrisoner, "you are a prisoner: the test would free you")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h.Clan != Clan.PlayerClan && Mapping.HeroPresence.IsInTheWorld(h)
                                                             && behavior.Store.Get(h.StringId) != null);
         if (t.Skip(lord == null, "no lord met yet (talk to one first)")) return t.Line();

         t.Note($"{lord.Name}");
         int gold = Hero.MainHero.Gold;
         t.Expect("noCaptivityNoPrice", Quests.CaptorTermsBehavior.RansomThePlayerCanPay(), 0);
         t.Expect("aRansomWithoutACaptivityIsRefused", Quests.CaptorTermsBehavior.GrantRansom(lord), false);
         t.Expect("andNoGoldMoved", Hero.MainHero.Gold, gold);
         int oaths = terms.Ledger.Oaths.Count;
         t.Expect("anOathFromAFreePlayerIsRefused", Quests.CaptorTermsBehavior.GrantParole(lord), false);
         t.Expect("andSwearsNothing", terms.Ledger.Oaths.Count, oaths);
         t.Expect("anExchangeFromAFreePlayerIsRefused", Quests.CaptorTermsBehavior.GrantExchange(lord), false);

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         int regard = profile.ReputationWithPlayer;
         int events = profile.Events.Count;
         int today = (int) CampaignTime.Now.ToDays;
         Logic.Captivity.CaptorParoleLedger before = terms.Ledger;
         terms.Ledger = new Logic.Captivity.CaptorParoleLedger();
         Quests.CaptorTermsBehavior.DebugSuppressGrudge = true;
         try
         {
            Logic.Captivity.CaptorParole kept = terms.Ledger.Add(lord.StringId, lord.MapFaction?.StringId, "the realm", today);
            terms.Close(kept, false, today);
            t.Expect("anOathKeptRaisesRegard", profile.ReputationWithPlayer > regard, true);
            t.Expect("andIsOver", terms.Ledger.Oaths.Count, 0);
            t.Expect("andIsRemembered", profile.Events.Count, events + 1);

            int warm = profile.ReputationWithPlayer;
            Logic.Captivity.CaptorParole broken = terms.Ledger.Add(lord.StringId, lord.MapFaction?.StringId, "the realm", today);
            terms.Close(broken, true, today);
            t.Expect("anOathBrokenLowersRegard", profile.ReputationWithPlayer < warm, true);
            t.Expect("andIsRememberedAsABetrayal", profile.Events.Last().type, NotableEventType.Betrayal);
         }
         finally
         {
            Quests.CaptorTermsBehavior.DebugSuppressGrudge = false;
            terms.Ledger = before;
            profile.ReputationWithPlayer = regard;
            while (profile.Events.Count > events) profile.Events.RemoveAt(profile.Events.Count - 1);
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestHelpPlea(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("help_plea");
         HelpPleas.HelpPleaBehavior pleas = HelpPleas.HelpPleaBehavior.Instance;
         if (t.Skip(behavior?.Store == null || pleas == null || Hero.MainHero == null, "no campaign")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsPrisoner && !h.IsChild && h.Clan != Clan.PlayerClan && Mapping.HeroPresence.IsInTheWorld(h)
                                                             && behavior.Store.Get(h.StringId) != null && !h.MapFaction.IsAtWarWith(Hero.MainHero.MapFaction));
         if (t.Skip(lord == null, "no lord met yet who is not at war with you")) return t.Line();

         Settlement quiet = Settlement.All.FirstOrDefault(s => s.IsFortification && !s.IsUnderSiege);
         if (t.Skip(quiet == null, "no quiet town or castle")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         int regardBefore = profile.ReputationWithPlayer;
         int eventsBefore = profile.Events.Count;
         int playerGold = Hero.MainHero.Gold;
         int lordGold = lord.Gold;
         Logic.HelpPleas.HelpPleaLedger ledgerBefore = pleas.Ledger;
         const int amount = 100;
         int today = HelpPleas.HelpPleaBehavior.Today;
         pleas.Ledger = new Logic.HelpPleas.HelpPleaLedger {NextId = ledgerBefore.NextId + 1000}; // never an id a real plea holds
         string reliefId = null;
         HelpPleas.HelpPleaBehavior.DebugSuppressLetters = true;
         HelpPleas.HelpPleaBehavior.DebugSuppressKeepsakes = true;
         try
         {
            t.Note($"{lord.Name}");
            Hero.MainHero.ChangeHeroGold(amount);

            Logic.HelpPleas.HelpPlea onTheRoad = pleas.Open(lord, Logic.HelpPleas.HelpCrisis.Besieged, lord.Clan, quiet, null, 0, "test:road", today);
            t.Expect("noAnswerIsWantedBeforeTheLetterArrives", pleas.Waiting(lord.StringId) == null, true);
            pleas.Upkeep(today);
            t.Expect("aSiegeOverWhileTheLetterRodeClosesIt", pleas.Ledger.From(lord.StringId) == null, true);
            t.Expect("andAskedNothingOfThePlayer", profile.ReputationWithPlayer, regardBefore);

            Logic.HelpPleas.HelpPlea coin = pleas.Open(lord, Logic.HelpPleas.HelpCrisis.Ruined, lord.Clan, null, null, amount, "test:coin", today);
            pleas.OnLetterReached(lord.StringId, today);
            t.Expect("onArrivalItWaitsForTheAnswer", pleas.Waiting(lord.StringId) == coin, true);
            var window = new LetterViewModel();
            window.SetupRead(new PendingLetter {Reason = LetterReason.ReinforcementRequest, Content = "Help."}, profile);
            t.Expect("theLetterShowsTheSumOnItsButton", window.AcceptOfferButtonText, $"Send {amount} denars");
            t.Expect("theYesIsOnOffer", window.ShowAcceptOffer, true);
            t.Expect("theNoIsOnOffer", window.ShowDeclineOffer, true);
            t.Expect("theFreeReplyIsNot", window.ShowReplyButton, false);
            t.Expect("norAcknowledge", window.ShowAcknowledge, false);
            t.Expect("thePriceIsTold", window.ShowOfferLapsedNote, true);
            t.Expect("theDeadlineRunsFromTheArrival", coin.DeadlineDay, today + Logic.HelpPleas.HelpPleaPolicy.DaysToAnswer);
            int before = lord.Gold;
            pleas.Accept(coin);
            t.Expect("theTrueSumReachesTheWriter", lord.Gold - before, amount);
            t.Expect("thePleaIsClosed", pleas.Ledger.From(lord.StringId) == null, true);
            t.Expect("andTheyAreThankful", profile.ReputationWithPlayer > regardBefore, true);

            int warm = profile.ReputationWithPlayer;
            Logic.HelpPleas.HelpPlea refused = pleas.Open(lord, Logic.HelpPleas.HelpCrisis.Starving, lord.Clan, quiet, null, Logic.HelpPleas.HelpPleaPolicy.FoodAsked, "test:food", today);
            pleas.OnLetterReached(lord.StringId, today);
            pleas.Refuse(refused);
            var answered = new LetterViewModel();
            answered.SetupRead(new PendingLetter {Reason = LetterReason.ReinforcementRequest, Content = "Help."}, profile);
            t.Expect("onceAnsweredTheButtonsAreGone", answered.ShowDeclineOffer, false);

            Logic.HelpPleas.HelpPlea stopped = pleas.Open(lord, Logic.HelpPleas.HelpCrisis.Ruined, lord.Clan, null, null, amount, "test:stopped", today);
            pleas.OnLetterStopped(lord.StringId);
            t.Expect("aLetterTheSwitchStoppedClosesItsPlea", pleas.Ledger.From(lord.StringId) == null, true);
            bool couldHave = refused.IncapacityWhenAnswered == Logic.HelpPleas.HelpIncapacity.None;
            t.Expect("anHonestNoLowersRegardOnlyIfThePlayerCould", profile.ReputationWithPlayer < warm, couldHave);

            Logic.HelpPleas.HelpPlea relief = pleas.Open(lord, Logic.HelpPleas.HelpCrisis.Besieged, quiet.OwnerClan, quiet, null, 0, "test:relief", today);
            pleas.OnLetterReached(lord.StringId, today);
            reliefId = relief.Id;
            pleas.Accept(relief);
            bool journalled = profile.ActiveQuests.Any(q => q.ExternalId == relief.Id && q.Status == QuestStatus.Active);
            t.Expect("aPromiseIsAJournalEntry", journalled, true);
            int promised = profile.ReputationWithPlayer;
            relief.DistanceWhenPromised = float.MaxValue; // the player has closed the distance: on the road, and late
            pleas.Upkeep(today);
            t.Expect("theSiegeOverClosesTheEntry", profile.ActiveQuests.Any(q => q.ExternalId == relief.Id && q.Status == QuestStatus.Active), false);
            t.Expect("aPlayerOnTheRoadWhoCameTooLateIsNotBlamed", profile.ReputationWithPlayer, promised);

            pleas.Ledger.Reproaches.Add(new Logic.HelpPleas.HelpReproach {SenderId = lord.StringId, Context = "test", OnDay = today});
            pleas.SendReproaches(today);
            t.Expect("aFreeWriterSendsTheLastLetter", pleas.Ledger.Reproaches.Count, 0);
            pleas.Ledger.Reproaches.Add(new Logic.HelpPleas.HelpReproach {SenderId = lord.StringId, Context = "test", OnDay = today - Logic.HelpPleas.HelpPleaPolicy.DaysAReproachWaits - 1});
            pleas.SendReproaches(today);
            t.Expect("onlyWhileTheMomentLasts", pleas.Ledger.Reproaches.Count, 0);

            Settlement besieged = Settlement.All.FirstOrDefault(s => s.IsFortification && s.IsUnderSiege && s.Town != null);
            if (besieged == null) t.Note("no siege in the world: the strengthening was not driven");
            else
            {
               float foodBefore = besieged.Town.FoodStocks;
               float militiaBefore = besieged.Militia;
               HelpPleas.HelpPleaBehavior.Strengthen(besieged);
               t.Expect("theHelpIsFeltAtTheWalls", besieged.Town.FoodStocks >= foodBefore && besieged.Militia >= militiaBefore, true);
               besieged.Town.FoodStocks = foodBefore;
               besieged.Militia = militiaBefore;
            }

            float quietFood = quiet.Town?.FoodStocks ?? 0f;
            HelpPleas.HelpPleaBehavior.Strengthen(quiet);
            t.Expect("aPlaceNotUnderSiegeGetsNothing", quiet.Town?.FoodStocks ?? 0f, quietFood);
         }
         finally
         {
            HelpPleas.HelpPleaBehavior.DebugSuppressLetters = false;
            HelpPleas.HelpPleaBehavior.DebugSuppressKeepsakes = false;
            pleas.Ledger = ledgerBefore;
            profile.ReputationWithPlayer = regardBefore;
            while (profile.Events.Count > eventsBefore) profile.Events.RemoveAt(profile.Events.Count - 1);
            profile.ActiveQuests.RemoveAll(q => q.ExternalId == reliefId);
            Hero.MainHero.ChangeHeroGold(playerGold - Hero.MainHero.Gold);
            lord.ChangeHeroGold(lordGold - lord.Gold);
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestNpcDossier(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("npc_dossier");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();

         // A lord already known to the store, so nothing is left behind in it.
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && Mapping.HeroPresence.IsInTheWorld(h) && behavior.Store.Get(h.StringId) != null);
         if (t.Skip(lord == null, "no lord met yet (talk to one first)")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         Fear fearBefore = profile.Fear;
         bool knownBefore = profile.FearKnown;
         var chat = new ChatViewModel();
         try
         {
            t.Note($"{lord.Name}");
            profile.Fear = Fear.Fire;
            profile.FearKnown = false;
            string secret = Logic.Character.NaturePolicy.PageLines(new Logic.Character.NaturePageFacts {Fear = Fear.Fire, FearKnown = true, IsFemale = lord.IsFemale})[0];

            chat.OpenCouncilDossier(lord.StringId);
            t.Expect("aFearNotYetLearnedStaysHidden", chat.PanelInfoDiscoveries.Contains(secret), false);

            ProfileMutator.Apply(profile, new ParsedResponse {
               Dialogue = "", Discovery = new DiscoveredTrait {Key = NatureDiscovery.FearKey, Description = "He said so."}
            }, (int) CampaignTime.Now.ToDays);
            t.Expect("hisWordsMarkItLearned", profile.FearKnown, true);

            chat.RefreshOpenDossier();
            t.Expect("theOpenPanelShowsItAtOnce", chat.PanelInfoDiscoveries.Contains(secret), true);
            t.Expect("underItsHeading", chat.ShowPanelDiscoveries, true);
            t.Expect("thePanelAndThePageReadTheSameGrievances", chat.PanelGrievances, Mapping.ShownText.Of(Logic.Chat.NpcDossierText.Bullets(Mapping.DossierReader.GrievanceLines(lord))));
            t.Expect("thePanelAndThePageReadTheSameKindnesses", chat.PanelKindnesses, Mapping.ShownText.Of(Logic.Chat.NpcDossierText.Bullets(Mapping.DossierReader.KindnessLines(lord))));
            if (!Logic.Trauma.TraumaPagePolicy.Shows(ModSettings.AdultContentLevel, false))
               t.Expect("traumaWaitsForHardcore", chat.ShowPanelTrauma, false);
         }
         finally
         {
            profile.Fear = fearBefore;
            profile.FearKnown = knownBefore;
            chat.CloseCouncilDossier();
            chat.ReleaseCouncilPortraits();
         }

         return t.Line();
      }

      private static string TestHoverGlow(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("hover_glow");

         // Gauntlet finds a widget by its class name when a prefab loads; a widget it cannot build breaks the whole chat window.
         t.Expect("the widget has the constructor the engine calls", typeof(CalradiaRemembers.Portraits.CrHoverGlowWidget).GetConstructor(new[] {typeof(TaleWorlds.GauntletUI.UIContext)}) != null, true);
         foreach (string prefab in new[] {"CalradiaRemembersChat.xml", "CalradiaRemembersChat_Manuscript.xml"})
         {
            string path = System.IO.Path.Combine(CalradiaRemembers.Paths.ModulePaths.Root, "GUI", "Prefabs", prefab);
            t.Expect($"the installed {prefab} carries the glow", System.IO.File.Exists(path) && System.IO.File.ReadAllText(path).Contains("<CrHoverGlowWidget"), true);
         }

         t.Expect("the halo picture is installed", System.IO.File.Exists(System.IO.Path.Combine(CalradiaRemembers.Paths.ModulePaths.Root, "GUI", "Images", "cr_hover_glow.png")), true);
         t.Note("the glow itself is seen in the game: hover a tool button in each chat skin.");

         return t.Line();
      }

      private static string TestKillRoll(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("kill_roll");

         Hero target = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(target == null || Hero.MainHero == null, "no lord in the world to stand in")) return t.Line();

         CalradiaRemembers.Logic.Violence.ViolenceFacts facts = CalradiaRemembers.Violence.ViolenceSceneReader.FactsFor(target);
         int chance = CalradiaRemembers.Logic.Violence.ViolencePolicy.SuccessChance(CalradiaRemembers.Logic.Violence.ViolentAct.Kill, facts);
         const int forcedRoll = 41;
         t.Note($"target={target.Name}, chance={chance}%, exposure={facts.Exposure}, forced roll={forcedRoll}");

         ChatViewModel NewChat()
         {
            var chat = new ChatViewModel {KillNarrationOffline = true, KillRollForcedRoll = forcedRoll};
            chat.SetNpcHero(target);
            chat.IsSendEnabled = true;

            return chat;
         }

         // Plays the roll out the way the chat panel's frame tick does, and reports what the landed number showed.
         (string shown, bool landedSucceeded, bool landedFailed) PlayOut(ChatViewModel chat)
         {
            string shown = null;
            bool succeeded = false, failed = false;
            for (var i = 0; i < 400 && chat.IsKillAttemptOpen; i++)
            {
               chat.TickKillRoll(0.05f);
               if (chat.IsKillRollLanded && shown == null)
               {
                  shown = chat.KillRollShownText;
                  succeeded = chat.IsKillRollSucceeded;
                  failed = chat.IsKillRollFailed;
               }
            }

            return (shown, succeeded, failed);
         }

         // Staying the hand: nothing happens and nothing stays open.
         ChatViewModel vm = NewChat();
         var struck = 0;
         bool offered = vm.OfferKillAttempt(target, facts, chance, roll => { struck++; return null; });
         t.Expect("the chat holds the killing window", offered && vm.IsKillRollVisible && vm.IsKillRollConfirming, true);
         t.Expect("the window names the measured chance", vm.KillRollChanceText.Contains($"{chance} in 100"), true);
         t.Expect("the window says where the chance comes from", !string.IsNullOrWhiteSpace(vm.KillRollReasons), true);
         // The painted art ships beside the prefab; a missing picture would leave a see-through window with only its text.
         string[] art = new[] {vm.KillRollPanelPath, vm.KillRollPlaquePath}.Concat(new[] {vm.KillRollStrikeArt, vm.KillRollStayArt}.SelectMany(stem => new[] {"normal", "hover", "pressed", "disabled"}.Select(state => $"{stem}_{state}.png"))).ToArray();
         t.Expect("every picture of the painted window is installed", art.Count(System.IO.File.Exists), art.Length);
         vm.ExecuteKillRollStay();
         t.Expect("staying the hand closes the window and leaves nothing open", !vm.IsKillRollVisible && !vm.IsKillAttemptOpen, true);
         t.Expect("and nothing was struck", struck, 0);

         // A failed attempt: the deed is struck with the rolled number, the number lands on it, the character answers.
         vm = NewChat();
         int gotRoll = -1;
         vm.OfferKillAttempt(target, facts, chance, roll =>
         {
            gotRoll = roll;

            return new CalradiaRemembers.Logic.Violence.KillAttemptResult {Verdict = CalradiaRemembers.Logic.Violence.ViolenceVerdict.Failed, Killed = false, Message = "test"};
         });
         vm.InputText = "a line typed while the window is open";
         vm.ExecuteSendMessage();
         t.Expect("the chat sends nothing while the window is open", vm.IsKillAttemptOpen && vm.InputText.Length > 0, true);
         vm.InputText = "";
         vm.ExecuteKillRollStrike();
         t.Expect("the strike is made with the game's roll", gotRoll, forcedRoll);
         (string shownFail, bool okFail, bool koFail) = PlayOut(vm);
         t.Expect("the number lands on that roll, shown from 1 to 100", shownFail, (forcedRoll + 1).ToString());
         t.Expect("a failure shows FAILURE, not SUCCESS", !okFail && koFail, true);
         t.Expect("after the scene, the character answers", vm.LastKillAftermath, CalradiaRemembers.Logic.Violence.KillAftermath.NpcReacts);
         t.Expect("and the chat is open again once the scene is told", !vm.IsKillAttemptOpen && vm.IsSendEnabled, true);

         // A kill: the scene ends the conversation and only leaving remains.
         vm = NewChat();
         vm.OfferKillAttempt(target, facts, chance, roll =>
            new CalradiaRemembers.Logic.Violence.KillAttemptResult {Verdict = CalradiaRemembers.Logic.Violence.ViolenceVerdict.Succeeded, Killed = true, Message = "test"});
         vm.ExecuteKillRollStrike();
         var (_, okKill, _) = PlayOut(vm);
         t.Expect("a kill shows SUCCESS", okKill, true);
         t.Expect("after a kill, the conversation ends", vm.LastKillAftermath, CalradiaRemembers.Logic.Violence.KillAftermath.ConversationEnds);
         t.Expect("and only Leave remains", vm.CloseButtonText == "Leave" && !vm.IsSendEnabled, true);
         t.Note("not driven here: a captive's escape (needs a captive scene) and the model's scene (a paid call); cr.kill_roll plays both in a real chat.");

         return t.Line();
      }

      private static string TestPlayerViolence(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("player_violence");

         if (t.Abort(behavior?.GameStateBridge == null || Hero.MainHero == null, "no bridge / main hero")) return t.Line();

         Hero target = Hero.AllAliveHeroes?.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner);
         if (t.Abort(target == null, "no live lord to stand in as a victim")) return t.Line();

         // THE guarantee: with the MCM toggle off (its default), a narrated murder must change nothing at all.
         // Driven through the REAL bridge dispatch, and asserted on the victim still being alive.
         bool lethalEnabled = ModSettings.AllowKillingCharacters;
         bool aliveBefore = target.IsAlive;

         ActionOutcome killed = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "kill_npc"}, target, new ActionContext(behavior.Store?.Get(target.StringId), null));

         t.Note($"target={target.Name}, lethalToggle={(lethalEnabled ? "ON" : "OFF")}, exposure={CalradiaRemembers.Violence.ViolenceSceneReader.ExposureOf(target)}");

         if (!lethalEnabled)
         {
            t.Expect("a kill is refused while the toggle is off", killed?.WasRefused, true);
            t.Expect("and the victim is still alive", target.IsAlive, aliveBefore);
         }
         else
         {
            t.Note("lethal violence is ENABLED in MCM, so the kill path was live; only the refusal case is asserted when off.");
         }

         // The scene reader must place a lord who leads soldiers, or stands in a town, out of easy reach; a victim
         // alone is the reporter's case and must read as such.
         CalradiaRemembers.Logic.Violence.ViolenceFacts facts = CalradiaRemembers.Violence.ViolenceSceneReader.FactsFor(target);
         t.Expect("both fighters are measured", facts.PlayerProwess > 0 && facts.TargetProwess > 0, true);
         t.Expect("robbery is never barred by the lethal toggle",
            CalradiaRemembers.Logic.Violence.ViolencePolicy.IsPermitted(CalradiaRemembers.Logic.Violence.ViolentAct.Rob, false), true);

         // A killing asks the PLAYER first (Gabriel 2026-09-06), so the model over-reading a threat can never end a
         // life on its own; nothing recoverable interrupts the scene with a modal.
         t.Expect("only a killing asks the player first",
            CalradiaRemembers.Logic.Violence.ViolencePolicy.RequiresConfirmation(CalradiaRemembers.Logic.Violence.ViolentAct.Kill), true);
         t.Expect("a beating never interrupts with a modal",
            CalradiaRemembers.Logic.Violence.ViolencePolicy.RequiresConfirmation(CalradiaRemembers.Logic.Violence.ViolentAct.Assault), false);

         // Inc 3: the world really answers. Drive the REAL consequence service for a FAILED assault (nothing is
         // wounded, nobody dies) and assert the engine's own crime rating actually moved, then undo it.
         Hero kin = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != target && h.Clan == target.Clan && !h.IsChild);
         IFaction realm = target.MapFaction;
         float crimeBefore = realm?.MainHeroCrimeRating ?? 0f;
         int kinGrudgesBefore = kin == null ? 0 : CalradiaRemembers.Grudges.GrudgeBehavior.Instance?.GrudgesFor(kin.StringId)?.Count ?? 0;
         // The consequence service really spends renown and really collapses the victim's regard, so BOTH must be
         // captured and put back: a diagnostic that leaves a lord hating the player by 50 is worse than no test.
         float renownBefore = Clan.PlayerClan?.Renown ?? 0f;
         NpcProfile victimProfile = behavior.Store?.Get(target.StringId);
         int victimRegardBefore = victimProfile?.ReputationWithPlayer ?? 0;

         try
         {
            CalradiaRemembers.Logic.Violence.ViolenceConsequence cost =
               CalradiaRemembers.Violence.ViolenceConsequenceService.Apply(target,
                  CalradiaRemembers.Logic.Violence.ViolentAct.Assault,
                  CalradiaRemembers.Logic.Violence.ViolenceVerdict.Failed,
                  CalradiaRemembers.Logic.Violence.ViolenceExposure.Onlookers);

            t.Note($"cost: crime={cost.CrimeRating} regard={cost.RelationHit} renown=-{cost.RenownLoss} kin={cost.KinGrudgeMagnitude}");
            t.Expect("a failed attempt still costs with the law", cost.CrimeRating > 0, true);
            t.Expect("the engine's own crime rating actually moved",
               realm != null && realm.MainHeroCrimeRating > crimeBefore, true);

            if (kin != null)
               t.Expect("kin of the victim take it up",
                  (CalradiaRemembers.Grudges.GrudgeBehavior.Instance?.GrudgesFor(kin.StringId)?.Count ?? 0) > kinGrudgesBefore, true);
         }
         finally
         {
            if (realm != null) realm.MainHeroCrimeRating = crimeBefore;
            if (kin != null && kinGrudgesBefore == 0) CalradiaRemembers.Grudges.GrudgeBehavior.Instance?.ClearGrudgesFor(kin.StringId);

            float renownNow = Clan.PlayerClan?.Renown ?? renownBefore;
            if (Clan.PlayerClan != null && Math.Abs(renownNow - renownBefore) > 0.01f)
               GainRenownAction.Apply(Hero.MainHero, renownBefore - renownNow, false);

            if (victimProfile != null)
            {
               victimProfile.ReputationWithPlayer = victimRegardBefore;
               behavior.Store.Set(victimProfile);
            }
         }

         return t.Line();
      }

      private static string TestBattleFeat(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("battle_feat");

         if (t.Abort(Hero.MainHero == null, "no main hero")) return t.Line();

         // A weak foe and a strong one, so both ends of the exploit ruling are exercised on LIVE hero facts.
         List<Hero> lords = Hero.AllAliveHeroes?.Where(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner).ToList();
         if (t.Abort(lords == null || lords.Count == 0, "no live lord to stand in as a foe")) return t.Line();

         CombatantFacts player = CalradiaRemembers.Mapping.BattleFeatFacts.For(Hero.MainHero);
         CombatantFacts foe = CalradiaRemembers.Mapping.BattleFeatFacts.For(lords[0]);

         // Synthetic extremes: the ruling itself must not depend on who happens to be alive in this campaign.
         var weakling = new CombatantFacts {BestWeaponSkill = 20, Riding = 0, Athletics = 0, Level = 2, ClanTier = 0};
         var champion = new CombatantFacts {BestWeaponSkill = 300, Riding = 200, Athletics = 200, Level = 35, ClanTier = CombatProwessPolicy.FamousClanTier};

         t.Note($"player prowess={CombatProwessPolicy.Prowess(player)}, {lords[0].Name} prowess={CombatProwessPolicy.Prowess(foe)}");
         t.Expect("live hero facts yield a real prowess score", CombatProwessPolicy.Prowess(foe) > 1, true);
         t.Expect("besting a champion is an exploit", CombatProwessPolicy.Rate(weakling, champion), CombatFeatTier.Exploit);
         t.Expect("an exploit travels as gossip", CombatProwessPolicy.TravelsAsGossip(CombatFeatTier.Exploit), true);
         t.Expect("stomping a weakling is unremarkable", CombatProwessPolicy.Rate(champion, weakling), CombatFeatTier.Unremarkable);
         t.Expect("an unremarkable win never travels", CombatProwessPolicy.TravelsAsGossip(CombatFeatTier.Unremarkable), false);

         // The journal itself: drive the REAL ledger through its debug seam (no battle needed) and assert it keeps
         // the deed, the mirror deed, and the troop tally apart.
         var journal = new CalradiaRemembers.Battles.BattleFeatJournal();
         journal.DebugRecord(lords[0].StringId, lords[0].StringId, 3);
         journal.DebugRecord(lords[0].StringId, null, 2); // duplicates must not pile up

         t.Expect("the felled hero is journaled once", journal.HeroesDowned.Count, 1);
         t.Expect("who downed the player is journaled", journal.DownedThePlayer.Count, 1);
         t.Expect("the troop tally accumulates", journal.TroopsFelled, 5);

         // A lord is BESTED, never called dead unless he truly died (Gabriel's truth rule).
         string bested = BattleFeatText.WitnessedFeat(lords[0].Name?.ToString(), CombatFeatOutcome.Bested, "open battle");
         t.Expect("a bested lord is not called killed", bested.Contains("kill"), false);

         // Inc 2, end to end on the REAL reporter. The DOWNING line always survives; the deed line only when the
         // foe was worth beating, so pick a lord the ruling actually rates (any campaign has stronger lords than
         // the player early on, but never assume it: fall back and assert only what holds).
         Hero ratedFoe = lords.FirstOrDefault(h =>
            CombatProwessPolicy.Rate(player, CalradiaRemembers.Mapping.BattleFeatFacts.For(h)) != CombatFeatTier.Unremarkable);

         var endToEnd = new CalradiaRemembers.Battles.BattleFeatJournal();
         endToEnd.DebugRecord(ratedFoe?.StringId, lords[0].StringId, 0);

         IReadOnlyList<string> lines = CalradiaRemembers.Battles.BattleFeatReporter.BuildReport(endToEnd, "open battle").LinesFor("some_bystander");
         string joined = string.Join(" | ", lines);

         t.Note($"ratedFoe={(ratedFoe == null ? "(none stronger)" : ratedFoe.Name.ToString())}; lines={lines.Count}: {joined}");
         t.Expect("who downed the player always survives distillation", lines.Count >= 1, true);
         t.Expect("every witness line is first-hand", lines.All(l => l.StartsWith("I saw")), true);
         t.Expect("the foe who downed the player is named", joined.Contains(lords[0].Name?.ToString() ?? "??"), true);

         if (ratedFoe != null && !ratedFoe.IsDead)
         {
            t.Expect("a worthy foe yields a deed line too", lines.Count >= 2, true);
            t.Expect("a living lord is never mourned", joined.Contains("cut"), false);
         }

         // Inc 4 (voice): the man a deed is ABOUT must not read it as a bystander's report. The lord who downed the
         // player says so himself; a bystander is told who did it.
         CalradiaRemembers.Battles.BattleFeatReport report =
            CalradiaRemembers.Battles.BattleFeatReporter.BuildReport(endToEnd, "open battle");
         string subjectLines = string.Join(" | ", report.LinesFor(lords[0].StringId));

         // NAMED, not "you". reminensce's report (2.5.18) was a lord taking the PLAYER's defeat for his own,
         // because memory lines under YOUR HISTORY WITH THIS PLAYER said "you" while the whole prompt says "you"
         // to mean the NPC. Every new memory names the player instead, so the line to look for is his name. This
         // assertion still read the old wording and only surfaced now, which is what a testall is for.
         string whoThePlayerIs = Hero.MainHero?.Name?.ToString() ?? "the player";

         t.Note($"subjectLines={subjectLines}");
         t.Expect("the man who downed the player says so himself", subjectLines.Contains($"I put {whoThePlayerIs} down myself"), true);
         t.Expect("he does not report himself in the third person",
            subjectLines.Contains($"I saw {lords[0].Name}"), false);

         // Inc 3 (circulation): only an EXPLOIT leaves the field. Drive the REAL recorder both ways and check the
         // world-event store, then retract whatever was seeded so the campaign is left untouched.
         Hero exploitFoe = lords.FirstOrDefault(h =>
            CombatProwessPolicy.Rate(player, CalradiaRemembers.Mapping.BattleFeatFacts.For(h)) == CombatFeatTier.Exploit);
         Hero pushoverFoe = lords.FirstOrDefault(h =>
            CombatProwessPolicy.Rate(player, CalradiaRemembers.Mapping.BattleFeatFacts.For(h)) == CombatFeatTier.Unremarkable);
         var today = (int) CampaignTime.Now.ToDays;

         try
         {
            if (pushoverFoe != null)
            {
               bool travelled = CalradiaRemembers.Battles.BattleFeatReporter.TryRecordExploit(
                  pushoverFoe, CombatFeatOutcome.Bested, "open battle");
               t.Expect("an unremarkable win never leaves the field", travelled, false);
            }

            if (exploitFoe != null)
            {
               bool travelled = CalradiaRemembers.Battles.BattleFeatReporter.TryRecordExploit(
                  exploitFoe, CombatFeatOutcome.Bested, "open battle");
               WorldEvents.WorldEvent we = WorldEvents.WorldEventStore.Instance?.GetById($"cr_feat_{exploitFoe.StringId}_{today}");

               t.Note($"exploitFoe={exploitFoe.Name}");
               t.Expect("an exploit leaves the field", travelled, true);
               t.Expect("it is recorded as a player feat", we?.Type, WorldEvents.WorldEventType.PlayerFeat);
               t.Expect("it is the player's own deed (a rumour ABOUT them)", we?.InvolvesPlayer, true);
               t.Expect("no faction is tagged, so no lord claims to have been there", (we?.FactionIds?.Count ?? 0), 0);
               t.Expect("the gossip line is hearsay", we != null && we.Summary.StartsWith("They say"), true);
            }
         }
         finally
         {
            if (exploitFoe != null) WorldEvents.WorldEventStore.Instance?.Remove($"cr_feat_{exploitFoe.StringId}_{today}");
            if (pushoverFoe != null) WorldEvents.WorldEventStore.Instance?.Remove($"cr_feat_{pushoverFoe.StringId}_{today}");
         }

         return t.Line();
      }

      private static string TestTournamentMemory(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tournament_memory");

         if (t.Abort(behavior?.Store == null || WorldEvents.WorldEventStore.Instance == null, "store / world-event store not initialized")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes?.Where(h => h != Hero.MainHero && h.IsLord && !h.IsPrisoner).Take(2).ToList();
         if (t.Abort(lords == null || lords.Count < 2, "need two live lords to stand in as tournament rivals")) return t.Line();

         Hero beaten = lords[0];   // the player bested them
         Hero champion = lords[1]; // they beat the player and took the crown

         NpcProfile beatenP = GetOrCreate(behavior, beaten);
         NpcProfile champP = GetOrCreate(behavior, champion);
         int beatenBefore = beatenP.Events?.Count ?? 0;
         int champBefore = champP.Events?.Count ?? 0;
         int champLettersBefore = champP.LetterCandidates?.Count ?? 0;
         int champHonor0 = champion.GetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor);

         var today = (int) CampaignTime.Now.ToDays;
         const string town = "SelfTestArena";
         string gossipId = $"cr_tourney_{town}_{today}";
         WorldEvents.WorldEventStore.Instance.Remove(gossipId); // clear residue

         var result = new CalradiaRemembers.Logic.Tournaments.TournamentResult(
            town, today, playerWonTournament: false, playerEliminatedRound: 4, championHeroId: champion.StringId,
            bouts: new List<CalradiaRemembers.Logic.Tournaments.TournamentBout>
            {
               new(2, new List<string> {beaten.StringId}, playerAdvanced: true),
               new(4, new List<string> {champion.StringId}, playerAdvanced: false)
            });

         try
         {
            // Force the champion gracious so the grounded-letter path is exercised (default traits yield a measured
            // tone that writes no letter).
            champion.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, 2);

            CalradiaRemembers.Tournaments.TournamentMemoryFeeder.Apply(result);

            string beatenLast = beatenP.Events != null && beatenP.Events.Count > beatenBefore ? beatenP.Events[beatenP.Events.Count - 1].summary : "";
            string champLast = champP.Events != null && champP.Events.Count > champBefore ? champP.Events[champP.Events.Count - 1].summary : "";
            WorldEvents.WorldEvent gossip = WorldEvents.WorldEventStore.Instance.GetById(gossipId);
            bool letterQueued = champP.LetterCandidates != null
                                && champP.LetterCandidates.Any(c => c.Reason == NpcMemoryService.Core.Models.LetterReason.TournamentResult);

            t.Note($"beaten={beaten.Name} champion={champion.Name}");
            t.Expect("the player-beaten lord remembers losing", beatenLast.Contains("bested me"), true);
            t.Expect("the champion remembers besting the player", champLast.Contains("bested the player"), true);
            t.Expect("the champion recalls the crown", champLast.Contains("crown"), true);
            t.Expect("a champion gossip event is recorded", gossip != null, true);
            t.Expect("the gossip does not involve the player", gossip?.InvolvesPlayer, false);
            t.Expect("a grounded tournament letter is queued", letterQueued, true);
         }
         finally
         {
            champion.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, champHonor0);
            if (beatenP.Events != null) while (beatenP.Events.Count > beatenBefore) beatenP.Events.RemoveAt(beatenP.Events.Count - 1);
            if (champP.Events != null) while (champP.Events.Count > champBefore) champP.Events.RemoveAt(champP.Events.Count - 1);
            if (champP.LetterCandidates != null) while (champP.LetterCandidates.Count > champLettersBefore) champP.LetterCandidates.RemoveAt(champP.LetterCandidates.Count - 1);
            behavior.Store.Set(beatenP);
            behavior.Store.Set(champP);
            WorldEvents.WorldEventStore.Instance.Remove(gossipId);
         }

         return t.Line();
      }

      /// <summary>
      ///   A grudge-free lord whose OWN character actually lets a grievance of this weight take hold. The grudge
      ///   system's formation floor is trait-modulated (MagnitudeFloor + Mercy*5 - Calculating*5), so a merciful
      ///   lord silently refuses a light grievance, exactly as designed. Picking "the first grudge-free lord" made
      ///   these tests a coin flip on who happened to come first in the campaign's list: they passed on one save and
      ///   failed on the next without a line of code changing (found 2026-09-06, two tests failing at once on the
      ///   same merciful lord). Asks the real policy, through the very facts TryPlant will build.
      /// </summary>
      private static Hero GrudgeCapableLord(GrudgeSource source, int magnitude, int today, Func<Hero, bool> also = null)
         => Hero.AllAliveHeroes?.FirstOrDefault(h =>
            h != null && h != Hero.MainHero && h.IsAlive && h.IsLord && !h.IsPrisoner
            && (GrudgeBehavior.Instance?.LiveGrudgesFor(h, today)?.Count ?? 0) == 0
            && GrudgePolicy.ShouldForm(GrudgeBridge.BuildCandidateFacts(h, source, magnitude, false))
            && (also == null || also(h)));

      private static string TestTournamentRivalry(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tournament_rivalry");

         CalradiaRemembers.Tournaments.TournamentRivalryBehavior rb = CalradiaRemembers.Tournaments.TournamentRivalryBehavior.Instance;
         CalradiaRemembers.Grudges.GrudgeBehavior grudges = CalradiaRemembers.Grudges.GrudgeBehavior.Instance;
         if (t.Abort(rb == null || grudges == null || Hero.MainHero == null, "rivalry / grudge behavior not initialized")) return t.Line();

         // No existing grudge and no tally, so the cleanup removes exactly what we plant, AND a character that lets
         // a grudge this light form at all: BitterMagnitude (18) sits just above the base floor (15), so a merciful
         // lord legitimately shrugs off a sporting sourness and no grudge is planted.
         var today0 = (int) CampaignTime.Now.ToDays;
         Hero rival = GrudgeCapableLord(GrudgeSource.External, Logic.Tournaments.TournamentRivalryPolicy.BitterMagnitude,
            today0, h => rb.Tally(h.StringId) == null);
         if (t.Abort(rival == null, "no grudge-free, unforgiving lord to stand in as a bitter arena rival")) return t.Line();

         int honor0 = rival.GetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor);

         try
         {
            rival.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, -2); // force a BITTER rivalry (a grudge we can cleanly clear)

            rb.RecordEncounter(rival, playerWon: true);
            rb.RecordEncounter(rival, playerWon: true);
            bool formedEarly = rb.Tally(rival.StringId)?.Formed ?? false;

            rb.RecordEncounter(rival, playerWon: false); // crosses the threshold (3 total head-to-heads)
            CalradiaRemembers.Tournaments.RivalryTally tally = rb.Tally(rival.StringId);
            bool grudgePlanted = (grudges.GrudgesFor(rival.StringId)?.Count ?? 0) > 0;

            t.Note($"rival={rival.Name} pw={tally?.PlayerWins} hw={tally?.HeroWins}");
            t.Expect("no rivalry before the threshold", formedEarly, false);
            t.Expect("the rivalry forms at the threshold", tally?.Formed, true);
            t.Expect("three head-to-heads tallied", (tally?.PlayerWins ?? 0) + (tally?.HeroWins ?? 0), 3);
            t.Expect("a bitter rivalry plants a grudge", grudgePlanted, true);
         }
         finally
         {
            grudges.ClearGrudgesFor(rival.StringId);
            rb.ForgetTally(rival.StringId);
            rival.SetTraitLevel(TaleWorlds.CampaignSystem.CharacterDevelopment.DefaultTraits.Honor, honor0);
         }

         return t.Line();
      }

