      private static string TestAuthoredQuestBranches(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("authored_quest_branches");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, "a real tale is under way; not disturbing it")) return t.Line();

         const string id = "cr_selftest_crossroads";
         IReadOnlyList<string> problems = b.DebugLoadTale(BranchingSelfTestTale, "selftest.json");
         t.Expect("theTaleLoadsClean", string.Join(" | ", problems), "");
         Logic.AuthoredQuests.AuthoredQuest tale = b.Quests.FirstOrDefault(q => q.Id == id);
         if (t.Abort(tale == null, "the tale did not load")) return t.Line();

         try
         {
            var today = (int) CampaignTime.Now.ToDays;
            Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && b.TryOffer(h, today, 0, id));
            if (t.Skip(giver == null, "no lord at peace with the player could give it")) return t.Line();

            b.Accept(tale, b.Offer);
            t.Expect("acceptingLeadsToTheCrossroads", b.ActiveRun.StageId, "crossroads");
            List<string> journal = Campaign.Current.QuestManager.Quests.OfType<Quests.AuthoredStoryQuest>().FirstOrDefault(q => q.IsOngoing && q.StoryId == id)
                                           ?.JournalEntries.Select(j => j.LogText.ToString()).ToList() ?? new List<string>();
            t.Expect("theJournalShowsTheOpenWay", journal.Any(l => l.Contains("open way")), true);
            t.Expect("andNotTheClosedOne", journal.Any(l => l.Contains("closed way")), false);

            b.DebugConversationOpened(giver);
            t.Expect("meetingTheLordTakesTheFirstOpenWay", string.Join(",", b.ActiveRun.ChoicesTaken), "crossroads/go_on");
            t.Expect("intoTheScene", b.ActiveRun.StageId, "the_scene");

            t.Expect("theChatListsOnlyTheOpenWays", string.Join("|", b.DebugSceneWays()), "Go left|Walk away");
            b.DebugSceneMarkers("You look right. [[choice:right]]");
            t.Expect("aClosedWaysMarkerChangesNothing", b.ActiveRun.SceneChoiceId ?? "none", "none");

            b.DebugSceneMarkers("A token in the dust. [[found:token]]");
            t.Expect("theFindingSetsItsFlag", b.ActiveRun.Flags.Contains("knows_secret"), true);
            t.Expect("theWayItOpenedIsListed", string.Join("|", b.DebugSceneWays()), "Go left|Go right|Walk away");
            b.DebugSceneMarkers("You take the right path. [[choice:right]]");
            t.Expect("itsMarkerIsTaken", b.ActiveRun.SceneChoiceId, "right");

            b.DebugCloseScene();
            t.Expect("closingFollowsItToItsEnding", $"{b.ActiveRun.Status}/{b.ActiveRun.EndingId}", "Completed/secret");
         }
         finally
         {
            b.Abandon("Self-test.");
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
         }

         return t.Line();
      }

      private static string TestTaleCompanionGiver(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_companion_giver");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();

         const string id = "cr_selftest_companion_giver";
         t.Expect("theTaleLoadsClean", string.Join(" | ", b.DebugLoadTale(@"{ ""id"": """ + id + @""", ""title"": ""[SELFTEST] The Road Home"",
            ""requires"": { ""giver"": { ""role"": ""companion"", ""with_player"": true, ""min_regard"": -100, ""not_at_war_with_player"": false } },
            ""binds"": { ""giver"": ""a companion"" },
            ""stages"": [ { ""id"": ""ask"", ""journal"": ""[SELFTEST]"", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" }, ""on_complete"": { ""next"": ""reward"" } } ],
            ""reward"": { } }", "selftest.json")), "");
         try
         {
            using var arranged = ArrangedCompanion.Get(behavior, mustBeInMainParty: true);
            if (t.Skip(arranged?.Companion == null, "no companion could be arranged")) return t.Line();

            string companion = b.DebugEligibility(arranged.Companion, id) ?? "";
            t.Expect("aCompanionAlongBinds", companion.StartsWith("no:") ? companion : "binds", "binds");

            // Only someone free to take part, so the refusal is the role's and not "cannot take part right now".
            bool Free(Hero h) => h != null && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness);
            Hero notCompanion = Free(Hero.MainHero.Spouse)
               ? Hero.MainHero.Spouse
               : Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && !h.IsPlayerCompanion && Free(h));
            if (t.Skip(notCompanion == null, "no spouse nor lord to refuse")) return t.Line();
            string other = b.DebugEligibility(notCompanion, id) ?? "";
            t.Note($"refused: {notCompanion.Name}");
            t.Expect("theSpouseOrALordIsRefused", other.StartsWith("no:") && other.Contains("companions"), true);
         }
         finally
         {
            b.DebugForgetTale(id);
         }

         return t.Line();
      }

      private static string TestTaleRealm(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_realm");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();

         // A twin with no realm named: a lord it accepts was refused by nothing else, so a refusal of the realm tale is the
         // realm's alone (a lord refused for his regard or his role would make this test red for the wrong reason).
         const string id = "cr_selftest_realm", twinId = "cr_selftest_realm_twin";
         string Tale(string taleId, string realmLine) => @"{ ""id"": """ + taleId + @""", ""title"": ""[SELFTEST] One Realm"",
            ""requires"": { ""giver"": { ""role"": ""lord"", ""min_regard"": -100, ""not_at_war_with_player"": false" + realmLine + @" } },
            ""binds"": { ""giver"": ""a lord"" },
            ""stages"": [ { ""id"": ""ask"", ""journal"": ""[SELFTEST]"", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" }, ""on_complete"": { ""next"": ""reward"" } } ],
            ""reward"": { } }";
         t.Expect("theTwinLoadsClean", string.Join(" | ", b.DebugLoadTale(Tale(twinId, ""), "selftest.json")), "");
         try
         {
            bool Binds(Hero h, string taleId) => !(b.DebugEligibility(h, taleId) ?? "no").StartsWith("no:");
            List<Hero> bindable = Hero.AllAliveHeroes.Where(h => h.IsLord && h != Hero.MainHero && h.Clan?.Kingdom != null && Binds(h, twinId)).ToList();
            Hero inRealm = bindable.FirstOrDefault();
            if (t.Skip(inRealm == null, "no lord of a realm could give a tale at all")) return t.Line();
            Kingdom realm = inRealm.Clan.Kingdom;
            Hero elsewhere = bindable.FirstOrDefault(h => h.Clan.Kingdom != realm);
            if (t.Skip(elsewhere == null, "no lord of another realm could give a tale at all")) return t.Line();

            t.Expect("theTaleLoadsClean", string.Join(" | ", b.DebugLoadTale(Tale(id, @", ""realm"": """ + realm.StringId + @""""), "selftest.json")), "");
            t.Expect("aLordOfThatRealmStillBinds", Binds(inRealm, id), true);
            string other = b.DebugEligibility(elsewhere, id) ?? "";
            t.Expect("aLordOfAnotherRealmIsRefusedForItAlone", other.StartsWith("no:") && other.Contains("of the realm " + realm.StringId) && other.Contains(elsewhere.Clan.Kingdom.StringId), true);
         }
         finally
         {
            b.DebugForgetTale(id);
            b.DebugForgetTale(twinId);
         }

         return t.Line();
      }

