      private static string TestEdictEffects(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("edict_effects");

         Edicts.EdictBehavior b = Edicts.EdictBehavior.Instance;
         if (t.Abort(b == null || Campaign.Current?.Models == null, "edicts are not running")) return t.Line();
         Edicts.EdictModelPatches.EnsureOnActiveModels();
         t.Note($"attached: {string.Join(", ", Edicts.EdictModelPatches.Attached)}");
         // tashmetu (25/10/2026): under Harvest and Production the tax channel never attached and nothing said so.
         t.Expect("everyChannelIsAttached", Edicts.EdictModelPatches.Attached.Count, 6);

         Settlement place = Settlement.All.FirstOrDefault(s => s.IsTown && s.OwnerClan?.Leader is Hero h && h != Hero.MainHero && Mapping.HeroPresence.IsInTheWorld(h)
                                                              && b.Ledger.HoldingOn(s.StringId, s.OwnerClan.Kingdom?.StringId) == null && b.Ledger.LastEndedOn(s.StringId) == null);
         if (t.Skip(place == null, "no town held by a lord, free of any edict")) return t.Line();
         Town town = place.Town;
         Hero holder = place.OwnerClan.Leader;
         Hero stranger = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.Clan != null && h.Clan != place.OwnerClan && h != Hero.MainHero);
         var models = Campaign.Current.Models;

         float influenceBefore = holder.Clan.Influence, loyaltyBefore = town.Loyalty;
         int newsBefore = WorldEvents.WorldEventStore.Instance?.All().Count ?? 0;
         Logic.Edicts.Edict e = null;
         try
         {
            if (holder.Clan.Influence < Logic.Edicts.EdictCatalog.TownInfluenceCost) ChangeClanInfluenceAction.Apply(holder.Clan, Logic.Edicts.EdictCatalog.TownInfluenceCost);
            float influenceReady = holder.Clan.Influence;
            float loyaltyChange = models.SettlementLoyaltyModel.CalculateLoyaltyChange(town).ResultNumber;
            float tax = models.SettlementTaxModel.CalculateTownTax(town).ResultNumber;

            e = b.Decree(holder, Logic.Edicts.EdictScope.Town, place, Logic.Edicts.EdictKind.HeavyLevy, 40, "the Test Levy", out string refusal);
            t.Expect("theHolderDecreesIt", refusal, null);
            if (t.Abort(e == null, "the decree was refused")) return t.Line();
            t.Expect("theInfluenceIsSpent", (int) Math.Round(influenceReady - holder.Clan.Influence), Logic.Edicts.EdictCatalog.TownInfluenceCost);

            ExplainedNumber loyalty = models.SettlementLoyaltyModel.CalculateLoyaltyChange(town, true);
            t.Expect("theGamesOwnLoyaltyNamesTheEdict", loyalty.GetLines().Any(l => l.name.Contains("the Test Levy") && Math.Abs(l.number + 1f) < 0.01f), true);
            t.Note($"loyalty a day {loyaltyChange:0.00} -> {loyalty.ResultNumber:0.00}; tax {tax:0} -> {models.SettlementTaxModel.CalculateTownTax(town).ResultNumber:0}");
            t.Expect("theTaxRises", models.SettlementTaxModel.CalculateTownTax(town).ResultNumber > tax || tax <= 0f, true);
            Hero local = place.Notables.FirstOrDefault(n => Mapping.HeroPresence.IsInTheWorld(n));
            if (local != null)
               t.Expect("aNotableOfTheTownKnowsIt", Mapping.EdictNoteResolver.Resolve(local)?.Contains("the Test Levy") == true, true);
            else
               t.Note("the town has no notable to ask");

            b.Decree(holder, Logic.Edicts.EdictScope.Town, place, Logic.Edicts.EdictKind.TaxRelief, 40, null, out string second);
            t.Expect("aSecondEdictWaits", second?.Contains("already") == true, true);
            if (stranger != null)
            {
               b.Decree(stranger, Logic.Edicts.EdictScope.Town, place, Logic.Edicts.EdictKind.TaxRelief, 40, null, out string notHis);
               t.Expect("aStrangerCannotDecreeForIt", notHis?.Contains("head of the house") == true, true);
            }

            town.Loyalty = 10f;
            e.Grievance[place.StringId] = Logic.Edicts.EdictPolicy.RepealedAfterDays - 1;
            e.ContestedIn.Add(place.StringId);
            b.Daily(Edicts.EdictBehavior.Today);
            t.Expect("thePeopleForceItOff", e.Status, Logic.Edicts.EdictStatus.Repealed);
            t.Expect("andTheLineIsGone", models.SettlementLoyaltyModel.CalculateLoyaltyChange(town, true).GetLines().Any(l => l.name.Contains("the Test Levy")), false);
         }
         finally
         {
            town.Loyalty = loyaltyBefore;
            ChangeClanInfluenceAction.Apply(holder.Clan, influenceBefore - holder.Clan.Influence);
            if (e != null) b.Ledger.Edicts.Remove(e);
            WorldEvents.WorldEventStore store = WorldEvents.WorldEventStore.Instance;
            if (store != null)
               foreach (WorldEvents.WorldEvent news in store.All().Skip(newsBefore).Where(n => n.Summary?.Contains("the Test Levy") == true).ToList())
                  store.Remove(news.Id);
         }

         return t.Line();
      }

      private static string TestLordStrategy(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("lord_strategy");

         if (t.Abort(Strategy.LordStrategyBehavior.Instance == null || Campaign.Current?.Models == null, "the strategists are not running")) return t.Line();
         List<Kingdom> standing = Strategy.LordStrategyBehavior.Standing();
         if (t.Skip(standing.Count < 3, "fewer than three realms stand")) return t.Line();

         Kingdom dominant = Strategy.LordStrategyBehavior.DominantRealm();
         t.Note(dominant != null ? $"{dominant.Name} dominates" : "the balance holds; the strongest realm stands in");
         dominant ??= standing.OrderByDescending(k => k.CurrentTotalStrength).First();

         Kingdom players = Clan.PlayerClan?.Kingdom;
         if (players != null && players != dominant)
         {
            Strategy.LordStrategyBehavior.Prepare(players, dominant, out string why);
            t.Expect("thePlayersRealmIsLeftToThePlayer", why?.Contains("player") == true, true);
         }

         Strategy.LordStrategyBehavior.Proposal p = null;
         foreach (Kingdom realm in standing.Where(k => k != dominant && k != players))
         {
            p = Strategy.LordStrategyBehavior.Prepare(realm, dominant, out string why);
            if (p != null) break;
            t.Note($"{realm.Name}: {why}");
         }

         if (p != null)
         {
            t.Note($"{p.Realm.Name}: {p.Move} by {p.House.Name}, support {p.Support:0}");
            t.Expect("neverFiledByThePlayersHouse", p.House != Clan.PlayerClan, true);
            t.Expect("theHouseCanPayForIt", p.House.Influence >= p.Decision.GetProposalInfluenceCost(), true);
            t.Expect("theNewsNamesTheRealm", Strategy.LordStrategyBehavior.News(p)?.Contains(p.Realm.Name.ToString()) == true, true);
            // The road filing takes: the realm's vote is weighed on this very decision (as the game's own ConsiderWar
            // does), without starting it, so nothing is decided and the engine is exercised where a filing would throw.
            var election = new TaleWorlds.CampaignSystem.Election.KingdomElection(p.Decision);
            float likelihood = election.PossibleOutcomes.Sum(o => o.Likelihood);
            t.Note($"the realm's vote weighed: {election.PossibleOutcomes.Count} outcomes, {string.Join(" / ", election.PossibleOutcomes.Select(o => o.Likelihood.ToString("0.00")))}");
            t.Expect("theRealmCanVoteOnIt", election.PossibleOutcomes.Count >= 2 && Math.Abs(likelihood - 1f) < 0.05f, true);
         }
         else
            t.Note("no realm could take a step in this world now");

         int looked = 0;
         foreach (Clan own in Clan.All.Where(c => c != null && !c.IsEliminated && c.Kingdom != null && c != Clan.PlayerClan && c.Leader != null && Mapping.HeroPresence.IsInTheWorld(c.Leader)))
         {
            if (++looked > 80) break;
            string id = WorldEvents.SchemeStore.SelectOvershadowingTargetFor(own.Leader);
            if (id == null) continue;

            Hero target = Hero.FindFirst(h => h.StringId == id);
            t.Note($"{own.Leader.Name} would plot against {target?.Name} of {target?.Clan?.Name}");
            t.Expect("theTargetsHouseIsTwiceAsStrong", target?.Clan != null && target.Clan.CurrentTotalStrength >= 2f * Math.Max(own.CurrentTotalStrength, 1f), true);
            t.Expect("neverARuler", target?.MapFaction?.Leader == target, false);
            t.Expect("neverKin", target != null && GameState.CourtActionResolver.IsCloseKin(own.Leader, target), false);
            t.Expect("aRivalOfHisRealmOrAnEnemy", target != null && (target.MapFaction == own.Leader.MapFaction || FactionManager.IsAtWarAgainstFaction(own.Leader.MapFaction, target.MapFaction)), true);

            return t.Line();
         }

         t.Note("no house head is overshadowed in this world now");

         return t.Line();
      }

      private static string TestStrategistAim(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("strategist_aim");

         Aims.AimsBehavior aims = Aims.AimsBehavior.Instance;
         if (t.Abort(aims == null || Campaign.Current == null, "aims are not running")) return t.Line();

         Kingdom players = Hero.MainHero?.MapFaction as Kingdom;
         Hero giver = null;
         Kingdom enemy = null;
         foreach (Clan house in Clan.All.Where(c => c != null && !c.IsEliminated && c.Kingdom != null && c != Clan.PlayerClan))
         {
            Hero head = house.Leader;
            if (head == null || head.IsPrisoner || !Mapping.HeroPresence.IsInTheWorld(head) || aims.Book.ForNpc(head.StringId) != null) continue;
            enemy = Kingdom.All.FirstOrDefault(k => !k.IsEliminated && k != house.Kingdom && k != players && FactionManager.IsAtWarAgainstFaction(house.Kingdom, k));
            if (enemy == null) continue;
            giver = head;
            break;
         }

         if (t.Skip(giver == null, "no free house head whose realm is at war with a realm other than the player's")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         Logic.Aims.StandingAim aim = Aims.StrategistAims.Compose(giver, new Aims.StrategistAims.Deed {
            Whom = Logic.Strategy.StrategistDeed.BreakTheDominant, Act = Logic.Strategy.StrategistAct.Battle, Realm = enemy
         }, today);
         try
         {
            t.Expect("theAimIsAdmitted", aims.Register(aim), Logic.Aims.AimAdmission.Accepted);

            Aims.AimForContext voiced = aims.ForContext(giver, "cr-test-strategist-aim");
            t.Expect("itIsVoicedInHisConversation", voiced?.Want?.Contains(enemy.Name.ToString()) == true, true);
            t.Expect("heMayAskOutright", voiced?.Approach?.Contains("ask them outright") == true, true);

            Logic.Quests.QuestMenuEntry first = Aims.StrategistAims.MenuEntriesFor(giver).FirstOrDefault();
            t.Expect("itsDeedHeadsHisMenu", first?.TypeToken, "attack_faction");
            t.Expect("namedAsTheFactoryBindsIt", first?.TargetName, enemy.Name.ToString());

            Aims.StrategistAims.Prune(aims);
            t.Expect("itStandsWhileTheWarHolds", aims.Book.Find(Aims.StrategistAims.Source, aim.Id) != null, true);

            // Gabriel (30/10/2026), "go pour le pillage et le siège": the same lord asking a raid on one of that realm's villages.
            Settlement village = Settlement.All.FirstOrDefault(s => s.IsVillage && s.MapFaction == enemy && s.Village?.VillageState != Village.VillageStates.Looted);
            if (village != null)
            {
               Logic.Aims.StandingAim raid = Aims.StrategistAims.Compose(giver, new Aims.StrategistAims.Deed {
                  Whom = Logic.Strategy.StrategistDeed.BreakTheDominant, Act = Logic.Strategy.StrategistAct.Raid, Realm = enemy, Place = village
               }, today);
               t.Expect("theRaidReplacesTheAim", aims.Register(raid), Logic.Aims.AimAdmission.Updated);
               Logic.Quests.QuestMenuEntry raidEntry = Aims.StrategistAims.MenuEntriesFor(giver).FirstOrDefault();
               t.Expect("theRaidHeadsHisMenu", raidEntry?.TypeToken, "raid_village");
               t.Expect("onThatVillage", raidEntry?.TargetName, village.Name.ToString());
               t.Expect("hisWantNamesIt", aims.ForContext(giver, "cr-test-strategist-aim")?.Want?.Contains(village.Name.ToString()) == true, true);
            }
            else
               t.Note("the enemy realm holds no village standing to raid");
         }
         finally
         {
            aims.Retract(Aims.StrategistAims.Source, aim.Id);
         }

         return t.Line();
      }

      private static string TestEnactEdict(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("enact_edict");

         Edicts.EdictBehavior b = Edicts.EdictBehavior.Instance;
         if (t.Abort(b == null || Clan.PlayerClan == null, "edicts are not running")) return t.Line();
         Settlement place = Verbs.EnactEdictVerb.PlayerTowns().FirstOrDefault(s => b.Ledger.OwnOf(s.StringId) == null && b.Ledger.LastEndedOn(s.StringId) == null);
         if (t.Skip(place == null, "the player holds no town free of an edict, and arranging one would require a real, hard-to-cleanly-reverse settlement-ownership transfer")) return t.Line();
         using var arranged = ArrangedCompanion.Get(behavior);
         Hero steward = arranged?.Companion;
         if (t.Skip(steward == null, "no member of the player's house to carry a decree")) return t.Line();
         Edicts.EdictModelPatches.EnsureOnActiveModels();

         NpcProfile profile = GetOrCreate(behavior, steward);
         var ctx = new ActionContext(profile, null);
         string taught = Verbs.VerbRegistry.Instance.ComposeTeachings(new Verbs.VerbContext(steward, profile, behavior.GameStateBridge, null, null), new[] {"enact_edict"});
         t.Expect("theStewardIsTaughtTheCatalogue", taught.Contains("type: enact_edict") && taught.Contains("grain_requisition") && taught.Contains(place.Name.ToString()), true);

         float influenceBefore = Clan.PlayerClan.Influence;
         int newsBefore = WorldEvents.WorldEventStore.Instance?.All().Count ?? 0;
         try
         {
            if (Clan.PlayerClan.Influence < Logic.Edicts.EdictCatalog.TownInfluenceCost) ChangeClanInfluenceAction.Apply(Clan.PlayerClan, Logic.Edicts.EdictCatalog.TownInfluenceCost);

            var made = new GameAction {Type = "enact_edict", Parameters = new Dictionary<string, string> {["kind"] = "free gold", ["town"] = place.Name.ToString()}};
            t.Expect("anEdictOutsideTheCatalogueIsRefused", behavior.GameStateBridge.ExecuteAction(made, steward, ctx)?.Message?.Contains("No edict by that name") == true, true);

            var decree = new GameAction {Type = "enact_edict", Parameters = new Dictionary<string, string> {["kind"] = "feast_days", ["town"] = place.Name.ToString(), ["days"] = "30", ["name"] = "the Test Feast"}};
            var confirmation = new ActionConfirmationController();
            t.Expect("theDecreeIsAskedFirst", confirmation.Preprocess(decree, steward, profile, ctx), ActionDisposition.Queued);
            string question = confirmation.DebugNextQuestion;
            t.Note(question);
            t.Expect("theQuestionNamesWhatItDoesAndCosts", question?.Contains("the Test Feast") == true && question.Contains("loyalty +1.5 a day") && question.Contains("30 days") && question.Contains($"{Logic.Edicts.EdictCatalog.TownInfluenceCost} influence"), true);

            ActionOutcome done = behavior.GameStateBridge.ExecuteAction(decree, steward, ctx);
            t.Note(done?.Message);
            Logic.Edicts.Edict e = b.HoldingOn(place.Town);
            t.Expect("theTownHoldsThePlayersEdict", e != null && e.ByPlayer && e.Name == "the Test Feast", true);
            t.Expect("theGamesOwnLoyaltyNamesIt", Campaign.Current.Models.SettlementLoyaltyModel.CalculateLoyaltyChange(place.Town, true).GetLines().Any(l => l.name.Contains("the Test Feast")), true);
         }
         finally
         {
            b.Ledger.Edicts.RemoveAll(x => x.Name == "the Test Feast");
            ChangeClanInfluenceAction.Apply(Clan.PlayerClan, influenceBefore - Clan.PlayerClan.Influence);
            WorldEvents.WorldEventStore store = WorldEvents.WorldEventStore.Instance;
            if (store != null)
               foreach (WorldEvents.WorldEvent news in store.All().Skip(newsBefore).Where(n => n.Summary?.Contains("the Test Feast") == true).ToList())
                  store.Remove(news.Id);
            profile.Events.RemoveAll(ev => ev.summary?.Contains("the Test Feast") == true);
         }

         return t.Line();
      }

      private static string TestPlayerFame(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("player_fame");

         Clan clan = Clan.PlayerClan;
         if (t.Abort(clan == null || Hero.MainHero == null, "no player clan")) return t.Line();
         Hero stranger = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.Clan != null && h.Clan != clan && h.Culture != Hero.MainHero.Culture
                                                                 && h.MapFaction != Hero.MainHero.MapFaction && h.Age >= 18
                                                                 && behavior.Store.Get(h.StringId)?.Events?.Count is null or 0
                                                                 && !Mapping.FirstImpressionResolver.IsAlreadyKnown(h, behavior.Store.Get(h.StringId), behavior.GameStateBridge));
         if (t.Skip(stranger == null, "no foreign lord who never met the player")) return t.Line();
         NpcProfile profile = behavior.Store.Get(stranger.StringId);
         string player = Hero.MainHero.Name.ToString();

         float renownBefore = clan.Renown;
         int tierBefore = clan.Tier;
         try
         {
            clan.ResetClanRenown();
            string modest = EncounterContextBuilder.Build(stranger, profile, behavior.GameStateBridge, "Well met.").PlayerFameLine;
            t.Note($"{stranger.Name} at renown 0: {modest}");
            t.Expect("aStrangerIsToldOfTheName", modest?.Contains(player) == true, true);
            t.Expect("anUnknownHouseIsNoBannerHeKnows", modest?.Contains("know the banner") == true, false);

            clan.AddRenown(1000f, false);
            string famous = EncounterContextBuilder.Build(stranger, profile, behavior.GameStateBridge, "Well met.").PlayerFameLine;
            t.Note($"{stranger.Name} at renown 1000: {famous}");
            t.Expect("aGreatNameIsKnownAbroad", famous?.Contains("know the banner") == true, true);

            Hero own = clan.Heroes.FirstOrDefault(h => h != Hero.MainHero && Mapping.HeroPresence.IsInTheWorld(h));
            if (own != null)
               t.Expect("hisOwnClanNeedsNoWordOfHisName", Mapping.PlayerFameResolver.Resolve(own, behavior.Store.Get(own.StringId), behavior.GameStateBridge), null);
            else
               t.Note("no other member of the player's clan to ask");
         }
         finally
         {
            RestoreClanTier(clan, renownBefore, tierBefore);
         }

         return t.Line();
      }

      private static string TestTaleItems(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_items");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, "a real tale is under way; not disturbing it")) return t.Line();
         ItemRoster roster = MobileParty.MainParty?.ItemRoster;
         ItemObject grain = MBObjectManager.Instance.GetObject<ItemObject>("grain"), wine = MBObjectManager.Instance.GetObject<ItemObject>("wine");
         if (t.Abort(roster == null || grain == null || wine == null, "no party, or no grain or wine in this game")) return t.Line();

         const string id = "cr_selftest_items";
         t.Expect("theTaleLoadsClean", string.Join(" | ", b.DebugLoadTale(ItemsSelfTestTale, "selftest.json")), "");
         Logic.AuthoredQuests.AuthoredQuest tale = b.Quests.FirstOrDefault(q => q.Id == id);
         if (t.Abort(tale == null, "the tale did not load")) return t.Line();

         int grainBefore = roster.GetItemNumber(grain), wineBefore = roster.GetItemNumber(wine);
         try
         {
            var today = (int) CampaignTime.Now.ToDays;
            Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h.Spouse != Hero.MainHero && b.TryOffer(h, today, 0, id));
            if (t.Skip(giver == null, "no lord could give it")) return t.Line();
            b.Accept(tale, b.Offer);
            t.Expect("acceptingLeadsToTheGrain", b.ActiveRun.StageId, "bring_it");

            roster.AddToCounts(grain, 8);
            t.Expect("theBagSeesTheGrainAskedOfHim", b.TryDeliveryFor(giver, out string key, out int count) ? $"{key}/{count}" : "nothing", $"{Logic.ProvideGoodsPolicy.Grain}/3");
            Hero someoneElse = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != giver && h != Hero.MainHero);
            t.Expect("andOfNobodyElse", someoneElse != null && b.TryDeliveryFor(someoneElse, out _, out _), false);

            t.Expect("twoOfThreeTakeNothing", b.HandOver(giver, new List<GameState.ItemOffer> {new("grain", 2)}, out string shortLine), false);
            t.Note(shortLine);
            t.Expect("theGrainStays", roster.GetItemNumber(grain), grainBefore + 8);
            t.Expect("theStageWaits", b.ActiveRun.StageId, "bring_it");

            // A hand-over worded in the chat (Gabriel, 21/10/2026): the real bridge, as an LLM emission runs it.
            var ctx = new ActionContext(GetOrCreate(behavior, giver), null);
            var typed = new GameAction {Type = "give_item", Parameters = new Dictionary<string, string> {["item"] = grain.Name.ToString(), ["count"] = "1"}};
            int held = roster.GetItemNumber(grain);
            roster.AddToCounts(grain, 2 - held);
            ActionOutcome shortTyped = behavior.GameStateBridge.ExecuteAction(typed, giver, ctx);
            t.Note(shortTyped?.Message);
            t.Expect("aWordedHandOverShortKeepsTheGrain", roster.GetItemNumber(grain), 2);
            t.Expect("andTheStageStillWaits", b.ActiveRun.StageId, "bring_it");
            roster.AddToCounts(grain, held - 2);

            var confirmation = new ActionConfirmationController();
            t.Expect("aWordedHandOverIsAskedFirst", confirmation.Preprocess(typed, giver, GetOrCreate(behavior, giver), ctx), ActionDisposition.Queued);
            t.Expect("theQuestionNamesTheCountAsked", confirmation.DebugNextQuestion?.Contains("Hand 3 ") == true, true);
            t.Note(confirmation.DebugNextQuestion);

            ActionOutcome handed = behavior.GameStateBridge.ExecuteAction(typed, giver, ctx);
            t.Note(handed?.Message);
            t.Expect("exactlyThreeLeft", roster.GetItemNumber(grain), grainBefore + 5);
            t.Expect("theTaleEndsAsTheStageLeads", $"{b.ActiveRun.Status}/{b.ActiveRun.EndingId}", "Completed/fed");
            t.Expect("theEndingGivesTwoWine", roster.GetItemNumber(wine), wineBefore + 2);
         }
         finally
         {
            roster.AddToCounts(grain, grainBefore - roster.GetItemNumber(grain));
            roster.AddToCounts(wine, wineBefore - roster.GetItemNumber(wine));
            if (b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}) b.Abandon("Self-test.");
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
         }

         return t.Line();
      }

      private static string TestTaleWorldExits(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_world_exits");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, "a real tale is under way; not disturbing it")) return t.Line();

         const string id = "cr_selftest_world_exits";
         IReadOnlyList<string> problems = b.DebugLoadTale(WorldExitsSelfTestTale, "selftest.json");
         t.Expect("theTaleLoadsClean", string.Join(" | ", problems), "");
         Logic.AuthoredQuests.AuthoredQuest tale = b.Quests.FirstOrDefault(q => q.Id == id);
         if (t.Abort(tale == null, "the tale did not load")) return t.Line();

         try
         {
            var today = (int) CampaignTime.Now.ToDays;
            Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h.Spouse != Hero.MainHero && b.TryOffer(h, today, 0, id));
            if (t.Skip(giver == null, "no lord at peace with the player could give it")) return t.Line();

            b.Accept(tale, b.Offer);
            t.Expect("acceptingLeadsToTheWatch", b.ActiveRun.StageId, "watch");
            b.DebugDailyTick();
            t.Expect("aLivingUnwedLordAtPeaceMovesNothing", $"{b.ActiveRun.Status}/{b.ActiveRun.StageId}", "Active/watch");

            IFaction mine = Hero.MainHero.MapFaction;
            Hero enemy = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.MapFaction != null && h.MapFaction != mine && FactionManager.IsAtWarAgainstFaction(h.MapFaction, mine));
            if (enemy != null)
            {
               b.ActiveRun.BoundIds["giver"] = enemy.StringId;
               b.DebugDailyTick();
               t.Expect("aLordAtWarIsSeenAtWar", $"{b.ActiveRun.StageId}/{string.Join(",", b.ActiveRun.WarsSeen)}", "watch/{giver}");
               b.ActiveRun.BoundIds["giver"] = giver.StringId;
               b.DebugDailyTick();
               t.Expect("thatWarOverTheTaleEndsOnPeace", $"{b.ActiveRun.Status}/{b.ActiveRun.EndingId}", "Completed/peace");
               b.ForgetPlayed(id);
               if (t.Abort(!b.TryOffer(giver, today, 0, id), "the tale could not be taken on a second time")) return t.Line();
               b.Accept(tale, b.Offer);
            }
            else t.Note("no realm is at war with the player; the war's end was not walked (the unit tests pin it).");

            Hero dead = Hero.DeadOrDisabledHeroes.FirstOrDefault(h => h.IsDead);
            if (dead != null)
            {
               t.Expect("theDeadAreGone", Quests.AuthoredQuestBehavior.DebugRoleState(dead).Gone, true);
               b.ActiveRun.BoundIds["giver"] = dead.StringId;
               b.DebugDailyTick();
               t.Expect("theGiverDeadTheTaleEndsOnMourning", $"{b.ActiveRun.Status}/{b.ActiveRun.EndingId}", "Completed/mourned");
            }
            else t.Note("nobody has died yet in this campaign; the death was not walked (the unit tests pin it).");

            Hero spouse = Hero.MainHero.Spouse;
            if (spouse != null) t.Expect("thePlayersSpouseReadsWedToThePlayer", Quests.AuthoredQuestBehavior.DebugRoleState(spouse).WedToPlayer, true);
            t.Expect("aLordWhoIsNotTheSpouseDoesNot", Quests.AuthoredQuestBehavior.DebugRoleState(giver).WedToPlayer, false);
         }
         finally
         {
            b.Abandon("Self-test.");
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
         }

         return t.Line();
      }

