         return t.Line();
      }

      private static string TestWorldEventDiscretion(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("world_event_discretion");

         var store = WorldEvents.WorldEventStore.Instance;
         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && h.IsLord && h.MapFaction != null && Mapping.HeroPresence.IsInTheWorld(h)).Take(60).ToList();
         Hero bride = lords.FirstOrDefault();
         Hero groom = lords.FirstOrDefault(h => h != bride && h.MapFaction == bride?.MapFaction);
         Hero other = lords.FirstOrDefault(h => h != bride && h != groom && h.MapFaction == bride?.MapFaction);
         if (t.Skip(store == null || other == null, "no three lords of one realm")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         var e = new WorldEvents.WorldEvent {
            Type = WorldEvents.WorldEventType.Marriage, Day = today, Magnitude = 90, Summary = "[SELFTEST] a secret wedding.",
            ActorIds = new List<string> {bride.StringId, groom.StringId}, FactionIds = new List<string> {bride.MapFaction.StringId}
         };
         store.Record(e);
         try
         {
            t.Expect("aPublicEventIsHeardByTheRealm", store.IsAwareOf(other, e, today), true);

            TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.world_event_secret", e.Id, out _);
            t.Expect("aSecretIsNotHeardByAnOutsider", store.IsAwareOf(other, e, today), false);
            t.Expect("aSecretIsKnownToThoseItNames", store.IsAwareOf(bride, e, today), true);

            TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.world_event_secret", e.Id + " off", out _);
            TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.world_event_hide", e.Id + " " + other.StringId, out _);
            t.Note($"hidden from {other.Name}: {string.Join(",", e.HiddenFromIds ?? new List<string>())}");
            t.Expect("theHiddenOneIsKeptUnaware", store.IsAwareOf(other, e, today), false);
            t.Expect("everyoneElseStillHears", store.IsAwareOf(groom, e, today), true);

            TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.world_event_remove", e.Id, out _);
            t.Expect("aRemovedEventIsGone", store.GetById(e.Id) == null, true);
         }
         finally { store.Remove(e.Id); }

         return t.Line();
      }

      private static string TestPortraitChannels(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("portrait_channels");
         byte[] reference = ChannelProbe(System.Drawing.Imaging.PixelFormat.Format32bppArgb, System.Drawing.Imaging.ImageFormat.Png);
         byte[] rgbPng = ChannelProbe(System.Drawing.Imaging.PixelFormat.Format24bppRgb, System.Drawing.Imaging.ImageFormat.Png);
         byte[] jpg = ChannelProbe(System.Drawing.Imaging.PixelFormat.Format24bppRgb, System.Drawing.Imaging.ImageFormat.Jpeg);
         t.Expect("theReferenceIsAnRgbaPng", Logic.Diagnostics.PngHeader.ColorType(reference), Logic.Diagnostics.PngHeader.Rgba);
         t.Expect("theRgbProbeIsAnRgbPng", Logic.Diagnostics.PngHeader.ColorType(rgbPng), Logic.Diagnostics.PngHeader.Rgb);

         // The engine is NOT asked for its pixels: Texture.GetPixelData read protected memory on the first run (24/10/2026,
         // AccessViolationException), which can corrupt the game. What the loader hands the engine is checked instead: the
         // encoding the engine shows true (RGBA PNG, CR's icons and political map), with red still red and blue still blue.
         foreach ((string name, byte[] probe) in new[] {("reference", reference), ("rgbPng", rgbPng), ("jpg", jpg)})
         {
            byte[] normalized = Portraits.RuntimePortraitFactory.NormalizeToRgba(probe);
            t.Expect($"{name}IsHandedOverAsRgba", Logic.Diagnostics.PngHeader.ColorType(normalized), Logic.Diagnostics.PngHeader.Rgba);
            System.Drawing.Color c = FirstPixel(normalized);
            t.Note($"{name}: first pixel R{c.R} G{c.G} B{c.B} (probe R{ProbeColour.R} G{ProbeColour.G} B{ProbeColour.B})");
            t.Expect($"{name}KeepsItsRedAndBlue", Math.Abs(c.R - ProbeColour.R) <= 12 && Math.Abs(c.B - ProbeColour.B) <= 12, true);
         }

         return t.Line();
      }

      // One colour, distinct in every channel so red and blue can never be mistaken for each other or for alpha.
      private static readonly System.Drawing.Color ProbeColour = System.Drawing.Color.FromArgb(255, 220, 128, 30);

      private static byte[] ChannelProbe(System.Drawing.Imaging.PixelFormat format, System.Drawing.Imaging.ImageFormat encoding)
      {
         using var bmp = new System.Drawing.Bitmap(16, 16, format);
         using (System.Drawing.Graphics g = System.Drawing.Graphics.FromImage(bmp)) g.Clear(ProbeColour);
         using var ms = new System.IO.MemoryStream();
         bmp.Save(ms, encoding);

         return ms.ToArray();
      }

      private static System.Drawing.Color FirstPixel(byte[] image)
      {
         using var ms = new System.IO.MemoryStream(image);
         using var bmp = new System.Drawing.Bitmap(ms);

         return bmp.GetPixel(0, 0);
      }

