      private static string TestMercenaryJoinTerm(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("mercenary_join_term");
         Clan clan = Clan.PlayerClan;
         if (t.Abort(clan == null || behavior?.GameStateBridge == null, "no player clan or no bridge")) return t.Line();
         if (t.Skip(clan.Kingdom != null && clan.Kingdom.RulingClan == clan, "the player rules a realm and cannot be hired")) return t.Line();

         Kingdom priorRealm = clan.Kingdom;
         bool priorMercenary = clan.IsUnderMercenaryService;
         CampaignTime priorUntil = clan.ShouldStayInKingdomUntil;
         int priorFactor = clan.MercenaryAwardMultiplier;

         try
         {
            // Arranged: a free clan, the only kind join_as_mercenary hires.
            if (clan.Kingdom != null)
            {
               if (clan.IsUnderMercenaryService) ChangeKingdomAction.ApplyByLeaveKingdomAsMercenary(clan, false);
               else ChangeKingdomAction.ApplyByLeaveKingdom(clan, false);
            }

            Kingdom realm = Kingdom.All.FirstOrDefault(k => k != null && !k.IsEliminated && k.Leader != null && k.Leader != Hero.MainHero
                                                             && Mapping.HeroPresence.IsInTheWorld(k.Leader)
                                                             && !FactionManager.IsAtWarAgainstFaction(clan, k));
            if (t.Skip(realm == null, "every realm is at war with the player")) return t.Line();

            int gameFactor = Campaign.Current.Models.MinorFactionsModel.GetMercenaryAwardFactorToJoinKingdom(clan, realm);
            ActionOutcome hired = behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "join_as_mercenary"}, realm.Leader,
                                                                         new ActionContext(behavior.Store?.Get(realm.Leader.StringId), null));
            t.Note($"{realm.Name}: {hired?.Message}; until {clan.ShouldStayInKingdomUntil}, factor {clan.MercenaryAwardMultiplier} (game {gameFactor})");

            // STAKE: the clan serves the realm as hired swords.
            t.Expect("theClanServesAsAMercenary", clan.Kingdom == realm && clan.IsUnderMercenaryService, true);
            // STAKE: no fixed term, as the game's own hiring, so a contract mod does not end it on its first day.
            t.Expect("theContractHasNoFixedTerm", clan.ShouldStayInKingdomUntil == CampaignTime.Zero, true);
            // STAKE: paid at the game's own rate, not a flat figure.
            t.Expect("thePayRateIsTheGames", clan.MercenaryAwardMultiplier, gameFactor > 0 ? gameFactor : 50);
         }
         finally
         {
            if (clan.Kingdom != priorRealm || clan.IsUnderMercenaryService != priorMercenary)
            {
               if (clan.Kingdom != null)
               {
                  if (clan.IsUnderMercenaryService) ChangeKingdomAction.ApplyByLeaveKingdomAsMercenary(clan, false);
                  else ChangeKingdomAction.ApplyByLeaveKingdom(clan, false);
               }

               if (priorRealm != null && !priorRealm.IsEliminated)
               {
                  if (priorMercenary) ChangeKingdomAction.ApplyByJoinFactionAsMercenary(clan, priorRealm, priorUntil, priorFactor, false);
                  else ChangeKingdomAction.ApplyByJoinToKingdom(clan, priorRealm, priorUntil, false);
               }
            }
         }

         return t.Line();
      }

