      private static string TestSceneOpener(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scene_opener");
         CrSettings settings = CrSettings.Instance;
         if (t.Abort(settings == null, "no MCM settings instance")) return t.Line();

         bool before = settings.CharactersSetTheScene;
         bool model = behavior?.LlmServices?.IsAvailable == true;
         try
         {
            settings.CharactersSetTheScene = true;
            // STAKE: an interception or a tale meeting opens through the same door with its own opening: no second one.
            t.Expect("notByTheGreetingNoScene", Logic.Chat.SceneOpenerPolicy.ShouldOpen(Dialogue.LlmDialogFlow.SceneFacts(null, false, false)), false);
            // STAKE: the game's own dialogue already began the scene (a wanderer's backstory).
            t.Expect("gameDialogueCarriedNoScene", Logic.Chat.SceneOpenerPolicy.ShouldOpen(Dialogue.LlmDialogFlow.SceneFacts(null, true, true)), false);
            // STAKE: Lordfadooboo's cold open, the case the feature is for.
            t.Expect("byTheGreetingASceneWhenAModelAnswers", Logic.Chat.SceneOpenerPolicy.ShouldOpen(Dialogue.LlmDialogFlow.SceneFacts(null, true, false)), model);
            settings.CharactersSetTheScene = false;
            // STAKE: a player who counts the cost turned it off and pays nothing more.
            t.Expect("switchOffNoScene", Logic.Chat.SceneOpenerPolicy.ShouldOpen(Dialogue.LlmDialogFlow.SceneFacts(null, true, false)), false);
         }
         finally { settings.CharactersSetTheScene = before; }

         if (t.Skip(!model, "no model available: the live half (a real conversation) needs one")) return t.Line();
         if (t.Skip(Chat.ChatManager.IsOpen || Chat.ExplorationBackdrop.IsOpen || UI.CrPanelHost.AnyPanelOwnsScreen, "a window or panel already owns the screen")) return t.Line();
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && Mapping.HeroPresence.IsInTheWorld(h) && !h.IsPrisoner);
         if (t.Skip(lord == null, "no lord to speak with")) return t.Line();

         const string greeting = "[SELFTEST] Well met.";
         CampaignTimeControlMode timeBefore = Campaign.Current.TimeControlMode;
         try
         {
            GetOrCreate(behavior, lord);
            // Staged, not ordinary: every open drops a kept sitting, but only an ordinary one puts it back on screen, and
            // only an ordinary close keeps one, which would leave this test's lines waiting for the player's next talk.
            Chat.ChatManager.Open(lord.Name.ToString(), opening: Chat.ChatOpening.Staged);
            Chat.ChatViewModel vm = Chat.ChatManager.ActiveViewModel;
            if (t.Skip(vm == null, "the conversation did not open")) return t.Line();
            vm.SetNpcHero(lord);

            vm.OpenWithScene(greeting);
            t.Expect("theSceneIsBeingWritten", vm.SceneOpenerInFlightForDiagnostics, true);
            // STAKE: nobody waits on the model to be greeted: the greeting is on screen from the first frame.
            t.Expect("theGreetingShowsMeanwhile", vm.ShowsLineForDiagnostics(greeting), true);
            // STAKE: unlike every other opener, the player keeps the floor: he can type and send while it is written.
            t.Expect("thePlayerCanType", vm.IsChatInputVisible, true);
            t.Expect("thePlayerCanSend", vm.IsSendEnabled, true);

            vm.SetSceneOpenerAsideForDiagnostics();
            // STAKE: the player who spoke first keeps the floor: the greeting stands and is what the character said.
            t.Expect("theGreetingStillShows", vm.ShowsLineForDiagnostics(greeting), true);
            t.Expect("theGreetingIsRemembered", vm.LastRememberedLineForDiagnostics, greeting);
         }
         finally
         {
            if (Chat.ChatManager.IsOpen) Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();
            Campaign.Current.TimeControlMode = timeBefore;
         }

         return t.Line();
      }

      private static string TestSceneImageShown(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scene_image_shown");
         if (t.Skip(Chat.ChatManager.IsOpen || Chat.ExplorationBackdrop.IsOpen || UI.CrPanelHost.AnyPanelOwnsScreen, "a window or panel already owns the screen")) return t.Line();

         // A 2x1 PNG, enough for the panel to read its size and draw it.
         const string png = "iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAADklEQVR4nGNoSHD4D8IAEcMEPz986fMAAAAASUVORK5CYII=";
         string path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "cr_selftest_scene_image.png");
         CampaignTimeControlMode timeBefore = Campaign.Current.TimeControlMode;
         try
         {
            System.IO.File.WriteAllBytes(path, Convert.FromBase64String(png));
            Chat.ChatManager.OpenForExploration(new Chat.ExplorationSession {
               Title = "(selftest) The wood", ImagePath = path,
               BuildPrompt = () => throw new InvalidOperationException("selftest: no narration"),
               Apply = _ => new List<string>(), IsOver = () => false
            });

            t.Expect("theSceneOpened", Chat.ChatManager.IsOpen, true);
            // Dark Leather shows it in the margin beside the chat, Classic in its left pop-out.
            Chat.ChatViewModel vm = Chat.ChatManager.ActiveViewModel;
            bool inMargin = vm?.IsSceneImageVisible == true && vm.SceneImagePath == path;
            bool inPanel = vm?.ShowPanelCustomPortrait == true && vm.PanelPortraitPath == path;
            t.Note(inMargin ? "shown in the margin (Dark Leather)" : inPanel ? "shown in the left panel (Classic)" : "not shown");
            t.Expect("thatVeryPictureIsShown", inMargin || inPanel, true);
            if (inMargin)
            {
               // Slid right with the book, the margin picture would land over the pause menu (Gabriel, 31/10/2026).
               vm.SetVisualOffscreen(true);
               t.Expect("thePictureStepsAsideWithTheChat", vm.IsSceneImageVisible, false);
               vm.SetVisualOffscreen(false);
               t.Expect("andComesBackWithIt", vm.IsSceneImageVisible, true);
            }
         }
         finally
         {
            if (Chat.ChatManager.IsOpen) Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();
            if (Chat.ExplorationBackdrop.IsOpen) Chat.ExplorationBackdrop.Close();
            Campaign.Current.TimeControlMode = timeBefore;
            try { System.IO.File.Delete(path); } catch { /* a temp file left behind harms nothing */ }
         }

         return t.Line();
      }

      private static string TestCharacterVoice(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("character_voice");
         List<Hero> people = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && !h.IsChild && Mapping.SocialStationReader.StationOf(h) != null).Take(40).ToList();
         if (t.Skip(people.Count == 0, "no living character with a station")) return t.Line();

         var habits = new HashSet<string>();
         foreach (Hero someone in people)
         {
            string voice = Mapping.EncounterContextBuilder.ResolveCharacterVoice(someone);
            string station = Mapping.SocialStationReader.StationOf(someone);
            // STAKE: a character with no voice, or one that changes between two reads, has no voice at all.
            t.Expect($"{someone.StringId}:hasAVoice", !string.IsNullOrWhiteSpace(voice), true);
            t.Expect($"{someone.StringId}:sameWhenReadAgain", Mapping.EncounterContextBuilder.ResolveCharacterVoice(someone) == voice, true);
            string habit = Logic.Character.CharacterVoicePolicy.HabitsFor(station, (int) someone.Age).FirstOrDefault(h => voice?.StartsWith(h) == true);
            // STAKE: a merchant speaking of his forebears, or a girl calling a grown lord "child", breaks who they are.
            t.Expect($"{someone.StringId}:habitOfTheirStation", habit != null, true);
            if (habit != null) habits.Add(habit);
            if (station == "preacher") t.Expect($"{someone.StringId}:preacherNeverCurses", voice?.Contains("You never curse") == true, true);
         }

         t.Note($"{people.Count} characters, {habits.Count} habits; first: {Mapping.EncounterContextBuilder.ResolveCharacterVoice(people[0])}");
         // STAKE: the whole point: a hall of lords must not share one habit.
         if (people.Count >= 10) t.Expect("habitsAreNotAllOne", habits.Count > 1, true);

         return t.Line();
      }

      private static string TestCredulity(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("credulity");
         List<Hero> people = Hero.AllAliveHeroes.Where(h => h != Hero.MainHero && !h.IsChild && Mapping.SocialStationReader.StationOf(h) != null).Take(60).ToList();
         if (t.Skip(people.Count == 0 || Hero.MainHero == null, "no living character with a station")) return t.Line();

         int shrewd = 0, trusting = 0;
         Hero calm = null;
         foreach (Hero someone in people)
         {
            string note = Mapping.EncounterContextBuilder.ResolveCredulityNote(someone);
            // STAKE: nothing is saved; a character who believes differently on each read has no nature at all.
            t.Expect($"{someone.StringId}:sameWhenReadAgain", Mapping.EncounterContextBuilder.ResolveCredulityNote(someone) == note, true);
            if (note == null) calm ??= someone;
            else if (note.StartsWith("You are hard to fool")) shrewd++;
            else if (note.StartsWith("You are trusting")) trusting++;
         }

         t.Note($"{people.Count} characters: {shrewd} shrewd, {trusting} trusting, {people.Count - shrewd - trusting} ordinary or wary");
         if (t.Skip(calm == null || GrudgeBehavior.Instance == null, "no ordinary character to plant a broken oath on")) return t.Line();

         var planted = new Grudge {
            Id = "selftest_credulity", HolderId = calm.StringId, TargetId = Hero.MainHero.StringId, Source = GrudgeSource.BrokenOath,
            CauseSummary = "self-test: an oath broken", EventDay = (int) CampaignTime.Now.ToDays, Magnitude = 90, Rigidity = 50
         };
         try
         {
            GrudgeBehavior.Instance.AddGrudgeForTest(planted);
            // STAKE: once burned: a character the player swore false to does not take his word on trust again.
            t.Expect("brokenFaithMakesThemWary", Mapping.EncounterContextBuilder.ResolveCredulityNote(calm)?.Contains("broken faith with you before") == true, true);
         }
         finally
         {
            GrudgeBehavior.Instance.RemoveGrudge(planted);
         }

         t.Expect("waryNoLongerOnceTakenBack", Mapping.EncounterContextBuilder.ResolveCredulityNote(calm) == null, true);

         return t.Line();
      }

      private static string TestFriendsWithHouse(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("friends_with_house");

         foreach (Hero lord in Hero.AllAliveHeroes.Where(h => h.IsLord && h != Hero.MainHero && h.Clan != null).Take(200))
         {
            string block = Mapping.RelationshipsBuilder.Build(lord);
            string line = block.Split('\n').Select(l => l.Trim()).FirstOrDefault(l => l.StartsWith("Friends: ") || l.StartsWith("Enemies: "));
            if (line == null) continue;

            t.Note($"{lord.Name}: {line}");
            string[] names = line.Substring(line.IndexOf(':') + 1).TrimEnd('.').Split(',').Select(n => n.Trim()).ToArray();
            // STAKE: a friend or enemy of a house reaches the prompt with that house, never as a bare first name.
            bool everyHousedNameCarriesIt = names.All(n => n.Contains(" of ")
                                                           || Hero.AllAliveHeroes.Any(h => h.Name?.ToString() == n && (h.Clan == null || h.Clan.Name?.ToString() == "No clan")));
            t.Expect("everyHousedNameCarriesItsHouse", everyHousedNameCarriesIt, true);

            return t.Line();
         }

         t.Skip(true, "no lord among the first 200 has a friend or enemy listed");

         return t.Line();
      }

      private static string TestSilverTaste(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("silver_taste");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();

         List<ItemObject> items = MBObjectManager.Instance?.GetObjectTypeList<ItemObject>()?.ToList();
         ItemObject ore = items?.FirstOrDefault(it => it?.ItemCategory?.StringId == "silver");
         ItemObject silverware = items?.FirstOrDefault(it => it?.StringId == "jewelry");
         if (ore != null) t.Expect("silverOreIsNothingSpecial", Logic.Character.GiftTastePolicy.KindOf(ore.ItemCategory?.StringId), GiftKind.None);
         if (silverware != null) t.Expect("silverwareIsJewelry", Logic.Character.GiftTastePolicy.KindOf(silverware.ItemCategory?.StringId), GiftKind.Jewelry);

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && behavior.Store.Get(h.StringId) != null);
         if (t.Skip(lord == null, "no lord met yet (talk to one first)")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         List<GiftKind> lovedBefore = profile.LovedGifts, coldBefore = profile.ColdGifts, knownBefore = profile.KnownGifts;
         try
         {
            // STAKE: a love of silver rolled before 2.8.8 reads as a love of jewelry, learned as such.
            profile.LovedGifts = new List<GiftKind> {GiftKind.Silver};
            profile.ColdGifts = new List<GiftKind>();
            profile.KnownGifts = new List<GiftKind> {GiftKind.Silver};
            Mapping.NatureReader.Refresh(lord, profile);
            t.Note($"{lord.Name}: loved {string.Join(", ", profile.LovedGifts)}; known {string.Join(", ", profile.KnownGifts ?? new List<GiftKind>())}");
            t.Expect("lovedSilverIsJewelry", profile.LovedGifts.Count == 1 && profile.LovedGifts[0] == GiftKind.Jewelry, true);
            t.Expect("learnedSilverIsJewelry", profile.KnownGifts?.Contains(GiftKind.Jewelry) == true && !profile.KnownGifts.Contains(GiftKind.Silver), true);
         }
         finally
         {
            profile.LovedGifts = lovedBefore;
            profile.ColdGifts = coldBefore;
            profile.KnownGifts = knownBefore;
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestGiftTastes(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("gift_tastes");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null || MobileParty.MainParty?.ItemRoster == null, "no campaign")) return t.Line();

         // A lord with no live grudge against the player: the gift's grudge-softening tail must have nothing real to mend.
         var day = (int) CampaignTime.Now.ToDays;
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != Clan.PlayerClan
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness) && behavior.Store.Get(h.StringId) != null
                                                            && GrudgeBehavior.Instance?.LiveGrudgesFor(h, day)?.Any(g => g?.TargetId == Hero.MainHero.StringId) != true);
         if (t.Skip(lord == null, "no lord met yet without a grudge against you (talk to one first)")) return t.Line();
         ItemObject fur = MBObjectManager.Instance?.GetObjectTypeList<ItemObject>()?.FirstOrDefault(it => it?.ItemCategory?.StringId == "fur");
         if (t.Skip(fur == null, "no fur in the game data")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         List<GiftKind> lovedBefore = profile.LovedGifts, coldBefore = profile.ColdGifts, knownBefore = profile.KnownGifts;
         int regardBefore = profile.ReputationWithPlayer;
         try
         {
            t.Note($"{lord.Name}, {fur.Name} ({fur.Value} denars)");
            profile.LovedGifts = new List<GiftKind> {GiftKind.Furs};
            profile.ColdGifts = new List<GiftKind>();
            profile.KnownGifts = null;
            NpcMemoryService.Core.Services.ProfileMutator.ApplyReputationDelta(profile, 20 - profile.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
            var today = (int) CampaignTime.Now.ToDays;
            bool givenToday = AppreciationBehavior.Instance?.AppreciationsFor(lord.StringId)?
                                 .Any(a => a.Source == Logic.Appreciations.AppreciationSource.GiftReceived && a.TargetId == Hero.MainHero.StringId && a.EventDay == today) == true;
            int expected = Logic.Character.GiftTastePolicy.Warmth(Logic.DeedRegardPolicy.GiftRegard(fur.Value, givenToday), Logic.Character.GiftWelcome.Loved);

            MobileParty.MainParty.ItemRoster.AddToCounts(fur, 1);
            behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "give_item"}, lord, new ActionContext(profile, null) {OfferedItemId = fur.StringId});

            t.Expect("readAsFurs", Logic.Character.GiftTastePolicy.KindOf(fur.ItemCategory?.StringId), GiftKind.Furs);
            t.Expect("aLovedGiftEarnsTwice", profile.ReputationWithPlayer - 20, expected);
            t.Expect("theTasteIsLearned", profile.KnownGifts?.Contains(GiftKind.Furs) == true, true);
            t.Expect("andHisPageNamesIt", Mapping.KnownPageReader.LinesFor(lord).Any(l => l.Contains("Gifts that delight") && l.Contains("furs")), true);
         }
         finally
         {
            profile.LovedGifts = lovedBefore;
            profile.ColdGifts = coldBefore;
            profile.KnownGifts = knownBefore;
            NpcMemoryService.Core.Services.ProfileMutator.ApplyReputationDelta(profile, regardBefore - profile.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestMattersMost(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("matters_most");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();

         // A lord already known to the store, so nothing is left behind in it.
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != Clan.PlayerClan && h.Spouse != null
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness) && behavior.Store.Get(h.StringId) != null);
         if (t.Skip(lord == null, "no married lord met yet (talk to one first)")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lord.StringId);
         MattersMost mattersBefore = profile.MattersMost;
         bool knownBefore = profile.MattersMostKnown;
         int discoveriesBefore = profile.DiscoveredTraits.Count;
         try
         {
            t.Note($"{lord.Name}");
            profile.MattersMost = MattersMost.None;
            profile.MattersMostKnown = false;
            Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
            Logic.Character.MattersMostFacts facts = Mapping.MattersMostReader.FactsOf(lord, profile);
            t.Expect("somethingIsChosen", profile.MattersMost != MattersMost.None, true);
            t.Expect("andItIsTrueOfHim", Logic.Character.MattersMostPolicy.Grounded(profile.MattersMost, facts), true);
            t.Expect("hisPageIsSilentUntilHeSaysIt", Mapping.KnownPageReader.LinesFor(lord).Count, 0);

            ProfileMutator.Apply(profile, new ParsedResponse {
               Dialogue = "", Discovery = new DiscoveredTrait {Key = MattersMostDiscovery.Key, Description = "It is what he lives for."}
            }, (int) CampaignTime.Now.ToDays);
            t.Expect("hisWordsMarkItLearned", profile.MattersMostKnown, true);
            t.Expect("withNoFreeTextBesideIt", profile.DiscoveredTraits.Count, discoveriesBefore);
            t.Expect("hisPageNamesIt", Mapping.KnownPageReader.LinesFor(lord).FirstOrDefault()?.StartsWith("What matters most to ") == true, true);

            Logic.Character.MattersMostFacts unwed = new() {
               HeroId = facts.HeroId, Traits = facts.Traits, HasChildren = facts.HasChildren, HasSpouse = false, HasLover = facts.HasLover,
               LovesThePlayer = facts.LovesThePlayer, HasKin = facts.HasKin, IsNoble = facts.IsNoble, LeadsTheirHouse = facts.LeadsTheirHouse,
               HoldsLands = facts.HoldsLands, IsWanderer = facts.IsWanderer, HasScoreToSettle = facts.HasScoreToSettle
            };
            t.Expect("aSpouseLostMovesIt", Logic.Character.MattersMostPolicy.Resolve(MattersMost.Spouse, unwed) != MattersMost.Spouse, true);
         }
         finally
         {
            profile.MattersMost = mattersBefore;
            profile.MattersMostKnown = knownBefore;
            if (profile.DiscoveredTraits.Count > discoveriesBefore) profile.DiscoveredTraits.RemoveRange(discoveriesBefore, profile.DiscoveredTraits.Count - discoveriesBefore);
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestIntimateActs(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("intimate_acts");
         if (t.Skip(ModSettings.AdultContentLevel != AdultContentLevel.Hardcore, "the Adult Content level is not Hardcore")) return t.Line();
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && !h.IsPrisoner && h.Clan != Clan.PlayerClan
                                                            && h.IsFemale != Hero.MainHero.IsFemale && h.Spouse == null
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness));
         if (t.Skip(lord == null, "no free unwed lord of the other sex")) return t.Line();

         NpcProfile stored = behavior.Store.Get(lord.StringId);
         bool hadProfile = stored != null;
         NpcProfile profile = stored ?? Mapping.HeroProfileMapper.FromHero(lord);
         Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
         RomanticProfile r = profile.Romantic;
         if (t.Skip(r == null, $"{lord.Name} has no romantic profile")) return t.Line();

         int regardBefore = profile.ReputationWithPlayer, eventsBefore = profile.Events.Count;
         RomanticStatus statusBefore = r.Status;
         List<IntimateAct> lovedBefore = r.LovedActs, dislikedBefore = r.DislikedActs, lessFondBefore = r.LessFondActs, knownBefore = r.KnownActs;
         int revisionBeforeAll = r.TastesRevision;
         IGameStateBridge bridge = behavior.GameStateBridge;
         GameAction Act(string act, string done) => new() {Type = Logic.Romance.IntimateActReading.Verb, Parameters = new Dictionary<string, string> {["act"] = act, ["done"] = done}};
         try
         {
            r.LovedActs = new List<IntimateAct> {IntimateAct.OralGiving};
            r.DislikedActs = new List<IntimateAct> {IntimateAct.AnalReceiving};
            r.LessFondActs = new List<IntimateAct> {IntimateAct.DirtyTalk};
            r.KnownActs = null;
            r.Status = RomanticStatus.Intimate;
            NpcMemoryService.Core.Services.ProfileMutator.ApplyReputationDelta(profile, 60 - profile.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
            if (t.Skip(!bridge.PermitsIntimacyWith(lord, profile), $"{lord.Name} would not permit intimacy even so")) return t.Line();
            Mapping.IntimateActApplier.ForgetCharges();
            t.Note($"{lord.Name}");

            EncounterContext context = Mapping.EncounterContextBuilder.Build(lord, profile, bridge);
            t.Expect("theReaderIsTaughtHerTastes", context.StoryChoicesForInterpreter?.Contains("- anal_receiving:") == true
                                                   && context.StoryChoicesForInterpreter.Contains("- oral_giving:"), true);

            t.Expect("nothingLearnedNothingOnHerPage", Mapping.HeartPageReader.TastesLine(lord, profile), null);
            Mapping.IntimateActApplier.Apply(Act("anal_receiving", "proposed"), lord, profile, bridge);
            t.Expect("askingCostsNothing", profile.ReputationWithPlayer, 60);
            t.Expect("butTheTasteIsLearned", r.KnownActs?.Contains(IntimateAct.AnalReceiving) == true, true);
            t.Expect("andHerPageNamesIt", Mapping.HeartPageReader.TastesLine(lord, profile)?.Contains("does not like being taken anally") == true, true);

            Mapping.IntimateActApplier.Apply(Act("anal_receiving", "performed"), lord, profile, bridge);
            t.Expect("imposedItCostsRegard", profile.ReputationWithPlayer, 60 + Logic.DeedRegardPolicy.ImposedDislikedGestureVictim);
            t.Expect("andSheRemembers", profile.Events.Count > eventsBefore, true);

            Mapping.IntimateActApplier.Apply(Act("anal_receiving", "performed"), lord, profile, bridge);
            t.Expect("oneNightIsOneOffence", profile.ReputationWithPlayer, 60 + Logic.DeedRegardPolicy.ImposedDislikedGestureVictim);

            Mapping.IntimateActApplier.Apply(Act("oral_giving", "performed"), lord, profile, bridge);
            t.Expect("whatSheLovesWarmsHer", profile.ReputationWithPlayer, 60 + Logic.DeedRegardPolicy.ImposedDislikedGestureVictim + Logic.DeedRegardPolicy.FoundLovedGestureVictim);

            Mapping.IntimateActApplier.Apply(Act("dirty_talk", "performed"), lord, profile, bridge);
            t.Expect("whatSheIsLessFondOfCostsNothing", profile.ReputationWithPlayer, 60 + Logic.DeedRegardPolicy.ImposedDislikedGestureVictim + Logic.DeedRegardPolicy.FoundLovedGestureVictim);
            t.Expect("andHerPageTellsAllThree", Mapping.HeartPageReader.TastesLine(lord, profile)?.Contains("is less fond of crude words") == true, true);

            // A profile rolled before the list widened, read through the real load path: what she loved and learned stays,
            // the new gestures are added, and it is done once.
            r.TastesRevision = 0;
            Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
            t.Expect("anOldProfileIsCompleted", r.TastesRevision, Logic.Romance.IntimateActPolicy.Revision);
            t.Expect("keepingWhatSheLoved", r.LovedActs?.FirstOrDefault(), IntimateAct.OralGiving);
            t.Expect("andWhatThePlayerLearned", r.DislikedActs?.Contains(IntimateAct.AnalReceiving) == true, true);
         }
         finally
         {
            Mapping.IntimateActApplier.ForgetCharges();
            r.LovedActs = lovedBefore;
            r.DislikedActs = dislikedBefore;
            r.LessFondActs = lessFondBefore;
            r.KnownActs = knownBefore;
            r.Status = statusBefore;
            r.TastesRevision = revisionBeforeAll;
            if (profile.Events.Count > eventsBefore) profile.Events.RemoveRange(eventsBefore, profile.Events.Count - eventsBefore);
            NpcMemoryService.Core.Services.ProfileMutator.ApplyReputationDelta(profile, regardBefore - profile.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
            if (hadProfile) behavior.Store.Set(profile);
         }

         return t.Line();
      }

      private static string TestOverridePreferences(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("override_preferences");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();
         if (t.Skip(CrSettings.Instance == null || Lore.CharacterLoreBehavior.Instance == null, "MCM settings or the lore behaviour unavailable")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != Clan.PlayerClan
                                                            && CharacterOverrideLoader.For(h) == null && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness));
         if (t.Skip(lord == null, "no lord without an authored entry")) return t.Line();

         NpcProfile stored = behavior.Store.Get(lord.StringId);
         bool hadProfile = stored != null;
         NpcProfile profile = stored ?? Mapping.HeroProfileMapper.FromHero(lord);
         Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
         RomanticProfile r = profile.Romantic;
         if (t.Skip(r == null, $"{lord.Name} has no romantic profile")) return t.Line();

         bool wasEnabled = ModSettings.UseCustomTraits;
         List<RomanticPreference> before = r.Preferences.ToList();
         var authored = new[] {RomanticPreference.Polyamorous, RomanticPreference.Devoted};
         void Old()
         {
            r.Preferences.Clear();
            r.Preferences.Add(RomanticPreference.Reserved);
         }

         try
         {
            CrSettings.Instance.UseCustomTraits = true;
            CharacterOverrideLoader.InjectRuntimeOverride(new CharacterOverride {
               Id = lord.StringId, Hero = lord.Name?.ToString(), Preferences = new List<string> {"Polyamorous", "Devoted"}
            });
            t.Note($"{lord.Name}; preferences-only entry injected at runtime, character_overrides.json untouched");

            // STAKE (the report): the reload lays an entry's preferences on the stored profile, traits and kinks absent.
            Old();
            behavior.Store.Set(profile);
            Lore.CharacterLoreBehavior.Instance.ApplyAll();
            RomanticProfile inStore = behavior.Store.Get(lord.StringId)?.Romantic;
            t.Expect("theReloadLaysThePreferencesOnTheStoredProfile", inStore != null && inStore.Preferences.SequenceEqual(authored), true);

            // STAKE: a conversation's own profile, brought up to date, carries them too.
            Old();
            Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
            t.Expect("thePathAConversationTakesSeesThem", r.Preferences.SequenceEqual(authored), true);
         }
         finally
         {
            CharacterOverrideLoader.Load();
            CrSettings.Instance.UseCustomTraits = wasEnabled;
            if (wasEnabled) Lore.CharacterLoreBehavior.Instance.ApplyAll();
            else Lore.CharacterLoreBehavior.Instance.RestoreAll();
            r.Preferences.Clear();
            r.Preferences.AddRange(before);
            if (hadProfile) behavior.Store.Set(profile);
            else behavior.Store.Remove(lord.StringId);
         }

         return t.Line();
      }

      private static string TestOverrideActs(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("override_acts");
         if (t.Skip(behavior?.Store == null || Hero.MainHero == null, "no campaign")) return t.Line();
         if (t.Skip(CrSettings.Instance == null || Lore.CharacterLoreBehavior.Instance == null, "MCM settings or the lore behaviour unavailable")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != Clan.PlayerClan
                                                            && CharacterOverrideLoader.For(h) == null && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness));
         if (t.Skip(lord == null, "no lord without an authored entry")) return t.Line();

         NpcProfile stored = behavior.Store.Get(lord.StringId);
         bool hadProfile = stored != null;
         NpcProfile profile = stored ?? Mapping.HeroProfileMapper.FromHero(lord);
         Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
         RomanticProfile r = profile.Romantic;
         if (t.Skip(r == null, $"{lord.Name} has no romantic profile")) return t.Line();

         bool wasEnabled = ModSettings.UseCustomTraits;
         List<IntimateAct> lovedBefore = r.LovedActs, dislikedBefore = r.DislikedActs, lessFondBefore = r.LessFondActs, knownBefore = r.KnownActs;
         int revisionBefore = r.TastesRevision;
         void Roll()
         {
            r.LovedActs = new List<IntimateAct> {IntimateAct.Massage};
            r.LessFondActs = new List<IntimateAct> {IntimateAct.Kissing};
            r.DislikedActs = new List<IntimateAct> {IntimateAct.Spanking};
            r.TastesRevision = Logic.Romance.IntimateActPolicy.Revision;
         }

         try
         {
            CrSettings.Instance.UseCustomTraits = true;
            CharacterOverrideLoader.InjectRuntimeOverride(new CharacterOverride {
               Id = lord.StringId, Hero = lord.Name?.ToString(), Loves = new List<string> {"kissing", "beneath"},
               LessFond = new List<string> {"dirty_talk"}, Dislikes = new List<string>()
            });
            t.Note($"{lord.Name}; lock injected at runtime, character_overrides.json untouched");
            t.Expect("theLoreBehaviourPluggedTheSyncIntoTheProfileUpgrade", Mapping.HeroProfileMapper.AuthoredTastesSync != null, true);

            Roll();
            r.KnownActs = null;
            behavior.Store.Set(profile);
            Lore.CharacterLoreBehavior.Instance.ApplyAll();
            RomanticProfile inStore = behavior.Store.Get(lord.StringId)?.Romantic;
            t.Expect("theReloadLaysTheLockOnTheStoredProfile", inStore?.LovedActs != null && inStore.LovedActs.SequenceEqual(new[] {IntimateAct.Kissing, IntimateAct.Beneath}), true);
            t.Expect("kissingSitsInOneListOnly", inStore?.LessFondActs != null && inStore.LessFondActs.SequenceEqual(new[] {IntimateAct.DirtyTalk}), true);
            t.Expect("anEmptyDislikeStaysEmpty", inStore?.DislikedActs?.Count, 0);

            inStore.KnownActs = new List<IntimateAct> {IntimateAct.Beneath};
            t.Expect("theHeartLineReadsTheAuthoredGesture", Mapping.HeartPageReader.TastesLine(lord, behavior.Store.Get(lord.StringId)) != null, true);
            inStore.KnownActs = null;

            Roll();
            Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
            t.Expect("thePathCrActsTakesSeesTheLock", r.LovedActs.SequenceEqual(new[] {IntimateAct.Kissing, IntimateAct.Beneath}), true);

            r.TastesRevision = 0;
            Mapping.HeroProfileMapper.UpgradeIfNeeded(profile, lord);
            t.Expect("anOlderRevisionIsNotPaddedPastTheLock", r.LovedActs.Count == 2 && r.DislikedActs.Count == 0 && r.LessFondActs.SequenceEqual(new[] {IntimateAct.DirtyTalk}), true);

            behavior.Store.Set(profile);
            CrSettings.Instance.UseCustomTraits = false;
            Lore.CharacterLoreBehavior.Instance.RestoreAll();
            RomanticProfile lifted = behavior.Store.Get(lord.StringId)?.Romantic;
            Logic.Romance.IntimateTastes own = Logic.Romance.IntimateActPolicy.Roll(Mapping.RomanticProfileBuilder.TasteFacts(lord, lifted?.Kinks, lifted?.Preferences));
            t.Expect("customTraitsOffGivesBackTheirOwnRoll", lifted?.LovedActs != null && lifted.LovedActs.SequenceEqual(own.Loved), true);
         }
         finally
         {
            CharacterOverrideLoader.Load();
            CrSettings.Instance.UseCustomTraits = wasEnabled;
            if (wasEnabled) Lore.CharacterLoreBehavior.Instance.ApplyAll();
            else Lore.CharacterLoreBehavior.Instance.RestoreAll();
            r.LovedActs = lovedBefore;
            r.DislikedActs = dislikedBefore;
            r.LessFondActs = lessFondBefore;
            r.KnownActs = knownBefore;
            r.TastesRevision = revisionBefore;
            if (hadProfile) behavior.Store.Set(profile);
            else behavior.Store.Remove(lord.StringId);
         }

         return t.Line();
      }

      private static string TestSummonedMeetingOnBackdrop(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("summoned_meeting_on_backdrop");
         if (t.Skip(Chat.ChatManager.IsOpen || Chat.ExplorationBackdrop.IsOpen || UI.CrPanelHost.AnyPanelOwnsScreen, "a window or panel already owns the screen")) return t.Line();
         if (t.Skip(behavior?.DialogFlow == null, "the dialogue flow is not ready")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && !h.IsPrisoner && h.Clan != Clan.PlayerClan
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness));
         if (t.Skip(lord == null, "no free lord to meet")) return t.Line();

         TaleWorlds.Core.GameState before = TaleWorlds.Core.Game.Current?.GameStateManager?.ActiveState;
         CampaignTimeControlMode timeBefore = Campaign.Current.TimeControlMode;
         try
         {
            behavior.DialogFlow.OpenChatForSummonedMeeting(lord);
            t.Expect("theMeetingOpened", Chat.ChatManager.IsOpen, true);
            t.Expect("onTheScenesBackdrop", Chat.ExplorationBackdrop.IsOpen && Chat.ChatManager.MeetingOnBackdrop, true);
            t.Expect("noVanillaConversationRuns", Campaign.Current.ConversationManager?.IsConversationInProgress == true, false);
            t.Expect("theCharacterSpeaksFirst", Chat.ChatManager.ActiveViewModel?.IsSendEnabled, false);

            Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();

            t.Expect("theBackdropIsGone", Chat.ExplorationBackdrop.IsOpen, false);
            t.Expect("theMapIsGivenBack", TaleWorlds.Core.Game.Current?.GameStateManager?.ActiveState == before, true);
         }
         finally
         {
            if (Chat.ChatManager.IsOpen) Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();
            if (Chat.ExplorationBackdrop.IsOpen) Chat.ExplorationBackdrop.Close();
            Campaign.Current.TimeControlMode = timeBefore;
         }

         return t.Line();
      }

      private static string TestSceneCloseGivesTheMapBack(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scene_close_gives_the_map_back");
         if (t.Skip(Chat.ChatManager.IsOpen || Chat.ExplorationBackdrop.IsOpen || UI.CrPanelHost.AnyPanelOwnsScreen, "a window or panel already owns the screen")) return t.Line();

         TaleWorlds.Core.GameState before = TaleWorlds.Core.Game.Current?.GameStateManager?.ActiveState;
         CampaignTimeControlMode timeBefore = Campaign.Current.TimeControlMode;
         bool closed = false, queuedRan = false;
         var session = new Chat.ExplorationSession {
            Title = "(selftest) The wood",
            // Refused before any model is asked: this test is about the close, not the narration.
            BuildPrompt = () => throw new InvalidOperationException("selftest: no narration"),
            Apply = _ => new List<string>(),
            IsOver = () => false,
            OnClose = () =>
            {
               closed = true;
               MainThreadDispatcher.Enqueue(() => queuedRan = true);
            }
         };
         try
         {
            Chat.ChatManager.OpenForExploration(session);
            t.Expect("theSceneOpened", Chat.ChatManager.IsOpen, true);
            t.Expect("onItsBackdrop", Chat.ExplorationBackdrop.IsOpen, true);

            Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();

            t.Expect("theScenesOwnCloseRan", closed, true);
            t.Expect("whatTheCloseQueuedRan", queuedRan, true);
            t.Expect("theBackdropIsGone", Chat.ExplorationBackdrop.IsOpen, false);
            t.Expect("theMapIsGivenBack", TaleWorlds.Core.Game.Current?.GameStateManager?.ActiveState == before, true);
         }
         finally
         {
            if (Chat.ChatManager.IsOpen) Chat.ChatManager.Close();
            MainThreadDispatcher.Pump();
            if (Chat.ExplorationBackdrop.IsOpen) Chat.ExplorationBackdrop.Close();
            Campaign.Current.TimeControlMode = timeBefore;
         }

         return t.Line();
      }

