      private static string TestPlayerCompany(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("player_company");

         List<(Hero Hero, CompanyRole Role)> members = Witnesses.PlayerCompany.Members();

         // GABRIEL'S RULE (13/10/2026): arrange a companion into the main party when nobody travels with the
         // player, rather than report MANUAL. PlayerCompany.Members() reads MobileParty.MainParty.MemberRoster
         // directly (CalradiaRemembers/Witnesses/PlayerCompany.cs), which is exactly what ArrangedCompanion's
         // mustBeInMainParty tier puts a hero into.
         using var arranged = members.Count == 0 ? ArrangedCompanion.Get(behavior, mustBeInMainParty: true) : null;

         if (arranged != null)
         {
            t.Note($"arranged {arranged.Companion.Name} into the main party");
            members = Witnesses.PlayerCompany.Members();
         }

         if (t.Skip(members.Count == 0,
                "nobody travels with the player, and no companion/wanderer template was available to arrange one")) return t.Line();

         t.Note(string.Join(", ", members.Select(m => $"{m.Hero.Name} ({m.Role})")));
         t.Expect("thePlayerIsNeverOfHisOwnCompany", members.Any(m => m.Hero == Hero.MainHero), false);
         t.Expect("everyPrisonerIsHeld", members.Where(m => m.Role == CompanyRole.Prisoner).All(m => m.Hero.IsPrisoner), true);

         // Inviting: the person spoken to is never offered.
         (Hero first, CompanyRole _) = members[0];
         IReadOnlyList<CompanyMember> offered = PlayerCompanyPolicy.InviteCandidates(Witnesses.PlayerCompany.AsCandidates(), first.StringId, new string[0]);
         t.Expect("theOneSpokenToIsNotOffered", offered.Any(c => c.Id == first.StringId), false);

         // A room made only of the player's company, as Invite would seat them: cleared at once (Gabriel, 03/10/2026).
         var seated = members.Select(m => Witnesses.PlayerCompany.EntryFor(m.Hero, m.Role)).Where(e => e != null)
                             .Select(e => new PresentWitness {HeroId = e.HeroStringId, IsPlayerCompanion = e.IsPlayerCompanion, IsBroughtCaptive = e.IsBroughtCaptive});
         bool allMine = PlayerCompanyPolicy.AllAreThePlayers(seated, Witnesses.PlayerCompany.Ids());
         t.Expect("aRoomOfThePlayersOwnIsClearedAtOnce",
                  PrivateAudiencePolicy.Decide(new PrivateAudienceFacts {Allowed = true, AnyWitness = true, AllWitnessesAreThePlayers = allMine}),
                  PrivateAudienceVerdict.ClearAtOnce);

         return t.Line();
      }

      /// <summary>
      ///   Fakade (Nexus, 10/11/2026): with no fact of how a captive was kept, the model invented a mistreatment. Drives the
      ///   real CaptureFactsFor on a really captured lord and the line built from it.
      /// </summary>
      private static string TestCaptureNormFacts(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("capture_norm_facts");

         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.PartyBelongedTo != null && h.Clan?.Leader != h);
         if (t.Skip(captive == null, "no free in-party lord to capture")) return t.Line();

         Hero hearer = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h != captive && h.IsLord && h.Clan != null && h.Clan != captive.Clan);
         if (t.Skip(hearer == null, "no other lord to hear of it")) return t.Line();

         TakePrisonerAction.Apply(PartyBase.MainParty, captive);
         try
         {
            if (t.Abort(!captive.IsPrisoner, $"capture failed for {captive.Name}")) return t.Line();

            var e = new WorldEvent {Status = CaptureNorm.Status, ActorIds = new List<string> {Hero.MainHero.StringId, captive.StringId}};
            CaptiveKeepingFacts facts = EncounterContextBuilder.CaptureFactsFor(hearer, e, CaptureStake.None);
            string line = CaptureNorm.Line(facts);

            t.Note($"{captive.Name} heard by {hearer.Name}");
            t.Expect("still held", facts.StillHeld, true);
            t.Expect("held in the player's party", facts.HeldInPlayersParty, true);
            t.Expect("sex read", facts.CaptiveIsFemale, captive.IsFemale);
            t.Expect("forbids inventing ill treatment", line.Contains("Nothing you know tells of ill treatment"), true);
            t.Expect("keeping no longer named the offence", line.Contains("What would truly offend"), false);
         }
         finally
         {
            try { if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive); }
            catch { }
         }

         return t.Line();
      }

      private static string TestCaptiveNotoriety(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_notoriety");

         Hero ruler = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.Clan?.Kingdom?.Leader == h);
         if (t.Skip(ruler == null, "no ruler")) return t.Line();

         Stature stature = Mapping.StatureReader.Of(ruler);
         t.Expect("aRulersCaptureIsKnownAsARulers", CaptiveNotoriety.Describe(stature, ruler.IsClanLeader), "a ruler");
         t.Expect("aRulersCaptureIsNews", CaptiveNotoriety.NewsMagnitude(stature, ruler.IsClanLeader) > 0, true);

         // The real prompt of a captive of rank, when the game holds one: she knows the world talks of her.
         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsPrisoner && h != Hero.MainHero
                                                               && CaptiveNotoriety.Describe(Mapping.StatureReader.Of(h), h.IsClanLeader) != null);
         if (captive == null)
         {
            t.Note($"{ruler.Name} reads as a ruler; no captive of rank in this game to read a prompt from.");

            return t.Line();
         }

         NpcProfile profile = behavior.Store.Get(captive.StringId) ?? Mapping.HeroProfileMapper.FromHero(captive);
         EncounterContext context = Mapping.EncounterContextBuilder.Build(captive, profile, behavior.GameStateBridge, null);
         string prompt = behavior.LlmServices.ChatService.PromptBuilder.BuildSystemPrompt(profile, new WorldState {CurrentDay = (int) CampaignTime.Now.ToDays}, context);
         t.Note($"{captive.Name}, captive: notoriety '{context.CaptiveNotoriety}'");
         t.Expect("theCaptiveKnowsTheWorldTalksOfHer", prompt.Contains("is talked of in every hall"), true);

         return t.Line();
      }

      private static string TestMemoryRepairAccents(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("memory_repair_accents");

         Hero hero = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && behavior.Store.Get(h.StringId) != null);
         if (t.Skip(hero == null, "no lord with a CR profile")) return t.Line();

         const string typed = "[SELFTEST] Elle m'a aidé à Pravend, cœur vaillant.";
         try
         {
            // As a save made before the console fix holds it: the memory already stored mangled.
            NpcProfile profile = behavior.Store.Get(hero.StringId);
            profile.Events.Add(new NotableEvent(1, NotableEventType.Other, Logic.Diagnostics.ConsoleTextRepair.Mangle(typed)));
            behavior.Store.Set(profile);

            string reply = TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.memory_repair_accents", "", out bool found);
            t.Note($"{hero.Name}: {reply}");
            t.Expect("theCommandWasFound", found, true);
            t.Expect("theMemoryReadsAsTyped", behavior.Store.Get(hero.StringId).Events.Any(e => e.summary == typed), true);
         }
         finally
         {
            NpcProfile profile = behavior.Store.Get(hero.StringId);
            if (profile?.Events != null)
            {
               profile.Events.RemoveAll(e => e.summary != null && e.summary.StartsWith("[SELFTEST]"));
               behavior.Store.Set(profile);
            }
         }

         return t.Line();
      }

      private static string TestConsoleAccents(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("console_accents");

         // A one-word name, so cr.memory_add's own last-token lookup lands on the same hero this test reads back.
         Hero hero = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.IsLord && h.Name != null && !h.Name.ToString().Contains(" "));
         if (t.Skip(hero == null, "no lord with a one-word name")) return t.Line();

         string token = hero.Name.ToString();
         Hero target = Hero.AllAliveHeroes.FirstOrDefault(h => h != Hero.MainHero && h.Name != null && h.Name.ToString().IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0);
         const string typed = "[SELFTEST] é è ê à ù ç œ É È Ê À Ù Ç Œ";

         try
         {
            // Exactly what the console delivers: the text mangled, through the engine's own dispatch.
            TaleWorlds.Library.CommandLineFunctionality.CallFunction("cr.memory_add", "0 " + Logic.Diagnostics.ConsoleTextRepair.Mangle(typed) + " " + token, out bool found);
            t.Expect("theCommandWasFound", found, true);

            NpcProfile profile = behavior.Store.Get(target.StringId);
            t.Note($"{target.Name}: last memory reads \"{profile?.Events?.LastOrDefault(e => e.summary.StartsWith("[SELFTEST]"))?.summary}\"");
            t.Expect("theMemoryReadsExactlyAsTyped", profile?.Events?.Any(e => e.summary == typed) == true, true);
         }
         finally
         {
            NpcProfile profile = behavior.Store.Get(target.StringId);
            if (profile?.Events != null)
            {
               profile.Events.RemoveAll(e => e.summary != null && e.summary.StartsWith("[SELFTEST]"));
               behavior.Store.Set(profile);
            }
         }

         return t.Line();
      }

