         MethodInfo setData = HarmonyLib.AccessTools.Method(typeof(TaleWorlds.MountAndBlade.ViewModelCollection.Inquiries.SingleQueryPopUpVM), "SetData");
         t.Expect("thePopupTellsWhatItShows", HarmonyLib.Harmony.GetPatchInfo(setData)?.Postfixes.Any(p => p.PatchMethod.DeclaringType == typeof(AudienceWhoSetDataPatch)) == true, true);

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h.Clan?.Kingdom != null && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(lord == null, "no lord of a realm in the world")) return t.Line();

         string who = AudienceInquiry.WhoLine(lord);
         t.Note(who.Trim());
         t.Expect("theWhoLineNamesHim", who.Contains("Who: ") && who.Contains(lord.Name.ToString()), true);

         // THE REPORTED CASE: a stranger reads as one. A lord never met and never remembered says so, with no regard.
         Hero stranger = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.HasMet && h != Hero.MainHero && Mapping.HeroPresence.IsInTheWorld(h) && behavior?.Store?.Get(h.StringId) == null);
         if (stranger != null)
         {
            string strangerLine = AudienceInquiry.WhoLine(stranger);
            t.Expect("aStrangerReadsAsNeverMet", strangerLine.Contains("You have never met.") && !strangerLine.Contains("regard"), true);
         }
         else t.Note("no lord unmet and unremembered: the stranger case is not checked");

         // A notable's trade in plain words: the game has no text for most trades and would print an ERROR line.
         Hero notable = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && Mapping.HeroPresence.IsInTheWorld(h) && h.Occupation != Occupation.Merchant);
         if (notable != null)
         {
            string notableLine = AudienceInquiry.WhoLine(notable);
            t.Note(notableLine.Trim());
            t.Expect("aNotablesTradeReadsPlainly", !notableLine.Contains("ERROR") && notableLine.Contains("Who: "), true);
         }

         // GABRIEL'S RULE (13/10/2026) considered: a popup already up when this test starts (a live CR
         // audience invitation raised by real gameplay, or some other feature's inquiry) is a REAL one, not
         // test residue (no OTHER self-test in this file ever leaves an InquiryData open), so it is never
         // dismissed to force this test through. Checked BEFORE calling Show at all, via the engine's own
         // InformationManager.IsAnyInquiryActive, so this test's own popup is never even queued behind it
         // (InformationManager.ShowInquiry's default prioritize=false would otherwise leave AudienceInquiry
         // .Showing pointing at the OTHER inquiry, which used to read as a vague, unexplained MANUAL).
         if (t.Skip(TaleWorlds.Library.InformationManager.IsAnyInquiryActive(),
                "a real popup/inquiry is already up (another feature's, or a live CR audience invitation); left untouched rather than dismissed to force this test through")) return t.Line();

         TaleWorlds.Library.InquiryData data = AudienceInquiry.Show(lord, "[testall] audience_who", "A test invitation. It closes itself.", "Close", "Close", null, null);
         try
         {
            if (t.Skip(AudienceInquiry.Showing != data, "another popup appeared the instant this test's own invitation was shown (a genuine race, not a pre-existing one): the test invitation waits behind it")) return t.Line();

            t.Expect("theInvitationCarriesHim", AudienceInquiry.DebugHeroOf(data), lord.StringId);
            t.Expect("theButtonShowsOnTheMap", AudienceWhoButtonMixin.Current?.IsCrWhoShown == true, TaleWorlds.MountAndBlade.Mission.Current == null);

            AudienceInquiry.DebugStartDetour(data);
            t.Expect("theInvitationStepsAside", AudienceInquiry.Showing == null && AudienceInquiry.DebugDetourPending, true);
            AudienceInquiry.Tick(Logic.Interception.EncyclopediaDetour.SecondsToOpen + 0.1f);
            t.Expect("theSameInvitationComesBack", AudienceInquiry.Showing == data && !AudienceInquiry.DebugDetourPending, true);
         }
         finally
         {
            AudienceInquiry.DebugCancelDetour();
            if (AudienceInquiry.Showing == data) TaleWorlds.Library.InformationManager.HideInquiry();
         }

         return t.Line();
      }

      /// <summary>
      ///   Wallace1067 (Nexus, 13/10/2026): "I ride up to a friendly lord ... standing alone on open ground ...
      ///   On End Conversation the encounter is not closed, and I'm left in the vanilla encounter menu ... It
      ///   happens every time." His log: "[CLOSE] encounter kept: a battle is under way in it; the game settles
      ///   it", with no battle anywhere. Drives the pure policy with each of the three sighting shapes directly,
      ///   so this stays green without a live fight on the map to arrange.
      /// </summary>
      private static string TestCloseLeavesMeeting(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("close_leaves_meeting");

         bool Leaves(Logic.Conversation.MeetingLeaveFacts f) => Logic.Conversation.MapEncounterClosePolicy.LeavesTheMeeting(f);

         t.Expect("aFriendlyPartyMetLeaves", Leaves(new() {HasEncounter = true, TalkedWithTheMetParty = true}), true);
         t.Expect("aPartyGoneLeaves", Leaves(new() {HasEncounter = true, MetPartyGone = true}), true);
         t.Expect("anEnemyAtWarStays", Leaves(new() {HasEncounter = true, TalkedWithTheMetParty = true, AtWarWithTheMetParty = true}), false);
         t.Expect("aSettlementVisitIsNotEnded", Leaves(new() {HasEncounter = true, TalkedWithTheMetParty = true, AtASettlement = true}), false);
         t.Expect("aBriefingIsNotEnded", Leaves(new() {HasEncounter = true, TalkedWithTheMetParty = true, BriefingReturnPending = true}), false);

         if (TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.Current != null)
            t.Note($"an encounter is open: met={TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.EncounteredParty?.Name}, "
                   + $"leave={TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.LeaveEncounter}, meetingDone={TaleWorlds.CampaignSystem.Encounters.PlayerEncounter.MeetingDone}");

         return t.Line();
      }

      private static string TestCloseSettledBattle(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("close_settled_battle");

         var live = new Logic.Conversation.MapEventSighting {Exists = true};
         var finalized = new Logic.Conversation.MapEventSighting {Exists = true, IsFinalized = true};
         var hasWinner = new Logic.Conversation.MapEventSighting {Exists = true, HasWinner = true};
         var none = new Logic.Conversation.MapEventSighting();

         t.Expect("aLiveFightIsLive", Logic.Conversation.MapEncounterClosePolicy.IsLive(live), true);
         t.Expect("aFinalizedFightIsNotLive", Logic.Conversation.MapEncounterClosePolicy.IsLive(finalized), false);
         t.Expect("aFightWithAWinnerIsNotLive", Logic.Conversation.MapEncounterClosePolicy.IsLive(hasWinner), false);
         t.Expect("noEventIsNotLive", Logic.Conversation.MapEncounterClosePolicy.IsLive(none), false);

         Logic.Conversation.MapEncounterCloseFacts FactsFor(bool battleUnderWay) => new() {HasEncounter = true, BattleUnderWay = battleUnderWay};

         t.Expect("aLiveFightKeepsTheEncounter", Logic.Conversation.MapEncounterClosePolicy.MayFinish(FactsFor(Logic.Conversation.MapEncounterClosePolicy.IsLive(live))), false);
         t.Expect("aFinalizedFightLetsItFinish", Logic.Conversation.MapEncounterClosePolicy.MayFinish(FactsFor(Logic.Conversation.MapEncounterClosePolicy.IsLive(finalized))), true);
         t.Expect("aFightWithAWinnerLetsItFinish", Logic.Conversation.MapEncounterClosePolicy.MayFinish(FactsFor(Logic.Conversation.MapEncounterClosePolicy.IsLive(hasWinner))), true);
         // Zivkyn (18/10/2026): a siege keeps the encounter, fight or none.
         t.Expect("aSiegeKeepsTheEncounter", Logic.Conversation.MapEncounterClosePolicy.MayFinish(new Logic.Conversation.MapEncounterCloseFacts {HasEncounter = true, SiegeUnderWay = true}), false);

         TaleWorlds.CampaignSystem.MapEvents.MapEvent mainPartyEvent = TaleWorlds.CampaignSystem.Party.MobileParty.MainParty?.MapEvent;
         if (mainPartyEvent != null) t.Note($"player's own party has a live MapEvent: finalized={mainPartyEvent.IsFinalized}, hasWinner={mainPartyEvent.HasWinner}, raid={mainPartyEvent.IsRaid}");

         return t.Line();
      }

      /// <summary>
      ///   tashmetu (Nexus, 13/10/2026, via cr.prompt_dump of a companion on 2.7.9): "I saw you cut down 168 of
      ///   them yourself at at the siege of Thorios Castle" doubled the preposition (WorldEventFeeders used to
      ///   hand the feat reporter the already-shaped place CLAUSE, " at the siege of X", where BattleFeatText's
      ///   own " at " expects the bare noun phrase) and addressed the player as "you" in a line that should name
      ///   them. Builds the same siege place the real feeder builds (BattleMemoryText.PlaceClause /
      ///   ChronicleEngagement) and drives the real BattleFeatReporter the way WorldEventFeeders now does
      ///   (engagement, not placeClause), with a synthetic rank-and-file toll. Mutates nothing: no journal, event,
      ///   or profile is persisted.
      /// </summary>
      private static string TestBattleMemoryWording(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("battle_memory_wording");

         const string settlementName = "Thorios Castle";
         string placeClause = BattleMemoryText.PlaceClause(BattleSetting.Siege, settlementName);
         string engagement = BattleMemoryText.ChronicleEngagement(BattleSetting.Siege, settlementName);
         t.Note($"placeClause='{placeClause}' engagement='{engagement}'");

         var journal = new CalradiaRemembers.Battles.BattleFeatJournal();
         journal.DebugRecord(null, null, 168); // a rank-and-file toll well past RemarkableTollThreshold

         // The real wiring (WorldEventFeeders.RecordBattlePerformanceIntoProfiles) hands the reporter ENGAGEMENT,
         // the noun phrase, never placeClause (which already carries its own " at "/" in "/" near ").
         string line = CalradiaRemembers.Battles.BattleFeatReporter.BuildReport(journal, engagement)
            .LinesFor("some_bystander").FirstOrDefault() ?? "";

         t.Note($"line='{line}'");
         t.Expect("a siege engagement yields exactly one 'at'", line.Contains("at at"), false);
         t.Expect("the witness line never addresses the player as 'you'", line.Contains(" you "), false);
         t.Expect("the witness line names the player", line.Contains(Hero.MainHero?.Name?.ToString() ?? "the player"), true);

         return t.Line();
      }

      private static string TestRealmFaces(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("realm_faces");
         Mapping.RealmFaceBehavior b = Mapping.RealmFaceBehavior.Instance;
         if (t.Skip(b == null, "the faces behaviour is not active")) return t.Line();

         b.LoadFaces();
         t.Note($"{b.Faces.Count} face(s): {string.Join(", ", b.Faces.Keys)}; problems: {b.Problems.Count}");
         t.Expect("everyFaceFileReads", b.Problems.Count, 0);
         foreach (string realm in b.Faces.Keys)
            t.Expect(realm + "IsARealm", Kingdom.All.Any(k => string.Equals(k.StringId, realm, StringComparison.OrdinalIgnoreCase)), true);

         Kingdom kingdom = Kingdom.All.FirstOrDefault(k => !k.IsEliminated && k.Leader?.Spouse != null && Mapping.HeroPresence.IsInTheWorld(k.Leader.Spouse));
         if (t.Skip(kingdom == null, "no ruler with a wife in the world")) return t.Line();

         Hero queen = kingdom.Leader.Spouse;
         StaticBodyProperties before = queen.StaticBodyProperties;
         string key = b.Faces.Values.FirstOrDefault()?.Key ?? "<BodyProperties version=\"4\" age=\"20\" weight=\"0.5\" build=\"0.5\" key=\"000A980810003015757A74679866577687B5878679788C47987777788567956720300602078868950701350000CC06200000000000000007000000003EFC10C2\" />";
         BodyProperties.FromString(key, out BodyProperties wanted);
         try
         {
            t.Expect("sheIsDressed", b.DebugDress(queen, kingdom.StringId, key), true);
            t.Expect("sheWearsTheFace", queen.StaticBodyProperties == wanted.StaticProperties, true);
            b.Faces.TryGetValue(kingdom.StringId, out RealmFace realmFace);
            string portrait = b.PortraitPath(realmFace);
            t.Note($"{kingdom.StringId} portrait: {portrait ?? "none named"}");
            t.Expect("herPortraitIsHerRealms", b.PortraitFor(queen.StringId), portrait);
            string shown = Portraits.ChatPortraitResolver.ResolveForHero(queen.StringId, queen.Name?.ToString());
            bool fromPlayersOwn = shown != null && Portraits.ChatPortraitResolver.PortraitDirs().Any(d => shown.StartsWith(d, StringComparison.OrdinalIgnoreCase));
            t.Expect("theChatShowsIt", portrait == null || shown == portrait || fromPlayersOwn, true);
            t.Expect("herFaceIsGivenBack", b.DebugGiveBack(queen), true);
            t.Expect("sheIsHerselfAgain", queen.StaticBodyProperties == before, true);
            t.Expect("herUsualPortraitIsBack", b.PortraitFor(queen.StringId), null);
         }
         finally
         {
            if (queen.StaticBodyProperties != before) b.DebugGiveBack(queen);
            b.Apply();
         }

         return t.Line();
      }

      private static string TestTaleScenarioBridge(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_scenario_bridge");
         if (t.Abort(WorldEventStore.Instance == null, "world-event store not ready")) return t.Line();

         Hero lady = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.IsFemale && h.Spouse != null && h.Spouse != Hero.MainHero
                                                            && Mapping.HeroPresence.IsInTheWorld(h) && Mapping.HeroPresence.IsInTheWorld(h.Spouse));
         if (t.Skip(lady == null || Hero.MainHero == null, "no married lady in the world")) return t.Line();

         Hero husband = lady.Spouse;
         var roles = new Dictionary<string, string> {["giver"] = lady.StringId, ["husband"] = husband.StringId, ["player"] = Hero.MainHero.StringId};
         ScenarioContext ctx = Scenarios.ScenarioBehavior.ForTale(roles);
         var runtime = new ScenarioRuntime(new HashSet<string>());
         runtime.Load(new[] {
            ScenarioRule.Parse("cr_selftest_whole_tale", "ON_TALE:cr_selftest_tale", new[] {"IF_ALIVE:{husband}"}, null, "cr selftest: {husband} heard of it", true),
            ScenarioRule.Parse("cr_selftest_this_end", "ON_TALE:cr_selftest_tale:end:won", new[] {"IF_HERO_IS:{giver}"}, null, "cr selftest: this ending", true),
            ScenarioRule.Parse("cr_selftest_other_end", "ON_TALE:cr_selftest_tale:end:lost", null, null, "cr selftest: never", true),
            ScenarioRule.Parse("cr_selftest_other_tale", "ON_TALE:cr_selftest_tale_two", null, null, "cr selftest: never", true)
         });

         var worldBefore = new HashSet<string>(WorldEventStore.Instance.All().Select(e => e.Id));
         try
         {
            List<string> played = runtime.Fire(KeywordToken.Parse("ON_TALE:cr_selftest_tale:end:won"), ctx).Select(r => r.Id).ToList();
            List<string> told = WorldEventStore.Instance.All().Where(e => !worldBefore.Contains(e.Id)).Select(e => e.Summary).ToList();
            t.Note($"{lady.Name}, wife of {husband.Name}: played={string.Join(",", played)}");

            t.Expect("theWholeTaleRuleAnswers", played.Contains("cr_selftest_whole_tale"), true);
            t.Expect("theEndingRuleAnswers", played.Contains("cr_selftest_this_end"), true);
            t.Expect("anotherEndingDoesNot", played.Contains("cr_selftest_other_end"), false);
            t.Expect("anotherTaleDoesNot", played.Contains("cr_selftest_other_tale"), false);
            t.Expect("theNewsNamesTheHusband", told.Any(s => s.Contains(husband.Name.ToString()) && !s.Contains("{husband}")), true);

            IFaction his = husband.MapFaction, mine = Hero.MainHero.MapFaction;
            bool twoRealmsAtPeace = his is Kingdom && mine != null && his != mine && !FactionManager.IsAtWarAgainstFaction(his, mine);
            t.Expect("pressForWarAppliesExactlyBetweenTwoRealmsAtPeace",
               ScenarioConsequenceExecutor.CanApply(KeywordToken.Parse("PRESS_FOR_WAR:{husband},{player}"), ctx), twoRealmsAtPeace);
         }
         finally
         {
            foreach (WorldEvent e in WorldEventStore.Instance.All().Where(e => !worldBefore.Contains(e.Id)).ToList())
               WorldEventStore.Instance.Remove(e.Id);
         }

         return t.Line();
      }

      /// <summary>The tale tale_on_enter walks: she leaves on a stage, and is given back at an ending.</summary>
      private const string OnEnterSelfTestTale = @"{
        ""id"": ""cr_selftest_on_enter"", ""title"": ""[SELFTEST] The Garden"",
        ""requires"": { ""giver"": { ""married"": true, ""min_regard"": -100 }, ""husband"": { ""role"": ""spouse_of_giver"" } },
        ""binds"": { ""giver"": ""a lady"", ""husband"": ""her husband"" },
        ""stages"": [
          { ""id"": ""ask"", ""journal"": ""[SELFTEST] {giver} asks for a word."", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" },
            ""on_complete"": { ""next"": ""garden"" } },
          { ""id"": ""garden"", ""journal"": ""[SELFTEST] {giver} waits."",
            ""choices"": [
              { ""id"": ""take_her"", ""label"": ""Leave with her"", ""sets"": ""with_her"",
                ""said"": { ""to"": ""{giver}"", ""meaning"": ""the player agrees to take {giver} away"" }, ""next"": ""away"" } ] },
          { ""id"": ""away"", ""journal"": ""[SELFTEST] {giver} rides with you."",
            ""on_enter"": [ { ""type"": ""elope"", ""if"": ""with_her"" } ],
            ""choices"": [
              { ""id"": ""give_back"", ""label"": ""Give her back"",
                ""said"": { ""to"": ""{husband}"", ""meaning"": ""the player gives {giver} back"" }, ""next"": ""end:returned"" } ] }
        ],
        ""endings"": { ""returned"": { ""consequences"": [ { ""type"": ""return_spouse"" } ] } }
      }";

      private static string TestTaleOnEnter(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_on_enter");
         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null || MobileParty.MainParty == null, "authored quests are not active, or no player party")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, "a real tale is under way; not disturbing it")) return t.Line();

         IFaction mine = Hero.MainHero?.MapFaction;
         Hero her = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.IsFemale && !h.IsChild && !h.IsPregnant && !h.IsPrisoner
                                                           && h.Spouse != null && h.Spouse != Hero.MainHero && !h.Spouse.IsPrisoner
                                                           && Mapping.HeroPresence.IsInTheWorld(h) && Mapping.HeroPresence.IsInTheWorld(h.Spouse)
                                                           && h.Clan?.Leader != h && h.GovernorOf == null && (h.PartyBelongedTo == null || h.PartyBelongedTo.LeaderHero != h)
                                                           && h.MapFaction != null && h.MapFaction != mine
                                                           && h.Spouse.PartyBelongedTo?.Army == null && h.Spouse.PartyBelongedTo?.MapEvent == null);
         if (t.Skip(her == null, "no married lady of another realm free to leave")) return t.Line();

         const string id = "cr_selftest_on_enter";
         t.Expect("theTaleLoadsClean", string.Join(" | ", b.DebugLoadTale(OnEnterSelfTestTale, "selftest_on_enter.json")), "");
         Logic.AuthoredQuests.AuthoredQuest tale = b.Quests.FirstOrDefault(q => q.Id == id);
         if (t.Abort(tale == null, "the tale did not load")) return t.Line();

         Hero him = her.Spouse;
         Clan herClan = her.Clan;
         var grudgesBefore = new HashSet<Logic.Grudges.Grudge>((IEnumerable<Logic.Grudges.Grudge>) Grudges.GrudgeBehavior.Instance?.GrudgesFor(him.StringId) ?? new List<Logic.Grudges.Grudge>());
         var reached = new List<CrTaleProgress>();
         var ended = new List<CrTaleProgress>();
         Action<CrTaleProgress> onReached = p => { if (p.TaleId == id) reached.Add(p); };
         Action<CrTaleProgress> onEnded = p => { if (p.TaleId == id) ended.Add(p); };
         CrTales.StageReached += onReached;
         CrTales.Ended += onEnded;
         try
         {
            var today = (int) CampaignTime.Now.ToDays;
            if (t.Abort(!b.TryOffer(her, today, 0, id, out string whyNot), $"{her.Name} could not give it: {whyNot}")) return t.Line();
            b.Accept(tale, b.Offer);
            t.Note($"{her.Name} and {him.Name}");

            b.DebugChoose("take_her");
            CrTaleProgress away = reached.LastOrDefault();
            CrTaleConsequence elope = away?.Consequences.FirstOrDefault(c => c.Type == "elope");
            t.Expect("theStageIsReported", away?.Where, "away");
            t.Expect("withTheFlagTheChoiceSet", away?.Flags.Contains("with_her") == true, true);
            t.Expect("andTheHusbandBound", away != null && away.Roles.TryGetValue("husband", out string h) && h == him.StringId, true);
            t.Expect("theElopementIsReportedDone", elope?.Status.ToString(), "Done");
            t.Expect("sheLeftHimMidway", her.Spouse == null && him.Spouse == null, true);
            t.Expect("sheRidesWithThePlayer", her.PartyBelongedTo == MobileParty.MainParty, true);

            b.DebugDailyTick();
            t.Expect("theTaleGoesOnAfterADay", b.ActiveRun?.QuestId == id && b.ActiveRun.Status == Logic.AuthoredQuests.AuthoredQuestStatus.Active, true);

            b.DebugChoose("give_back");
            CrTaleProgress end = ended.LastOrDefault();
            t.Expect("theEndingIsReported", end?.Where, "end:returned");
            t.Expect("theReturnIsReportedDone", end?.Consequences.FirstOrDefault(c => c.Type == "return_spouse")?.Status.ToString(), "Done");
            t.Expect("sheIsHisWifeAgain", her.Spouse == him && him.Spouse == her, true);
         }
         finally
         {
            CrTales.StageReached -= onReached;
            CrTales.Ended -= onEnded;
            b.Abandon("Self-test.");
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
            if (her.Spouse != him && her.Spouse == null && him.Spouse == null) TaleWorlds.CampaignSystem.Actions.MarriageAction.Apply(her, him, false);
            if (her.PartyBelongedTo == MobileParty.MainParty && him.Clan?.HomeSettlement != null)
               TaleWorlds.CampaignSystem.Actions.TeleportHeroAction.ApplyImmediateTeleportToSettlement(her, him.Clan.HomeSettlement);
            if (herClan != null && her.Clan != herClan) her.Clan = herClan;
            foreach (Logic.Grudges.Grudge g in ((IEnumerable<Logic.Grudges.Grudge>) Grudges.GrudgeBehavior.Instance?.GrudgesFor(him.StringId) ?? new List<Logic.Grudges.Grudge>()).Where(g => !grudgesBefore.Contains(g)).ToList())
               Grudges.GrudgeBehavior.Instance?.RemoveGrudge(g);
            Marriage.NpcMarriageEstrangementBehavior.Instance?.DebugClear(her.StringId);
         }

         return t.Line();
      }

