         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();

         const string json = @"{ ""id"": ""cr_selftest_husband"", ""title"": ""[SELFTEST] A Queen's Tale"",
           ""requires"": { ""giver"": { ""role"": ""lord"", ""gender"": ""female"", ""married"": true, ""not_clan_leader"": true, ""not_of_players_realm"": true, ""not_at_war_with_player"": false, ""min_regard"": -100 },
                           ""husband"": { ""role"": ""spouse_of_giver"" } },
           ""binds"": { ""giver"": ""a married lady"", ""husband"": ""her husband"" },
           ""stages"": [ { ""id"": ""ask"", ""journal"": ""[SELFTEST] {husband}"", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" },
             ""on_complete"": { ""next"": ""reward"" } } ], ""reward"": { ""regard"": 1 } }";
         try
         {
            t.Expect("theTaleLoads", b.DebugLoadTale(json, "selftest_husband.json").Count, 0);

            IFaction mine = Hero.MainHero?.MapFaction;
            Hero lady = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.IsFemale && !h.IsChild && h.Spouse != null && h.Spouse != Hero.MainHero
                                                               && Mapping.HeroPresence.IsInTheWorld(h) && Mapping.HeroPresence.IsInTheWorld(h.Spouse)
                                                               && h.Clan?.Leader != h && h.MapFaction != null && h.MapFaction != mine);
            if (t.Skip(lady == null, "no married lady of another realm who does not lead her house")) return t.Line();

            string why = b.DebugBind("cr_selftest_husband", lady, out Dictionary<string, string> ids);
            t.Note($"{lady.Name}, wife of {lady.Spouse.Name}: {(why ?? "bound")}");
            t.Expect("herHusbandIsBound", why == null && ids != null && ids.TryGetValue("husband", out string h) && h == lady.Spouse.StringId, true);

            Hero single = Hero.AllAliveHeroes.FirstOrDefault(x => x.IsLord && x.IsFemale && !x.IsChild && x.Spouse == null && Mapping.HeroPresence.IsInTheWorld(x)
                                                                 && x.Clan?.Leader != x && x.MapFaction != null && x.MapFaction != mine);
            if (single != null)
               t.Expect("anUnmarriedLadyIsRefused", (b.DebugBind("cr_selftest_husband", single, out _) ?? "").Contains("married"), true);
         }
         finally { b.DebugForgetTale("cr_selftest_husband"); }

         return t.Line();
      }

      private static string TestPromptProfile(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prompt_profile");
         if (t.Abort(behavior?.LlmServices?.ChatService?.PromptBuilder == null, "no prompt builder")) return t.Line();
         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && !h.IsChild && !h.IsPrisoner && h.Spouse != Hero.MainHero
                                                            && h.CompanionOf != Clan.PlayerClan && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(lord == null, "no free lord to build a prompt for")) return t.Line();

         string before = Mapping.PromptProfileService.AppliedId;
         string Build()
         {
            NpcProfile profile = behavior.Store.Get(lord.StringId) ?? Mapping.HeroProfileMapper.FromHero(lord);
            EncounterContext context = Mapping.EncounterContextBuilder.Build(lord, profile, behavior.GameStateBridge, null);
            return behavior.LlmServices.ChatService.PromptBuilder.BuildSystemPrompt(profile, new WorldState {CurrentDay = behavior.GameStateBridge.GetCurrentGameDay()}, context);
         }

         try
         {
            Mapping.PromptProfileService.DebugUse(null);
            string stock = Build();

            var everyFreeSectionOff = NpcMemoryService.Core.Prompts.PromptBuilder.CharacterSections
               .Where(s => s.Lock == NpcMemoryService.Core.Prompts.PromptSectionLock.None && s.Zone != NpcMemoryService.Core.Prompts.PromptZone.Marker)
               .Select(s => s.Key).ToList();
            var profileUsed = new PromptProfile {
               Id = "cr_selftest_profile", Name = "Self-test", Source = "Custom",
               Layouts = {[PromptKinds.Default] = new NpcMemoryService.Core.Prompts.PromptLayout {Off = everyFreeSectionOff, Source = "self-test"}},
               // Increment 3: a reworded required section reaches the prompt; a sealed one is never reworded.
               Sections = {
                  ["role_anchor"] = new NpcMemoryService.Core.Prompts.PromptSectionText {Text = "CR_SELFTEST_ROLE_ANCHOR {{char}}"},
                  ["format_instructions"] = new NpcMemoryService.Core.Prompts.PromptSectionText {Text = "CR_SELFTEST_SEALED"}
               }
            };
            Mapping.PromptProfileService.DebugUse(profileUsed);
            string custom = Build();

            t.Note($"{lord.Name}: stock {stock.Length} chars, every free section off {custom.Length} chars");
            t.Expect("theLayoutReachedTheRealPrompt", custom.Length < stock.Length, true);
            t.Expect("theSealedParserContractStays", custom.Contains("[DIALOGUE]"), true);
            t.Expect("aRewordedSectionReachesThePrompt", custom.Contains("CR_SELFTEST_ROLE_ANCHOR " + lord.Name), true);
            t.Expect("aSealedSectionIsNeverReworded", custom.Contains("CR_SELFTEST_SEALED"), false);
            t.Expect("theLogSaysACustomPromptIsActive", Mapping.PromptProfileService.ActiveLine().Contains("cr_selftest_profile"), true);
         }
         finally { Mapping.PromptProfileService.Refresh(); }

         t.Expect("thePlayersPickIsBack", Mapping.PromptProfileService.AppliedId, before);

         return t.Line();
      }

