      private static string TestEnvoyPacing(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("envoy_pacing");
         Letters.PrisonerEnvoyBehavior envoys = Letters.PrisonerEnvoyBehavior.Instance;
         if (t.Abort(envoys == null, "the envoy behaviour is not registered")) return t.Line();

         const string captive = "cr_selftest_envoy_captive", other = "cr_selftest_envoy_captive_2";
         const int taken = 1000;
         envoys.Forget(captive);
         envoys.Forget(other);
         try
         {
            envoys.RecordSent(captive, "lord_a", taken + 3);
            envoys.RecordCame(captive, taken);
            t.Expect("anotherLordWaitsAfterAnEnvoy", envoys.MayCome(captive, taken, "lord_b", taken + 4), false);
            t.Expect("anotherLordMayComeAfterTheSpacing", envoys.MayCome(captive, taken, "lord_b", taken + 3 + PrisonerExchangePolicy.CaptiveSpacingDays), true);
            // Gabriel (12/10/2026): fewer envoys whatever the prisoner.
            t.Expect("anotherPrisonerWaitsToo", envoys.MayCome(other, taken, "lord_c", taken + 4), false);
            t.Expect("anotherPrisonerAfterTheQuietDays", envoys.MayCome(other, taken, "lord_c", taken + 3 + PrisonerExchangePolicy.AnyCaptiveSpacingDays), true);

            for (int i = 1; i < PrisonerExchangePolicy.EnvoysBeforeGivingUp; i++) envoys.RecordCame(captive, taken);
            t.Expect("aNoIsANo", envoys.MayCome(captive, taken, "lord_b", taken + 400), false);
            t.Expect("aNewCaptivityStartsOver", envoys.MayCome(captive, taken + 300, "lord_b", taken + 400), true);
         }
         finally
         {
            envoys.Forget(captive);
            envoys.Forget(other);
         }

         return t.Line();
      }

      private static string TestRansomEnvoyQuest(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("ransom_envoy_quest");

         Hero man = null, giver = null;
         foreach (Hero h in Hero.AllAliveHeroes.Where(h => h.IsLord && h.IsPrisoner && h != Hero.MainHero && h.Clan?.Leader != null && h.Clan.Leader != h && h.Clan != Clan.PlayerClan))
         {
            int purse = RansomEnvoyPolicy.Advance(GameState.CourtActionResolver.RansomAnchor(h));
            if (!RansomEnvoyPolicy.MaySend(Quests.QuestFactory.EnvoyFacts(h, h.Clan.Leader, purse))) continue;

            man = h;
            giver = h.Clan.Leader;
            break;
         }

         if (t.Skip(man == null, "no captive lord held where the player is at peace, with a lord able to pay")) return t.Line();

         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.RansomEnvoy, TargetHero = man.Name.ToString()}, giver, (int) CampaignTime.Now.ToDays);
         if (t.Abort(quest == null, $"the factory refused an envoy for {man.Name} from {giver.Name}")) return t.Line();

         int expected = RansomEnvoyPolicy.Advance(GameState.CourtActionResolver.RansomAnchor(man));
         t.Note($"{giver.Name} sends the player to buy back {man.Name}, held by {man.PartyBelongedToAsPrisoner?.Name}; purse {quest.AdvanceGold}");
         t.Expect("boundToHisMan", quest.TargetHeroId, man.StringId);
         t.Expect("purseIsHalfAgainTheRansom", quest.AdvanceGold, expected);

         return t.Line();
      }

