      private static string TestGarrisonReinforcement(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("garrison_reinforcement");

         Hero holder = null;
         Settlement thin = null;
         foreach (Settlement place in Settlement.All.Where(st => (st?.IsTown == true || st?.IsCastle == true) && st.OwnerClan?.Leader != null && st.OwnerClan.Leader != Hero.MainHero))
         {
            thin = Quests.QuestFactory.ThinGarrisonsOf(place.OwnerClan.Leader).FirstOrDefault();
            if (thin == null) continue;

            holder = place.OwnerClan.Leader;
            break;
         }

         if (t.Skip(holder == null, "no held garrison is thin today")) return t.Line();

         PartyBase garrison = thin.Town.GarrisonParty.Party;
         int room = garrison.PartySizeLimit - garrison.NumberOfHealthyMembers;
         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.ReinforceGarrison, TargetSettlement = thin.Name.ToString(), RequiredCount = 500}, holder, (int) CampaignTime.Now.ToDays);
         if (t.Abort(quest == null, $"the factory refused men for {thin.Name} from {holder.Name}")) return t.Line();

         t.Note($"{holder.Name} asks for {quest.RequiredItemCount} men for {thin.Name} ({garrison.NumberOfHealthyMembers}/{garrison.PartySizeLimit})");
         t.Expect("boundToTheThinPlace", quest.TargetSettlement, thin.Name.ToString());
         t.Expect("withinTheBandAndTheRoom", quest.RequiredItemCount >= ReinforceGarrisonPolicy.MinTroops
                                           && quest.RequiredItemCount <= ReinforceGarrisonPolicy.MaxTroops && quest.RequiredItemCount <= room, true);

         return t.Line();
      }

      private static string TestTownNeedsSupply(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("town_needs_supply");

         Hero holder = null;
         (Settlement Place, MarketReading Good)? need = null;
         foreach (Settlement town in Settlement.All.Where(st => st?.IsTown == true && st.OwnerClan?.Leader != null && st.OwnerClan.Leader != Hero.MainHero))
         {
            need = Mapping.TownNeeds.MostLackingFor(town.OwnerClan.Leader);
            if (need == null) continue;

            holder = town.OwnerClan.Leader;
            break;
         }

         if (t.Skip(holder == null, "no held town lacks anything at its market today")) return t.Line();

         string name = need.Value.Good.Name;
         t.Note($"{need.Value.Place.Name} lacks {name} (price x{need.Value.Good.PriceFactor:0.0}); asked by {holder.Name}");

         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.ProvideGoods, Category = name, RequiredCount = 10}, holder, (int) CampaignTime.Now.ToDays);
         if (t.Abort(quest == null, $"the factory refused a supply of {name} for {holder.Name}")) return t.Line();

         t.Expect("keyedToTheLackingGood", quest.RequiredItemCategory, ProvideGoodsPolicy.MarketKey(need.Value.Good.CategoryId));

         ItemObject item = TaleWorlds.CampaignSystem.Extensions.Items.All.FirstOrDefault(i => i?.ItemCategory?.StringId == need.Value.Good.CategoryId);
         if (item != null) t.Expect("anItemOfThatGoodCounts", CalradiaRemembers.Items.SupplyItemMatcher.Matches(item, quest.RequiredItemCategory), true);
         t.Expect("deliveredToThatTownsMarket", Mapping.TownNeeds.MarketFor(holder, need.Value.Good.CategoryId) == need.Value.Place, true);

         return t.Line();
      }

      private static string TestPleadCaseQuest(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("plead_case_quest");

         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan);
         Hero before = giver == null ? null
            : Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != giver.Clan);
         if (t.Skip(giver == null || before == null, "no lord pair to give and hear the plea")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.PleadCase, TargetHero = before.Name.ToString()}, giver, today);
         if (t.Abort(quest == null, $"the factory refused a plea before {before.Name} for {giver.Name}")) return t.Line();
         t.Note($"{giver.Name} asks the player to plead his case before {quest.TargetHeroName}");
         t.Expect("boundToThePersonToPersuade", quest.TargetHeroId, before.StringId);

         NpcProfile giverProfile = GetOrCreate(behavior, giver);
         giverProfile.ActiveQuests.Add(quest);
         behavior.Store.Set(giverProfile);
         try
         {
            int against = Quests.QuestDeedTracker.CreditPlea(new SwayFacts {PersuadedId = before.StringId, AboutId = giver.StringId, Warmer = false});
            int elsewhere = Quests.QuestDeedTracker.CreditPlea(new SwayFacts {PersuadedId = before.StringId, AboutId = Hero.MainHero.StringId, Warmer = true});
            t.Expect("aSwayAgainstOrAboutAnotherDoesNotAnswer", against == 0 && elsewhere == 0 && quest.SatisfiedOnDay == null, true);

            int won = Quests.QuestDeedTracker.CreditPlea(new SwayFacts {PersuadedId = before.StringId, AboutId = giver.StringId, Warmer = true});
            t.Expect("wonOverTowardTheGiverAnswersIt", won >= 1 && quest.SatisfiedOnDay == today, true);
         }
         finally
         {
            giverProfile.ActiveQuests.Remove(quest);
            behavior.Store.Set(giverProfile);
         }

         return t.Line();
      }

      private static string TestEarnRegardQuest(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("earn_regard_quest");

         Hero giver = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan);
         Hero target = giver == null ? null
            : Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != giver.Clan
                                                     && Quests.QuestFactory.RegardFor(h) < EarnRegardPolicy.NothingLeftToWin);
         if (t.Skip(giver == null || target == null, "no lord pair to give and receive the task")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         InformalQuest quest = Quests.QuestFactory.Create(new QuestProposal {Type = QuestType.EarnRegard, TargetHero = target.Name.ToString(), DeadlineDays = 5}, giver, today);
         if (t.Abort(quest == null, $"the factory refused to bind {target.Name} for {giver.Name}")) return t.Line();

         int baseline = Quests.QuestFactory.RegardFor(target);
         t.Note($"{giver.Name} asks the player to win over {quest.TargetHeroName}: regard {quest.RegardBaseline} -> {quest.RegardGoal}, deadline {quest.DeadlineDay - today} days");
         t.Expect("boundToTheTarget", quest.TargetHeroId, target.StringId);
         t.Expect("baselineIsTheirRegardNow", quest.RegardBaseline, baseline);
         t.Expect("goalIsTenBeyond", quest.RegardGoal, baseline + EarnRegardPolicy.RequiredGain);
         t.Expect("aShortDeadlineIsLengthened", quest.DeadlineDay - today, EarnRegardPolicy.MinimumDays);

         NpcProfile giverProfile = GetOrCreate(behavior, giver);
         giverProfile.ActiveQuests.Add(quest);
         behavior.Store.Set(giverProfile);
         try
         {
            int shortOf = Quests.QuestDeedTracker.CreditRegard(target.StringId, quest.RegardGoal.Value - 1);
            t.Expect("onePointShortDoesNotComplete", shortOf == 0 && quest.SatisfiedOnDay == null, true);

            int reached = Quests.QuestDeedTracker.CreditRegard(target.StringId, quest.RegardGoal.Value);
            t.Expect("theGoalCompletesIt", reached >= 1 && quest.SatisfiedOnDay == today, true);
         }
         finally
         {
            giverProfile.ActiveQuests.Remove(quest);
            behavior.Store.Set(giverProfile);
         }

         return t.Line();
      }

