      /// <summary>
      ///   Every MCM hint fits on the screen. This is a shipped bug with a receipt: v2.5.6 fixed NINETEEN hints
      ///   that ran off the edge, and the reason it hurt is that they are written "On (default): ... Off: ...",
      ///   so the half that got clipped was always the one explaining the other position. They were repaired by
      ///   hand and nothing was left to stop the twentieth doing it again - which matters now, because
      ///   2026-09-12 added the twentieth.
      ///   <para>
      ///     Reads the ATTRIBUTES rather than the live settings object, so it holds whether or not MCM has
      ///     loaded, and so a hint is checked as it was WRITTEN rather than as it happened to render here.
      ///   </para>
      /// </summary>
      private static string TestSpawnAgentSignature(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("spawn_agent_signature");

         MethodInfo method = Duels.MissionSpawn.Method;
         t.Note(method == null ? "none found" : $"{method.Name}({string.Join(", ", method.GetParameters().Select(p => p.ParameterType.Name))})");
         t.Expect("aDuelFighterCanBeSpawnedOnThisGameVersion", method != null, true);

         return t.Line();
      }

      private static string TestSettingHintsFit(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("setting_hints_fit");

         var toolong = new List<string>();
         var empty = new List<string>();
         var checkedCount = 0;

         foreach (PropertyInfo declared in typeof(CrSettings).GetProperties(BindingFlags.Public | BindingFlags.Instance))
         foreach (CustomAttributeData attribute in declared.GetCustomAttributesData())
         {
            string hint = ReadHintText(attribute);
            if (hint == null) continue;

            checkedCount++;

            if (hint.Trim().Length == 0) empty.Add(declared.Name);
            else if (hint.Length > MaxHintChars) toolong.Add($"{declared.Name}={hint.Length}");
         }

         if (t.Skip(checkedCount == 0, "no setting declares a hint, so there is nothing to measure")) return t.Line();

         t.Note($"{checkedCount} hint(s) measured against {MaxHintChars} chars");
         t.Expect("everyHintFitsOnTheScreen", toolong.Count == 0 ? "" : string.Join(", ", toolong), "");
         t.Expect("noSettingIsLeftWithoutItsExplanation", empty.Count == 0 ? "" : string.Join(", ", empty), "");

         return t.Line();
      }

      /// <summary>
      ///   The MCM Test buttons call CrSettings.ConnectionTest and its two siblings, which the submodule sets at load
      ///   (the settings live in Foundation and cannot name Services' tester). Unset, a button would do nothing.
      /// </summary>
      private static string TestTaleArc(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_arc");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null || Hero.MainHero == null || behavior?.Store == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, $"a tale is under way ('{b.ActiveRun?.QuestId}')")) return t.Line();
         if (t.Skip(behavior.LlmServices?.ChatService?.PromptBuilder == null, "no prompt builder")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Spouse != Hero.MainHero && !h.IsPrisoner
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness) && h.Clan != Clan.PlayerClan);
         if (t.Skip(lord == null, "no free lord to play the tale with")) return t.Line();

         const string id = "cr_selftest_arc";
         const string json = @"{ ""id"": ""cr_selftest_arc"", ""title"": ""[SELFTEST] An Arc"", ""unique"": false,
           ""requires"": { ""giver"": { ""role"": ""lord"", ""min_regard"": -100, ""not_at_war_with_player"": false } },
           ""on_scenario"": { ""invitation"": ""[SELFTEST] {giver} asks to see you."" },
           ""binds"": { ""giver"": ""a lord"" },
           ""stages"": [
             { ""id"": ""talk"", ""journal"": ""[SELFTEST] The talk."",
               ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"", ""when"": ""closed"",
                 ""arc"": { ""beats"": [
                   { ""id"": ""first"", ""exchanges"": 2, ""do"": ""[SELFTEST] the first beat"" },
                   { ""id"": ""last"", ""exchanges"": 1, ""lead"": ""player"", ""do"": ""[SELFTEST] the last beat"" } ] } },
               ""canvas"": ""[SELFTEST] the talk"", ""on_complete"": { ""next"": ""end:done"" } } ],
           ""endings"": { ""done"": { } } }";

         string Prompt()
         {
            NpcProfile profile = behavior.Store.Get(lord.StringId) ?? Mapping.HeroProfileMapper.FromHero(lord);
            EncounterContext context = Mapping.EncounterContextBuilder.Build(lord, profile, behavior.GameStateBridge, null);
            return behavior.LlmServices.ChatService.PromptBuilder.BuildSystemPrompt(profile, new WorldState {CurrentDay = behavior.GameStateBridge.GetCurrentGameDay()}, context);
         }

         try
         {
            t.Expect("theTaleLoads", string.Join(" | ", b.DebugLoadTale(json, "selftest_arc.json")), "");
            b.ForgetPlayed(id);
            t.Expect("itOpens", b.DebugOpenFromScenario(id, lord), null);
            b.DebugConversationOpened(lord);
            t.Expect("itWaitsForTheClose", b.ActiveRun?.StageId, "talk");

            string first = Prompt();
            t.Expect("theFirstBeatIsInHerPrompt", first.Contains("[SELFTEST] the first beat"), true);
            t.Expect("andNotTheNext", first.Contains("[SELFTEST] the last beat"), false);

            t.Expect("theFirstExchangeDoesNotClose", b.ArcExchanged(lord), false);
            t.Expect("norTheSecond", b.ArcExchanged(lord), false);
            string last = Prompt();
            t.Expect("theLastBeatIsInHerPrompt", last.Contains("[SELFTEST] the last beat"), true);
            t.Expect("andSheIsToldItIsHerLastReply", last.Contains("LAST reply of the scene"), true);
            t.Expect("theThirdExchangeClosesTheArc", b.ArcExchanged(lord), true);

            b.DebugConversationEnded(lord);
            t.Expect("theCloseCompletesTheStage", $"{b.ActiveRun?.Status}/{b.ActiveRun?.EndingId}", "Completed/done");

            // The signals, through the same bridge an LLM report takes.
            t.Expect("theSignalTaleLoads", string.Join(" | ", b.DebugLoadTale(SignalJson, "selftest_arc_signal.json")), "");
            ActionOutcome Signal(string sid) => behavior.GameStateBridge.ExecuteAction(new GameAction {
               Type = Logic.AuthoredQuests.TaleArc.SignalVerb, Parameters = new Dictionary<string, string> {["signal"] = sid}
            }, lord, null);

            b.ForgetPlayed(SignalTaleId);
            t.Expect("theSignalTaleOpens", b.DebugOpenFromScenario(SignalTaleId, lord), null);
            b.DebugConversationOpened(lord);
            t.Expect("aSignalTheArcDoesNotWatchIsRefused", Signal("cr_selftest_unknown") is {IsPositive: true}, false);
            t.Expect("theWatchedSignalIsTaken", Signal("cr_selftest_seen") is {IsPositive: true}, true);
            t.Expect("andSetsItsFlag", b.ActiveRun?.Flags.Contains("cr_selftest_seen") == true, true);
            b.ArcExchanged(lord, () => 0.99);
            b.ArcExchanged(lord, () => 0.99);
            b.ArcExchanged(lord, () => 0.99);
            t.Expect("theTransitionFollowsTheFlag", b.ActiveRun?.ArcBeatId, "last");
            b.DebugConversationEnded(lord);

            b.ForgetPlayed(SignalTaleId);
            t.Expect("itOpensAgain", b.DebugOpenFromScenario(SignalTaleId, lord), null);
            b.DebugConversationOpened(lord);
            b.ArcExchanged(lord, () => 0.0);
            b.ArcExchanged(lord, () => 0.0);
            t.Expect("theNetDecidesIt", b.ActiveRun?.Flags.Contains("cr_selftest_seen") == true, true);
            t.Expect("andSheIsToldToNarrateIt", Prompt().Contains("The game has decided that this happens"), true);
            b.DebugConversationEnded(lord);
         }
         finally
         {
            if (b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}) b.Abandon("Self-test.");
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
            b.ForgetPlayed(SignalTaleId);
            b.DebugForgetTale(SignalTaleId);
         }

         return t.Line();
      }

      private const string SignalTaleId = "cr_selftest_arc_signal";

      // first (2 exchanges, watching) -> mid (1, watching; on to last only if the signal was seen, else back to first) -> last.
      private const string SignalJson = @"{ ""id"": ""cr_selftest_arc_signal"", ""title"": ""[SELFTEST] An Arc That Turns"", ""unique"": false,
           ""requires"": { ""giver"": { ""role"": ""lord"", ""min_regard"": -100, ""not_at_war_with_player"": false } },
           ""on_scenario"": { ""invitation"": ""[SELFTEST] {giver} asks to see you."" },
           ""binds"": { ""giver"": ""a lord"" },
           ""stages"": [
             { ""id"": ""talk"", ""journal"": ""[SELFTEST] The talk."",
               ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"", ""when"": ""closed"",
                 ""arc"": { ""max_exchanges"": 10,
                   ""signals"": [ { ""id"": ""cr_selftest_seen"", ""means"": ""[SELFTEST] something happens"", ""net"": { ""after"": 1, ""chance"": 0.5 } } ],
                   ""beats"": [
                     { ""id"": ""first"", ""exchanges"": 2, ""listens"": ""cr_selftest_seen"", ""do"": ""[SELFTEST] the first beat"" },
                     { ""id"": ""mid"", ""exchanges"": 1, ""listens"": ""cr_selftest_seen"", ""do"": ""[SELFTEST] the middle beat"",
                       ""next"": [ { ""if"": ""cr_selftest_seen"", ""to"": ""last"" }, { ""to"": ""first"" } ] },
                     { ""id"": ""last"", ""exchanges"": 1, ""do"": ""[SELFTEST] the last beat"" } ] } },
               ""canvas"": ""[SELFTEST] the talk"", ""on_complete"": { ""next"": ""end:done"" } } ],
           ""endings"": { ""done"": { } } }";

      private static string TestTaleInterrupted(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_interrupted");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null || Hero.MainHero == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active} || b.PausedRun != null,
                $"a tale is under way or set aside ('{b.ActiveRun?.QuestId ?? b.PausedRun?.QuestId}')")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Spouse != Hero.MainHero && !h.IsPrisoner
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness) && h.Clan != Clan.PlayerClan);
         if (t.Skip(lord == null, "no free lord to play the tales with")) return t.Line();

         const string trail = "cr_selftest_trail", night = "cr_selftest_interruption";
         string Tale(string id, string title) => @"{ ""id"": ""@@ID@@"", ""title"": ""[SELFTEST] @@TITLE@@"", ""unique"": false,
           ""requires"": { ""giver"": { ""role"": ""lord"", ""min_regard"": -100, ""not_at_war_with_player"": false } },
           ""on_scenario"": { },
           ""binds"": { ""giver"": ""a lord"" },
           ""failure"": { ""days"": 40 },
           ""stages"": [
             { ""id"": ""asked"", ""journal"": ""[SELFTEST] Asked."", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" }, ""on_complete"": { ""next"": ""waiting"" } },
             { ""id"": ""waiting"", ""journal"": ""[SELFTEST] Waiting."", ""objective"": { ""type"": ""wait"", ""days"": 30 }, ""on_complete"": { ""next"": ""end:done"" } } ],
           ""endings"": { ""done"": { } } }".Replace("@@ID@@", id).Replace("@@TITLE@@", title);

         try
         {
            t.Expect("theTalesLoad", string.Join(" | ", b.DebugLoadTale(Tale(trail, "The Trail"), "selftest_trail.json").Concat(b.DebugLoadTale(Tale(night, "The Interruption"), "selftest_interruption.json"))), "");
            b.ForgetPlayed(trail);
            b.ForgetPlayed(night);

            t.Expect("theFirstOpens", b.DebugOpenFromScenario(trail, lord), null);
            t.Expect("theSecondOpensOverIt", b.DebugOpenFromScenario(night, lord), null);
            t.Expect("theFirstWaits", b.PausedRun?.QuestId, trail);
            t.Expect("theSecondPlays", b.ActiveRun?.QuestId, night);
            b.DebugReconcileJournal();
            t.Expect("theWaitingEntryStaysOpen", b.DebugJournalOpen(trail), true);
            t.Expect("aThirdSummonsIsRefused", b.OpenFromScenario(night, lord, dryRun: true) != null, true);

            Logic.AuthoredQuests.AuthoredQuestRun waiting = b.PausedRun;
            int startDay = waiting?.StartDay ?? 0;
            if (waiting != null) waiting.PausedOnDay -= 5; // as if it had waited five days

            b.Abandon("Self-test: the interruption is over.");
            b.DebugResume(playerFree: false);
            t.Expect("itStaysAsideWhileThePlayerIsHeld", b.PausedRun?.QuestId, trail);
            b.DebugResume(playerFree: true);
            t.Expect("itIsTakenUpOnceFree", $"{b.ActiveRun?.QuestId}/{b.ActiveRun?.StageId}", trail + "/waiting");
            t.Expect("nothingWaitsAnyMore", b.PausedRun == null, true);
            t.Expect("theDaysItWaitedDoNotCount", b.ActiveRun?.StartDay, startDay + 5);
            t.Expect("itsEntryIsStillOpen", b.DebugJournalOpen(trail), true);
         }
         finally
         {
            if (b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}) b.Abandon("Self-test.");
            if (b.PausedRun != null) b.Abandon("Self-test.");
            b.ForgetPlayed(trail);
            b.DebugForgetTale(trail);
            b.ForgetPlayed(night);
            b.DebugForgetTale(night);
         }

         return t.Line();
      }

      private static string TestTaleOpenedByScenario(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_opened_by_scenario");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null || Hero.MainHero == null || behavior?.Store == null, "authored quests are not active")) return t.Line();
         if (t.Skip(b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}, $"a tale is under way ('{b.ActiveRun?.QuestId}')")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Spouse != Hero.MainHero && !h.IsPrisoner
                                                            && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness) && h.Clan != Clan.PlayerClan);
         if (t.Skip(lord == null, "no free lord to play the tale with")) return t.Line();

         const string id = "cr_selftest_night";
         const string json = @"{ ""id"": ""cr_selftest_night"", ""title"": ""[SELFTEST] A Summons by Night"", ""unique"": false,
           ""requires"": { ""giver"": { ""role"": ""lord"", ""min_regard"": -100, ""not_at_war_with_player"": false } },
           ""on_scenario"": { ""invitation"": ""[SELFTEST] {giver} asks to see you."", ""decline_ending"": ""refused"" },
           ""binds"": { ""giver"": ""a lord"" },
           ""stages"": [
             { ""id"": ""summoned"", ""journal"": ""[SELFTEST] {giver} sent for you."", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" },
               ""on_complete"": { ""next"": ""chamber"" } },
             { ""id"": ""chamber"", ""journal"": ""[SELFTEST] The night."", ""image_pool"": [ ""night_{giver_realm}_a.crvid"", ""night_{giver_realm}_b.crvid"" ],
               ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"", ""when"": ""closed"" }, ""canvas"": ""[SELFTEST] the chamber at night"",
               ""on_complete"": { ""next"": ""end:dawn"" } } ],
           ""endings"": { ""dawn"": { ""consequences"": [
             { ""type"": ""memory"", ""who"": ""{giver}"", ""text"": ""[SELFTEST] warm night"", ""if"": ""regard_rose"" },
             { ""type"": ""regard"", ""amount"": 5, ""if"": ""regard_rose"" },
             { ""type"": ""memory"", ""who"": ""{giver}"", ""text"": ""[SELFTEST] cold night"", ""if"": [ ""!regard_rose"", ""!regard_fell"" ] },
             { ""type"": ""memory"", ""who"": ""{giver}"", ""text"": ""[SELFTEST] bad night"", ""if"": ""regard_fell"" } ] },
             ""refused"": { ""regard"": -2, ""memory"": ""[SELFTEST] refused"" } } }";

         NpcProfile existing = behavior.Store.Get(lord.StringId);
         bool hadProfile = existing != null;
         int regardBefore = existing?.ReputationWithPlayer ?? 0;
         try
         {
            t.Expect("theTaleLoads", string.Join(" | ", b.DebugLoadTale(json, "selftest_night.json")), "");
            b.ForgetPlayed(id);

            var nobody = new Scenarios.ScenarioContext();
            t.Expect("openTaleCanApply", Scenarios.ScenarioConsequenceExecutor.CanApply(Logic.KeywordToken.Parse("OPEN_TALE:" + id + "," + lord.StringId), nobody), true);
            t.Expect("chanceOfOneHolds", Scenarios.ScenarioGuardResolver.Resolve(Logic.KeywordToken.Parse("IF_CHANCE:1"), nobody), true);
            t.Expect("chanceOfZeroNeverHolds", Scenarios.ScenarioGuardResolver.Resolve(Logic.KeywordToken.Parse("IF_CHANCE:0"), nobody), false);
            if (!Hero.MainHero.IsPrisoner)
               t.Expect("aFreePlayerHasNoCaptor", Scenarios.ScenarioGuardResolver.Resolve(Logic.KeywordToken.Parse("IF_CAPTOR_IS:" + lord.StringId), nobody), false);

            Hero offering = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Issue != null && !h.IsPrisoner
                                                                   && h.Clan != Clan.PlayerClan);
            if (offering != null) t.Expect("anErrandOnOfferDoesNotBarTheSummons", b.OpenFromScenario(id, offering, dryRun: true), null);
            Hero busy = Campaign.Current.QuestManager.Quests.Where(x => x != null && x.IsOngoing && x is not Quests.AuthoredStoryQuest).Select(x => x.QuestGiver)
                                .FirstOrDefault(h => h != null && h.IsLord && !h.IsChild && h != Hero.MainHero && !h.IsPrisoner && h.Clan != Clan.PlayerClan);
            if (busy != null) t.Expect("aQuestOfTheirsUnderWayDoesNotBarTheSummons", b.OpenFromScenario(id, busy, dryRun: true), null);

            t.Expect("itOpens", b.DebugOpenFromScenario(id, lord), null);
            Logic.AuthoredQuests.AuthoredQuestRun run = b.ActiveRun;
            t.Expect("theStartIsNoted", run?.GiverRegardAtStart, regardBefore);
            t.Expect("itWaitsInTheChamber", run?.StageId, "chamber");
            string picked = run != null && run.ImagePicks.TryGetValue("chamber", out string p) ? p : null;
            t.Note($"{lord.Name}: regard {regardBefore}, picture {picked ?? "(none)"}");
            t.Expect("aVideoOfThePoolIsChosen", picked != null && picked.StartsWith("night_{giver_realm}_"), true);

            b.DebugConversationOpened(lord);
            t.Expect("theOpeningDoesNotEndTheNight", b.ActiveRun?.StageId, "chamber");
            t.Expect("sheIsToldTheScene", b.PromptBlockFor(lord)?.Contains("[SELFTEST] the chamber at night") == true, true);

            NpcProfile profile = behavior.Store.Get(lord.StringId) ?? Mapping.HeroProfileMapper.FromHero(lord);
            ProfileMutator.ApplyReputationDelta(profile, 4, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
            behavior.Store.Set(profile);
            b.DebugConversationEnded(lord);

            NpcProfile after = behavior.Store.Get(lord.StringId);
            t.Expect("theCloseEndsIt", run?.Status, Logic.AuthoredQuests.AuthoredQuestStatus.Completed);
            t.Expect("theRegardRose", run?.Flags?.Contains(Logic.AuthoredQuests.TaleRegardFlags.Rose) == true, true);
            t.Expect("theWarmMemoryAlone", string.Join(" | ", after?.Events.Where(e => e.summary != null && e.summary.Contains("[SELFTEST]")).Select(e => e.summary) ?? new string[0]), "[SELFTEST] warm night");
            t.Expect("theRewardIsPaid", (after?.ReputationWithPlayer ?? 0) - regardBefore, 9);

            // Gabriel (25/10/2026): the player who will not follow the lady ends the tale, and she is disappointed.
            b.ForgetPlayed(id);
            int beforeNo = behavior.Store.Get(lord.StringId)?.ReputationWithPlayer ?? 0;
            t.Expect("aNoCanBeSaid", b.DebugDeclineFromScenario(id, lord), null);
            NpcProfile refused = behavior.Store.Get(lord.StringId);
            t.Expect("theNoEndsTheTale", b.ActiveRun?.EndingId, "refused");
            t.Expect("sheIsDisappointed", (refused?.ReputationWithPlayer ?? 0) - beforeNo, -2);
            t.Expect("andRemembersIt", refused?.Events.Any(e => e.summary == "[SELFTEST] refused") == true, true);
            t.Expect("theSecondPlayingKnowsTheFirst", b.ActiveRun?.Flags?.Contains(Logic.AuthoredQuests.TaleHistory.PlayedBefore) == true
                                                        && b.ActiveRun.Flags.Any(f => f.StartsWith(Logic.AuthoredQuests.TaleHistory.EndedBeforePrefix)), true);
         }
         finally
         {
            if (b.ActiveRun is {Status: Logic.AuthoredQuests.AuthoredQuestStatus.Active}) b.Abandon("Self-test.");
            NpcProfile profile = behavior.Store.Get(lord.StringId);
            if (profile != null)
            {
               profile.Events.RemoveAll(e => e.summary != null && e.summary.Contains("[SELFTEST]"));
               ProfileMutator.ApplyReputationDelta(profile, regardBefore - profile.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
               if (hadProfile) behavior.Store.Set(profile);
               else behavior.Store.Remove(lord.StringId);
            }

            b.DebugForgetPools(id);
            b.DebugForgetHistory(id);
            b.ForgetPlayed(id);
            b.DebugForgetTale(id);
         }

         return t.Line();
      }

      private static string TestTaleKeys(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_keys");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null || Hero.MainHero == null, "authored quests are not active")) return t.Line();

         bool Free(Hero h) => h != null && Mapping.ActionGate.Allows(h, Logic.ActionKind.Witness);
         Hero merchant = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && h.Occupation == Occupation.Merchant && h.HomeSettlement?.IsTown == true
                                                                && !h.HomeSettlement.IsUnderSiege && Free(h)
                                                                && (h.MapFaction == null || Hero.MainHero.MapFaction == null || !FactionManager.IsAtWarAgainstFaction(h.MapFaction, Hero.MainHero.MapFaction)));
         Hero headman = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && h.Occupation == Occupation.Headman && Free(h));
         if (t.Skip(merchant == null, "no free town merchant at peace with the player")) return t.Line();
         t.Note($"{merchant.Name} of {merchant.HomeSettlement.Name}");

         string sex = Hero.MainHero.IsFemale ? "female" : "male", other = Hero.MainHero.IsFemale ? "male" : "female";
         const string id = "cr_selftest_tale_keys", twinId = "cr_selftest_tale_keys_twin";
         string Tale(string taleId, string playerSex) => @"{ ""id"": """ + taleId + @""", ""title"": ""[SELFTEST] The Merchant's Debt"",
            ""requires"": { ""giver"": { ""role"": ""notable"", ""trade"": ""merchant"", ""min_regard"": -100, ""not_at_war_with_player"": false },
                          ""village"": { ""type"": ""town"" }, ""player"": { ""gender"": """ + playerSex + @""" } },
            ""binds"": { ""giver"": ""a merchant"", ""village"": ""a town"" },
            ""stages"": [ { ""id"": ""ask"", ""journal"": ""[SELFTEST]"", ""objective"": { ""type"": ""talk_to"", ""hero"": ""{giver}"" }, ""on_complete"": { ""next"": ""reward"" } } ],
            ""reward"": { ""gold"": -1 } }";
         t.Expect("theTaleLoadsClean", string.Join(" | ", b.DebugLoadTale(Tale(id, sex), "selftest.json")), "");
         t.Expect("itsTwinLoadsClean", string.Join(" | ", b.DebugLoadTale(Tale(twinId, other), "selftest.json")), "");
         try
         {
            // The place is read off the binding itself: the offer can be "not now" for a reason of the world's (the merchant
            // has a vanilla task of his own), which prints no bound place and failed this on Gabriel's save (20/10/2026).
            t.Note(b.DebugEligibility(merchant, id) ?? "");
            string bindWhy = b.DebugBind(id, merchant, out Dictionary<string, string> ids);
            t.Expect("aTownMerchantBinds", bindWhy ?? "binds", "binds");
            t.Expect("withTheTownAsItsPlace", ids != null && ids.TryGetValue("village", out string place) && place == merchant.HomeSettlement.StringId, true);
            if (headman != null)
            {
               string no = b.DebugEligibility(headman, id) ?? "";
               t.Expect("aHeadmanIsRefusedForTheTrade", no.StartsWith("no:") && no.Contains("merchant"), true);
            }
            string twin = b.DebugEligibility(merchant, twinId) ?? "";
            t.Expect("theOtherSexIsRefused", twin.StartsWith("no:") && twin.Contains("told to"), true);

            if (Hero.MainHero.Gold >= 1)
            {
               int player = Hero.MainHero.Gold, his = merchant.Gold;
               Quests.AuthoredQuestBehavior.DebugPayGold(-1, merchant);
               t.Expect("thePlayerPaysTheGiver", (Hero.MainHero.Gold, merchant.Gold), (player - 1, his + 1));
               TaleWorlds.CampaignSystem.Actions.GiveGoldAction.ApplyBetweenCharacters(merchant, Hero.MainHero, 1, disableNotification: true);
            }
         }
         finally
         {
            b.DebugForgetTale(id);
            b.DebugForgetTale(twinId);
         }

         return t.Line();
      }

      private static string TestTaleLocalsMemory(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tale_locals_memory");

         Quests.AuthoredQuestBehavior b = Quests.AuthoredQuestBehavior.Instance;
         if (t.Skip(b == null, "authored quests are not active")) return t.Line();

         // A village with two notables or more, so the others can be seen still hearing it; one will do otherwise.
         Settlement village = Settlement.All.Where(s => s.IsVillage && s.Notables?.Count(n => n != null) > 0)
            .OrderByDescending(s => s.Notables.Count(n => n != null)).FirstOrDefault();
         if (t.Skip(village == null, "no village has a notable")) return t.Line();
         Hero giver = village.Notables.First(n => n != null);
         t.Note($"{giver.Name} of {village.Name}, {village.Notables.Count(n => n != null)} notable(s)");

         (List<string> giverMemory, List<string> locals) = b.DebugEndingMemoryRecipients(giver, village);
         t.Expect("theGiverHasHisOwnMemory", giverMemory.Contains(giver.StringId), true);
         t.Expect("theGiverIsLeftOutOfTheLocals", locals.Contains(giver.StringId), false);
         t.Expect("theOtherNotablesStillHearIt", locals.Count, village.Notables.Count(n => n != null && n != giver));

         return t.Line();
      }

      private static string TestMemoryPanelSecrets(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("memory_panel_secrets");

         var store = behavior?.Store;
         if (t.Abort(store == null, "no profile store")) return t.Line();
         if (t.Skip(CrSettings.Instance == null, "the mod options are not loaded")) return t.Line();

         NpcProfile profile = store.ListIds().Select(store.Get)
                                   .FirstOrDefault(p => p != null && Hero.FindFirst(h => h.StringId == p.Id) is {IsAlive: true} h && h != Hero.MainHero);
         if (t.Skip(profile == null, "no met character to remember anything")) return t.Line();

         const string secret = "(self-test) A secret fondness.", open = "(self-test) A tale's ending.", briefing = "(self-test) The player drew me aside.";
         bool keep = CrSettings.Instance.ShowSecretMemories;
         try
         {
            CrNpcMemory.AddMemory(new CrMemoryEntry {NpcId = profile.Id, Summary = secret, Private = true, SourceMod = "cr.test all"});
            CrNpcMemory.AddMemory(new CrMemoryEntry {NpcId = profile.Id, Summary = open, SourceMod = "cr.test all"});
            CrNpcMemory.AddMemory(new CrMemoryEntry {NpcId = profile.Id, Summary = briefing, Private = true, SourceMod = Logic.Chat.MemoryPanelPolicy.OwnSource});
            const string unnamed = "(self-test) A secret with no source.";
            CrNpcMemory.AddMemory(new CrMemoryEntry {NpcId = profile.Id, Summary = unnamed, Private = true});
            NpcProfile after = store.Get(profile.Id);
            NotableEvent Find(string s) => after.Events.LastOrDefault(e => e.summary == s);
            if (t.Abort(Find(secret) == null || Find(open) == null || Find(briefing) == null, "the memories were not stored")) return t.Line();

            CrSettings.Instance.ShowSecretMemories = false;
            t.Expect("anotherModsSecretIsLeftOut", Chat.ChatViewModel.PanelShow(Find(secret)), Logic.Chat.MemoryPanelShow.Hidden);
            t.Expect("anOpenMemoryIsListed", Chat.ChatViewModel.PanelShow(Find(open)), Logic.Chat.MemoryPanelShow.Plain);
            t.Expect("thePlayersOwnPrivateWordIsListed", Chat.ChatViewModel.PanelShow(Find(briefing)), Logic.Chat.MemoryPanelShow.Plain);
            // A mod that names no source still keeps its secret out of the panel, and may still take it back.
            t.Expect("aSecretWithNoSourceIsLeftOut", Find(unnamed) == null ? (Logic.Chat.MemoryPanelShow?) null : Chat.ChatViewModel.PanelShow(Find(unnamed)), Logic.Chat.MemoryPanelShow.Hidden);
            t.Expect("andItsModMayStillTakeItBack", CrNpcMemory.RemoveMemory(new CrMemoryRemoval {NpcId = profile.Id, Summary = unnamed}), 1);
            CrSettings.Instance.ShowSecretMemories = true;
            t.Expect("askedForTheSecretIsMarked", Chat.ChatViewModel.PanelShow(Find(secret)), Logic.Chat.MemoryPanelShow.MarkedSecret);
         }
         finally
         {
            CrSettings.Instance.ShowSecretMemories = keep;
            NpcProfile current = store.Get(profile.Id);
            current?.Events.RemoveAll(e => e.summary != null && e.summary.StartsWith("(self-test) ", StringComparison.Ordinal));
            if (current != null) store.Set(current);
         }

         return t.Line();
      }

      // Gabriel (20/10/2026): "le testall peut creer des heart et des traumatismes permanents sur les NPC et le joueur car c'est une
      // sauvegarde de test." The victim is a companion of the player's (reused, or minted into the party) and what is recorded
      // stays, so the page can be opened in the encyclopedia afterwards. Only the MCM adult level, which is not the save's, is
      // put back.
      // A stranger to an event is no kin of its actors: kin know it whatever the realm or house (LongTermHistoryPolicy.WouldKnow),
      // and a daughter married into another realm stays a daughter (authored_history picked one on Gabriel's test save, 20/10/2026).
      private static bool IsKinOf(Hero h, Hero of)
         => h == of || h.Spouse == of || h.Father == of || h.Mother == of || of.Father == h || of.Mother == h || of.Siblings.Contains(h);

      private static string TestTraumaPage(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("trauma_page");
         if (t.Abort(CrSettings.Instance == null || Hero.MainHero == null, "the MCM settings are not loaded")) return t.Line();

         Hero captor = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && !h.IsChild);
         Hero victim = ArrangedCompanion.Get(behavior)?.Companion;
         if (t.Abort(victim == null || captor == null, "no companion could be arranged or no lord stands as the captor")) return t.Line();

         string keep = CrSettings.Instance.AdultContentLevel.SelectedValue;
         try
         {
            Mapping.TraumaLedgerBehavior.Record(victim, captor, Logic.Trauma.TraumaKind.Tortured, Logic.Trauma.TraumaAuthor.Captor);
            Mapping.TraumaLedgerBehavior.Record(victim, captor, Logic.Trauma.TraumaKind.Tortured, Logic.Trauma.TraumaAuthor.Captor);
            Mapping.TraumaLedgerBehavior.Record(victim, null, Logic.Trauma.TraumaKind.Robbed, Logic.Trauma.TraumaAuthor.Player);

            CrSettings.Instance.AdultContentLevel.SelectedValue = "Hardcore";
            IReadOnlyList<string> hardcore = Mapping.TraumaPageReader.LinesFor(victim);
            t.Note($"{victim.Name}: {string.Join(" | ", hardcore)}");
            string when = Mapping.HeartPageReader.When((int) CampaignTime.Now.ToDays);
            string she = victim.IsFemale ? "She" : "He";
            t.Expect("atHardcoreTheCaptorIsNamedOnce", hardcore.Count(l => l == $"{she} was tortured by {captor.Name} while held captive, before your eyes, in {when}."), 1);
            t.Expect("theRobberyIsThePlayersOwnDeed", hardcore.Count(l => l == $"{she} was robbed at swordpoint by you, in {when}."), 1);
            t.Expect("neverOnThePlayersOwnPage", Mapping.TraumaPageReader.LinesFor(Hero.MainHero).Count, 0);

            CrSettings.Instance.AdultContentLevel.SelectedValue = "Explicit";
            t.Expect("belowHardcoreNothingShows", Mapping.TraumaPageReader.LinesFor(victim).Count, 0);
         }
         finally
         {
            CrSettings.Instance.AdultContentLevel.SelectedValue = keep;
         }

         return t.Line();
      }

      private static string TestHeartIntimacy(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("heart_intimacy");
         if (t.Abort(CrSettings.Instance == null || behavior?.Store == null || Hero.MainHero == null, "the MCM settings or the store are not ready")) return t.Line();

         Hero lover = ArrangedCompanion.Get(behavior, oppositeSexOfPlayer: true, unwed: true,
                                            reject: h => Hero.MainHero.ExSpouses?.Contains(h) == true)?.Companion;
         Hero prisoner = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h != lover && !h.IsChild);
         if (t.Abort(lover == null || prisoner == null, "no companion of the other sex could be arranged or no lord stands as the prisoner")) return t.Line();

         var today = (int) CampaignTime.Now.ToDays;
         NpcProfile profile = behavior.Store.Get(lover.StringId) ?? HeroProfileMapper.FromHero(lover);
         profile.Events.RemoveAll(e => e.type == NotableEventType.Intimacy && e.summary?.StartsWith("[SELFTEST]", StringComparison.Ordinal) == true);
         profile.Events.Add(new NotableEvent(Math.Max(1, today - 100), NotableEventType.Intimacy, "[SELFTEST] Our first night together."));
         profile.Events.Add(new NotableEvent(today, NotableEventType.Intimacy, "[SELFTEST] Another night together."));
         behavior.Store.Set(profile);
         Mapping.TraumaLedgerBehavior.Record(prisoner, null, Logic.Trauma.TraumaKind.Assaulted, Logic.Trauma.TraumaAuthor.Player);

         string keep = CrSettings.Instance.AdultContentLevel.SelectedValue;
         try
         {
            CrSettings.Instance.AdultContentLevel.SelectedValue = "Hardcore";
            IReadOnlyList<string> herPage = Mapping.HeartPageReader.LinesFor(lover);
            IReadOnlyList<string> playersPage = Mapping.HeartPageReader.LinesFor(Hero.MainHero);
            t.Note($"{lover.Name}: {string.Join(" | ", herPage)}");
            t.Note($"player: {string.Join(" | ", playersPage)}");
            t.Expect("herPageCountsTheNights", herPage.Any(l => l.StartsWith("You have shared ", StringComparison.Ordinal) && l.Contains(" nights together")), true);
            t.Expect("thePlayersPageNamesHerNights", playersPage.Any(l => l.Contains($" nights with {lover.Name}, ")), true);
            IReadOnlyList<string> misdeeds = Mapping.MisdeedsPageReader.LinesFor(Hero.MainHero);
            t.Note($"misdeeds: {string.Join(" | ", misdeeds)}");
            t.Expect("theForcedActIsNotUnderHeart", playersPage.Any(l => l.Contains("by force")), false);
            t.Expect("thePlayersMisdeedsTellTheForcedAct", misdeeds.Any(l => l.StartsWith($"You took {prisoner.Name} by force while", StringComparison.Ordinal)), true);
            t.Expect("noMisdeedsOnHerPage", Mapping.MisdeedsPageReader.LinesFor(lover).Count, 0);

            CrSettings.Instance.AdultContentLevel.SelectedValue = "Explicit";
            t.Expect("belowHardcoreNoNightOnHerPage", Mapping.HeartPageReader.LinesFor(lover).Any(l => l.Contains("night")), false);
            t.Expect("belowHardcoreNothingOnThePlayersPage", Mapping.HeartPageReader.LinesFor(Hero.MainHero).Any(l => l.Contains("night")), false);
            t.Expect("belowHardcoreNoForcedActInMisdeeds", Mapping.MisdeedsPageReader.LinesFor(Hero.MainHero).Any(l => l.Contains("by force while")), false);
         }
         finally
         {
            CrSettings.Instance.AdultContentLevel.SelectedValue = keep;
         }

         return t.Line();
      }

      private static string TestPrisonerMemory(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("prisoner_memory");
         if (t.Abort(behavior?.Store == null || Hero.MainHero == null, "the store is not ready")) return t.Line();

         Settlement town = Settlement.All.FirstOrDefault(s => s.IsTown && s.OwnerClan?.Leader != null && s.OwnerClan != Clan.PlayerClan);
         Hero captive = town == null ? null : Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Clan != town.OwnerClan);
         if (t.Skip(town == null || captive == null, "no town held by another house, or no lord to stand as the prisoner")) return t.Line();
         Hero keeper = town.OwnerClan.Leader;

         var before = new Dictionary<string, (bool Had, int Count)>();
         foreach (Hero h in new[] {captive, keeper, town.Town?.Governor}.Where(h => h != null).Distinct())
         {
            NpcProfile p = behavior.Store.Get(h.StringId);
            before[h.StringId] = (p != null, p?.Events.Count ?? 0);
         }

         try
         {
            CalradiaRemembers.Battles.PrisonerMemoryBehavior.RecordLeftInDungeon(captive, town);
            string player = Hero.MainHero.Name.ToString();
            string captiveLine = behavior.Store.Get(captive.StringId)?.Events.LastOrDefault()?.summary ?? "";
            string keeperLine = behavior.Store.Get(keeper.StringId)?.Events.LastOrDefault()?.summary ?? "";
            t.Note($"{captive.Name}: '{captiveLine}' | {keeper.Name}: '{keeperLine}'");
            t.Expect("theCaptiveRemembersTheDungeon", captiveLine, $"{player} left me in the dungeon of {town.Name}.");
            t.Expect("theHoldingHouseKnowsWhoItHolds", keeperLine.StartsWith($"{player} left {captive.Name}", StringComparison.Ordinal) && keeperLine.EndsWith($"in my dungeon at {town.Name}.", StringComparison.Ordinal), true);
         }
         finally
         {
            CalradiaRemembers.Battles.PrisonerMemoryBehavior.DebugForget(captive.StringId);
            foreach (KeyValuePair<string, (bool Had, int Count)> b in before)
            {
               if (!b.Value.Had) { behavior.Store.Remove(b.Key); continue; }
               NpcProfile p = behavior.Store.Get(b.Key);
               if (p != null && p.Events.Count > b.Value.Count) p.Events.RemoveRange(b.Value.Count, p.Events.Count - b.Value.Count);
            }
         }

         return t.Line();
      }

      private static string TestTournamentAudience(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("tournament_audience");
         if (t.Abort(behavior?.Store == null || WorldEventStore.Instance == null || Hero.MainHero == null, "the store or the world events are not ready")) return t.Line();

         int today = behavior.GameStateBridge.GetCurrentGameDay();
         Settlement hargard = Settlement.All.FirstOrDefault(s => s.IsTown && s.OwnerClan != null && s.OwnerClan != Clan.PlayerClan
                                                                 && (s.HeroesWithoutParty.Any(h => h.Clan == s.OwnerClan && h.IsLord && !h.IsChild)
                                                                     || s.Parties.Any(p => p.LeaderHero != null && p.LeaderHero.Clan == s.OwnerClan)))
                              ?? Settlement.All.FirstOrDefault(s => s.IsTown && s.MapFaction != null && s.OwnerClan != Clan.PlayerClan);
         if (t.Skip(hargard == null, "no town stands outside the player's house")) return t.Line();

         string eventId = $"cr_tourney_won_{hargard.StringId}_{today}";
         var lady = (Hero) null;
         NpcProfile ladyBefore = null;
         int ladyEvents = 0;
         try
         {
            CalradiaRemembers.Letters.LetterTriggerEvaluator.RecordTournamentVictoryChronicle(today, hargard.Town);
            Hero ofTheRealm = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.MapFaction == hargard.MapFaction && h != Hero.MainHero && h.Clan != Clan.PlayerClan);
            if (ofTheRealm != null)
               t.Expect("aLordOfTheTownsRealmKnowsTheVictory", WorldEventStore.Instance.GetKnownEvents(ofTheRealm, today, 200).Any(e => e.Id == eventId), true);

            lady = hargard.HeroesWithoutParty.FirstOrDefault(h => h.Clan == hargard.OwnerClan && h.IsLord && !h.IsChild)
                   ?? hargard.Parties.Select(p => p.LeaderHero).FirstOrDefault(h => h != null && h.Clan == hargard.OwnerClan);
            if (t.Skip(lady == null, $"no lord or lady of the holding house stands in {hargard.Name} today")) return t.Line();

            ladyBefore = behavior.Store.Get(lady.StringId);
            ladyEvents = ladyBefore?.Events.Count ?? 0;
            var result = new CalradiaRemembers.Logic.Tournaments.TournamentResult(hargard.Name.ToString(), today, true, 0, null, new List<CalradiaRemembers.Logic.Tournaments.TournamentBout>());
            int written = CalradiaRemembers.Tournaments.TournamentMemoryFeeder.RecordAudience(behavior, result, hargard, new HashSet<string>());
            NpcProfile after = behavior.Store.Get(lady.StringId);
            string line = after?.Events.LastOrDefault()?.summary ?? "";
            t.Note($"{lady.Name} of {hargard.Name}: written={written}, '{line}'");
            t.Expect("theHoldingHouseRemembersTheTourney", line.StartsWith($"I watched the tourney at {hargard.Name}, where the player took the crown", StringComparison.Ordinal), true);
         }
         finally
         {
            WorldEventStore.Instance.Remove(eventId);
            if (lady != null)
            {
               if (ladyBefore == null) behavior.Store.Remove(lady.StringId);
               else
               {
                  NpcProfile p = behavior.Store.Get(lady.StringId);
                  if (p != null && p.Events.Count > ladyEvents) p.Events.RemoveRange(ladyEvents, p.Events.Count - ladyEvents);
               }
            }
         }

         return t.Line();
      }

      private static string TestBattleReader(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("battle_reader");
         if (t.Abort(behavior?.Store == null || MobileParty.MainParty == null || WorldEventStore.Instance == null || behavior.WorldFeeders == null,
                     "the store, the main party or the world feeders are not ready")) return t.Line();

         using var arranged = ArrangedCompanion.Get(behavior, mustBeInMainParty: true);
         if (t.Skip(arranged == null, "the player has no companion at all, and no wanderer template to arrange one")) return t.Line();
         Hero companion = arranged.Companion;
         NpcProfile original = behavior.Store.Get(companion.StringId);
         int today = behavior.GameStateBridge.GetCurrentGameDay();
         string player = Hero.MainHero?.Name?.ToString() ?? "the player";
         WorldEvent siege = null;

         try
         {
            behavior.Store.Remove(companion.StringId);
            var first = new CalradiaRemembers.Battles.BattleFeatJournal();
            first.DebugTally(companion.StringId, 2, null, null);
            WorldEventFeeders.RecordCompanionSkirmishMemories(today, new SkirmishFacts {PlayerName = player, Foe = "a band of Looters", PlayerWon = true, PlaceClause = ""},
                                                              CalradiaRemembers.Battles.BattleFeatReport.ForOwnParts(first));
            var second = new CalradiaRemembers.Battles.BattleFeatJournal();
            second.DebugTally(companion.StringId, 4, null, "");
            WorldEventFeeders.RecordCompanionSkirmishMemories(today, new SkirmishFacts {PlayerName = player, Foe = "men of Vlandia", PlayerWon = false, PlaceClause = ""},
                                                              CalradiaRemembers.Battles.BattleFeatReport.ForOwnParts(second));

            NpcProfile profile = behavior.Store.Get(companion.StringId);
            var lines = profile?.Events.Where(e => SkirmishMemoryText.CountIn(e?.summary, player) > 0).ToList() ?? new List<NotableEvent>();
            string line = lines.LastOrDefault()?.summary ?? "";
            t.Note($"{companion.Name}: {line}");
            t.Expect("theFightsStillFoldIntoOneLine", lines.Count, 1);
            t.Expect("theLineStillCountsBothFights", SkirmishMemoryText.CountIn(line, player), 2);
            t.Expect("theCompanionTellsTheirOwnPartInTheLast", line.EndsWith("My own part: I cut down four of their men, before I was struck down.", StringComparison.Ordinal), true);

            Settlement town = Settlement.All.FirstOrDefault(s => s.IsTown && s.Owner != null && s.Owner != Hero.MainHero && s.MapFaction != null);
            MobileParty besieger = MobileParty.All.FirstOrDefault(p => p.LeaderHero is {IsLord: true} lh && lh != Hero.MainHero && p.MapFaction != null
                                                                        && town != null && p.MapFaction != town.MapFaction && !p.MapFaction.IsBanditFaction);
            if (t.Skip(town == null || besieger == null, "no town held by a lord, or no lord's party of another realm")) return t.Line();

            siege = behavior.WorldFeeders.DebugRecordSiegeNews(town, besieger, lifted: false);
            t.Note($"siege: {siege?.Summary}");
            t.Expect("theNewsNamesTheBesieger", siege?.Summary?.Contains(besieger.LeaderHero.Name.ToString()) == true, true);
            t.Expect("theTownsHolderKnowsIt", WorldEventStore.Instance.GetKnownEvents(town.Owner, today, 200).Any(e => e.Id == siege?.Id), true);
            Hero ofTheBesiegersRealm = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h.MapFaction == besieger.MapFaction && h != besieger.LeaderHero && h != Hero.MainHero);
            if (ofTheBesiegersRealm != null)
               t.Expect("aLordOfTheBesiegersRealmKnowsIt", WorldEventStore.Instance.GetKnownEvents(ofTheBesiegersRealm, today, 200).Any(e => e.Id == siege?.Id), true);
         }
         finally
         {
            if (original != null) behavior.Store.Set(original);
            else behavior.Store.Remove(companion.StringId);
            if (siege?.Id != null) WorldEventStore.Instance.Remove(siege.Id);
         }

         return t.Line();
      }

      private static string TestCombatJournal(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("combat_journal");
         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && !h.IsChild && h != Hero.MainHero).Take(3).ToList();
         if (t.Abort(lords.Count < 3, "fewer than three lords stand in the world")) return t.Line();

         var journal = new CalradiaRemembers.Battles.BattleFeatJournal();
         journal.DebugTally(lords[0].StringId, 7, lords[1].StringId, lords[2].StringId);
         string battle = CalradiaRemembers.Battles.BattleFeatReporter.OwnPartOf(journal, lords[0].StringId, arena: false);
         string lists = CalradiaRemembers.Battles.BattleFeatReporter.OwnPartOf(journal, lords[0].StringId, arena: true);
         t.Note($"battle: {battle}");
         t.Note($"lists: {lists}");
         t.Expect("hisKillsAreTold", battle.Contains("cut down seven of their men"), true);
         t.Expect("theLordHeBestedIsNamed", battle.Contains("bested " + lords[1].Name), true);
         // The name is told as the prompt tells it ("Arcor of Osticos (Empire)"), so only its start is pinned.
         t.Expect("whoStruckHimDownIsNamed", battle.Contains("before " + lords[2].Name) && battle.Contains("struck me down"), true);
         t.Expect("aTournamentKillsNoOne", lists.Contains("out of the lists") && !lists.Contains("cut down"), true);
         t.Expect("someoneWhoDidNothingHasNoLine", CalradiaRemembers.Battles.BattleFeatReporter.OwnPartOf(journal, Hero.MainHero.StringId, false), "");

         try
         {
            journal.DebugBind(null, tournament: true);
            CalradiaRemembers.Battles.BattleFeatJournal.DebugPark(journal);
            t.Expect("aTournamentIsNeverTakenForABattle", CalradiaRemembers.Battles.BattleFeatJournal.ConsumeFor(MobileParty.MainParty?.MapEvent) == null, true);
            t.Expect("theTournamentReaderTakesIt", CalradiaRemembers.Battles.BattleFeatJournal.ConsumeTournament() == journal, true);
            t.Expect("andOnlyOnce", CalradiaRemembers.Battles.BattleFeatJournal.ConsumeTournament() == null, true);

            var field = new CalradiaRemembers.Battles.BattleFeatJournal();
            field.DebugBind(null, tournament: false);
            CalradiaRemembers.Battles.BattleFeatJournal.DebugPark(field);
            t.Expect("aBattleIsNeverTakenForATournament", CalradiaRemembers.Battles.BattleFeatJournal.ConsumeTournament() == null, true);
         }
         finally
         {
            CalradiaRemembers.Battles.BattleFeatJournal.ConsumeCompleted(); // nothing of the test is left for a real fight
         }

         return t.Line();
      }

      private static string TestDeedRegard(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("deed_regard");
         if (t.Abort(behavior?.Store == null || Hero.MainHero == null, "the store is not ready")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && h != Hero.MainHero && h.Spouse is {IsAlive: true} s && s != Hero.MainHero
                                                             && behavior.Store.Get(h.StringId) == null);
         if (t.Abort(lord == null, "no married lord without a profile stands in the world")) return t.Line();

         Hero wife = lord.Spouse;
         bool wifeHadProfile = behavior.Store.Get(wife.StringId) != null;
         int wifeBefore = behavior.Store.Get(wife.StringId)?.ReputationWithPlayer ?? 0;
         try
         {
            Mapping.DeedRegardApplier.Apply(lord, Logic.PlayerDeed.StoleSpouse);
            NpcProfile his = behavior.Store.Get(lord.StringId);
            t.Note($"{lord.Name}: regard {his?.ReputationWithPlayer}; {wife.Name}: {wifeBefore} -> {behavior.Store.Get(wife.StringId)?.ReputationWithPlayer}");
            t.Expect("aProfileIsMadeForAManNeverMet", his != null, true);
            t.Expect("hisRegardFallsByTheTable", his?.ReputationWithPlayer, Math.Max(-100, Logic.DeedRegardPolicy.StoleSpouseVictim));
            t.Expect("heHoldsThePlayerInContempt", (his?.ReputationWithPlayer ?? 0) <= NpcMemoryService.Core.Standing.Regard.WaryTier, true);
            t.Expect("theFamilyCools", (behavior.Store.Get(wife.StringId)?.ReputationWithPlayer ?? 0) - wifeBefore,
                     Math.Max(-100, wifeBefore + Logic.DeedRegardPolicy.StoleSpouseKin) - wifeBefore);

            int beforeGift = his?.ReputationWithPlayer ?? 0;
            Mapping.DeedRegardApplier.Apply(lord, Logic.PlayerDeed.Gift, Logic.DeedRegardPolicy.GiftRegard(2000, false));
            t.Expect("aGiftWarmsByItsWorth", (behavior.Store.Get(lord.StringId)?.ReputationWithPlayer ?? 0) - beforeGift, Logic.DeedRegardPolicy.GiftRegard(2000, false));
         }
         finally
         {
            behavior.Store.Remove(lord.StringId);
            NpcProfile w = behavior.Store.Get(wife.StringId);
            if (w != null && !wifeHadProfile) behavior.Store.Remove(wife.StringId);
            else if (w != null) NpcMemoryService.Core.Services.ProfileMutator.ApplyReputationDelta(w, wifeBefore - w.ReputationWithPlayer, NpcMemoryService.Core.Standing.RegardCause.SelfTest);
         }

         return t.Line();
      }

      private static string TestMisdeedsPage(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("misdeeds_page");
         if (t.Abort(CrSettings.Instance == null || behavior?.Store == null || Hero.MainHero == null, "the MCM settings or the store are not ready")) return t.Line();

         Hero wronged = ArrangedCompanion.Get(behavior, oppositeSexOfPlayer: true, unwed: true,
                                              reject: h => Hero.MainHero.ExSpouses?.Contains(h) == true)?.Companion;
         Hero prisoner = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h != wronged && !h.IsChild);
         Kingdom realm = Kingdom.All.FirstOrDefault(k => !k.IsEliminated);
         if (t.Abort(wronged == null || prisoner == null || realm == null, "no companion, lord or realm could be arranged")) return t.Line();

         Mapping.MisdeedLedgerBehavior.Record(wronged.StringId, Logic.Trauma.MisdeedKind.Unfaithful);
         Mapping.MisdeedLedgerBehavior.Record(prisoner.StringId, Logic.Trauma.MisdeedKind.HandedToEnemy);
         Mapping.MisdeedLedgerBehavior.Record(realm.StringId, Logic.Trauma.MisdeedKind.ForsookRealm);
         Mapping.TraumaLedgerBehavior.Record(prisoner, null, Logic.Trauma.TraumaKind.Robbed, Logic.Trauma.TraumaAuthor.Player);
         Mapping.TraumaLedgerBehavior.Record(prisoner, null, Logic.Trauma.TraumaKind.Assaulted, Logic.Trauma.TraumaAuthor.Player);

         // The real listeners, with the player as raider and besieger, on a village and a town; the first a lord's, which must leave nothing.
         TaleWorlds.CampaignSystem.Settlements.Village village = TaleWorlds.CampaignSystem.Settlements.Village.All.FirstOrDefault(v => v.Settlement.MapFaction != Hero.MainHero.MapFaction);
         TaleWorlds.CampaignSystem.Settlements.Town town = TaleWorlds.CampaignSystem.Settlements.Town.AllTowns.FirstOrDefault();
         if (t.Abort(village == null || town == null, "no village or town to read")) return t.Line();

         int deeds = Mapping.MisdeedLedgerBehavior.All().Count;
         MobileParty anotherLord = MobileParty.AllLordParties.FirstOrDefault(p => p != MobileParty.MainParty);
         Mapping.MisdeedLedgerBehavior.OnVillageStateChanged(village, TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.Normal, TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.BeingRaided, anotherLord);
         Mapping.MisdeedLedgerBehavior.OnSiegeAftermath(anotherLord, town.Settlement, SiegeAftermathAction.SiegeAftermath.Devastate, null, null);
         t.Expect("anotherLordsRaidAndSackAreNotTheirs", Mapping.MisdeedLedgerBehavior.All().Count, deeds);
         Mapping.MisdeedLedgerBehavior.OnSiegeAftermath(MobileParty.MainParty, town.Settlement, SiegeAftermathAction.SiegeAftermath.ShowMercy, null, null);
         t.Expect("mercyIsNoMisdeed", Mapping.MisdeedLedgerBehavior.All().Count, deeds);
         Mapping.MisdeedLedgerBehavior.OnVillageStateChanged(village, TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.Normal, TaleWorlds.CampaignSystem.Settlements.Village.VillageStates.BeingRaided, MobileParty.MainParty);
         Mapping.MisdeedLedgerBehavior.OnSiegeAftermath(MobileParty.MainParty, town.Settlement, SiegeAftermathAction.SiegeAftermath.Devastate, null, null);

         string keep = CrSettings.Instance.AdultContentLevel.SelectedValue;
         try
         {
            CrSettings.Instance.AdultContentLevel.SelectedValue = "Off";
            IReadOnlyList<string> off = Mapping.MisdeedsPageReader.LinesFor(Hero.MainHero);
            t.Note($"off: {string.Join(" | ", off)}");
            t.Expect("theRaidedVillageIsNamed", off.Any(l => l.Contains(village.Name.ToString()) && (l.StartsWith("You raided ", StringComparison.Ordinal) || l.StartsWith("You fell on ", StringComparison.Ordinal))), true);
            t.Expect("theDevastatedTownIsNamed", off.Any(l => l.StartsWith($"You devastated {town.Name}", StringComparison.Ordinal)), true);
            t.Expect("theAdulteryShows", off.Any(l => l.StartsWith($"You were unfaithful to {wronged.Name}", StringComparison.Ordinal)), true);
            t.Expect("thePrisonerHandedOverShows", off.Any(l => l.StartsWith($"You handed {prisoner.Name} over to ", StringComparison.Ordinal)), true);
            t.Expect("theRobberyShows", off.Any(l => l.StartsWith($"You robbed {prisoner.Name} by force", StringComparison.Ordinal)), true);
            t.Expect("theRealmForsakenShows", off.Any(l => l.StartsWith($"You forsook your oath to {realm.Name}", StringComparison.Ordinal)), true);
            t.Expect("theActOfForceWaitsForHardcore", off.Any(l => l.Contains("by force while")), false);

            CrSettings.Instance.AdultContentLevel.SelectedValue = "Hardcore";
            IReadOnlyList<string> hardcore = Mapping.MisdeedsPageReader.LinesFor(Hero.MainHero);
            t.Expect("atHardcoreTheActOfForceShows", hardcore.Any(l => l.StartsWith($"You took {prisoner.Name} by force while", StringComparison.Ordinal)), true);
            t.Expect("aCharactersPageHasNoMisdeeds", Mapping.MisdeedsPageReader.LinesFor(wronged).Count, 0);
         }
         finally
         {
            CrSettings.Instance.AdultContentLevel.SelectedValue = keep;
         }

         return t.Line();
      }

      // Gabriel (20/10/2026): a test save, so the lover stays the player's lover, a companion of the other sex (reused, or minted
      // into the party), and her page and the player's recap can be opened afterwards.
      private static string TestHeartPage(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("heart_page");
         if (t.Abort(behavior?.Store == null || Hero.MainHero == null, "the store is not ready")) return t.Line();

         // The player's former spouse is turned away: her page tells the dissolved marriage first, not a new love (Gabriel's
         // save, 21/10/2026: Khilam, once wed to the player, was picked).
         Hero lover = ArrangedCompanion.Get(behavior, oppositeSexOfPlayer: true, unwed: true,
                                            reject: h => Hero.MainHero.ExSpouses?.Contains(h) == true)?.Companion;
         if (t.Abort(lover == null, "no companion of the other sex could be arranged")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lover.StringId) ?? HeroProfileMapper.FromHero(lover);
         profile.Romantic ??= new RomanticProfile();
         var today = (int) CampaignTime.Now.ToDays;
         int began = today - 100;
         // A rerun starts the story again: the first day they became lovers is otherwise kept for good.
         profile.Romantic.LoversSinceDay = null;
         profile.Romantic.StatusSinceDay = null;
         profile.Romantic.Status = RomanticStatus.Courting;
         profile.Romantic.MoveTo(RomanticStatus.Intimate, began);
         profile.Romantic.MoveTo(RomanticStatus.Intimate, today);
         behavior.Store.Set(profile);

         CampaignTime now = CampaignTime.Now;
         t.Expect("aDayIsTheCalendarsDay", Mapping.HeartPageReader.When(today), $"{now.GetSeasonOfYear.ToString().ToLowerInvariant()} {now.GetYear}");

         IReadOnlyList<string> page = Mapping.HeartPageReader.LinesFor(lover);
         t.Note($"{lover.Name}: {string.Join(" | ", page)}");
         t.Expect("herPageTellsTheBondAndWhenItBegan", page.FirstOrDefault(), $"{(lover.IsFemale ? "She" : "He")} has been your lover since {Mapping.HeartPageReader.When(began)}.");

         IReadOnlyList<string> recap = Mapping.HeartPageReader.LinesFor(Hero.MainHero);
         t.Expect("thePlayersPageListsHer", recap.Any(l => l.StartsWith($"{lover.Name}, your lover", StringComparison.Ordinal)), true);

         return t.Line();
      }

      private static string TestBountySettled(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("bounty_settled");
         Arrests.ArrestBehavior law = Arrests.ArrestBehavior.Instance;
         if (t.Abort(law == null || behavior?.GameStateBridge == null || Hero.MainHero == null, "the law or the bridge is not ready")) return t.Line();
         if (t.Skip(law.HoldsPlayer, "the law holds the player")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsChild && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan
                                                             && h.MapFaction is Kingdom k && k != Clan.PlayerClan?.Kingdom && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(lord == null, "no lord of another realm")) return t.Line();

         IFaction realm = lord.MapFaction;
         string kept = law.DebugSnapshot();
         int gold = Hero.MainHero.Gold;
         int lordGold = lord.Gold;
         float crime = realm.MainHeroCrimeRating;
         var today = (int) CampaignTime.Now.ToDays;
         string Arranged() => "{\"Bounties\":[{\"RealmId\":\"" + realm.StringId + "\",\"Reason\":1,\"PlacedDay\":" + today + "}],\"HuntersSentDay\":{\"" + realm.StringId + "\":" + today + "}}";
         try
         {
            law.DebugRestore(Arranged());
            t.Note($"{lord.Name} of {realm.Name}");
            // STAKE: a load must not send a fresh band at once: the day survives the save's own serialisation.
            t.Expect("theHuntersDaySurvivesTheSave", law.DebugSnapshot().Contains($"\"{realm.StringId}\":{today}"), true);

            NpcProfile profile = behavior.Store?.Get(lord.StringId) ?? HeroProfileMapper.FromHero(lord);
            var verbCtx = new VerbContext(lord, profile, behavior.GameStateBridge, null, null);
            string teaching = VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"pay_bounty"}) ?? "";
            t.Expect("theLordIsTaughtTheExactPrice", teaching.Contains($"exactly {OutlawPolicy.BrigandageBountyPrice} denars"), true);
            string question = Verbs.PayBountyVerb.Question(lord, out _);
            t.Expect("theQuestionNamesLordRealmAndPrice", question, $"Pay {lord.Name} {OutlawPolicy.BrigandageBountyPrice} denars to lift the price on your head in {realm.Name}?");

            if (Hero.MainHero.Gold < OutlawPolicy.BrigandageBountyPrice)
               GiveGoldAction.ApplyBetweenCharacters(null, Hero.MainHero, OutlawPolicy.BrigandageBountyPrice - Hero.MainHero.Gold, true);
            int before = Hero.MainHero.Gold;
            ActionOutcome paid = VerbRegistry.Instance.Execute(new GameAction {Type = "pay_bounty"}, verbCtx);
            t.Note(paid?.Message);
            t.Expect("theGoldLeaves", before - Hero.MainHero.Gold, OutlawPolicy.BrigandageBountyPrice);
            t.Expect("theBountyIsLifted", law.BountyOf(realm) == null, true);
            t.Expect("noLongerTaught", VerbRegistry.Instance.ComposeTeachings(verbCtx, new[] {"pay_bounty"}) ?? "", "");

            law.DebugRestore(Arranged());
            law.LiftBountiesWhenOff(arrestsOn: true);
            t.Expect("onTheBountyStands", law.BountyOf(realm) != null, true);
            law.LiftBountiesWhenOff(arrestsOn: false);
            // STAKE: froggyluv: "I've disabled that in options but they're still showing up".
            t.Expect("offTheBountyIsLifted", law.BountyOf(realm) == null, true);
         }
         finally
         {
            law.DebugRestore(kept);
            int give = gold - Hero.MainHero.Gold;
            if (give > 0) GiveGoldAction.ApplyBetweenCharacters(null, Hero.MainHero, give, true);
            else if (give < 0) GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, null, -give, true);
            int back = lord.Gold - lordGold;
            if (back > 0) GiveGoldAction.ApplyBetweenCharacters(lord, null, back, true);
            float drift = crime - realm.MainHeroCrimeRating;
            if (Math.Abs(drift) > 0.01f) ChangeCrimeRatingAction.Apply(realm, drift, false);
         }

         return t.Line();
      }

      private static string TestRomanceStatusDoor(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("romance_status_door");
         if (t.Abort(behavior?.Store == null || Hero.MainHero == null, "the store is not ready")) return t.Line();

         Hero lover = ArrangedCompanion.Get(behavior, oppositeSexOfPlayer: true, unwed: true,
                                            reject: h => Hero.MainHero.ExSpouses?.Contains(h) == true)?.Companion;
         if (t.Abort(lover == null, "no companion of the other sex could be arranged")) return t.Line();

         NpcProfile profile = behavior.Store.Get(lover.StringId) ?? HeroProfileMapper.FromHero(lover);
         profile.Romantic ??= new RomanticProfile();
         RomanticProfile r = profile.Romantic;
         (RomanticStatus status, int? since, int? lovers, bool secret, int? secretSince) kept = (r.Status, r.StatusSinceDay, r.LoversSinceDay, r.IsSecretLover, r.SecretLoverSinceDay);
         var heard = new List<CrRomanceStatusChange>();
         void Listen(CrRomanceStatusChange c)
         {
            if (c.NpcId == lover.StringId) heard.Add(c);
         }

         CrRomance.CheckForChanges(); // whatever moved before the test is announced now, not counted as the test's
         CrRomance.StatusChanged += Listen;
         try
         {
            var today = (int) CampaignTime.Now.ToDays;
            r.IsSecretLover = false;
            r.SecretLoverSinceDay = null;
            r.Status = RomanticStatus.Courting;
            behavior.Store.Set(profile);
            CrRomance.CheckForChanges();
            t.Expect("aCourtshipReadsCourting", CrRomance.GetStatus(lover.StringId)?.Bond, "courting");
            heard.Clear();

            // As take_as_secret_lover sets it: the flag, the day, and the state.
            r.MoveTo(RomanticStatus.SecretLover, today);
            r.IsSecretLover = true;
            r.SecretLoverSinceDay = today;
            behavior.Store.Set(profile);
            CrRomance.CheckForChanges();

            CrRomanceStatus now = CrRomance.GetStatus(lover.StringId);
            t.Note($"{lover.Name}: {now?.Bond} since day {now?.SinceDay}");
            t.Expect("sheReadsSecretLover", now?.Bond, "secret_lover");
            t.Expect("sinceToday", now?.SinceDay, (int?) today);
            t.Expect("theChangeIsHeardOnce", heard.Count, 1);
            t.Expect("fromCourting", heard.FirstOrDefault()?.Before?.Bond, "courting");
            t.Expect("toSecretLover", heard.FirstOrDefault()?.After?.Bond, "secret_lover");
            // STAKE: a bridge mirroring bonds into its own mod must be able to skip a test's change.
            t.Expect("markedAsATestsChange", heard.FirstOrDefault()?.DuringSelfTest, true);
         }
         finally
         {
            r.Status = kept.status;
            r.StatusSinceDay = kept.since;
            r.LoversSinceDay = kept.lovers;
            r.IsSecretLover = kept.secret;
            r.SecretLoverSinceDay = kept.secretSince;
            behavior.Store.Set(profile);
            CrRomance.CheckForChanges();
            CrRomance.StatusChanged -= Listen;
         }

         return t.Line();
      }

      private static string TestMatchAsksThePlayer(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("match_asks_the_player");
         if (t.Skip(Clan.PlayerClan?.Leader != Hero.MainHero, "the player does not lead their house")) return t.Line();

         Hero GroomFor(Hero woman)
            => Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsFemale && h.Spouse == null && !h.IsChild && !h.IsPrisoner && h.Clan != null
                                                      && h.Clan != Clan.PlayerClan && h.Clan.Leader != null && !h.Clan.Leader.IsPrisoner
                                                      && Campaign.Current.Models.MarriageModel.IsCoupleSuitableForMarriage(h, woman)
                                                      && (h.MapFaction == null || Hero.MainHero.MapFaction == null || !FactionManager.IsAtWarAgainstFaction(h.MapFaction, Hero.MainHero.MapFaction)));

         Hero bride = null, groom = null, minted = null;
         foreach (Hero woman in Clan.PlayerClan.Heroes.Where(h => h != Hero.MainHero && h.IsFemale && h.Spouse == null && !h.IsChild && !h.IsPrisoner
                                                                  && Mapping.HeroPresence.IsInTheWorld(h)))
         {
            groom = GroomFor(woman);
            if (groom == null) continue;
            bride = woman;
            break;
         }

         try
         {
            if (bride == null)
            {
               // Gabriel (20/10/2026): the test arranges its own sister of the house. Minted off the map into the player's clan and
               // made one of the family the way the game makes a companion one (CompanionRolesCampaignBehavior: SetNewOccupation
               // Lord), with no parent named, so no real kin of the player is touched; removed again below.
               CharacterObject template = MBObjectManager.Instance.GetObjectTypeList<CharacterObject>()
                  .FirstOrDefault(c => c != null && c.IsTemplate && c.Occupation == Occupation.Wanderer && c.IsFemale);
               if (t.Abort(template == null, "no female wanderer template to mint a woman of the house from")) return t.Line();

               minted = HeroCreator.CreateSpecialHero(template, null, Clan.PlayerClan, null, 22);
               minted.ChangeState(Hero.CharacterStates.Active);
               minted.SetNewOccupation(Occupation.Lord);
               groom = GroomFor(minted);
               if (t.Skip(groom == null, "no lawful groom of another house at peace for a woman of the player's house")) return t.Line();
               bride = minted;
               t.Note($"minted {minted.Name} into the player's house");
            }

            Hero groomSide = groom.Clan.Leader;
            t.Note($"{bride.Name} for {groom.Name}, asked by {groomSide.Name}");
            t.Expect("theGroomsSideIsTaken", CrMatches.Register(new CrMatchRequest {SuitorId = groom.StringId, BrideId = bride.StringId, DeciderId = groomSide.StringId, SourceMod = "cr.test all"}),
               MatchRegistrationResult.Registered);
            PendingMatch taught = behavior.GameStateBridge.MatchToArrange(groomSide);
            t.Expect("heIsTaughtToAskThePlayer", taught?.AsksThePlayer, (bool?) true);
            PendingMatch hand = BannerlordGameStateBridge.HandAskedOfThePlayer(groomSide);
            t.Expect("theChatAsksThePlayer", hand == null ? null : Logic.Actions.ActionConfirmationPolicy.BuildHandQuestion(new Logic.Actions.HandConfirmationFacts {BrideName = hand.BrideName, SuitorName = hand.SuitorName}),
               $"Give {bride.Name}'s hand to {groom.Name}?");
         }
         finally
         {
            if (groom != null && bride != null) CrMatches.Withdraw(groom.StringId, bride.StringId);
            try
            {
               if (minted is {IsDead: false})
               {
                  // Her purse would go to the head of her house, the player, as ArrangedCompanion's minted hero's would.
                  if (minted.Gold != 0) minted.ChangeHeroGold(-minted.Gold);
                  KillCharacterAction.ApplyByRemove(minted);
                  behavior?.Store?.Remove(minted.StringId);
               }
            }
            catch (Exception ex) { ModLog.Info($"[SELFTEST] match_asks_the_player cleanup failed: {ex.GetType().Name}: {ex.Message}"); }
         }

         return t.Line();
      }

