         t.Note($"player placed as \"{where ?? "(unsaid)"}\" ({men} in party); {seekers.Count} possible audience seekers across towns");
         t.Expect("thePlayerNeverRidesWithTheWritersRetinue", where == null || !where.Contains("your"), true);
