      private static string TestRpSway(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("rp_sway");

         if (t.Abort(WorldEventStore.Instance == null, "WorldEventStore not active")) return t.Line();

         (Hero npc, Hero target)? pair = ResolveSwayPair();

         if (t.Skip(pair == null, "need an NPC + a distinct third lord to sway an opinion of")) return t.Line();
         (Hero npc, Hero target) = pair.Value;

         NpcProfile profile = GetOrCreate(behavior, npc);

         if (t.Skip(!CourtActionResolver.CanTeachSway(npc, profile), "NPC not eligible to teach sway_opinion")) return t.Line();

         // SelectSwayTarget picks the most-negative rival, which can already sit at the -100 engine floor
         // where a further drop clamps to nothing. Give the relation headroom so the delta is measurable.
         if (Mapping.PairBondReader.Points(npc, target) <= NearTheEngineFloor)
            Mapping.RelationLedgerBehavior.SetAsHistory(npc, target, -50);

         int relBefore = Mapping.PairBondReader.Points(npc, target);

         // Maifailun (01/10/2026): a bow is no case. The player never names the target: refused, nothing moves.
         ActionOutcome unargued = behavior.GameStateBridge.ExecuteAction(
            new GameAction {
               Type = "sway_opinion",
               Parameters = new Dictionary<string, string> {{"target", target.Name.ToString()}, {"stance", "against"}}
            }, npc, new ActionContext(profile, null) {PlayerWordsThisConversation = "Have you enjoyed the tournament, my lady? *bows*"});
         t.Expect("unarguedSwayRefused", unargued != null && !unargued.IsPositive && Mapping.PairBondReader.Points(npc, target) == relBefore, true);

         int eventsBefore = WorldEventStore.Instance.Count;

         ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {
               Type = "sway_opinion",
               Parameters = new Dictionary<string, string> {{"target", target.Name.ToString()}, {"stance", "against"}}
            }, npc, new ActionContext(profile, null) {PlayerWordsThisConversation = $"{target.Name} has betrayed you."});

         int relAfter = Mapping.PairBondReader.Points(npc, target);
         int eventsAfter = WorldEventStore.Instance.Count;
         NpcProfile after = behavior.Store.Get(npc.StringId);
         bool marked = after != null &&
                       after.CourtActionCooldowns.ContainsKey(CourtActionResolver.SwayMarker(target.StringId))
                       && !after.Events.Any(e => (e.summary ?? "").Contains("[cr_"));

         // Same pair, same day — the per-target cooldown must refuse a repeat.
         ActionOutcome again = behavior.GameStateBridge.ExecuteAction(
            new GameAction {
               Type = "sway_opinion",
               Parameters = new Dictionary<string, string> {{"target", target.Name.ToString()}, {"stance", "against"}}
            }, npc, new ActionContext(after, null));

         t.Note($"{npc.Name} vs {target.Name}: relation {relBefore}->{relAfter}, worldEvents {eventsBefore}->{eventsAfter}");
         t.Expect("outcomePositive", outcome?.IsPositive, true);
         t.Expect("relationDropped", relAfter - relBefore, CourtActionPolicy.SwayAgainstDelta);
         t.Expect("markerStamped", marked, true);
         t.Expect("worldEventRecorded", eventsAfter > eventsBefore, true);
         t.Expect("repeatRefused", again == null || !again.IsPositive, true);

         return t.Line();
      }

      private static string TestCaptiveDungeonBargain(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("captive_dungeon_bargain");
         Settlement fief = Clan.PlayerClan?.Settlements?.FirstOrDefault(s => (s.IsTown || s.IsCastle) && s.Party != null);
         if (t.Skip(fief == null, "the player's house holds no town or castle, so it has no dungeon")) return t.Line();
         Hero captive = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != Hero.MainHero && h.Clan != null && h.Clan != Clan.PlayerClan && !h.IsPrisoner
                                                               && h.PartyBelongedTo == null && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(captive == null, "no free lord without a party of his own to hold")) return t.Line();

         NpcProfile profile = GetOrCreate(behavior, captive);
         int eventsBefore = profile.Events.Count, relationBefore = captive.GetRelation(Hero.MainHero);
         try
         {
            // Arranged (GABRIEL'S RULE 13/10/2026): the lord is put in the dungeon of the player's own fief.
            TakePrisonerAction.Apply(fief.Party, captive);
            t.Note($"{captive.Name} held in {fief.Name}'s dungeon");

            // STAKE: LapitaPolata's report: a captive in the player's dungeon is the player's captive, offered terms.
            t.Expect("theDungeonCaptiveIsThePlayers", behavior.GameStateBridge.GetPlayerStatus(captive), PlayerStatusVsNpc.NpcIsCaptive);
            t.Expect("termsAreOpenToHim", Mapping.EncounterContextBuilder.ResolveCaptiveOffer(captive, profile, PlayerStatusVsNpc.NpcIsCaptive, false) != null, true);

            // STAKE: an accord struck in the conversation frees him, where it used to be refused as "not yours".
            ActionOutcome deal = behavior.GameStateBridge.ExecuteAction(new GameAction {Type = "counter_offer", Parameters = new Dictionary<string, string> {{"terms", "goodwill"}}},
                                                                        captive, new ActionContext(profile, null));
            t.Expect("theAccordIsSettled", deal?.IsPositive, true);
            t.Expect("heWalksFree", captive.IsPrisoner, false);
         }
         finally
         {
            if (captive.IsPrisoner) EndCaptivityAction.ApplyByReleasedByChoice(captive, Hero.MainHero);
            while (profile.Events.Count > eventsBefore) profile.Events.RemoveAt(profile.Events.Count - 1);
            int drift = captive.GetRelation(Hero.MainHero) - relationBefore;
            if (drift != 0) ChangeRelationAction.ApplyRelationChangeBetweenHeroes(captive, Hero.MainHero, -drift, false);
         }

         return t.Line();
      }

      private static string TestPressForWar(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("press_for_war");
         if (t.Abort(WorldEventStore.Instance == null || Verbs.PressForWarBehavior.Instance == null || Grudges.SwayExposureBehavior.Instance == null, "the war pressing, the world events or the exposure watch is not active")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h.IsLord && h != Hero.MainHero && h.Clan != null && h.Clan != Clan.PlayerClan && h.Clan.Kingdom != null
                                                           && Mapping.HeroPresence.IsInTheWorld(h) && !Verbs.PressForWarBehavior.Instance.IsPressing(h.Clan.StringId)).ToList();
         Hero lord = lords.FirstOrDefault(h => Verbs.PressForWarVerb.Targets(h).Count > 0);
         float lent = 0f;
         if (lord == null)
         {
            // Arranged (GABRIEL'S RULE 13/10/2026): a house short of influence is lent what a proposal costs, restored after.
            lord = lords.FirstOrDefault(h => Kingdom.All.Any(k => k != h.Clan.Kingdom && !k.IsEliminated && !FactionManager.IsAtWarAgainstFaction(k, h.Clan.Kingdom)));
            if (t.Skip(lord == null, "every realm is at war with every other; no war is left to press")) return t.Line();
            lent = Campaign.Current.Models.DiplomacyModel.GetInfluenceCostOfProposingWar(lord.Clan) + 10f;
            ChangeClanInfluenceAction.Apply(lord.Clan, lent);
            t.Note($"{lord.Clan.Name} was lent {lent:0} influence");
         }

         NpcProfile profile = GetOrCreate(behavior, lord);
         string rumourId = null;
         int eventsBefore = profile.Events.Count;
         try
         {
            List<(Kingdom Realm, Logic.HouseLeaning Leaning)> targets = Verbs.PressForWarVerb.Targets(lord);
            if (t.Skip(targets.Count == 0, $"{lord.Name}'s house can press no war even with influence (fresh peace or a proposal pending)")) return t.Line();
            Kingdom target = targets[0].Realm;
            t.Note($"{lord.Name} of {lord.Clan.Kingdom.Name} against {target.Name} ({targets[0].Leaning})");

            // STAKE: declared before the lord speaks: the realms he could press, with how his house leans.
            string teachings = VerbRegistry.Instance.ComposeTeachings(new VerbContext(lord, profile, behavior.GameStateBridge, null, null)) ?? "";
            t.Expect("taughtWithTheRealm", teachings.Contains("type: press_for_war") && teachings.Contains(target.Name.ToString()), true);

            var press = new GameAction {Type = "press_for_war", Parameters = new Dictionary<string, string> {{"target", target.Name.ToString()}}};
            // STAKE: a case for war names the realm; small talk moves nothing.
            ActionOutcome unargued = behavior.GameStateBridge.ExecuteAction(press, lord, new ActionContext(profile, null) {PlayerWordsThisConversation = "A fine morning, my lord."});
            t.Expect("unarguedRefused", unargued != null && !unargued.IsPositive && !Verbs.PressForWarBehavior.Instance.IsPressing(lord.Clan.StringId), true);

            ActionOutcome outcome = behavior.GameStateBridge.ExecuteAction(press, lord, new ActionContext(profile, null) {PlayerWordsThisConversation = $"{target.Name} grows fat on your borders; strike first."});
            t.Expect("persuaded", outcome?.IsPositive, true);
            // STAKE: nothing is declared at once; the house carries it to court days later.
            Verbs.PressForWarBehavior.PendingPress pending = Verbs.PressForWarBehavior.Instance.Pending.FirstOrDefault(p => p.ClanId == lord.Clan.StringId);
            t.Expect("theHouseWillPressIt", pending != null && pending.TargetId == target.StringId, true);
            t.Expect("notAtWarYet", FactionManager.IsAtWarAgainstFaction(lord.Clan.Kingdom, target), false);

            // STAKE: Gabriel's cost: the talk is gossip, watched for the target realm's heads.
            rumourId = Verbs.PressForWarVerb.DebugLastRumourId;
            WorldEvent rumour = WorldEventStore.Instance.GetById(rumourId);
            t.Expect("theTalkIsGossip", rumour?.Type, WorldEventType.WarLooming);
            t.Expect("theTargetsHeadsMayLearnOfIt", Grudges.SwayExposureBehavior.Instance.Pending.Any(p => p.RumourEventId == rumourId && p.TargetId == target.Leader?.StringId && p.Cause != null), true);

            // STAKE: on the day, the game's own proposal is what is filed (prepared here, never filed: an AI realm votes at once).
            TaleWorlds.CampaignSystem.Election.DeclareWarDecision decision = Verbs.PressForWarBehavior.Instance.Prepare(pending, out string whyNot);
            if (whyNot != null) t.Note($"not filed: {whyNot}");
            t.Expect("theGamesOwnProposal", decision != null && decision.ProposerClan == lord.Clan && decision.FactionToDeclareWarOn == target, true);
         }
         finally
         {
            Verbs.PressForWarBehavior.Instance.DebugForget(lord.Clan.StringId);
            if (rumourId != null)
            {
               Grudges.SwayExposureBehavior.Instance.DebugDrop(rumourId);
               WorldEventStore.Instance.Remove(rumourId);
            }
            while (profile.Events.Count > eventsBefore) profile.Events.RemoveAt(profile.Events.Count - 1);
            if (lent > 0f) ChangeClanInfluenceAction.Apply(lord.Clan, -lent);
         }

         return t.Line();
      }

