         {
            "rhagaea_death_eagles_turn", "rhagaea_marriage_consort", "rhagaea_marriage_two_crowns", "rhagaea_marriage_regent",
            "rhagaea_marriage_suspicious"
         };
         var loaded = new HashSet<string>(runtime.Rules.Select(r => r.Id));
         t.Expect("shippedMissing", string.Join(",", shipped.Where(id => !loaded.Contains(id))), "");

         // An empty context: references resolve against the whole world, as a rule's author meant them.
         var world = new ScenarioContext();
         var problems = new List<string>();

         foreach (ScenarioRule rule in runtime.Rules)
         {
            // Whose pack it is, so a broken rule in another mod's pack is never read as CR's.
            string who = $"{rule.Id} ({runtime.SourceOf(rule.Id)})";
            if (!ScenarioBehavior.KnownTriggers.Contains(rule.Trigger?.Verb)) problems.Add($"{who}: trigger {rule.Trigger}");

            foreach (KeywordToken g in rule.Guards)
               if (!ScenarioGuardResolver.KnownVerbs.Contains(g.Verb)) problems.Add($"{who}: unknown guard {g.Verb}");
               else if (g.Verb == "IF_HERO_IS" && !ScenarioHeroExists(world, g.Payload)) problems.Add($"{who}: no hero '{g.Payload}'");
               else if ((g.Verb == "IF_PLAYER_AT_WAR" || g.Verb == "IF_KINGDOM_EXISTS") && world.ResolveFaction(g.Payload) == null) problems.Add($"{who}: no faction '{g.Payload}'");
               else if (g.Verb == "IF_ALIVE" && !ScenarioHeroExists(world, g.Payload)) problems.Add($"{who}: no hero '{g.Payload}'");
               else if ((g.Verb == "IF_AT_WAR" || g.Verb == "IF_AT_PEACE")
                        && (g.Args.Count < 2 || world.ResolveFaction(g.Args[0]) == null || world.ResolveFaction(g.Args[1]) == null))
                  problems.Add($"{who}: {g.Verb} '{g.Payload}' does not name two factions");
               else if (g.Verb == "IF_RULES" && (g.Args.Count < 2 || !ScenarioHeroExists(world, g.Args[0]) || world.ResolveFaction(g.Args[1]) == null))
                  problems.Add($"{who}: IF_RULES '{g.Payload}' does not name a hero and a kingdom");

            foreach (KeywordToken c in rule.Consequences)
            {
               if (!ScenarioConsequenceExecutor.KnownVerbs.Contains(c.Verb))
               {
                  problems.Add($"{who}: unknown consequence {c.Verb}");
                  continue;
               }

               switch (c.Verb)
               {
                  case "DECLARE_WAR":
                  case "MAKE_PEACE":
                     IFaction a = c.Args.Count > 0 ? world.ResolveFaction(c.Args[0]) : null;
                     IFaction b = c.Args.Count > 1 ? world.ResolveFaction(c.Args[1]) : null;
                     if (a == null || b == null || a == b) problems.Add($"{who}: {c.Verb} '{c.Payload}' resolves to {a?.StringId ?? "nothing"} / {b?.StringId ?? "nothing"}");
                     break;
                  case "CHANGE_RELATION":
                  case "CHANGE_INFLUENCE":
                     if (!ScenarioArgs.TryParseTargetDelta(c.Payload, out string target, out _) || !ScenarioHeroExists(world, target))
                        problems.Add($"{who}: {c.Verb} '{c.Payload}' names no hero");
                     break;
                  case "INJECT_MEMORY":
                     if (!ScenarioArgs.TryParseTargetRest(c.Payload, out string remembers, out _) || !ScenarioHeroExists(world, remembers))
                        problems.Add($"{who}: INJECT_MEMORY names no hero");
                     break;
               }
            }
         }

         t.Note($"{runtime.Rules.Count} rule(s) loaded");
         t.Expect("problems", problems.Count == 0 ? "none" : string.Join("; ", problems), "none");

         return t.Line();
      }

      // A hero a rule names exists in this world, alive or not (a dead Rhagaea is a fact of this save, not a broken pack).
      private static bool ScenarioHeroExists(ScenarioContext world, string reference)
      {
         if (world.ResolveHero(reference) != null) return true;
         string r = reference?.Trim();
         if (string.IsNullOrEmpty(r)) return false;

         return Hero.DeadOrDisabledHeroes.Any(h => string.Equals(h.StringId, r, StringComparison.OrdinalIgnoreCase)
                                                   || (h.Name?.ToString() ?? "").IndexOf(r, StringComparison.OrdinalIgnoreCase) >= 0);
      }

      private static string TestScenarioAllPlay(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scenario_all_play");
         if (t.Abort(WorldEventStore.Instance == null, "world-event store not ready")) return t.Line();

         Kingdom kingdom = Kingdom.All.FirstOrDefault(k => !k.IsEliminated);
         if (t.Skip(kingdom == null, "no kingdom standing in this campaign")) return t.Line();

         // A runtime of its own: the rules the game runs and their seals are not touched.
         var seals = new HashSet<string>();
         var runtime = new ScenarioRuntime(seals);
         const string group = "cr_selftest_group";
         runtime.Load(new[] {
            ScenarioRule.Parse("cr_selftest_war", "ON_PEACE", new[] {"IF_ALIVE:PLAYER"}, null, "cr selftest: the first of two", true),
            ScenarioRule.Parse("cr_selftest_pretender", "ON_PEACE", null, null, "cr selftest: the second of two", true),
            ScenarioRule.Parse("cr_selftest_alt1", "ON_PEACE", null, null, "cr selftest: an alternative", true, 1, group),
            ScenarioRule.Parse("cr_selftest_alt2", "ON_PEACE", null, null, "cr selftest: the other alternative", true, 1, group),
            // A realm cannot make peace with itself: this consequence can never apply, so the rule must not be told.
            ScenarioRule.Parse("cr_selftest_blocked", "ON_PEACE", null, new[] {$"MAKE_PEACE:{kingdom.StringId},{kingdom.StringId}"}, "cr selftest: never told", true)
         });

         var worldBefore = new HashSet<string>(WorldEventStore.Instance.All().Select(e => e.Id));
         try
         {
            List<string> played = runtime.Fire(KeywordToken.Parse("ON_PEACE"), new ScenarioContext()).Select(r => r.Id).ToList();
            List<string> told = WorldEventStore.Instance.All().Where(e => !worldBefore.Contains(e.Id)).Select(e => e.Summary).ToList();

            t.Note("played=" + string.Join(",", played));
            t.Expect("bothRulesPlay", played.Contains("cr_selftest_war") && played.Contains("cr_selftest_pretender"), true);
            t.Expect("oneAlternative", played.Count(id => id.StartsWith("cr_selftest_alt", StringComparison.Ordinal)), 1);
            t.Expect("impossibleNotPlayed", played.Contains("cr_selftest_blocked"), false);
            t.Expect("impossibleNotSealed", seals.Contains("cr_selftest_blocked"), false);
            t.Expect("impossibleNotTold", told.Contains("cr selftest: never told"), false);
            t.Expect("eachPlayedIsTold", told.Count, played.Count);
         }
         finally
         {
            foreach (WorldEvent e in WorldEventStore.Instance.All().Where(e => !worldBefore.Contains(e.Id)).ToList())
               WorldEventStore.Instance.Remove(e.Id);
         }

         return t.Line();
      }

      private static string TestScenarioGuards(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scenario_guards");

         List<Kingdom> standing = Kingdom.All.Where(k => !k.IsEliminated && k.Leader != null).ToList();
         if (t.Skip(standing.Count < 2, "fewer than two kingdoms standing with a ruler")) return t.Line();

         Kingdom a = standing[0];
         Kingdom b = standing[1];
         bool atWar = FactionManager.IsAtWarAgainstFaction(a, b);
         var world = new ScenarioContext();
         bool Guard(string raw) => ScenarioGuardResolver.Resolve(KeywordToken.Parse(raw), world);
         bool Applies(string raw) => ScenarioConsequenceExecutor.CanApply(KeywordToken.Parse(raw), world);

         t.Note($"{a.StringId} vs {b.StringId}: atWar={atWar}");
         t.Expect("atWarReadsTheGame", Guard($"IF_AT_WAR:{a.StringId},{b.StringId}"), atWar);
         t.Expect("atPeaceReadsTheGame", Guard($"IF_AT_PEACE:{a.StringId},{b.StringId}"), !atWar);
         t.Expect("playerAlive", Guard("IF_ALIVE:PLAYER"), true);
         Hero dead = Hero.DeadOrDisabledHeroes.FirstOrDefault(h => h.IsDead && h.IsLord);
         if (dead != null) t.Expect("deadLordNotAlive", Guard($"IF_ALIVE:{dead.StringId}"), false);
         t.Expect("kingdomExists", Guard($"IF_KINGDOM_EXISTS:{a.StringId}"), true);
         t.Expect("rulerRules", Guard($"IF_RULES:{a.Leader.StringId},{a.StringId}"), true);
         t.Expect("rulerDoesNotRuleAnother", Guard($"IF_RULES:{a.Leader.StringId},{b.StringId}"), false);
         t.Expect("warPossibleOnlyAtPeace", Applies($"DECLARE_WAR:{a.StringId},{b.StringId}"), !atWar);
         t.Expect("peacePossibleOnlyAtWar", Applies($"MAKE_PEACE:{a.StringId},{b.StringId}"), atWar);
         t.Expect("noWarWithItself", Applies($"DECLARE_WAR:{a.StringId},{a.StringId}"), false);
         t.Expect("unknownConsequenceNever", Applies("SUMMON_DRAGON:x"), false);

         return t.Line();
      }

      private static string TestScenarioSources(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scenario_sources");
         const string mod = "CrSelfTestMod";
         const string fresh = "crselftestmod_fresh_rule";
         const string taken = "rhagaea_death_eagles_turn";

         string folder = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "cr_selftest_scenarios_" + Guid.NewGuid().ToString("N"));
         try
         {
            System.IO.Directory.CreateDirectory(folder);
            System.IO.File.WriteAllText(System.IO.Path.Combine(folder, "test_pack.json"),
               "{\"rules\":[{\"id\":\"" + fresh + "\",\"trigger\":\"ON_PEACE\",\"message\":\"a test line\"},"
               + "{\"id\":\"" + taken + "\",\"trigger\":\"ON_PEACE\",\"message\":\"an impostor\"}]}");

            ScenarioMergeResult r = ScenarioPackLoader.Load(new List<ScenarioPackFolder> {
               new() {Source = ScenarioPackFolders.OwnSource, Folder = ScenarioPackLoader.ShippedFolder()},
               new() {Source = mod, Folder = folder}
            });

            ScenarioRule kept = r.Rules.FirstOrDefault(x => x.Id == taken);
            t.Expect("modRuleLoaded", r.Rules.Any(x => x.Id == fresh), true);
            t.Expect("modRuleSource", r.SourceOf.TryGetValue(fresh, out string s) ? s : null, mod);
            t.Expect("crKeepsItsId", r.SourceOf.TryGetValue(taken, out string owner) ? owner : null, ScenarioPackFolders.OwnSource);
            t.Expect("crRuleIsCrs", kept?.Trigger?.Verb, "ON_DEATH");
            t.Expect("impostorReported", r.Problems.Any(p => p.Contains(taken) && p.Contains(mod)), true);
         }
         finally
         {
            try { System.IO.Directory.Delete(folder, true); }
            catch { /* a temp folder left behind is harmless */ }
         }

         return t.Line();
      }

      private static string TestScenarioDeath(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scenario_death");

         ScenarioRuntime runtime = ScenarioBehavior.Instance?.Runtime;
         if (t.Abort(runtime == null, "scenario engine not ready")) return t.Line();

         ScenarioRule rule = runtime.Rules.FirstOrDefault(r => r.Id == "rhagaea_death_eagles_turn");
         if (t.Skip(rule == null, "the shipped death rule is not loaded (see scenario_packs)")) return t.Line();
         if (t.Skip(runtime.FiredRuleIds.Contains(rule.Id), "the death rule is already sealed in this save")) return t.Line();

         Hero rhagaea = AliveRhagaea();
         if (t.Skip(rhagaea == null, "Rhagaea is not alive in this campaign")) return t.Line();

         Hero other = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != rhagaea && h != Hero.MainHero && h.MapFaction != null && h.MapFaction != rhagaea.MapFaction)
                      ?? Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && h != rhagaea && h != Hero.MainHero);
         if (t.Skip(other == null, "no other living lord to stand in the death")) return t.Line();

         KeywordToken onDeath = KeywordToken.Parse("ON_DEATH");
         ScenarioContext sheDies = ScenarioBehavior.ForDeath(rhagaea, other);
         ScenarioContext sheKills = ScenarioBehavior.ForDeath(other, rhagaea);

         // The readiness the game asks (ScenarioPass.IsReady), its wars taken as possible: who the death is about decides.
         ScenarioChecks Checks(ScenarioContext ctx, bool realWars) => new()
         {
            Sealed = runtime.FiredRuleIds,
            GuardPasses = g => ScenarioGuardResolver.Resolve(g, ctx),
            ConsequenceApplies = c => !realWars || ScenarioConsequenceExecutor.CanApply(c, ctx)
         };
         bool whenSheDies = ScenarioSelector.TriggerMatches(rule.Trigger, onDeath) && ScenarioPass.IsReady(rule, Checks(sheDies, false));
         bool whenSheKills = ScenarioSelector.TriggerMatches(rule.Trigger, onDeath) && ScenarioPass.IsReady(rule, Checks(sheKills, false));
         // On this save, as it stands: would her death play it? Only when the North and the West are both at peace with the South.
         bool readyNow = ScenarioPass.IsReady(rule, Checks(sheDies, true));

         // The wars as the executor would resolve them on her death: each side as the game's kingdom id.
         string wars = string.Join(",", rule.Consequences.Where(c => c.Verb == "DECLARE_WAR").Select(c =>
            $"{(c.Args.Count > 0 ? sheDies.ResolveFaction(c.Args[0])?.StringId : null) ?? "?"}->{(c.Args.Count > 1 ? sheDies.ResolveFaction(c.Args[1])?.StringId : null) ?? "?"}"));

         t.Note($"other={other.Name} ({other.MapFaction?.StringId}); her death would play it on this save now: {readyNow}");
         t.Expect("firesWhenSheDies", whenSheDies, true);
         t.Expect("firesWhenSheKills", whenSheKills, false);
         t.Expect("wars", wars, "empire->empire_s,empire_w->empire_s");

         return t.Line();
      }

      private static string TestScenarioMarriage(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scenario_marriage");
         const string prefix = "rhagaea_marriage_";

         ScenarioRuntime runtime = ScenarioBehavior.Instance?.Runtime;
         if (t.Abort(runtime == null, "scenario engine not ready")) return t.Line();
         var store = behavior?.Store;
         if (t.Abort(store == null || WorldEventStore.Instance == null, "memory or world-event store not ready")) return t.Line();

         List<ScenarioRule> outcomes = runtime.Rules.Where(r => r.Id != null && r.Id.StartsWith(prefix, StringComparison.Ordinal)).ToList();
         if (t.Skip(outcomes.Count == 0, "the shipped marriage rules are not loaded (see scenario_packs)")) return t.Line();

         Hero rhagaea = AliveRhagaea();
         Hero player = Hero.MainHero;
         if (t.Skip(rhagaea == null || player == null, "Rhagaea is not alive in this campaign")) return t.Line();
         if (t.Skip(rhagaea.Spouse == player, "Rhagaea is already the player's spouse in this save")) return t.Line();

         var firedBefore = new HashSet<string>(runtime.FiredRuleIds);
         if (t.Skip(outcomes.Any(r => firedBefore.Contains(r.Id)), "a marriage outcome is already sealed in this save")) return t.Line();

         // What the outcomes touch, kept to be put back exactly (a relation gain is scaled by the game, so no -delta).
         // Her profile is taken as the save has it: a marriage must play its outcome even when CR never recorded her yet.
         bool hadProfile = store.Get(rhagaea.StringId) != null;
         List<NotableEvent> eventsBefore = store.Get(rhagaea.StringId)?.Events.ToList() ?? new List<NotableEvent>();
         var worldBefore = new HashSet<string>(WorldEventStore.Instance.All().Select(e => e.Id));
         Campaign.Current.Models.DiplomacyModel.GetHeroesForEffectiveRelation(player, rhagaea, out Hero side1, out Hero side2);
         int relationBefore = CharacterRelationManager.GetHeroRelation(side1, side2);
         float influenceBefore = Clan.PlayerClan?.Influence ?? 0f;
         bool playerRules = player.MapFaction is Kingdom kingdom && kingdom.Leader == player;

         ScenarioContext wedding = ScenarioBehavior.ForMarriage(rhagaea, player);
         try
         {
            foreach (ScenarioRule rule in outcomes)
            {
               string name = rule.Id.Substring(prefix.Length);
               string memory = rule.Consequences.Where(c => c.Verb == "INJECT_MEMORY")
                                   .Select(c => ScenarioArgs.TryParseTargetRest(c.Payload, out _, out string text) ? text : null)
                                   .FirstOrDefault();

               // A runtime holding this outcome alone, through the REAL Fire: no other rule (another outcome, a mod's
               // marriage rule, repeatable or not) can play here, and the game's own seals are not touched.
               var solo = new ScenarioRuntime(new HashSet<string>(firedBefore));
               solo.Load(new[] {rule});
               IReadOnlyList<ScenarioRule> fired = solo.Fire(KeywordToken.Parse("ON_MARRIAGE"), wedding);

               if (rule.Guards.Any(g => g.Verb == "IF_PLAYER_RULES") && !playerRules)
               {
                  t.Expect($"{name}ClosedWithoutACrown", fired.Count, 0);
                  continue;
               }

               t.Expect($"{name}Fired", string.Join(",", fired.Select(r => r.Id)), rule.Id);
               if (fired.Count == 0) continue;

               bool remembered = memory == null || store.Get(rhagaea.StringId)?.Events.Any(e => e.summary == memory) == true;
               bool told = WorldEventStore.Instance.All().Any(e => !worldBefore.Contains(e.Id) && e.Summary == rule.Message);
               t.Expect($"{name}Remembered", remembered, true);
               t.Expect($"{name}Told", told, true);
               t.Expect($"{name}Sealed", solo.FiredRuleIds.Contains(rule.Id), true);
            }
         }
         finally
         {
            runtime.FiredRuleIds.Clear();
            foreach (string id in firedBefore) runtime.FiredRuleIds.Add(id);

            foreach (WorldEvent e in WorldEventStore.Instance.All().Where(e => !worldBefore.Contains(e.Id)).ToList())
               WorldEventStore.Instance.Remove(e.Id);

            NpcProfile profile = store.Get(rhagaea.StringId);
            if (!hadProfile && profile != null) store.Remove(rhagaea.StringId);
            else if (profile != null)
            {
               profile.Events.RemoveAll(e => !eventsBefore.Any(b => ReferenceEquals(b, e)));
               store.Set(profile);
            }

            side1.SetPersonalRelation(side2, relationBefore);
            float influenceDrift = influenceBefore - (Clan.PlayerClan?.Influence ?? 0f);
            if (Clan.PlayerClan != null && Math.Abs(influenceDrift) > 0.01f) ChangeClanInfluenceAction.Apply(Clan.PlayerClan, influenceDrift);
         }

         t.Note($"playerRules={playerRules}, hadProfile={hadProfile}, relation back to {CharacterRelationManager.GetHeroRelation(side1, side2)} (was {relationBefore})");

         return t.Line();
      }

      private static string TestSchemeAssist(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scheme_assist");

         if (t.Abort(SchemeStore.Instance == null, "SchemeStore not active")) return t.Line();


         // Pick actors NOT already entangled in an active scheme, so an earlier test's plot
         // (e.g. scheme_warn leaving one Discovered) can't taint the precondition here.
         bool Free(Hero h)
         {
            return !SchemeStore.Instance.Active.Any(s => s.PlotterId == h.StringId || s.TargetId == h.StringId);
         }


         Hero plotter = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && h.Clan != Clan.PlayerClan && Free(h));
         // The target must NOT be allied with the player (relation < 20, different faction)
         Hero target = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != plotter && h != Hero.MainHero && h.IsLord && h.MapFaction != Hero.MainHero?.MapFaction && h.GetRelation(Hero.MainHero) < VanillaRelation.TrustedTier && h.Clan != plotter?.Clan && Free(h));

         if (t.Skip(plotter == null || target == null, "need a fresh plotter + non-allied target (none unentangled)")) return t.Line();

         SchemeStore.Instance.ForcePlot(plotter, target, SchemeKind.Slander);
         ChangeRelationAction.ApplyRelationChangeBetweenHeroes(plotter, Hero.MainHero, 60, false); // plotter now regards the player
         int regard = plotter.GetRelation(Hero.MainHero);

         string msg = SchemeStore.Instance.PlayerAssists(plotter);

         if (t.Skip(msg == null, $"plot not recruitable (regard={regard}, need >=20; or alliance/state) — env-dependent")) return t.Line();

         Scheme scheme = SchemeStore.Instance.Active.FirstOrDefault(s => s.PlotterId == plotter.StringId);
         t.Note($"plotter={plotter.Name} -> {target.Name}, regard={regard}");
         // The aid advanced the plot (progress > 0) or carried it to completion (no longer active)
         t.Expect("plotAdvancedOrDone", scheme == null || scheme.Progress > 0, true);

         return t.Line();
      }

      private static string TestSchemeWarn(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("scheme_warn");

         if (t.Abort(SchemeStore.Instance == null, "SchemeStore not active")) return t.Line();

         // Nobody already entangled: ForcePlot refuses to lay a plot over a live one, so a pair left over from an
         // earlier run would leave nothing warnable and fail on a world this test itself made. The plotter must
         // also be grudge-free, so the cleanup below clears exactly the grudge that warning the target plants.
         var today = (int) CampaignTime.Now.ToDays;
         Hero plotter = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != Hero.MainHero && h.IsLord && h.Clan != Clan.PlayerClan
            && !SchemeStore.Instance.Active.Any(sc => sc.PlotterId == h.StringId)
            && (GrudgeBehavior.Instance?.LiveGrudgesFor(h, today)?.Count ?? 0) == 0);
         Hero target = Hero.AllAliveHeroes.FirstOrDefault(h =>
            h != plotter && h != Hero.MainHero && h.IsLord && h.Clan != null && h.Clan != plotter?.Clan && h.Clan != Clan.PlayerClan
            && !SchemeStore.Instance.Active.Any(sc => sc.TargetId == h.StringId));

         if (t.Skip(plotter == null || target == null, "need 2+ unentangled lords from distinct non-player clans")) return t.Line();

         int plotterBefore = behavior.GameStateBridge.GetPlayerRelation(plotter);
         int targetBefore = behavior.GameStateBridge.GetPlayerRelation(target);

         try
         {
            // Both relations arranged at 0 first, restored by the finally (17/10/2026: the target already stood at the
            // +100 cap in a save made after earlier runs, so his +26 gratitude could not show).
            ChangeRelationAction.ApplyRelationChangeBetweenHeroes(plotter, Hero.MainHero, -plotterBefore, false);
            ChangeRelationAction.ApplyRelationChangeBetweenHeroes(target, Hero.MainHero, -targetBefore, false);
            int plotterArranged = behavior.GameStateBridge.GetPlayerRelation(plotter);
            int targetArranged = behavior.GameStateBridge.GetPlayerRelation(target);

            SchemeStore.Instance.ForcePlot(plotter, target, SchemeKind.Slander);

            string msg = SchemeStore.Instance.TargetHeeds(target);

            if (t.Abort(msg == null, $"TargetHeeds({target.Name}) returned null: no eligible scheme after ForcePlot")) return t.Line();

            int plotterDelta = behavior.GameStateBridge.GetPlayerRelation(plotter) - plotterArranged;
            int targetDelta = behavior.GameStateBridge.GetPlayerRelation(target) - targetArranged;
            t.Note($"plotter={plotter.Name} delta={plotterDelta} (was {plotterBefore}) | target={target.Name} delta={targetDelta} (was {targetBefore})");
            t.Expect("plotterResents(<=-20)", plotterDelta <= -20, true);
            t.Expect("targetGrateful(>=16)", targetDelta >= 16, true);
         }
         finally
         {
            // Warning a target moves REAL vanilla relations and plants a real grudge. Left standing, a diagnostic
            // sweep would quietly turn a lord against the player in a campaign that never played the scene.
            ChangeRelationAction.ApplyRelationChangeBetweenHeroes(plotter, Hero.MainHero,
               plotterBefore - behavior.GameStateBridge.GetPlayerRelation(plotter), false);
            ChangeRelationAction.ApplyRelationChangeBetweenHeroes(target, Hero.MainHero,
               targetBefore - behavior.GameStateBridge.GetPlayerRelation(target), false);
            GrudgeBehavior.Instance?.ClearGrudgesFor(plotter.StringId);
            SchemeStore.Instance.DebugForgetSchemesBetween(plotter, target);
         }

         return t.Line();
      }

      // ── DIVORCE, Phase 2b: the player's OWN spouse demands the divorce ────────────────────────────

      /// <summary>
      ///   Scenario A (accept): marries the player to a test spouse when unmarried (reuses the real
      ///   marriage if the campaign already has one), force-demands, then exercises accept_divorce through
      ///   the real bridge path — asserts the marriage dissolved, neither party left clanless, and the
      ///   demand flag cleared. Scenario B (decline): marries the player to a SECOND test spouse (freed up
      ///   by Scenario A's dissolution), force-demands, exercises decline_divorce — asserts the demand flag
      ///   cleared (so it can resurface) and a GrudgeSource.Divorce grudge planted on the refused spouse.
      ///   Best-effort: either scenario is skipped, with a note, on a barren campaign (no eligible test
      ///   spouse to seed), without failing the other.
      /// </summary>
      private static string TestSpouseDivorceDemand(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("spouse_divorce");

         if (t.Abort(SpouseDivorceDemandBehavior.Instance == null, "SpouseDivorceDemandBehavior not active")) return t.Line();
         if (t.Abort(GrudgeBehavior.Instance == null, "GrudgeBehavior not active")) return t.Line();

         var demands = SpouseDivorceDemandBehavior.Instance;

         // ── Scenario A: ACCEPT ───────────────────────────────────────────────────────────────────
         Hero spouseA = Hero.MainHero.Spouse;

         if (spouseA == null)
         {
            spouseA = FindTestSpouseForPlayer();

            if (t.Skip(spouseA == null, "no eligible test spouse found to marry the player (scenario A)")) return t.Line();

            // GABRIEL'S RULE (13/10/2026): try the native pipeline, fall back to the direct seed form rather
            // than report MANUAL when the context can be arranged. Seeding is still best-effort: skip cleanly
            // rather than mis-report the demand path as broken. The path itself is exercised in full whenever
            // the player already has a spouse.
            string seedPathA = SeedPlayerMarriage(spouseA, viaCr: false);
            t.Note($"scenario A seed path={seedPathA ?? "none"}");

            if (t.Skip(seedPathA == null,
                   "could not seed a marriage on this campaign (neither the native MarriageAction nor the direct fallback took); demand path unchanged")) return t.Line();
         }

         NpcProfile profileA = GetOrCreate(behavior, spouseA);
         ArrangeCleanNpc(behavior, profileA, spouseA);

         demands.ForceDemand();
         bool demandingBeforeAccept = demands.IsDemanding(spouseA.StringId);

         if (t.Abort(!demandingBeforeAccept, "force-demand did not set the flag (scenario A)")) return t.Line();

         // M-R6: a divorce must clear a stale IsConsort flag on the ex-partner (nothing else ever reset it). Seed
         // one so the accept path (which flows through MarriageDissolutionService.TryDissolve) is proven to clear it.
         bool consortSeeded = profileA.Romantic != null;
         if (consortSeeded)
         {
            profileA.Romantic.IsConsort = true;
            behavior.Store.Set(profileA);
         }

         ActionOutcome acceptOutcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "accept_divorce"}, spouseA, new ActionContext(profileA, null));

         bool consortClearedAfterDivorce = !consortSeeded
                                           || behavior.Store.Get(spouseA.StringId)?.Romantic?.IsConsort != true;
         t.Expect("consortFlagClearedAfterDivorce", consortClearedAfterDivorce, true);

         bool dissolved = Hero.MainHero.Spouse == null;
         bool neitherClanless = Hero.MainHero.Clan != null && spouseA.Clan != null;
         bool flagClearedAfterAccept = !demands.IsDemanding(spouseA.StringId);

         t.Note($"scenario A (accept) spouse={spouseA.Name}: outcome={(acceptOutcome != null ? acceptOutcome.IsPositive.ToString() : "null")}");
         t.Expect("acceptOutcomePositive", acceptOutcome is {IsPositive: true}, true);
         t.Expect("dissolvedAfterAccept", dissolved, true);
         t.Expect("neitherClanlessAfterAccept", neitherClanless, true);
         t.Expect("demandFlagClearedAfterAccept", flagClearedAfterAccept, true);

         // ── Scenario B: DECLINE — a second, distinct test spouse (the player is free again after A) ──
         Hero spouseB = FindTestSpouseForPlayer(spouseA);

         if (t.Skip(spouseB == null, "no second eligible test spouse found for the decline scenario")) return t.Line();

         string seedPathB = SeedPlayerMarriage(spouseB, viaCr: false);
         t.Note($"scenario B seed path={seedPathB ?? "none"}");

         if (t.Skip(seedPathB == null,
                "could not seed the second marriage on this campaign (neither the native MarriageAction nor the direct fallback took); decline path unexercised")) return t.Line();

         NpcProfile profileB = GetOrCreate(behavior, spouseB);
         ArrangeCleanNpc(behavior, profileB, spouseB);

         demands.ForceDemand();
         bool demandingBeforeDecline = demands.IsDemanding(spouseB.StringId);

         if (t.Abort(!demandingBeforeDecline, "force-demand did not set the flag (scenario B)")) return t.Line();

         int today = behavior.GameStateBridge.GetCurrentGameDay();
         int relBeforeDecline = spouseB.GetRelation(Hero.MainHero); // ~0 (ArrangeCleanNpc neutralised it)

         ActionOutcome declineOutcome = behavior.GameStateBridge.ExecuteAction(
            new GameAction {Type = "decline_divorce"}, spouseB, new ActionContext(profileB, null));

         bool stillMarriedAfterDecline = Hero.MainHero.Spouse == spouseB;
         bool flagClearedAfterDecline = !demands.IsDemanding(spouseB.StringId);
         bool refusalGrudgePlanted = GrudgeBehavior.Instance.GrudgesFor(spouseB.StringId)
                                                   .Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == today);
         // M-D4 guard: each refusal must also cost a little vanilla relation, or a grudge-triggered demand loops
         // forever (nothing lowers the relation ShouldEscalate gates on). The drip must be visible here.
         bool refusalDroppedRelation = spouseB.GetRelation(Hero.MainHero) < relBeforeDecline;

         t.Note($"scenario B (decline) spouse={spouseB.Name}: outcome={(declineOutcome != null ? declineOutcome.IsPositive.ToString() : "null")}, relation {relBeforeDecline}->{spouseB.GetRelation(Hero.MainHero)}");
         t.Expect("stillMarriedAfterDecline", stillMarriedAfterDecline, true);
         t.Expect("demandFlagClearedAfterDecline", flagClearedAfterDecline, true);
         t.Expect("refusalGrudgePlanted", refusalGrudgePlanted, true);
         t.Expect("refusalDroppedRelation", refusalDroppedRelation, true);

         // ── Scenario C (M-D5): DEMAND-PHASE RECONCILIATION on the still-married spouseB ──
         // Re-open a demand, warm the player's PERSONAL regard above the reconciliation bar, tick: the demand
         // must be WITHDRAWN (not ground into another refusal), mirroring the escalation-phase reconciliation.
         demands.ForceDemand();
         bool demandingBeforeReconcile = demands.IsDemanding(spouseB.StringId);
         profileB.ReputationWithPlayer = SpouseDivorceDemandPolicy.ReconciliationThreshold + 5;
         behavior.Store.Set(profileB);
         demands.RunTick();

         bool demandWithdrawnOnReconcile = demandingBeforeReconcile && !demands.IsDemanding(spouseB.StringId) && Hero.MainHero.Spouse == spouseB;
         t.Note($"scenario C (demand-phase reconciliation) spouse={spouseB.Name}: withdrawn={demandWithdrawnOnReconcile}");
         t.Expect("demandWithdrawnOnReconciliation", demandWithdrawnOnReconcile, true);

         // The scenario leaves them wed by design; the test's own seed is undone (Gabriel's new-game run, 14/10/2026).
         if (Hero.MainHero.Spouse == spouseB) MarriageDissolutionService.TryDissolvePlayerMarriage(spouseB, out _);

         return t.Line();
      }

      // ── DIVORCE ESCALATION: a refused-enough, still-miserable spouse begins ending it themselves ──

      /// <summary>
      ///   Scenario A (walk-out): marries the player to a test spouse when unmarried, force-escalates
      ///   (bypassing the natural refusal-count gate), then force-moves the deadline to TODAY so the sweep
      ///   walks out immediately rather than waiting the real estrangement length — asserts the marriage
      ///   dissolved, neither party left clanless, a spouse-side Divorce grudge planted, and the escalation
      ///   record cleared. Scenario B (reconciliation): marries the player to a SECOND test spouse
      ///   (freed up by Scenario A's dissolution), force-escalates, then raises the relation ABOVE
      ///   <see cref="SpouseDivorceDemandPolicy.ReconciliationThreshold" /> BEFORE ticking — asserts the
      ///   marriage SURVIVES and the escalation record is cleared. Best-effort: either scenario is skipped,
      ///   with a note, on a barren campaign (no eligible test spouse to seed), without failing the other.
      /// </summary>
      private static string TestSpouseEstrangement(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("spouse_estrangement");

         if (t.Abort(SpouseDivorceDemandBehavior.Instance == null, "SpouseDivorceDemandBehavior not active")) return t.Line();
         if (t.Abort(GrudgeBehavior.Instance == null, "GrudgeBehavior not active")) return t.Line();
         if (t.Abort(WorldEventStore.Instance == null, "WorldEventStore not active")) return t.Line();

         var demands = SpouseDivorceDemandBehavior.Instance;

         // ── Scenario A: WALK-OUT ─────────────────────────────────────────────────────────────────
         Hero spouseA = Hero.MainHero.Spouse;

         if (spouseA == null)
         {
            spouseA = FindTestSpouseForPlayer();

            if (t.Skip(spouseA == null, "no eligible test spouse found to marry the player (scenario A)")) return t.Line();

            // GABRIEL'S RULE (13/10/2026): try the native pipeline, fall back to the direct seed form rather
            // than report MANUAL when the context can be arranged.
            string seedPathA = SeedPlayerMarriage(spouseA, viaCr: false);
            t.Note($"scenario A seed path={seedPathA ?? "none"}");

            if (t.Skip(seedPathA == null,
                   "could not seed a marriage on this campaign (neither the native MarriageAction nor the direct fallback took); walk-out path unexercised")) return t.Line();
         }

         NpcProfile profileA = GetOrCreate(behavior, spouseA);
         ArrangeCleanNpc(behavior, profileA, spouseA); // neutral relation — comfortably below the reconciliation bar

         (bool forcedA, string forceMessageA) = demands.ForceEscalate();
         bool estrangingBeforeTick = demands.IsEstranging(spouseA.StringId);

         if (t.Abort(!forcedA || !estrangingBeforeTick, $"force-escalate did not set the record (scenario A): {forceMessageA}")) return t.Line();

         int todayA = behavior.GameStateBridge.GetCurrentGameDay();
         demands.DebugForceEscalationDeadline(spouseA.StringId, todayA); // skip the 15-day wait for this test

         int worldEventsBefore = WorldEventStore.Instance.Count;
         int relBeforeWalkOut = spouseA.GetRelation(Hero.MainHero); // baseline (ArrangeCleanNpc neutralised it to ~0)

         demands.RunTick();

         bool dissolvedA = Hero.MainHero.Spouse == null;
         bool neitherClanlessA = Hero.MainHero.Clan != null && spouseA.Clan != null;
         bool escalationClearedAfterWalkOut = !demands.IsEstranging(spouseA.StringId);
         bool walkOutGrudgePlanted = GrudgeBehavior.Instance.GrudgesFor(spouseA.StringId)
                                                   .Any(g => g.Source == GrudgeSource.Divorce && g.EventDay == todayA);
         bool worldEventRecorded = WorldEventStore.Instance.Count > worldEventsBefore;
         // M-D1 guard: the walk-out must SET the relation from the pre-dissolution baseline (a moderate hit),
         // never leave the engine's hidden dissolution penalty (observed crashing to -100) standing. A moderate
         // result stays well clear of that crash; without the SET this assertion fails.
         int relAfterWalkOut = spouseA.GetRelation(Hero.MainHero);
         bool walkOutRelationModerate = relAfterWalkOut > -50;

         t.Note($"scenario A (walk-out) spouse={spouseA.Name}, relation {relBeforeWalkOut}->{relAfterWalkOut}");
         t.Expect("dissolvedAfterWalkOut", dissolvedA, true);
         t.Expect("neitherClanlessAfterWalkOut", neitherClanlessA, true);
         t.Expect("escalationClearedAfterWalkOut", escalationClearedAfterWalkOut, true);
         t.Expect("walkOutGrudgePlanted", walkOutGrudgePlanted, true);
         t.Expect("walkOutWorldEventRecorded", worldEventRecorded, true);
         t.Expect("walkOutRelationModerateNotCrashed", walkOutRelationModerate, true);

         // ── Scenario B: RECONCILIATION — a second, distinct test spouse (the player is free again after A) ──
         Hero spouseB = FindTestSpouseForPlayer(spouseA);

         if (t.Skip(spouseB == null, "no second eligible test spouse found for the reconciliation scenario")) return t.Line();

         string seedPathB = SeedPlayerMarriage(spouseB, viaCr: false);
         t.Note($"scenario B seed path={seedPathB ?? "none"}");

         if (t.Skip(seedPathB == null,
                "could not seed the second marriage on this campaign (neither the native MarriageAction nor the direct fallback took); reconciliation path unexercised")) return t.Line();

         NpcProfile profileB = GetOrCreate(behavior, spouseB);
         ArrangeCleanNpc(behavior, profileB, spouseB);

         (bool forcedB, string forceMessageB) = demands.ForceEscalate();

         if (t.Abort(!forcedB, $"force-escalate did not set the record (scenario B): {forceMessageB}")) return t.Line();

         // Reconciliation is read from the mod's PERSONAL regard (ReputationWithPlayer), the number the player
         // warms through conversation, NOT the vanilla clan relation (SweepEscalations reads exactly that). Set
         // THAT signal above the bar, or the sweep never sees the reconciliation this scenario is meant to prove.
         profileB.ReputationWithPlayer = SpouseDivorceDemandPolicy.ReconciliationThreshold + 5; // comfortably above the bar
         behavior.Store.Set(profileB);

         // Deadline is left far in the future (set by ForceEscalate itself) — reconciliation must win on its
         // own merits, checked BEFORE the deadline, not because the deadline happened to be reached too.
         demands.RunTick();

         bool stillMarriedAfterReconciliation = Hero.MainHero.Spouse == spouseB;
         bool escalationClearedAfterReconciliation = !demands.IsEstranging(spouseB.StringId);

         t.Note($"scenario B (reconciliation) spouse={spouseB.Name}");
         t.Expect("stillMarriedAfterReconciliation", stillMarriedAfterReconciliation, true);
         t.Expect("escalationClearedAfterReconciliation", escalationClearedAfterReconciliation, true);

         // The scenario leaves them wed by design; the test's own seed is undone (Gabriel's new-game run, 14/10/2026).
         if (Hero.MainHero.Spouse == spouseB) MarriageDissolutionService.TryDissolvePlayerMarriage(spouseB, out _);

         return t.Line();
      }

      /// <summary>
      ///   The STARVING LORD bug, reproduced and then proven fixed against the live engine. A player watched a
      ///   clan party that had intercepted him stand on one spot until its food ran out and it starved (Fakade,
      ///   2026-07-13). The cause: we ended the chase with SetMoveModeHold, believing it handed the lord back to
      ///   his own AI. It does the opposite. Hold is not a release, it is an ORDER to stand still, and the party's
      ///   AI, seeing a behaviour it considers perfectly valid, never reconsidered it. He obeyed until he died.
      ///   <para>
      ///     This freezes a real lord party exactly as the old code did, proves it looks frozen, then proves both
      ///     halves of the fix: the release hands a party back, and the on-load rescue frees one already stranded
      ///     by an earlier version (without which a broken campaign stays broken forever).
      ///   </para>
      /// </summary>
      private static string TestInterceptionHoldsCourse(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("interception_holds_course");

         if (t.Abort(Interception.InterceptionBehavior.Instance == null, "interception behavior not initialized")) return t.Line();

         MobileParty lordParty = MobileParty.All.FirstOrDefault(
            p => p != null && p != MobileParty.MainParty && p.LeaderHero is {IsLord: true}
                 && p.CurrentSettlement == null && p.Army == null && p.MapEvent == null && !p.IsCurrentlyAtSea);
         if (t.Skip(lordParty == null, "no free lord party in the open field")) return t.Line();

         var read = Interception.InterceptionBehavior.Instance.DebugSteerAndRelease(lordParty);
         if (t.Skip(read == null, "a real pursuit is under way; not disturbing it")) return t.Line();

         t.Note($"{lordParty.Name}: locked {read.Value.Locked}, on the player {read.Value.OnThePlayer}, free after {read.Value.FreeAfter}, thinks again {read.Value.ThinksAgainAfter}");
         // Held on course only while MCM "Lords Hold Their Course" is on (Fakade, 03/10/2026); off, the order alone, as before 2.6.8.
         t.Expect("heIsHeldOnCourseAsTheMenuSays", read.Value.Locked, ModSettings.LordsHoldTheirCourse);
         t.Expect("heRidesAtThePlayer", read.Value.OnThePlayer, true);
         t.Expect("theChaseOverHisDecisionsAreHisOwn", read.Value.FreeAfter, true);
         t.Expect("andHeIsToldToThinkAfresh", read.Value.ThinksAgainAfter, true);

         return t.Line();
      }

      private static string TestPartyRelease(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("party_release");

         MobileParty victim = MobileParty.All.FirstOrDefault(
            p => p != null && p != MobileParty.MainParty && p.LeaderHero != null
                 && p.CurrentSettlement == null && p.Army == null && p.MapEvent == null);

         if (t.Skip(victim == null, "no free lord party in the open field to release")) return t.Line();

         AiBehavior wasDoing = victim.DefaultBehavior;
         t.Note($"{victim.Name}: was {wasDoing}");

         // Freeze it EXACTLY as the old code did, and prove that this alone is what stranded the party: it sits
         // on Hold with nothing telling it to think again, which is precisely how a lord starved in place.
         victim.SetMoveModeHold();
         victim.Ai.RethinkAtNextHourlyTick = false;

         t.Expect("theOldStandDownLeavesItHolding", victim.DefaultBehavior, AiBehavior.Hold);
         t.Expect("andWithNothingTellingItToThinkAgain", victim.Ai.RethinkAtNextHourlyTick, false);

         // The fix: releasing it must actually hand it back, which means MAKING it decide afresh.
         InterceptionBehavior.ReleaseToVanillaAi(victim);
         t.Expect("theReleaseMakesItThinkAgain", victim.Ai.RethinkAtNextHourlyTick, true);
         t.Expect("andNothingOfOursHoldsItsDecisionsShut", victim.Ai.DoNotMakeNewDecisions, false);

         // The rescue: a campaign already broken by an earlier version must heal on load, or the stranded party
         // starves anyway however well we fixed the cause.
         victim.SetMoveModeHold();
         victim.Ai.RethinkAtNextHourlyTick = false;
         int freed = InterceptionBehavior.RescueHeldParties();

         t.Note($"on-load rescue nudged {freed} held party(ies)");
         t.Expect("theOnLoadRescueFreesAnAlreadyStrandedParty", victim.Ai.RethinkAtNextHourlyTick, true);
         t.Expect("andItFoundAtLeastTheOneWeStranded", freed >= 1, true);

         return t.Line();
      }

      /// <summary>
      ///   A lord who can actually BE GIVEN a quest: one with no outstanding task already on their plate. The
      ///   pipeline correctly refuses a second one ("offered a task while one is outstanding"), so a test that
      ///   simply grabbed the first lord it found would fail on a perfectly legitimate refusal and blame the
      ///   pipeline for it. Null when every lord is already busy.
      /// </summary>
      private static Hero FreeQuestGiver(NpcMemoryCampaignBehavior behavior)
         => Hero.AllAliveHeroes.FirstOrDefault(
            h => h != null && h != Hero.MainHero && h.IsAlive && h.IsLord && !HasOutstandingQuest(behavior, h));

      /// <summary>True when this hero already holds a task the player has not settled, which bars a new one.</summary>
      private static bool HasOutstandingQuest(NpcMemoryCampaignBehavior behavior, Hero hero)
      {
         NpcProfile p = behavior?.Store?.Get(hero.StringId);

         return p != null && p.ActiveQuests.Any(q => q.IsOutstanding);
      }

      /// <summary>
      ///   A THROWAWAY profile for a hero whose only memory is sixty days stale, so the elapsed-gap note would
      ///   certainly fire. Never stored, so it mutates nothing. Built fresh rather than aged in place, because
      ///   the gap is measured from the NEWEST memory: adding an old event to a live profile that already holds
      ///   a fresher one changes nothing at all, and the assertion would then pass for the wrong reason.
      /// </summary>
      private static NpcProfile AgedProfile(Hero hero, int today)
      {
         NpcProfile p = HeroProfileMapper.FromHero(hero);
         p.Events.Add(new NotableEvent(today - 60, NotableEventType.Other, "(selftest) a memory sixty days stale"));

         return p;
      }

      /// <summary>
      ///   The in-chat Options button, which a player reported dead across three versions (SuperGraham339, still
      ///   reproducing in v1.30.14). It reaches the vanilla escape menu entirely by REFLECTION, so a TaleWorlds
      ///   rename does not throw: the button just goes quiet, and the log even claims success. That is the exact
      ///   shape of the bug he lived with. The game answers ESC with TWO different mechanisms (a mission view
      ///   while a scene is loaded, a navigation handler on the map) and the mod must find BOTH, because whichever
      ///   one it fails to find is a screen on which the player's menu will never appear. This asserts they still
      ///   resolve on the running game version, and says which path is live right now.
      /// </summary>
      private static string TestMenu(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("menu");

         var (missionMechanism, mapMechanism, missionRunning, escapeViewPresent, detail) = GameMenuOpener.Probe();

         t.Note(detail);

         // The mission mechanism is the one that was MISSING until now: the chat can be hosted by a MissionScreen
         // (a settlement, a conversation, a naval scene), which carries no navigation handler at all, so the menu
         // was being opened on the map hidden behind the scene.
         t.Expect("theMissionEscapeMechanismStillExists", missionMechanism, true);

         // And the map one must survive too, or the button dies on the ordinary campaign map instead.
         t.Expect("theMapEscapeMechanismStillExists", mapMechanism, true);

         // Only assertable when a scene happens to be loaded; on the bare map there is no mission to carry a view.
         if (missionRunning) t.Expect("aRunningMissionCarriesItsEscapeView", escapeViewPresent, true);
         else t.Note("no mission running during the test, so the mission-side view could not be inspected live: open the chat inside a settlement and click Options to confirm by eye");

         return t.Line();
      }

      /// <summary>
      ///   Player report: the letter view's decorative Galahad font has no proper Cyrillic glyphs, so a Russian
      ///   game language rendered it through a broken per-glyph fallback (miscentered, unreadable). Proves both
      ///   halves: the pure <see cref="LetterFontPolicy" /> decision, and the actual wiring into
      ///   <see cref="LetterViewModel" />'s BodyBrush/HeadingBrush/InputBrush bindings via
      ///   <see cref="LetterFontResolver.LanguageIdProvider" /> forced to the Russian id (no real game-language
      ///   switch, so this never disturbs a live campaign). Restores the seam in a finally.
      /// </summary>
      private static string TestLetterFont(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("letter_font");

         // STAKE: this policy's whole purpose. "Русский" is the id TaleWorlds.Localization.MBTextManager
         // .ActiveTextLanguage actually returns for Russian (verified against this engine build's own
         // Native/ModuleData/Languages/RU/language_data.xml, id="Русский").
         t.Expect("policyPrefersPlainFontForRussian", LetterFontPolicy.PreferPlainFont("Русский"), true);

         // STAKE: the decorative parchment look (Galahad) must survive for the game's default/dev language.
         t.Expect("policyKeepsDecorativeFontForEnglish", LetterFontPolicy.PreferPlainFont("English"), false);

         Func<string> priorProvider = LetterFontResolver.LanguageIdProvider;
         try
         {
            var vm = new LetterViewModel();

            // STAKE: the pure policy alone does not prove the VM actually reads it: a wiring slip (wrong brush
            // name, a binding never refreshed) would leave the player's letters broken even with a correct policy.
            LetterFontResolver.LanguageIdProvider = () => "Русский";
            t.Expect("vmBodyBrushIsPlainForRussian", vm.BodyBrush, "CR.Letter.Body.Plain");
            t.Expect("vmHeadingBrushIsPlainForRussian", vm.HeadingBrush, "CR.Letter.Heading.Plain");
            t.Expect("vmInputBrushIsPlainForRussian", vm.InputBrush, "CR.Letter.Input.Plain");

            LetterFontResolver.LanguageIdProvider = () => "English";
            t.Expect("vmBodyBrushStaysDecorativeForEnglish", vm.BodyBrush, "CR.Letter.Body");
            t.Expect("vmHeadingBrushStaysDecorativeForEnglish", vm.HeadingBrush, "CR.Letter.Heading");
            t.Expect("vmInputBrushStaysDecorativeForEnglish", vm.InputBrush, "CR.Letter.Input");
         }
         finally
         {
            LetterFontResolver.LanguageIdProvider = priorProvider;
         }

         return t.Line();
      }

      // Fakade (Nexus, 12/11/2026): an action out of reach is shown greyed with its reason, and a free lord's
      // recruitment is one of the rows. Drives the menu's real fact resolution on live lords; the per-gate wording
      // lives in ManualMenuGreyedRowsTests.
      private static string TestActionsMenuLordJoin(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("actions_menu_lord_join");
         Hero player = Hero.MainHero;
         if (t.Abort(player == null || behavior?.Store == null || behavior.GameStateBridge == null, "the campaign or the store is not ready")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsPrisoner && !h.IsChild && h.Clan != null && h.Clan != Clan.PlayerClan
                                                           && h.Clan.Leader != h && h != player);
         Hero leader = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsLord && !h.IsPrisoner && h.Clan != null && h.Clan != Clan.PlayerClan && h.Clan.Leader == h);
         if (t.Skip(lord == null || leader == null, "no lord of another house who is not its leader, or no leader of another house")) return t.Line();

         NpcProfile profile = GetOrCreate(behavior, lord);
         int priorRegard = profile.ReputationWithPlayer;

         ManualActionStatus Join(Hero h) => Chat.ManualActionMenuController.DebugDescribe(h, behavior.Store.Get(h.StringId), behavior.GameStateBridge)
                                                                         .SingleOrDefault(x => x.Entry.Type == ManualActionCatalog.JoinClan.Type);

         try
         {
            string regardBar = LordRecruitment.MinRelation.ToString();

            profile.ReputationWithPlayer = LordRecruitment.MinRelation - 30;
            behavior.Store.Set(profile);
            ManualActionStatus low = Join(lord);
            t.Note($"{lord.Name}: at regard {profile.ReputationWithPlayer}, {low?.State} ({low?.Reason})");
            // STAKE: the player sees the lord could be recruited, and what regard it takes.
            t.Expect("lowRegardIsListedBlocked", low?.State, ManualActionState.Blocked);
            t.Expect("lowRegardNamesTheRegardNeeded", low?.Reason?.Contains(regardBar) == true, true);

            profile.ReputationWithPlayer = 95;
            behavior.Store.Set(profile);
            ManualActionStatus high = Join(lord);
            t.Note($"{lord.Name}: at regard 95, {high?.State} ({high?.Reason})");
            // STAKE: once the regard is there, the row names the next gate (or opens), never the regard again.
            t.Expect("highRegardIsNoLongerTheReason", high != null && high.Reason.Contains(regardBar) == false, true);

            ManualActionStatus head = Join(leader);
            t.Note($"{leader.Name} leads {leader.Clan?.Name}: {head?.State}");
            // STAKE: a clan leader is never offered what the bridge would always refuse.
            t.Expect("aClanLeaderNeverJoins", head?.State, ManualActionState.NotForThisPerson);

            // STAKE: the menu lists open and out-of-reach rows only, never the folded "never" rank.
            bool menuHasNever = ManualActionAvailability.MenuRows(new ManualActionFacts()).Any(x => x.State == ManualActionState.NotForThisPerson);
            t.Expect("menuLeavesOutTheNeverRank", menuHasNever, false);
         }
         finally
         {
            NpcProfile now = behavior.Store.Get(lord.StringId);
            if (now != null)
            {
               now.ReputationWithPlayer = priorRegard;
               behavior.Store.Set(now);
            }
         }

         return t.Line();
      }

      // Manual action-injection menu (2026-08-21): the pure ManualActionAvailability gate deciding which
      // catalog entries the menu offers for a given snapshot of facts. Mechanical and engine-free by
      // construction (no Hero, no bridge call), so this drives it directly against seeded facts rather than
      // through a live conversation; the exhaustive per-gate coverage lives in
      // ManualActionAvailabilityTests (CalradiaRemembers.Tests), this is the self-test smoke line proving the
      // wiring the task brief itself named: a held prisoner exposes execute/free/recruit, and a non-ruler
      // hides grant_fief while keeping the always-on take_gold baseline.
      private static string TestManualConceptionEntry(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("manual_conception_entry");
         CrSettings s = CrSettings.Instance;
         Hero player = Hero.MainHero;
         if (t.Abort(s?.AdultContentLevel == null || player == null || behavior?.Store == null, "MCM or the store is not ready")) return t.Line();

         // Arranged: someone the player could have a child with (a woman of 18 to 45 for a man, a man for a woman).
         Hero partner = Hero.AllAliveHeroes.FirstOrDefault(h => h != player && !h.IsPrisoner && h.IsFemale != player.IsFemale && !h.IsChild
                                                                && (h.IsFemale ? h.Age >= 18 && h.Age <= 45 : player.Age >= 18 && player.Age <= 45));
         if (t.Skip(partner == null, "no one of the other sex and of fertile age in the world")) return t.Line();

         int priorLevel = s.AdultContentLevel.SelectedIndex;
         NpcProfile profile = GetOrCreate(behavior, partner);
         RomanticStatus? priorStatus = profile.Romantic?.Status;
         bool priorConsort = profile.Romantic?.IsConsort ?? false;

         ManualActionStatus Entry() => Chat.ManualActionMenuController.DebugDescribe(partner, behavior.Store.Get(partner.StringId), behavior.GameStateBridge)
                                                                       .SingleOrDefault(x => x.Entry.Type == ManualActionCatalog.ConceptionRisk.Type);

         try
         {
            if (profile.Romantic == null) profile.Romantic = new RomanticProfile();
            profile.Romantic.IsConsort = false;
            profile.Romantic.Status = RomanticStatus.Intimate;
            behavior.Store.Set(profile);

            s.AdultContentLevel.SelectedIndex = 2; // Explicit
            ManualActionStatus asLovers = Entry();
            t.Note($"{partner.Name}: lovers at Explicit {asLovers?.State}");
            // STAKE: lovers whose scene was missed can record it by hand.
            t.Expect("loversMayRecordTheScene", asLovers?.State == ManualActionState.Open, true);

            profile.Romantic.Status = RomanticStatus.None;
            behavior.Store.Set(profile);
            if (partner.Spouse != player)
            {
               // STAKE: with someone who is not a lover, the scene is not even shown.
               t.Expect("notListedForAStranger", Entry() == null, true);
            }

            profile.Romantic.Status = RomanticStatus.Intimate;
            behavior.Store.Set(profile);
            s.AdultContentLevel.SelectedIndex = 1; // Mature
            // STAKE: below Explicit the option is not even listed.
            t.Expect("notListedBelowExplicit", Entry() == null, true);
         }
         finally
         {
            s.AdultContentLevel.SelectedIndex = priorLevel;
            NpcProfile now = behavior.Store.Get(partner.StringId);
            if (now?.Romantic != null)
            {
               now.Romantic.Status = priorStatus ?? RomanticStatus.None;
               now.Romantic.IsConsort = priorConsort;
               behavior.Store.Set(now);
            }
         }

         return t.Line();
      }

      private static string TestManualActionMenu(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("manual_action_menu");

         var heldEligible = new ManualActionFacts {NpcIsPlayerPrisoner = true, CanRecruitPrisoner = true};
         IReadOnlyList<ManualActionEntry> heldEligibleAvailable = ManualActionAvailability.GetAvailable(heldEligible);
         t.Expect("heldEligibleExecute", heldEligibleAvailable.Contains(ManualActionCatalog.ExecutePrisoner), true);
         t.Expect("heldEligibleFree", heldEligibleAvailable.Contains(ManualActionCatalog.FreePrisoner), true);
         t.Expect("heldEligibleRecruit", heldEligibleAvailable.Contains(ManualActionCatalog.RecruitPrisoner), true);

         // Held but not (yet) eligible to turn: execute/free stand on custody alone, recruit needs its own
         // regard/clan-leader gate on top (PrisonerRecruitmentPolicy), guarding against the empty-promise
         // class of bug: a menu entry the bridge would only ever refuse.
         var heldIneligible = new ManualActionFacts {NpcIsPlayerPrisoner = true, CanRecruitPrisoner = false};
         IReadOnlyList<ManualActionEntry> heldIneligibleAvailable = ManualActionAvailability.GetAvailable(heldIneligible);
         t.Expect("heldIneligibleExecute", heldIneligibleAvailable.Contains(ManualActionCatalog.ExecutePrisoner), true);
         t.Expect("heldIneligibleFree", heldIneligibleAvailable.Contains(ManualActionCatalog.FreePrisoner), true);
         t.Expect("heldIneligibleRecruit", heldIneligibleAvailable.Contains(ManualActionCatalog.RecruitPrisoner), false);

         var nonRuler = new ManualActionFacts();
         IReadOnlyList<ManualActionEntry> nonRulerAvailable = ManualActionAvailability.GetAvailable(nonRuler);
         t.Expect("nonRulerNoGrantFief", nonRulerAvailable.Contains(ManualActionCatalog.GrantFief), false);
         t.Expect("nonRulerNoRecruitPrisoner", nonRulerAvailable.Contains(ManualActionCatalog.RecruitPrisoner), false);
         t.Expect("nonRulerStillHasTakeGold", nonRulerAvailable.Contains(ManualActionCatalog.TakeGold), true);

         return t.Line();
      }

      /// <summary>
      ///   The system prompt the LIVE pipeline would send for this hero, so a test can read what the model is
      ///   actually about to be told. Prefers the configured builder (the very one the chat uses); falls back to
      ///   a fresh one when no LLM is configured, so a mechanical test never has to be skipped for want of a key.
      /// </summary>
      private static string SystemPromptFor(NpcMemoryCampaignBehavior behavior, Hero npc, NpcProfile profile)
      {
         try
         {
            IPromptBuilder builder = behavior.LlmServices?.ChatService?.PromptBuilder ?? new PromptBuilder();
            var world = new WorldState {CurrentDay = behavior.GameStateBridge.GetCurrentGameDay()};
            EncounterContext ctx = EncounterContextBuilder.Build(npc, profile, behavior.GameStateBridge, "hello");

            return builder.BuildSystemPrompt(profile, world, ctx);
         }
         catch (Exception ex)
         {
            ModLog.Error($"[SELFTEST] could not build the system prompt: {ex.Message}");

            return null;
         }
      }

      /// <summary>
      ///   CONVICTION, end to end against the live prompt. A player asked to author what a character BELIEVES
      ///   rather than merely how they sound, and the existing backstory could not deliver it: its own prompt
      ///   section tells the model, in as many words, that it shapes how you SPEAK and not what you DECIDE. So a
      ///   belief written there was a costume. This test injects a conviction at runtime (no file edit), then
      ///   follows it along every link of the real chain: the loader hands it back, the chat's own per-turn sync
      ///   carries it onto the profile, and the section lands in the system prompt the model would actually
      ///   receive, saying that it moves what the NPC decides and carrying the three limits that keep it inside
      ///   the bridge (no powers, no imported lore, cannot bend the world). Finally it proves the MCM gate: turn
      ///   custom data off and the belief must leave the prompt entirely, not linger on a stale profile.
      ///   Deliberately calls <see cref="CharacterOverrideLoader.SyncAuthoredProse" />, the same method the chat
      ///   calls each turn, so removing that call from the chat breaks this test instead of passing beside it.
      /// </summary>
      private static string TestTradeGuidelines(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("trade_guidelines");

         Hero merchant = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && h.IsMerchant && Mapping.HeroPresence.IsInTheWorld(h));
         Hero other = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && !h.IsMerchant && !h.IsGangLeader && Mapping.HeroPresence.IsInTheWorld(h));
         if (t.Skip(merchant == null || other == null, "no merchant and other notable in the world")) return t.Line();

         const string marker = "CR SELFTEST: the merchant's own guidelines.";
         string before = NarrativeLoader.ReplaceStationGuidelinesForTest("merchant", marker);
         try
         {
            t.Note(merchant.Name + " (merchant), " + other.Name + " (" + other.Occupation + ")");
            t.Expect("aMerchantIsVoicedByTheMerchantFile",
                     (EncounterContextBuilder.ResolveStationGuidelines(merchant) ?? "").Contains(marker), true);
            t.Expect("anotherTradeKeepsTheSharedNotableFile",
                     (EncounterContextBuilder.ResolveStationGuidelines(other) ?? "").Contains(marker), false);
         }
         finally
         {
            NarrativeLoader.ReplaceStationGuidelinesForTest("merchant", before);
         }

         t.Expect("withTheFileGoneTheMerchantIsANotableAgain",
                  (EncounterContextBuilder.ResolveStationGuidelines(merchant) ?? "").Contains(marker), false);

         Hero named = Hero.AllAliveHeroes.FirstOrDefault(h => h.IsNotable && (h.IsHeadman || h.IsPreacher) && Mapping.HeroPresence.IsInTheWorld(h));
         if (named == null) t.Note("no headman or preacher in the world: their profile line is covered by unit tests only");
         else
         {
            string personality = HeroProfileMapper.FromHero(named).Personality ?? "";
            t.Expect("theProfileNamesAHeadmanOrPreacher",
                     personality.Contains(named.IsHeadman ? "headman" : "preacher"), true);
         }

         return t.Line();
      }

      private static string TestSpawnSpot(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("spawn_spot");

         Settlement village = Settlement.All?.FirstOrDefault(s => s != null && s.IsVillage
                                                              && Helpers.NavigationHelper.IsPositionValidForNavigationType(s.GatePosition, MobileParty.NavigationType.Default));
         if (t.Skip(village == null, "no village with a walkable gate")) return t.Line();

         Campaign.Current.MapSceneWrapper.GetMapBorders(out TaleWorlds.Library.Vec2 min, out TaleWorlds.Library.Vec2 _, out float _);
         var beyond = new TaleWorlds.Library.Vec2(min.x - 50f, min.y - 50f);

         CampaignVec2? atTheGate = Travel.MapSpot.Walkable(village.GatePosition.ToVec2(), village, "[SELFTEST] gate");
         CampaignVec2? moved = Travel.MapSpot.Walkable(beyond, village, "[SELFTEST] beyond the edge");
         CampaignVec2? refused = Travel.MapSpot.Walkable(beyond, null, "[SELFTEST] nowhere to fall back");

         t.Note(village.Name + ": gate " + village.GatePosition.ToVec2() + ", moved to " + (moved?.ToVec2().ToString() ?? "none"));
         t.Expect("aWalkablePointIsKept", atTheGate.HasValue && atTheGate.Value.ToVec2().DistanceSquared(village.GatePosition.ToVec2()) < 0.01f, true);
         t.Expect("aPointOffTheMapIsMovedToWalkableGround", moved.HasValue && Helpers.NavigationHelper.IsPositionValidForNavigationType(moved.Value, MobileParty.NavigationType.Default), true);
         t.Expect("andNearTheVillage", moved.HasValue && moved.Value.ToVec2().Distance(village.GatePosition.ToVec2()) <= 4f, true);
         t.Expect("withNowhereToFallBackNothingIsSpawned", refused.HasValue, false);

         return t.Line();
      }

      private static string TestOverrideNotInherited(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("override_not_inherited");

         Hero child = Hero.AllAliveHeroes.FirstOrDefault(h => h != null && h != Hero.MainHero && (h.Mother != null || h.Father != null)
                                                              && !string.IsNullOrWhiteSpace(h.Template?.StringId) && h.Template.StringId != h.StringId);

         if (t.Skip(child == null, "no living hero born in the campaign from a parent's character")) return t.Line();

         string parentKey = child.Template.StringId;
         const string marker = "[SELFTEST] a past written for the parent only.";

         try
         {
            CharacterOverrideLoader.InjectRuntimeOverride(new CharacterOverride {Id = parentKey, Hero = "[SELFTEST] parent entry", Backstory = marker});

            t.Note($"{child.Name} ({child.StringId}) was made from {parentKey}; an entry keyed on {parentKey} was authored at runtime");
            t.Expect("theParentsEntryDoesNotReachTheChild", CharacterOverrideLoader.For(child)?.Backstory == marker, false);
         }
         finally
         {
            CharacterOverrideLoader.Load();
         }

         return t.Line();
      }

      private static string TestConviction(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("conviction");

         Hero npc = ConversationNpc();

         if (t.Skip(npc == null, "no NPC to author a conviction on")) return t.Line();
         if (t.Skip(CrSettings.Instance == null, "MCM settings unavailable, cannot toggle custom character data")) return t.Line();

         const string belief =
            "[SELFTEST] He is convinced the player's clan is quietly plotting to unseat him, and reads every " +
            "kindness as a move in that game. He has told no one, and never will.";

         bool wasEnabled = ModSettings.UseCustomTraits;
         NpcProfile profile = GetOrCreate(behavior, npc);

         try
         {
            CrSettings.Instance.UseCustomTraits = true;

            CharacterOverrideLoader.InjectRuntimeOverride(new CharacterOverride {
               Id = npc.StringId,
               Hero = npc.Name?.ToString(),
               Conviction = belief
            });

            t.Note($"authored a conviction on {npc.Name} ({npc.StringId}) at runtime; character_overrides.json untouched");
            t.Expect("theLoaderHandsBackWhatWasAuthored", CharacterOverrideLoader.ConvictionFor(npc), belief);

            // The chat's own per-turn sync, called here exactly as ChatViewModel calls it.
            CharacterOverrideLoader.SyncAuthoredProse(profile, npc);
            t.Expect("thePerTurnSyncCarriesItOntoTheProfile", profile.AuthoredConviction, belief);

            string prompt = SystemPromptFor(behavior, npc, profile);

            if (t.Abort(prompt == null, "could not build the live system prompt")) return t.Line();

            t.Expect("itReachesTheSystemPromptTheModelWouldGet", prompt.Contains(belief), true);
            t.Expect("underItsOwnSection", prompt.Contains("WHAT YOU HOLD TRUE"), true);

            // The whole reason this field exists rather than a longer backstory: it must be taught as a MOTIVE.
            t.Expect("andItSaysHeACTSOnIt", prompt.Contains("you ACT on it"), true);
            t.Expect("andThatItMovesWhatHeDECIDES", prompt.Contains("moves what"), true);

            // The three limits. A belief a player types into a text box may not become a licence to rewrite the
            // world's rules, so each one is pinned individually: losing any single limit is a distinct failure.
            t.Expect("limitItGrantsNoPowers", prompt.Contains("NO powers"), true);
            t.Expect("limitItImportsNoOutsideLore", prompt.Contains("imports no lore"), true);
            t.Expect("limitItCannotBendTheWorld", prompt.Contains("does not bend the world"), true);

            // The MCM gate, and the reason the sync runs every turn instead of being persisted: switching custom
            // data off must ERASE the belief from the next prompt, not leave it stranded on the stored profile.
            CrSettings.Instance.UseCustomTraits = false;
            CharacterOverrideLoader.SyncAuthoredProse(profile, npc);
            t.Expect("switchingCustomDataOffErasesItFromTheProfile", profile.AuthoredConviction, null);

            string without = SystemPromptFor(behavior, npc, profile);
            t.Expect("andTheSectionLeavesThePromptEntirely", without != null && !without.Contains("WHAT YOU HOLD TRUE"), true);
         }
         finally
         {
            // Give the campaign back exactly what it lent: the file-backed overrides, the player's own MCM
            // choice, and a profile carrying no trace of the injected belief.
            CharacterOverrideLoader.Load();
            CrSettings.Instance.UseCustomTraits = wasEnabled;
            CharacterOverrideLoader.SyncAuthoredProse(profile, npc);
            behavior.Store.Set(profile);
         }

         return t.Line();
      }

      /// <summary>
      ///   Per-role provider routing (2026-08-13) + per-role API keys (player request, 2026-08-17: "I also need the
      ///   ability to have separate API keys for those endpoints, too, otherwise I can't use them"). The feature
      ///   lets the player send each TEXT role to a DIFFERENT provider, and (for OpenAI-Compatible) authenticate
      ///   each role with its OWN key. This drives <see cref="LlmServices.DebugDescribeRoleRouting" /> (which
      ///   reports what a role WOULD use with NO network call) to prove BOTH halves: distinct selections produce
      ///   distinct base URLs + kinds (the feature works at all), and leaving every role on "(default)" collapses
      ///   them onto the ONE default provider (the migration guarantee: an upgraded single-provider config behaves
      ///   exactly as before); then <see cref="LlmServices.DebugResolveApiKeyFor" /> (same no-network-call shape,
      ///   NEVER surfaced to any player-facing command) proves the twin claim for keys, using dummy sentinel
      ///   strings only, never a real key. Snapshots and restores every dropdown + the custom endpoint/key fields it
      ///   touches, so a real campaign is unchanged.
      /// </summary>
      private static string TestInitiativeDirector(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("initiative_director");
         if (t.Skip(Initiative.WorldInitiativeBehavior.Instance == null, "the director is not registered")) return t.Line();

         double now = CampaignTime.Now.ToHours;
         var copy = new Initiative.WorldInitiativeState {
            KeptSinceHour = now - 48,
            Requests = {new InitiativeRequest {Key = "cr_selftest_req", Family = InitiativeFamily.Household, Rank = InitiativeRank.Pressing, CharacterId = "x", FiledAtHour = now - 5, LastAskedAtHour = now - 1}},
            Grants = {new InitiativeGrant {Key = "cr_selftest_turn", Family = InitiativeFamily.Letters, GrantedAtHour = now - 30, Cost = 0.5}}
         };

         Initiative.WorldInitiativeState back = Initiative.WorldInitiativeBehavior.Deserialize(Initiative.WorldInitiativeBehavior.Serialize(copy));
         InitiativeRequest r = back?.Requests.FirstOrDefault();
         InitiativeGrant g = back?.Grants.FirstOrDefault();
         t.Expect("requestRoundTrip", r != null && r.Key == "cr_selftest_req" && r.Family == InitiativeFamily.Household && r.Rank == InitiativeRank.Pressing
                                      && r.CharacterId == "x" && System.Math.Abs(r.LastAskedAtHour - (now - 1)) < 0.01, true);
         t.Expect("turnRoundTrip", g != null && g.Family == InitiativeFamily.Letters && System.Math.Abs(g.Cost - 0.5) < 0.01, true);
         t.Expect("keptSinceRoundTrip", back != null && System.Math.Abs(back.KeptSinceHour - (now - 48)) < 0.01, true);

         InitiativeDecision d = WorldInitiativePolicy.Decide(back?.Requests, back?.Grants, new InitiativeSettings(),
            new InitiativeMoment {NowHour = now, KeptSinceHour = now - 48}, 0.5);
         t.Expect("calmMomentGivesTheTurn", d.Verdict, InitiativeVerdict.Granted);

         return t.Line();
      }

      private static string TestInitiativeDials(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("initiative_dials");
         var pace = CrSettings.Instance?.WorldInitiativePace;
         var lords = CrSettings.Instance?.InterceptionPacing;
         if (t.Skip(pace == null || lords == null, "the MCM is not ready")) return t.Line();

         int priorPace = pace.SelectedIndex, priorLords = lords.SelectedIndex;
         int Index(MCM.Common.Dropdown<string> d, string value) => d.ToList().IndexOf(value);
         try
         {
            pace.SelectedIndex = Index(pace, "Occasionally");
            lords.SelectedIndex = Index(lords, "Rarely");
            t.Expect("whilePacedTheLordsRollStepsAside", Interception.InterceptionBehavior.DailyInterceptChancePercent, 100);
            t.Expect("andRarelyIsHalfTheirWeight", ModSettings.WorldInitiative.FamilyWeights[InitiativeFamily.Lords], ModSettings.InitiativeWeightLords / 2);

            lords.SelectedIndex = Index(lords, "Never");
            t.Expect("neverStopsTheirTurns", ModSettings.WorldInitiative.FamilyWeights[InitiativeFamily.Lords], 0);
            t.Expect("andTheirRoll", Interception.InterceptionBehavior.DailyInterceptChancePercent, 0);

            pace.SelectedIndex = Index(pace, "Off");
            lords.SelectedIndex = Index(lords, "Occasionally");
            t.Expect("offBringsBackTheShippedRoll", Interception.InterceptionBehavior.DailyInterceptChancePercent,
               Logic.InterceptionPacingRules.DailyChancePercent(Logic.InterceptionPacing.Occasionally));
         }
         finally
         {
            pace.SelectedIndex = priorPace;
            lords.SelectedIndex = priorLords;
         }

         return t.Line();
      }

      private static string TestInitiativeTurns(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("initiative_turns");
         Initiative.WorldInitiativeBehavior director = Initiative.WorldInitiativeBehavior.Instance;
         if (t.Skip(director == null, "the director is not registered")) return t.Line();
         if (t.Skip(ModSettings.WorldInitiativeOff, "the world's initiative is Off in the MCM")) return t.Line();
         if (t.Skip(director.MomentAt(CampaignTime.Now.ToHours).Busy, "the player is busy right now")) return t.Line();
         if (t.Skip(director.MomentAt(CampaignTime.Now.ToHours).ActiveCount > 0, "a lord is riding after the player right now")) return t.Line();

         Initiative.WorldInitiativeState live = director.State;
         var savedRequests = live.Requests.ToList();
         var savedGrants = live.Grants.ToList();
         double savedSettled = live.LastSettledHour, savedOwnTalk = live.LastOwnTalkHour;
         const string key = "road:cr_selftest";
         double now = CampaignTime.Now.ToHours;

         try
         {
            live.LastSettledHour = double.MinValue;
            live.LastOwnTalkHour = double.MinValue;
            live.Requests.Clear();
            live.Grants.Clear();
            live.Grants.Add(new InitiativeGrant {Key = "cr_selftest_before", Family = InitiativeFamily.Letters, GrantedAtHour = now - 0.5});

            // STAKE: two knocks back to back pull the player out of the game: the second waits, and nothing is recorded for it.
            t.Expect("waitsRightAfterAnother", director.MayKnock(key, InitiativeFamily.Lords, InitiativeRank.Pressing), false);
            t.Expect("requestKept", live.Requests.Any(r => r.Key == key), true);
            t.Expect("noTurnRecorded", live.Grants.Any(g => g.Key == key), false);

            // STAKE: at a free moment the lord has his turn, and it is recorded.
            live.Grants.Clear();
            t.Expect("hasItsTurnWhenFree", director.MayKnock(key, InitiativeFamily.Lords, InitiativeRank.Pressing), true);
            t.Expect("turnRecorded", live.Grants.Any(g => g.Key == key), true);

            // STAKE (29/10/2026): a weekly source (a wife's divorce demand) kept waiting must not lose its chance until next
            // week: it waits and acts the day its turn comes; and it leaves the queue when its reason goes.
            const string household = "household:cr_selftest";
            var acted = 0;
            var stillHolds = true;
            t.Expect("theHouseholdWaitsRightAfterATurn", director.KnockOrWait(household, InitiativeFamily.Household, InitiativeRank.Pressing, null, true, () => stillHolds, () => acted++), false);
            t.Expect("andNothingHappenedYet", acted, 0);
            live.Grants.Clear();
            director.KnockForTheWaiting();
            t.Expect("itActsWhenItsTurnComes", acted, 1);
            live.Grants.Add(new InitiativeGrant {Key = "cr_selftest_before", Family = InitiativeFamily.Letters, GrantedAtHour = now - 0.5});
            director.KnockOrWait(household, InitiativeFamily.Household, InitiativeRank.Pressing, null, true, () => stillHolds, () => acted++);
            stillHolds = false;
            director.KnockForTheWaiting();
            t.Expect("aReasonGoneLeavesTheQueue", live.Requests.Any(r => r.Key == household) || acted != 1, false);
         }
         finally
         {
            live.Requests.Clear();
            live.Requests.AddRange(savedRequests);
            live.Grants.Clear();
            live.Grants.AddRange(savedGrants);
            live.LastSettledHour = savedSettled;
            live.LastOwnTalkHour = savedOwnTalk;
         }

         return t.Line();
      }

      private static string TestAimsChannels(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("aims_channels");

         Aims.AimsBehavior aims = Aims.AimsBehavior.Instance;
         if (t.Skip(aims == null, "the aims behavior is not registered")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != null && h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.Age >= 18
                                                             && aims.Book.ForNpc(h.StringId) == null && !Aims.AimsBehavior.IsEnemyOfPlayer(h));
         if (t.Skip(lord == null, "no lord at peace with the player to hold a test aim")) return t.Line();

         int today = (int) CampaignTime.Now.ToDays;
         const string source = "cr_selftest";
         const string session = "cr_selftest_audience";

         try
         {
            aims.Register(new Logic.Aims.StandingAim {
               Id = "aim", SourceMod = source, NpcId = lord.StringId, Want = "The selftest wants the ford's mill rebuilt.",
               Channels = Logic.Aims.AimChannels.Audience | Logic.Aims.AimChannels.Letter
            });

            t.Expect("mayRaiseByAudience", aims.AimToRaise(lord, Logic.Aims.AimChannels.Audience) != null, true);
            t.Expect("mayRaiseByLetter", aims.AimToRaise(lord, Logic.Aims.AimChannels.Letter) != null, true);
            t.Expect("notByConversationItIsClosedTo", aims.AimToRaise(lord, Logic.Aims.AimChannels.Conversation) == null, true);

            // STAKE: the lord who sought the player out may say why in the conversation that follows.
            aims.ExpectAudience(lord);
            t.Expect("soughtAudienceGivesLeave", aims.OnConversationStarted(new CrConversationInfo(lord.StringId, null, today, session)),
               Logic.Aims.AimRaiseVerdict.MayRaise);
            t.Expect("recordedAsAnAudience", aims.Book.ForNpc(lord.StringId)?.LastRaisedChannel, (Logic.Aims.AimChannels?) Logic.Aims.AimChannels.Audience);

            // STAKE: tashmetu's worry, across channels: the letter does not follow on the heels of the audience.
            t.Expect("letterWaitsAfterTheAudience", aims.AimToRaise(lord, Logic.Aims.AimChannels.Letter) == null, true);

            aims.Register(new Logic.Aims.StandingAim {
               Id = "aim", SourceMod = source, NpcId = lord.StringId, Want = "The selftest wants the ford's mill rebuilt.",
               Channels = Logic.Aims.AimChannels.Letter
            });
            t.Expect("closedToAudiencesIsNoReasonToSeek", aims.AimToRaise(lord, Logic.Aims.AimChannels.Audience) == null, true);
         }
         finally
         {
            aims.Retract(source, "aim");
            aims.OnConversationEnded(session);
         }

         return t.Line();
      }

      private static string TestAimsConversation(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("aims_conversation");

         Aims.AimsBehavior aims = Aims.AimsBehavior.Instance;
         if (t.Skip(aims == null, "the aims behavior is not registered")) return t.Line();

         List<Hero> lords = Hero.AllAliveHeroes.Where(h => h != null && h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.Age >= 18
                                                            && h.MapFaction != null && Hero.MainHero?.MapFaction != null
                                                            && !FactionManager.IsAtWarAgainstFaction(h.MapFaction, Hero.MainHero.MapFaction)
                                                            && aims.Book.ForNpc(h.StringId) == null
                                                            && (behavior?.Store?.Get(h.StringId)?.ReputationWithPlayer ?? 0) > NpcMemoryService.Core.Standing.VanillaRelation.EnemyTier)
                                               .Take(2).ToList();
         if (t.Skip(lords.Count < 2, "no two lords at peace with the player to hold a test aim")) return t.Line();

         Hero lord = lords[0];
         int today = (int) CampaignTime.Now.ToDays;
         const string source = "cr_selftest";
         const string first = "cr_selftest_session_1", second = "cr_selftest_session_2";

         try
         {
            const string want = "The selftest wants the mill at the ford rebuilt before the spring floods.";
            t.Expect("registered", aims.Register(new Logic.Aims.StandingAim {Id = "aim", SourceMod = source, NpcId = lord.StringId, Want = want}),
               Logic.Aims.AimAdmission.Accepted);

            // STAKE: the lord brings his aim up in a conversation the player opens.
            t.Expect("firstOpeningGivesLeave", aims.OnConversationStarted(new CrConversationInfo(lord.StringId, null, today, first)),
               Logic.Aims.AimRaiseVerdict.MayRaise);
            t.Expect("contextCarriesTheWant", aims.ForContext(lord, first)?.Want, want);
            t.Expect("contextCarriesTheLeave", aims.ForContext(lord, first)?.MayRaise, (bool?) true);

            // STAKE: tashmetu's worry: not in every conversation.
            t.Expect("secondOpeningSameDayHasNoLeave", aims.OnConversationStarted(new CrConversationInfo(lord.StringId, null, today, second)),
               Logic.Aims.AimRaiseVerdict.TooSoon);
            t.Expect("secondContextKnowsButMayNotRaise", aims.ForContext(lord, second)?.MayRaise, (bool?) false);

            aims.OnConversationEnded(first);
            t.Expect("leaveEndsWithTheConversation", aims.ForContext(lord, first)?.MayRaise, (bool?) false);

            // STAKE: the war duty has its own section with its terms; the generic one must not voice it a second time.
            aims.Register(new Logic.Aims.StandingAim {Id = "cr_selftest_own", SourceMod = Aims.AimsBehavior.CrSource, NpcId = lords[1].StringId, Want = "A duty of CR's own."});
            t.Expect("crOwnAimNotVoicedGenerically", aims.ForContext(lords[1], first) == null, true);
         }
         finally
         {
            aims.Retract(source, "aim");
            aims.Retract(Aims.AimsBehavior.CrSource, "cr_selftest_own");
            aims.OnConversationEnded(first);
            aims.OnConversationEnded(second);
         }

         return t.Line();
      }

      private static string TestAimsDoor(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("aims_door");

         Aims.AimsBehavior aims = Aims.AimsBehavior.Instance;
         if (t.Skip(aims == null, "the aims behavior is not registered")) return t.Line();

         Hero lord = Hero.AllAliveHeroes.FirstOrDefault(h => h != null && h != Hero.MainHero && h.IsLord && !h.IsPrisoner && h.Age >= 18
                                                            && h.MapFaction != null && Hero.MainHero?.MapFaction != null
                                                            && !FactionManager.IsAtWarAgainstFaction(h.MapFaction, Hero.MainHero.MapFaction)
                                                            && aims.Book.ForNpc(h.StringId) == null
                                                            && (behavior?.Store?.Get(h.StringId)?.ReputationWithPlayer ?? 0) > NpcMemoryService.Core.Standing.VanillaRelation.EnemyTier);
         if (t.Skip(lord == null, "no lord at peace with the player to hold a test aim")) return t.Line();
         t.Note(lord.Name.ToString());

         const string source = "cr_selftest_door", session = "cr_selftest_door_session";
         const string want = "The selftest wants the old watchtower manned again.";
         var raised = new List<CrAimRaised>();
         void OnRaised(CrAimRaised r) { if (r.SourceMod == source) raised.Add(r); }
         CrAims.Raised += OnRaised;
         try
         {
            t.Expect("accepted", CrAims.Register(new ExternalAim {Id = "tower", SourceMod = source, NpcId = lord.StringId, Want = want, Channels = {"conversation"}}),
               AimResult.Accepted);
            t.Expect("updatedUnderTheSameId", CrAims.Register(new ExternalAim {Id = "tower", SourceMod = source, NpcId = lord.StringId, Want = want}),
               AimResult.Updated);
            // CrAims.List (since 2.8.10, Bhelogan): a mod reads back its aims, a copy with every channel once none is named.
            ExternalAim listed = CrAims.List(source).FirstOrDefault(a => a.Id == "tower");
            t.Expect("listedForItsSource", listed?.NpcId == lord.StringId && listed?.Want == want, true);
            t.Expect("listedWithItsChannels", listed == null ? "" : string.Join(",", listed.Channels), "conversation,letter,audience");
            t.Expect("crsOwnAimsAreNotListed", CrAims.List(Aims.AimsBehavior.CrSource).Count, 0);
            t.Expect("oneAimPerLord", CrAims.Register(new ExternalAim {Id = "other", SourceMod = source + "_b", NpcId = lord.StringId, Want = want}),
               AimResult.LordAlreadyHasAnAim);
            t.Expect("anUnknownHeroIsRefused", CrAims.Register(new ExternalAim {Id = "x", SourceMod = source, NpcId = "no_such_hero", Want = want}),
               AimResult.UnknownHero);
            t.Expect("crsOwnNameIsReserved", CrAims.Register(new ExternalAim {Id = "x", SourceMod = Aims.AimsBehavior.CrSource, NpcId = lord.StringId, Want = want}),
               AimResult.ReservedSource);

            // STAKE: the lord gets leave to raise it in a conversation the player opens, and the mod hears it.
            aims.OnConversationStarted(new CrConversationInfo(lord.StringId, null, (int) CampaignTime.Now.ToDays, session));
            t.Expect("theContextCarriesTheWant", aims.ForContext(lord, session)?.Want, want);
            t.Expect("theModHearsItWasRaised", raised.Count == 1 && raised[0].AimId == "tower" && raised[0].NpcId == lord.StringId && raised[0].Channel == "conversation", true);

            t.Expect("retracted", CrAims.Retract(source, "tower"), true);
            t.Expect("goneOnceRetracted", aims.Book.ForNpc(lord.StringId) == null, true);
         }
         finally
         {
            CrAims.Raised -= OnRaised;
            CrAims.Retract(source, "tower");
            aims.OnConversationEnded(session);
         }

         return t.Line();
      }

      private static string TestCompanionPatrol(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("companion_patrol");
         CompanionPatrolBehavior patrols = CompanionPatrolBehavior.Instance;
         if (t.Skip(patrols == null, "the patrol system is not active")) return t.Line();
         if (t.Skip(MobileParty.MainParty?.MapEvent != null, "the player is in a battle")) return t.Line();

         using var arranged = ArrangedCompanion.Get(behavior, mustBeInMainParty: true);
         if (t.Skip(arranged == null, "no available companion in your party, and no wanderer template to arrange one")) return t.Line();
         Hero companion = arranged.Companion;

         TaleWorlds.Library.Vec2 here = MobileParty.MainParty.GetPosition2D;
         Settlement village = Settlement.All.Where(s => s.IsVillage).OrderBy(s => s.GetPosition2D.Distance(here)).FirstOrDefault();
         if (t.Skip(village == null, "no village in the world")) return t.Line();

         // Arranged men: the test needs a few healthy soldiers, and takes back exactly what it added.
         CharacterObject recruit = Hero.MainHero.Culture?.BasicTroop;
         var added = 0;
         int healthy = MobileParty.MainParty.MemberRoster.GetTroopRoster().Where(e => e.Character is {IsHero: false}).Sum(e => e.Number - e.WoundedNumber);
         if (healthy < 10 && recruit != null)
         {
            added = 10;
            MobileParty.MainParty.MemberRoster.AddToCounts(recruit, added);
         }

         int totalBefore = MobileParty.MainParty.MemberRoster.TotalManCount;
         CrPatrolEnd heardEnd = null;
         void OnEnded(CrPatrolEnd e)
         {
            if (e.Patrol.CompanionId == companion.StringId) heardEnd = e;
         }

         CrPatrols.Ended += OnEnded;
         try
         {
            string notice = patrols.DebugConfirm(companion, village, 5);
            t.Note(notice);
            MobileParty party = patrols.DebugPartyOf(companion);
            if (t.Abort(party == null, "the patrol did not ride out: " + notice)) return t.Line();

            // STAKE: the men are the player's own, moved and never conjured (Gabriel, 16/10/2026).
            t.Expect("menLeftTheMainParty", MobileParty.MainParty.MemberRoster.TotalManCount, totalBefore - 6);
            t.Expect("theyRideWithThePatrol", party.MemberRoster.TotalManCount, 6);
            // STAKE: the spike: with the AI locked a patrol only watches bandits pass.
            t.Expect("anchoredOnTheVillage", party.TargetSettlement == village && party.DefaultBehavior == AiBehavior.PatrolAroundPoint, true);
            t.Expect("theAiIsFree", party.Ai.DoNotMakeNewDecisions, false);
            // STAKE: tashmetu read the patrols by reflection; the public copy lists this one with its place.
            t.Expect("anotherModReadsThePatrol", CrPatrols.Current.Any(p => p.CompanionId == companion.StringId && p.SettlementId == village.StringId), true);

            // STAKE: the spike's drift: dragged off its post, the hourly leash sends it back.
            party.SetMoveGoToPoint(new CampaignVec2(village.GatePosition.ToVec2() + new TaleWorlds.Library.Vec2(40f, 40f), true), MobileParty.NavigationType.Default);
            patrols.DebugHour();
            t.Expect("theLeashReAnchorsIt", party.TargetSettlement == village && party.DefaultBehavior == AiBehavior.PatrolAroundPoint, true);

            // STAKE: Gabriel: each month the companion writes and asks; the letter is due and sent (logged, not written here).
            CompanionPatrolBehavior.DebugSuppressLetters = true;
            patrols.DebugDay(forceReport: true);
            t.Expect("theMonthlyLetterGoesOut", patrols.DebugStateOf(companion)?.LastReportDay, (int) CampaignTime.Now.ToDays);

            // STAKE: a letter saying "come back" turns the patrol for home within the hour. The test's patrol stands next
            // to the player, so the same hour may already bring it home (17/10/2026 run: Returning, then home, in one
            // DebugHour): either is the letter obeyed; still on patrol is not.
            patrols.ObeyLetterToStop(companion.StringId);
            patrols.DebugHour();
            CompanionPatrolState? afterTheLetter = patrols.DebugStateOf(companion)?.State;
            t.Expect("aLetterToStopTurnsItHome", afterTheLetter == null || afterTheLetter == CompanionPatrolState.Returning, true);

            // STAKE (Aporo, Discord 10/11/2026: a returning companion "stands close to me and i can't do anything"): far
            // from the player, still riding before the grace days are out, and back in the party once they are.
            MobileParty riding = patrols.DebugPartyOf(companion);
            if (riding != null)
            {
               int today = (int) CampaignTime.Now.ToDays;
               riding.Position = new CampaignVec2(village.GatePosition.ToVec2() + new TaleWorlds.Library.Vec2(40f, 40f), true);
               patrols.DebugSetReturningSince(companion, today - ReturnHomePolicy.GraceDays + 1);
               patrols.DebugHour();
               t.Expect("farAwayItKeepsRidingBeforeTheGraceDays", patrols.IsPatrolling(companion.StringId), true);
               patrols.DebugSetReturningSince(companion, today - ReturnHomePolicy.GraceDays);
               patrols.DebugHour();
               t.Expect("afterTheGraceDaysItRejoinsWhereverItIs", patrols.IsPatrolling(companion.StringId), false);
            }

            // STAKE: coming home hands back every man (the spike's stop left the wounded behind).
            if (patrols.IsPatrolling(companion.StringId)) patrols.DebugBringHomeNow(companion);
            t.Expect("everyManIsBack", MobileParty.MainParty.MemberRoster.TotalManCount, totalBefore);
            t.Expect("noLongerOnPatrol", patrols.IsPatrolling(companion.StringId), false);
            // STAKE: another mod hears the patrol end, and how: home with the men.
            t.Expect("anotherModHearsItCameBack", heardEnd?.How, CrPatrolEndKind.Back);
            t.Expect("andItIsNoLongerListed", CrPatrols.Current.Any(p => p.CompanionId == companion.StringId), false);
         }
         finally
         {
            CrPatrols.Ended -= OnEnded;
            CompanionPatrolBehavior.DebugSuppressLetters = false;
            if (patrols.IsPatrolling(companion.StringId)) patrols.DebugBringHomeNow(companion);
            if (added > 0) MobileParty.MainParty.MemberRoster.AddToCounts(recruit, -added);
         }

         return t.Line();
      }

      private static string TestPlayerNamedOnScreen(NpcMemoryCampaignBehavior behavior)
      {
         var t = new TestRun("player_named_on_screen");
         string name = Hero.MainHero?.Name?.ToString();
         if (t.Skip(string.IsNullOrWhiteSpace(name), "no player character")) return t.Line();

         // STAKE: the reported grievance, as the encyclopedia and the chat side panel show it.
         var grudge = new Grudge {
            Id = "selftest|0|0", HolderId = "selftest", TargetId = "player", Source = GrudgeSource.FailedQuest,
            CauseSummary = "The marriage was ended by the player's own choice.", Magnitude = 50, Rigidity = 50
         };
